const LIST_LIMIT = 30;
const SENDER_DOMAIN_SCAN_MAX_PAGES = 4;
const OUTCOME_SUMMARY_SCAN_MAX_PAGES = 4;
const SIGNALDESK_AI_DETAIL_RETENTION_MS = 90 * 24 * 60 * 60 * 1_000;
const LEGACY_PENDING_SENDER_DOMAIN_ID = "sender_domain_pending_v1";
const SIGNALDESK_PROVIDER_BUDGET_BLOCKED_REASON = "provider_budget_blocked";
const SIGNALDESK_RESEARCH_AGENT_BLOCKED_REASON = "research_agent_blocked";

const getSignalDeskDb = () => {
    if (!isSignalDeskFirebaseConfigured && !process.env.FIRESTORE_EMULATOR_HOST) return null;
    const db = signaldeskFirestoreAdmin as any;
    return db && typeof db.collection === "function" ? signaldeskFirestoreAdmin : null;
};

const now = () => admin.firestore.Timestamp.now();
const increment = (value: number) => admin.firestore.FieldValue.increment(value);

const hashValue = (value: string) => createHash("sha256").update(value).digest("hex");
const isAlreadyExistsError = (error: unknown) => {
    const code = (error as { code?: unknown } | null)?.code;
    return code === 6 || code === "6" || code === "already-exists" || code === "ALREADY_EXISTS";
};

const normalizeText = (value?: unknown) => typeof value === "string" ? value.trim() : "";
const normalizeLower = (value?: unknown) => normalizeText(value).toLowerCase();
const normalizeUrl = (value?: unknown) => normalizeLower(value).replace(/^https?:\/\//, "").replace(/^www\./, "").replace(/\/$/, "");
const canonicalizeSenderDomain = (value?: unknown) => {
    const domain = normalizeLower(value).replace(/\.$/, "");
    const labels = domain.split(".");
    const valid = domain.length >= 3
        && domain.length <= 253
        && labels.length >= 2
        && labels.every((label) => (
            label.length >= 1
            && label.length <= 63
            && /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(label)
        ))
        && /[a-z]/.test(labels[labels.length - 1] || "")
        && (labels[labels.length - 1]?.length || 0) >= 2;
    if (!valid) throw new Error("SENDER_DOMAIN_INVALID");
    return domain;
};
const canonicalizeContentUrl = (value?: string | null) => {
    const rawUrl = normalizeText(value);
    if (!rawUrl) return null;
    if (rawUrl.length > 500) throw new Error("Content URL must be a valid credential-free HTTP(S) URL");
    let parsed: URL;
    try {
        parsed = new URL(rawUrl);
    } catch {
        throw new Error("Content URL must be a valid credential-free HTTP(S) URL");
    }
    if ((parsed.protocol !== "http:" && parsed.protocol !== "https:") || !parsed.hostname || parsed.username || parsed.password) {
        throw new Error("Content URL must be a valid credential-free HTTP(S) URL");
    }
    parsed.hash = "";
    return parsed.href;
};
const todayKey = () => new Date().toISOString().slice(0, 10);
const isValidIsoDay = (value: unknown): value is string => {
    if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
    const date = new Date(`${value}T00:00:00.000Z`);
    return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === value;
};
const env = (key: string) => process.env[key]?.trim() || "";
const operatingLayerEnabled = () => FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_OPERATING_LAYER === true;
const revenueOperatingLayerEnabled = () => FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_REVENUE_OPERATING_LAYER === true;
