const readList = async <T>(db: any, collection: string, orderField = "updatedAt", limit = LIST_LIMIT): Promise<T[]> => {
    const snap = await db.collection(collection).orderBy(orderField, "desc").limit(limit).get();
    return snap.docs.map((doc: any) => ({ ...toPlain(doc.data()), [`${collection}DocId`]: doc.id })) as T[];
};

const WORKSPACE_PROJECTION_SCAN_MAX_PAGES = 4;
const WORKSPACE_PROJECTION_PAGE_SIZE = 100;

const readProjectedWorkspaceRows = async <T>(
    db: FirebaseFirestore.Firestore,
    collection: string,
    projector: (row: AnyRecord) => T | null,
    options?: {
        includeRow?: (row: AnyRecord) => boolean;
        limit?: number;
        orderField?: string;
    },
): Promise<{ invalidCount: number; rows: T[]; scannedCount: number }> => {
    const limit = options?.limit ?? LIST_LIMIT;
    if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
        throw new Error("SIGNALDESK_WORKSPACE_PROJECTED_READ_INVALID");
    }
    const rows: T[] = [];
    let cursor: FirebaseFirestore.QueryDocumentSnapshot | null = null;
    let exhausted = false;
    let invalidCount = 0;
    let scannedCount = 0;
    for (let page = 0; page < WORKSPACE_PROJECTION_SCAN_MAX_PAGES && rows.length < limit; page += 1) {
        let query: FirebaseFirestore.Query = db.collection(collection)
            .orderBy(options?.orderField || "updatedAt", "desc")
            .limit(WORKSPACE_PROJECTION_PAGE_SIZE);
        if (cursor) query = query.startAfter(cursor);
        const snapshot = await query.get();
        if (snapshot.empty) {
            exhausted = true;
            break;
        }
        for (const document of snapshot.docs) {
            scannedCount += 1;
            const raw = {
                ...toPlain(document.data()),
                [`${collection}DocId`]: document.id,
            };
            if (options?.includeRow && !options.includeRow(raw)) continue;
            let projected: T | null = null;
            try {
                projected = projector(raw);
            } catch {
                projected = null;
            }
            if (projected) rows.push(projected);
            else invalidCount += 1;
            if (rows.length === limit) break;
        }
        cursor = snapshot.docs[snapshot.docs.length - 1] || null;
        if (snapshot.size < WORKSPACE_PROJECTION_PAGE_SIZE) {
            exhausted = true;
            break;
        }
    }
    if (!exhausted && rows.length < limit) {
        logRuntimeFailure(
            "signaldesk_projected_workspace_scan_limit_exceeded",
            new Error("signaldesk_projected_workspace_scan_limit_exceeded"),
            { collection, invalidCount, limit, product: "signaldesk", scannedCount },
        );
    }
    return { invalidCount, rows, scannedCount };
};

const readWorkspaceList = async <T extends SignalDeskWorkspaceProjection>(
    db: FirebaseFirestore.Firestore,
    collection: string,
    orderField = "updatedAt",
    limit = LIST_LIMIT,
): Promise<T[]> => {
    if (
        !isSignalDeskWorkspaceGenericCollection(collection)
        || !Number.isInteger(limit)
        || limit < 1
        || limit > 100
    ) throw new Error("SIGNALDESK_WORKSPACE_COLLECTION_READ_INVALID");
    const currentPeriod = getSignalDeskSpendPeriod();
    const projected: SignalDeskWorkspaceProjection[] = [];
    let cursor: FirebaseFirestore.QueryDocumentSnapshot | null = null;
    let rejectedCount = 0;
    let scannedCount = 0;
    for (let page = 0; page < WORKSPACE_PROJECTION_SCAN_MAX_PAGES && projected.length < limit; page += 1) {
        let query: FirebaseFirestore.Query = db.collection(collection)
            .orderBy(orderField, "desc")
            .limit(WORKSPACE_PROJECTION_PAGE_SIZE);
        if (cursor) query = query.startAfter(cursor);
        const snapshot = await query.get();
        if (snapshot.empty) break;
        for (const document of snapshot.docs) {
            scannedCount += 1;
            const item = projectSignalDeskWorkspaceDocument(
                collection as SignalDeskWorkspaceGenericCollection,
                document.data(),
                document.id,
                currentPeriod,
            );
            if (item) projected.push(item);
            else rejectedCount += 1;
            if (projected.length === limit) break;
        }
        cursor = snapshot.docs[snapshot.docs.length - 1] || null;
        if (snapshot.size < WORKSPACE_PROJECTION_PAGE_SIZE) break;
    }
    if (rejectedCount > 0) {
        logRuntimeFailure(
            "signaldesk_workspace_projection_rejected",
            new Error("SIGNALDESK_WORKSPACE_DOCUMENT_SHAPE_INVALID"),
            { collection, limit, rejectedCount, scannedCount },
        );
    }
    return projected as T[];
};

