const projectSignalDeskContentSource = (value: AnyRecord): SignalDeskContentSourceSummary | null => {
    const docId = normalizeText(value[`${SIGNALDESK_COLLECTIONS.CONTENT_SOURCES}DocId`]);
    const storedId = normalizeText(value.contentSourceId);
    const contentSourceId = docId || storedId;
    const title = normalizeText(value.title);
    const sourceType = normalizeText(value.sourceType) as SignalDeskContentSourceType;
    const defaultAudience = normalizeText(value.defaultAudience) as SignalDeskContentSourceSummary["defaultAudience"];
    const status = normalizeText(value.status) as SignalDeskControlStatus;
    const defaultMarketPodId = normalizeText(value.defaultMarketPodId) || null;
    const createdAt = toIso(value.createdAt);
    const lastAssetAt = toIso(value.lastAssetAt);
    const lastCheckedAt = toIso(value.lastCheckedAt);
    const updatedAt = toIso(value.updatedAt);
    if (
        normalizeText(value.pId) !== SIGNALDESK_PRODUCT_CODE
        || !contentSourceId
        || contentSourceId.length > 180
        || (docId && storedId && docId !== storedId)
        || title.length < 2
        || title.length > 160
        || (defaultMarketPodId?.length || 0) > 160
        || !CONTENT_SOURCE_TYPES.has(sourceType)
        || !CONTENT_SOURCE_AUDIENCES.has(defaultAudience)
        || !CONTENT_SOURCE_STATUSES.has(status)
        || (value.createdAt != null && !createdAt)
        || (value.lastAssetAt != null && !lastAssetAt)
        || (value.lastCheckedAt != null && !lastCheckedAt)
        || (value.updatedAt != null && !updatedAt)
    ) return null;
    let sourceUrl: string | null;
    try {
        if (value.sourceUrl != null && typeof value.sourceUrl !== "string") return null;
        sourceUrl = canonicalizeContentUrl(typeof value.sourceUrl === "string" ? value.sourceUrl : null);
    } catch {
        return null;
    }
    if ((sourceUrl?.length || 0) > 500) return null;
    return {
        contentSourceId,
        createdAt,
        defaultAudience,
        defaultMarketPodId,
        lastAssetAt,
        lastCheckedAt,
        sourceType,
        sourceUrl,
        status,
        title,
        updatedAt,
    };
};

const readContentSources = async (db: any, excludePendingAuthority = false) => {
    const { invalidCount, rows } = await readProjectedWorkspaceRows(
        db,
        SIGNALDESK_COLLECTIONS.CONTENT_SOURCES,
        projectSignalDeskContentSource,
        { includeRow: excludePendingAuthority ? (row) => row.dependentHoldReconciliationPending !== true : undefined },
    );
    if (invalidCount) {
        logRuntimeFailure("signaldesk_content_source_shape_invalid", new Error("signaldesk_content_source_shape_invalid"), {
            invalidCount,
            product: "signaldesk",
        });
    }
    return rows;
};

const projectSignalDeskProofPermission = (value: AnyRecord): SignalDeskProofPermissionSummary | null => {
    const docId = normalizeText(value[`${SIGNALDESK_COLLECTIONS.PROOF_PERMISSIONS}DocId`]);
    const storedId = normalizeText(value.proofPermissionId);
    const proofPermissionId = docId || storedId;
    const targetId = normalizeText(value.targetId);
    const status = normalizeText(value.status) as SignalDeskProofPermissionSummary["status"];
    const evidenceRef = normalizeText(value.evidenceRef);
    const grantedAt = toIso(value.grantedAt);
    const expiresAt = toIso(value.expiresAt);
    const revokedAt = toIso(value.revokedAt);
    const updatedAt = toIso(value.updatedAt);
    if (
        normalizeText(value.pId) !== SIGNALDESK_PRODUCT_CODE
        || !proofPermissionId
        || proofPermissionId.length > 180
        || (docId && storedId && docId !== storedId)
        || !targetId
        || targetId.length > 160
        || !PROOF_PERMISSION_STATUSES.has(status)
        || evidenceRef.length < 3
        || evidenceRef.length > 500
        || !Array.isArray(value.scopes)
        || value.scopes.length < 1
        || value.scopes.length > 8
        || new Set(value.scopes).size !== value.scopes.length
        || !value.scopes.every((scope: unknown) => typeof scope === "string" && PROOF_PERMISSION_SCOPES.has(scope as SignalDeskProofPermissionScope))
        || (value.grantedAt != null && !grantedAt)
        || (value.expiresAt != null && !expiresAt)
        || (value.revokedAt != null && !revokedAt)
        || (value.updatedAt != null && !updatedAt)
        || (status === "active" && (!grantedAt || new Date(grantedAt).getTime() > Date.now() + CONTENT_PUBLICATION_FUTURE_SKEW_MS))
        || (status === "active" && revokedAt !== null)
        || (status === "revoked" && (!revokedAt || new Date(revokedAt).getTime() > Date.now() + CONTENT_PUBLICATION_FUTURE_SKEW_MS))
        || (status === "expired" && (!expiresAt || new Date(expiresAt).getTime() > Date.now()))
        || (expiresAt != null && grantedAt != null && new Date(expiresAt).getTime() <= new Date(grantedAt).getTime())
        || (value.targetName != null && (typeof value.targetName !== "string" || value.targetName.trim().length > 240))
        || (value.notes != null && (typeof value.notes !== "string" || value.notes.trim().length > 500))
    ) return null;
    return {
        evidenceRef,
        expiresAt,
        grantedAt,
        notes: typeof value.notes === "string" ? value.notes.trim() || null : null,
        proofPermissionId,
        revokedAt,
        scopes: Array.from(new Set(value.scopes)) as SignalDeskProofPermissionScope[],
        status,
        targetId,
        targetName: typeof value.targetName === "string" ? value.targetName.trim() || null : null,
        updatedAt,
    };
};

const projectSignalDeskSelfServiceCta = (value: AnyRecord): SignalDeskSelfServiceCtaSummary | null => {
    const docId = normalizeText(value[`${SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS}DocId`]);
    const storedId = normalizeText(value.ctaId);
    const ctaId = docId || storedId;
    const label = normalizeText(value.label);
    const copy = normalizeText(value.copy);
    const ctaType = normalizeText(value.ctaType) as SignalDeskSelfServiceCtaSummary["ctaType"];
    const status = normalizeText(value.status) as SignalDeskControlStatus;
    if (
        normalizeText(value.pId) !== SIGNALDESK_PRODUCT_CODE
        || !ctaId
        || ctaId.length > 180
        || (docId && storedId && docId !== storedId)
        || label.length < 2
        || label.length > 80
        || copy.length < 2
        || copy.length > 500
        || !SELF_SERVICE_CTA_TYPES.has(ctaType)
        || !CONTENT_SOURCE_STATUSES.has(status)
        || (value.updatedAt != null && !toIso(value.updatedAt))
    ) return null;
    return { copy, ctaId, ctaType, label, status, updatedAt: toIso(value.updatedAt) };
};

const TRUST_PARTNER_BRIEF_STATUSES = new Set<SignalDeskTrustPartnerBriefSummary["status"]>([
    "draft", "ready", "approved", "blocked",
]);

const canonicalTrustPartnerClaims = (values: unknown) => {
    if (!Array.isArray(values)) return null;
    const claims = values.map(normalizeText);
    if (
        claims.length < 1
        || claims.length > 8
        || claims.some((claim) => claim.length < 2 || claim.length > 240)
    ) return null;
    return Array.from(new Set(claims)).sort((left, right) => left < right ? -1 : left > right ? 1 : 0);
};

const projectSignalDeskTrustPartnerBrief = (value: AnyRecord): SignalDeskTrustPartnerBriefSummary | null => {
    const docId = normalizeText(value[`${SIGNALDESK_COLLECTIONS.TRUST_PARTNER_BRIEFS}DocId`]);
    const storedId = normalizeText(value.briefId);
    const briefId = docId || storedId;
    const partnerId = normalizeText(value.partnerId);
    const dealId = normalizeText(value.dealId) || null;
    const ctaId = normalizeText(value.ctaId);
    const ctaFingerprintHash = normalizeText(value.ctaFingerprintHash);
    const disclosureText = normalizeText(value.disclosureText);
    const onePageBrief = normalizeText(value.onePageBrief);
    const status = normalizeText(value.status) as SignalDeskTrustPartnerBriefSummary["status"];
    const approvedClaims = canonicalTrustPartnerClaims(value.approvedClaims);
    const bannedClaims = canonicalTrustPartnerClaims(value.bannedClaims);
    const bannedClaimKeys = new Set((bannedClaims || []).map(normalizeLower));
    const updatedAt = toIso(value.updatedAt);
    if (
        normalizeText(value.pId) !== SIGNALDESK_PRODUCT_CODE
        || !briefId
        || briefId.length > 180
        || (docId && storedId && docId !== storedId)
        || !partnerId
        || partnerId.length > 180
        || (dealId?.length || 0) > 180
        || !ctaId
        || ctaId.length > 180
        || !/^[a-f0-9]{64}$/.test(ctaFingerprintHash)
        || value.disclosureRequired !== true
        || disclosureText.length < 5
        || disclosureText.length > 500
        || onePageBrief.length < 20
        || onePageBrief.length > 2000
        || !TRUST_PARTNER_BRIEF_STATUSES.has(status)
        || !approvedClaims
        || !bannedClaims
        || approvedClaims.some((claim) => bannedClaimKeys.has(normalizeLower(claim)))
        || (value.updatedAt != null && !updatedAt)
    ) return null;
    return {
        approvedClaims,
        bannedClaims,
        briefId,
        ctaFingerprintHash,
        ctaId,
        dealId,
        disclosureRequired: true,
        disclosureText,
        onePageBrief,
        partnerId,
        status,
        updatedAt,
    };
};

const readTrustPartnerBriefs = async (db: FirebaseFirestore.Firestore) => {
    let invalidSameProductCount = 0;
    const { rows } = await readProjectedWorkspaceRows(
        db,
        SIGNALDESK_COLLECTIONS.TRUST_PARTNER_BRIEFS,
        (row) => {
            const projected = projectSignalDeskTrustPartnerBrief(row);
            if (!projected && normalizeText(row.pId) === SIGNALDESK_PRODUCT_CODE) invalidSameProductCount += 1;
            return projected;
        },
    );
    if (invalidSameProductCount) {
        logRuntimeFailure("signaldesk_trust_partner_brief_shape_invalid", new Error("signaldesk_trust_partner_brief_shape_invalid"), {
            invalidSameProductCount,
            product: "signaldesk",
        });
    }
    return rows;
};

const signalDeskCtaFingerprintHash = (cta: SignalDeskSelfServiceCtaSummary) => hashValue(JSON.stringify({
    copy: cta.copy,
    ctaId: cta.ctaId,
    ctaType: cta.ctaType,
    label: cta.label,
    status: cta.status,
}));

const senderDomainIdFor = (domain: string) => `sender_${hashValue(domain).slice(0, 18)}`;

const projectSignalDeskSenderDomain = (value: AnyRecord): SignalDeskSenderDomainSummary | null => {
    const docId = normalizeText(value[`${SIGNALDESK_COLLECTIONS.SENDER_DOMAINS}DocId`]);
    const storedId = normalizeText(value.senderDomainId);
    const senderDomainId = docId || storedId;
    let domain: string;
    try {
        domain = canonicalizeSenderDomain(value.domain);
    } catch {
        return null;
    }
    const status = normalizeText(value.status) as SignalDeskControlStatus;
    const providerValue = normalizeText(value.provider);
    const provider = providerValue ? providerValue as SignalDeskProviderId : null;
    const authenticationState = normalizeText(value.authenticationState) as SignalDeskSenderDomainSummary["authenticationState"];
    const volumeRampState = normalizeText(value.volumeRampState) as SignalDeskSenderDomainSummary["volumeRampState"];
    const brandRisk = normalizeText(value.brandRisk) as SignalDeskSenderDomainSummary["brandRisk"];
    const updatedAt = toIso(value.updatedAt);
    if (
        normalizeText(value.pId) !== SIGNALDESK_PRODUCT_CODE
        || !docId
        || !storedId
        || !senderDomainId
        || senderDomainId.length > 180
        || senderDomainId !== senderDomainIdFor(domain)
        || docId !== storedId
        || !CONTENT_SOURCE_STATUSES.has(status)
        || (value.provider != null && (typeof value.provider !== "string" || !SIGNALDESK_PROVIDER_IDS.has(provider as SignalDeskProviderId)))
        || !SENDER_DOMAIN_AUTHENTICATION_STATES.has(authenticationState)
        || !SENDER_DOMAIN_VOLUME_RAMP_STATES.has(volumeRampState)
        || !SENDER_DOMAIN_BRAND_RISKS.has(brandRisk)
        || typeof value.bounceRate !== "number"
        || !Number.isFinite(value.bounceRate)
        || value.bounceRate < 0
        || value.bounceRate > 1
        || typeof value.complaintRate !== "number"
        || !Number.isFinite(value.complaintRate)
        || value.complaintRate < 0
        || value.complaintRate > 1
        || typeof value.unsubscribeReady !== "boolean"
        || value.dependentHoldReconciliationPending === true
        || !updatedAt
    ) return null;
    return {
        authenticationState,
        bounceRate: value.bounceRate,
        brandRisk,
        complaintRate: value.complaintRate,
        domain,
        provider,
        senderDomainId,
        status,
        unsubscribeReady: value.unsubscribeReady,
        updatedAt,
        volumeRampState,
    };
};

const senderDomainFingerprintHashFor = (sender: SignalDeskSenderDomainSummary) => hashValue(JSON.stringify({
    authenticationState: sender.authenticationState,
    bounceRate: sender.bounceRate,
    brandRisk: sender.brandRisk,
    complaintRate: sender.complaintRate,
    domain: sender.domain,
    provider: sender.provider || null,
    senderDomainId: sender.senderDomainId,
    status: sender.status,
    unsubscribeReady: sender.unsubscribeReady,
    volumeRampState: sender.volumeRampState,
}));

const LEGACY_PENDING_SENDER_DOMAIN_KEYS = new Set([
    `${SIGNALDESK_COLLECTIONS.SENDER_DOMAINS}DocId`,
    "authenticationState",
    "bounceRate",
    "brandRisk",
    "complaintRate",
    "createdAt",
    "domain",
    "pId",
    "provider",
    "senderDomainId",
    "status",
    "unsubscribeReady",
    "updatedAt",
    "updatedBy",
    "volumeRampState",
]);

const isLegacyPendingSenderSentinel = (value: AnyRecord) => (
    Object.keys(value).every((key) => LEGACY_PENDING_SENDER_DOMAIN_KEYS.has(key))
    && value[`${SIGNALDESK_COLLECTIONS.SENDER_DOMAINS}DocId`] === LEGACY_PENDING_SENDER_DOMAIN_ID
    && value.senderDomainId === LEGACY_PENDING_SENDER_DOMAIN_ID
    && value.pId === SIGNALDESK_PRODUCT_CODE
    && value.domain === "pending"
    && value.status === "hold"
    && value.provider === null
    && value.authenticationState === "missing"
    && value.volumeRampState === "not_started"
    && value.bounceRate === 0
    && value.complaintRate === 0
    && value.unsubscribeReady === false
    && value.brandRisk === "medium"
    && Boolean(toIso(value.createdAt))
    && Boolean(toIso(value.updatedAt))
    && Boolean(normalizeText(value.updatedBy))
);

const readSenderDomains = async (db: any) => {
    const rows: AnyRecord[] = [];
    let cursor: FirebaseFirestore.QueryDocumentSnapshot | null = null;
    let exhausted = false;
    for (let page = 0; page < SENDER_DOMAIN_SCAN_MAX_PAGES; page += 1) {
        let query = db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS)
            .orderBy(admin.firestore.FieldPath.documentId())
            .limit(LIST_LIMIT);
        if (cursor) query = query.startAfter(cursor);
        const snap = await query.get();
        rows.push(...snap.docs.map((doc: any) => ({
            ...toPlain(doc.data()),
            [`${SIGNALDESK_COLLECTIONS.SENDER_DOMAINS}DocId`]: doc.id,
        })));
        if (snap.size < LIST_LIMIT) {
            exhausted = true;
            break;
        }
        cursor = snap.docs[snap.docs.length - 1] || null;
    }
    const senderRows = rows.filter((row) => !isLegacyPendingSenderSentinel(row));
    const projected = senderRows.map(projectSignalDeskSenderDomain);
    const invalidCount = projected.filter((sender) => !sender).length;
    if (invalidCount) {
        logRuntimeFailure("signaldesk_sender_domain_shape_invalid", new Error("signaldesk_sender_domain_shape_invalid"), {
            invalidCount,
            product: "signaldesk",
        });
    }
    if (!exhausted) {
        logRuntimeFailure("signaldesk_sender_domain_scan_limit_exceeded", new Error("signaldesk_sender_domain_scan_limit_exceeded"), {
            product: "signaldesk",
            scannedCount: rows.length,
        });
    }
    return projected
        .filter((sender): sender is SignalDeskSenderDomainSummary => Boolean(sender))
        .sort((left, right) => (
            (Date.parse(right.updatedAt || "") - Date.parse(left.updatedAt || ""))
            || left.senderDomainId.localeCompare(right.senderDomainId)
        ))
        .slice(0, LIST_LIMIT);
};

