const readSignalDeskCtaAuthority = async (
    db: FirebaseFirestore.Firestore,
    transaction: FirebaseFirestore.Transaction,
    input: {
        ctaId?: string | null;
        existingSnap?: FirebaseFirestore.DocumentSnapshot | null;
        requireActive?: boolean;
        useAuthoritativePreview?: boolean;
    } = {},
) => {
    const ctaId = normalizeText(input.ctaId) || SIGNALDESK_AUTHORITATIVE_PREVIEW_CTA_ID;
    const useAuthoritativePreview = input.useAuthoritativePreview === true
        || !input.ctaId
        || ctaId === SIGNALDESK_AUTHORITATIVE_PREVIEW_CTA_ID;
    if (useAuthoritativePreview && ctaId !== SIGNALDESK_AUTHORITATIVE_PREVIEW_CTA_ID) {
        throw new Error("CONTENT_CTA_DEFAULT_IDENTITY_INVALID");
    }
    const ctaRef = db.collection(SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS).doc(ctaId);
    const activePreviewQuery = useAuthoritativePreview
        ? db.collection(SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS)
            .where("ctaType", "==", "preview")
            .where("status", "==", "active")
            .limit(3)
        : null;
    const [ctaSnap, activePreviewSnap] = await Promise.all([
        input.existingSnap || transaction.get(ctaRef),
        activePreviewQuery ? transaction.get(activePreviewQuery) : Promise.resolve(null),
    ]);
    if (activePreviewSnap) {
        const activeRows = activePreviewSnap.docs.map((doc) => {
            if (normalizeText(doc.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
                throw new Error("CONTENT_CTA_PRODUCT_MISMATCH");
            }
            if (doc.data()?.dependentHoldReconciliationPending === true) {
                throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
            }
            const projected = projectSignalDeskSelfServiceCta({
                ...toPlain(doc.data()),
                [`${SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS}DocId`]: doc.id,
            });
            if (!projected) throw new Error("CONTENT_CTA_SHAPE_INVALID");
            return projected;
        });
        if (activeRows.length > 1) throw new Error("CONTENT_CTA_ACTIVE_AMBIGUOUS");
        if (activeRows[0] && activeRows[0].ctaId !== SIGNALDESK_AUTHORITATIVE_PREVIEW_CTA_ID) {
            throw new Error("CONTENT_CTA_LEGACY_IDENTITY_CONFLICT");
        }
    }
    if (!ctaSnap.exists) throw new Error("CONTENT_CTA_NOT_FOUND");
    if (normalizeText(ctaSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
        throw new Error("CONTENT_CTA_PRODUCT_MISMATCH");
    }
    if (ctaSnap.data()?.dependentHoldReconciliationPending === true) {
        throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
    }
    const cta = projectSignalDeskSelfServiceCta({
        ...toPlain(ctaSnap.data()),
        [`${SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS}DocId`]: ctaRef.id,
    });
    if (!cta) throw new Error("CONTENT_CTA_SHAPE_INVALID");
    if (cta.ctaType === "preview" && cta.ctaId !== SIGNALDESK_AUTHORITATIVE_PREVIEW_CTA_ID) {
        throw new Error("CONTENT_CTA_LEGACY_IDENTITY_CONFLICT");
    }
    if (input.requireActive !== false && cta.status !== "active") throw new Error("CONTENT_CTA_NOT_ACTIVE");
    return { cta, ctaFingerprintHash: signalDeskCtaFingerprintHash(cta), ctaRef };
};

const assertSignalDeskCtaLineage = async (
    db: FirebaseFirestore.Firestore,
    transaction: FirebaseFirestore.Transaction,
    lineage: { ctaFingerprintHash?: string | null; ctaId?: string | null },
) => {
    const ctaId = normalizeText(lineage.ctaId);
    const ctaFingerprintHash = normalizeText(lineage.ctaFingerprintHash);
    if (!ctaId || !ctaFingerprintHash) throw new Error("CONTENT_CTA_LINEAGE_REQUIRED");
    const authority = await readSignalDeskCtaAuthority(db, transaction, {
        ctaId,
        requireActive: true,
        useAuthoritativePreview: ctaId === SIGNALDESK_AUTHORITATIVE_PREVIEW_CTA_ID,
    });
    if (authority.ctaFingerprintHash !== ctaFingerprintHash) throw new Error("CONTENT_CTA_STALE");
    return authority;
};

const projectSignalDeskMarketPod = (value: AnyRecord): SignalDeskMarketPodSummary | null => {
    const docId = normalizeText(value[`${SIGNALDESK_COLLECTIONS.MARKET_PODS}DocId`]);
    const storedId = normalizeText(value.marketPodId);
    const marketPodId = docId || storedId;
    const name = normalizeText(value.name);
    const status = normalizeText(value.status) as SignalDeskControlStatus;
    const offerAngle = normalizeText(value.offerAngle);
    const successMetric = normalizeText(value.successMetric);
    const confidence = normalizeText(value.confidence) as SignalDeskConfidence || null;
    const recommendation = normalizeText(value.recommendation) as SignalDeskMarketPodSummary["recommendation"] || null;
    const reviewDecision = normalizeText(value.reviewDecision) as SignalDeskMarketPodSummary["reviewDecision"] || null;
    const approvedAt = toIso(value.approvedAt);
    const reviewedAt = toIso(value.reviewedAt);
    const updatedAt = toIso(value.updatedAt);
    const optionalTextFields = [value.city, value.country, value.category, value.recommendationReason, value.reviewReason];
    if (
        normalizeText(value.pId) !== SIGNALDESK_PRODUCT_CODE
        || !marketPodId
        || marketPodId.length > 180
        || (docId && storedId && docId !== storedId)
        || name.length < 2
        || name.length > 180
        || !CONTENT_SOURCE_STATUSES.has(status)
        || offerAngle.length < 2
        || offerAngle.length > 500
        || successMetric.length < 2
        || successMetric.length > 180
        || !Number.isFinite(value.monthlyBudgetUsd)
        || value.monthlyBudgetUsd < 0
        || value.monthlyBudgetUsd > 10000000
        || (confidence != null && !SIGNALDESK_CONFIDENCE_VALUES.has(confidence))
        || (recommendation != null && !MARKET_POD_RECOMMENDATIONS.has(recommendation))
        || (reviewDecision != null && !MARKET_POD_REVIEW_DECISIONS.has(reviewDecision))
        || optionalTextFields.some((field) => field != null && (typeof field !== "string" || field.trim().length > 500))
        || (value.approvedBy != null && (typeof value.approvedBy !== "string" || !value.approvedBy.trim() || value.approvedBy.trim().length > 180))
        || (value.reviewedBy != null && (typeof value.reviewedBy !== "string" || !value.reviewedBy.trim() || value.reviewedBy.trim().length > 180))
        || (value.approvedAt != null && !approvedAt)
        || (value.reviewedAt != null && !reviewedAt)
        || (value.updatedAt != null && !updatedAt)
        || !Array.isArray(value.recommendedActions || [])
        || (value.recommendedActions || []).length > 10
        || !(value.recommendedActions || []).every((action: unknown) => typeof action === "string" && action.trim().length >= 2 && action.trim().length <= 240)
        || (status === "active" && (reviewDecision !== "approved" || !normalizeText(value.approvedBy)))
        || (reviewDecision === "approved" && (!normalizeText(value.approvedBy) || !approvedAt))
        || (reviewDecision === "rejected" && status !== "blocked")
    ) return null;
    return {
        approvedAt,
        approvedBy: normalizeText(value.approvedBy) || null,
        category: normalizeText(value.category) || null,
        city: normalizeText(value.city) || null,
        confidence,
        country: normalizeText(value.country) || null,
        marketPodId,
        monthlyBudgetUsd: value.monthlyBudgetUsd,
        name,
        offerAngle,
        recommendation,
        recommendationReason: normalizeText(value.recommendationReason) || null,
        recommendedActions: (value.recommendedActions || []).map((action: string) => action.trim()),
        reviewDecision,
        reviewedAt,
        reviewedBy: normalizeText(value.reviewedBy) || null,
        reviewReason: normalizeText(value.reviewReason) || null,
        status,
        successMetric,
        updatedAt,
    };
};

