const projectSignalDeskGrowthMission = (value: AnyRecord): SignalDeskGrowthMissionSummary | null => {
    const docId = normalizeText(value[`${SIGNALDESK_COLLECTIONS.GROWTH_MISSIONS}DocId`]);
    const storedId = normalizeText(value.growthMissionId);
    const growthMissionId = docId || storedId;
    const day = normalizeText(value.day);
    const title = normalizeText(value.title);
    const summary = normalizeText(value.summary);
    const expectedOutcome = normalizeText(value.expectedOutcome);
    const recommendedMarketPodId = normalizeText(value.recommendedMarketPodId) || null;
    const ownerDecision = normalizeText(value.ownerDecision) as SignalDeskGrowthMissionSummary["ownerDecision"];
    const status = normalizeText(value.status) as SignalDeskGrowthMissionSummary["status"];
    const ownerDecisionNote = normalizeText(value.ownerDecisionNote) || null;
    const createdAt = toIso(value.createdAt);
    const updatedAt = toIso(value.updatedAt);
    if (
        normalizeText(value.pId) !== SIGNALDESK_PRODUCT_CODE
        || !growthMissionId
        || growthMissionId.length > 180
        || (docId && storedId && docId !== storedId)
        || !isValidIsoDay(day)
        || growthMissionId !== growthMissionIdFor(day)
        || title.length < 2
        || title.length > 180
        || summary.length < 10
        || summary.length > 1200
        || expectedOutcome.length < 10
        || expectedOutcome.length > 600
        || (recommendedMarketPodId?.length || 0) > 160
        || !GROWTH_MISSION_OWNER_DECISIONS.has(ownerDecision)
        || !GROWTH_MISSION_STATUSES.has(status)
        || (ownerDecisionNote != null && ownerDecisionNote.length > 800)
        || !createdAt
        || !updatedAt
        || new Date(updatedAt).getTime() < new Date(createdAt).getTime()
        || !Number.isInteger(value.approvalActionCount)
        || value.approvalActionCount < 0
        || !Number.isInteger(value.blockedActionCount)
        || value.blockedActionCount < 0
        || !Array.isArray(value.missionActions)
        || value.missionActions.length < 1
        || value.missionActions.length > 5
        || (ownerDecision === "pending" && status !== "draft" && status !== "ready")
        || (ownerDecision !== "pending" && status !== growthMissionStatusForDecision(ownerDecision))
        || (ownerDecision === "pending" && ownerDecisionNote !== null)
    ) return null;

    const expectedActionStatus = growthMissionActionStatusForDecision(ownerDecision);
    const missionActions = value.missionActions.map((rawAction: unknown, index: number) => {
        if (!rawAction || typeof rawAction !== "object" || Array.isArray(rawAction)) return null;
        const action = rawAction as AnyRecord;
        const rank = index + 1;
        const actionId = normalizeText(action.actionId);
        const actionType = normalizeText(action.actionType) as SignalDeskGrowthMissionSummary["missionActions"][number]["actionType"];
        const entityId = normalizeText(action.entityId) || null;
        const normalizedEntityType = normalizeText(action.entityType);
        const entityType = normalizedEntityType
            ? normalizedEntityType as NonNullable<SignalDeskGrowthMissionSummary["missionActions"][number]["entityType"]>
            : null;
        const actionExpectedOutcome = normalizeText(action.expectedOutcome);
        const label = normalizeText(action.label);
        const reason = normalizeText(action.reason);
        const riskLevel = normalizeText(action.riskLevel) as SignalDeskConfidence;
        const actionStatus = normalizeText(action.status) as SignalDeskGrowthMissionSummary["missionActions"][number]["status"];
        if (
            actionId !== `mission_${day}_${rank}`
            || action.rank !== rank
            || !GROWTH_MISSION_ACTION_TYPES.has(actionType)
            || (entityId?.length || 0) > 180
            || (entityType !== null && !GROWTH_MISSION_ACTION_ENTITY_TYPES.has(entityType))
            || actionExpectedOutcome.length < 10
            || actionExpectedOutcome.length > 600
            || label.length < 2
            || label.length > 240
            || reason.length < 1
            || reason.length > 1000
            || !SIGNALDESK_CONFIDENCE_VALUES.has(riskLevel)
            || !GROWTH_MISSION_ACTION_STATUSES.has(actionStatus)
            || actionStatus !== expectedActionStatus
        ) return null;
        return {
            actionId,
            actionType,
            entityId,
            entityType,
            expectedOutcome: actionExpectedOutcome,
            label,
            rank,
            reason,
            riskLevel,
            status: actionStatus,
        } satisfies SignalDeskGrowthMissionSummary["missionActions"][number];
    });
    if (missionActions.some((action: SignalDeskGrowthMissionSummary["missionActions"][number] | null) => !action)) return null;
    const projectedActions = missionActions as SignalDeskGrowthMissionSummary["missionActions"];
    if (
        value.approvalActionCount !== projectedActions.filter((action) => action.actionType === "approve").length
        || value.blockedActionCount !== projectedActions.filter((action) => action.riskLevel === "high" || action.actionType === "hold").length
    ) return null;
    return {
        approvalActionCount: value.approvalActionCount,
        blockedActionCount: value.blockedActionCount,
        createdAt,
        day,
        expectedOutcome,
        growthMissionId,
        missionActions: projectedActions,
        ownerDecision,
        ownerDecisionNote,
        recommendedMarketPodId,
        status,
        summary,
        title,
        updatedAt,
    };
};

