const projectSignalDeskContentPerformance = (value: AnyRecord): SignalDeskContentPerformanceSummary | null => {
    const docId = normalizeText(value[`${SIGNALDESK_COLLECTIONS.CONTENT_PERFORMANCE_SUMMARIES}DocId`]);
    const storedId = normalizeText(value.contentPerformanceId);
    const contentPerformanceId = docId || storedId;
    const contentAssetId = normalizeText(value.contentAssetId);
    const contentDraftId = normalizeText(value.contentDraftId) || null;
    const channel = normalizeText(value.channel) as SignalDeskContentChannel;
    const engagementQuality = normalizeText(value.engagementQuality) as SignalDeskConfidence;
    const publishedAt = toIso(value.publishedAt);
    const capturedAt = toIso(value.capturedAt);
    let publicationUrl: string | null;
    try {
        if (value.publicationUrl != null && typeof value.publicationUrl !== "string") return null;
        publicationUrl = canonicalizeContentUrl(value.publicationUrl || null);
    } catch {
        return null;
    }
    const countFields = [
        [value.views, 100000000],
        [value.clicks, 100000000],
        [value.ownerLeads, 100000],
        [value.currentListSubmissions, 100000],
        [value.activations, 100000],
    ] as const;
    const observedMetricCount = countFields.reduce((sum, [count]) => sum + (Number.isInteger(count) ? count : 0), 0);
    const capturedAtMillis = capturedAt ? new Date(capturedAt).getTime() : Number.NaN;
    const publishedAtMillis = publishedAt ? new Date(publishedAt).getTime() : null;
    if (
        normalizeText(value.pId) !== SIGNALDESK_PRODUCT_CODE
        || !contentPerformanceId
        || contentPerformanceId.length > 180
        || (docId && storedId && docId !== storedId)
        || !contentAssetId
        || contentAssetId.length > 180
        || (contentDraftId?.length || 0) > 180
        || !CONTENT_CHANNELS.has(channel)
        || !SIGNALDESK_CONFIDENCE_VALUES.has(engagementQuality)
        || countFields.some(([count, maximum]) => !Number.isInteger(count) || count < 0 || count > maximum)
        || !capturedAt
        || (value.publishedAt != null && !publishedAt)
        || capturedAtMillis > Date.now() + CONTENT_PUBLICATION_FUTURE_SKEW_MS
        || Boolean(publicationUrl) !== Boolean(publishedAt)
        || (Boolean(publicationUrl) && !contentDraftId)
        || (observedMetricCount > 0 && (!publicationUrl || !publishedAt || !contentDraftId))
        || (publishedAtMillis != null && publishedAtMillis > capturedAtMillis + CONTENT_PUBLICATION_FUTURE_SKEW_MS)
        || (value.contractVersion != null && value.contractVersion !== 2)
    ) return null;
    return {
        activations: value.activations,
        capturedAt,
        channel,
        clicks: value.clicks,
        contentAssetId,
        contentDraftId,
        contentPerformanceId,
        currentListSubmissions: value.currentListSubmissions,
        engagementQuality,
        ownerLeads: value.ownerLeads,
        publicationUrl,
        publishedAt,
        views: value.views,
    };
};

