const SIGNALDESK_OWNED_EMAIL_SEND_COST_USD = 0.01;

const reserveSignalDeskOwnedEmailSenderCapacity = async (
    db: FirebaseFirestore.Firestore,
    transaction: FirebaseFirestore.Transaction,
    timestamp: FirebaseFirestore.Timestamp,
) => {
    const accountRef = db.collection(SIGNALDESK_COLLECTIONS.PROVIDER_ACCOUNTS)
        .doc(providerAccountIdFor("owned-email", "sender"));
    const budgetRef = db.collection(SIGNALDESK_COLLECTIONS.BUDGET_POLICIES)
        .doc(budgetPolicyIdFor("provider", "owned-email"));
    const [accountSnap, budgetSnap] = await Promise.all([
        transaction.get(accountRef),
        transaction.get(budgetRef),
    ]);
    const spendPeriod = getSignalDeskSpendPeriod(timestamp.toMillis());
    const account = accountSnap.exists
        ? parseSignalDeskProviderAccountDocument(accountSnap.data(), accountRef.id, spendPeriod)
        : null;
    const budget = budgetSnap.exists
        ? parseSignalDeskBudgetPolicyDocument(budgetSnap.data(), budgetRef.id, spendPeriod)
        : null;
    assertProviderBudgetState(account, budget, { estimatedCostUsd: SIGNALDESK_OWNED_EMAIL_SEND_COST_USD });
    if (!account) throw new Error("SIGNALDESK_PROVIDER_ACCOUNT_MISSING");
    transaction.set(accountRef, sanitizeForFirestore(buildSignalDeskSpendMutation({
        amountUsd: SIGNALDESK_OWNED_EMAIL_SEND_COST_USD,
        authority: account,
        currentPeriod: spendPeriod,
        updatedAt: timestamp,
    })), { merge: true });
    if (budget) {
        transaction.set(budgetRef, sanitizeForFirestore(buildSignalDeskSpendMutation({
            amountUsd: SIGNALDESK_OWNED_EMAIL_SEND_COST_USD,
            authority: budget,
            currentPeriod: spendPeriod,
            updatedAt: timestamp,
        })), { merge: true });
    }
    return {
        accountingDay: spendPeriod.spendDayKey,
        accountingMonth: spendPeriod.spendMonthKey,
        reservedAt: timestamp,
        reservedBudgetPolicy: Boolean(budget),
        reservedCostUsd: SIGNALDESK_OWNED_EMAIL_SEND_COST_USD,
    };
};

const markSignalDeskClaimUnresolved = async (params: {
    access: SignalDeskAccessContext;
    action: string;
    claimId: string;
    claimRef: FirebaseFirestore.DocumentReference;
    db: FirebaseFirestore.Firestore;
    entityId: string;
    entityType: string;
    failureCode: string;
    requestFingerprintHash: string;
}) => {
    await params.db.runTransaction(async (transaction) => {
        const claimSnap = await transaction.get(params.claimRef);
        const claim = claimSnap.exists ? claimSnap.data() as AnyRecord : null;
        if (
            claim?.status !== "in_progress"
            || claim?.claimId !== params.claimId
            || claim?.requestFingerprintHash !== params.requestFingerprintHash
        ) return;
        const failedAt = now();
        transaction.set(params.claimRef, sanitizeForFirestore({
            failedAt,
            failureCode: params.failureCode,
            status: "unresolved",
            updatedAt: failedAt,
        }), { merge: true });
        appendAudit(
            params.db,
            transaction,
            params.access,
            params.action,
            params.entityType,
            params.entityId,
            params.failureCode,
        );
    });
};

const targetPriorGuard = (target: SignalDeskTargetSummary, conversation?: AnyRecord | null) => {
    const reasons: string[] = [];
    if (target.suppressionStatus !== "clear") reasons.push(`Suppression is ${target.suppressionStatus}.`);
    if (target.status === "contacted" || target.status === "replied" || target.status === "converted") {
        reasons.push(`Target status is ${target.status}.`);
    }
    if (target.latestOutcomeAt) reasons.push("Target already has a MenuList outcome.");
    if (conversation?.state && conversation.state !== "new") {
        reasons.push(`Conversation state is ${conversation.state}.`);
    }
    return {
        clear: reasons.length === 0,
        reasons,
    };
};

const readTargetPriorGuard = async (db: any, target: SignalDeskTargetSummary) => {
    const conversationSnap = target.latestConversationId
        ? await db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES).doc(target.latestConversationId).get()
        : null;
    return targetPriorGuard(target, conversationSnap?.exists ? conversationSnap.data() as AnyRecord : null);
};

const requireNoPriorSpendBlock = async (db: any, target: SignalDeskTargetSummary) => {
    const guard = await readTargetPriorGuard(db, target);
    if (!guard.clear) throw new Error("Target has prior contact or outcome");
    return guard;
};

