const proofPermissionIdFor = (targetId: string) => (
    `proof_permission_${hashValue(targetId).slice(0, 22)}`
);

const PUBLIC_PROOF_SCOPES = new Set<SignalDeskProofPermissionScope>([
    "business-name",
    "logo",
    "quotation",
    "before-after-screenshots",
    "public-case-study",
    "partner-material",
]);

const isProofPermissionActive = (permission?: SignalDeskProofPermissionSummary | null) => {
    if (!permission || permission.status !== "active") return false;
    const grantedAt = toTimestampMillis(permission.grantedAt);
    if (!grantedAt || grantedAt > Date.now() + CONTENT_PUBLICATION_FUTURE_SKEW_MS) return false;
    const expiresAt = toTimestampMillis(permission.expiresAt);
    if (permission.expiresAt != null && !expiresAt) return false;
    if (expiresAt && expiresAt <= Date.now()) return false;
    return true;
};

const isProofPermissionUsable = (
    permission?: SignalDeskProofPermissionSummary | null,
    requiredScopes: SignalDeskProofPermissionScope[] = [],
) => {
    if (!permission || !isProofPermissionActive(permission)) return false;
    const requestedScopes = Array.from(new Set(requiredScopes));
    if (!requestedScopes.length) return false;
    const grantedScopes = new Set(permission.scopes);
    return requestedScopes.every((scope) => PUBLIC_PROOF_SCOPES.has(scope) && grantedScopes.has(scope));
};

const readSignalDeskContentAssetAuthority = async (
    db: FirebaseFirestore.Firestore,
    transaction: FirebaseFirestore.Transaction,
    assetRef: FirebaseFirestore.DocumentReference,
    existingAssetSnap?: FirebaseFirestore.DocumentSnapshot | null,
    requireReady = true,
) => {
    const assetSnap = existingAssetSnap || await transaction.get(assetRef);
    if (!assetSnap.exists) throw new Error("Content asset not found");
    if (assetSnap.data()?.dependentHoldReconciliationPending === true) {
        throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
    }
    if (requireReady && assetSnap.data()?.publicationReviewRequired === true) {
        throw new Error("CONTENT_ASSET_PUBLICATION_REVIEW_REQUIRED");
    }
    const asset = projectSignalDeskContentAsset({
        ...toPlain(assetSnap.data()),
        [`${SIGNALDESK_COLLECTIONS.CONTENT_ASSETS}DocId`]: assetRef.id,
    });
    if (!asset) throw new Error("CONTENT_ASSET_SHAPE_INVALID");
    if (requireReady && asset.status !== "ready" && asset.status !== "distributed") throw new Error("Content asset is not ready");
    if (requireReady && (asset.proofLevel === "internal-note" || asset.riskNotes.length > 0)) {
        throw new Error("CONTENT_ASSET_READINESS_BLOCKED");
    }
    const sourceRef = asset.sourceId ? db.collection(SIGNALDESK_COLLECTIONS.CONTENT_SOURCES).doc(asset.sourceId) : null;
    const permissionRef = asset.proofLevel === "customer-proof" && asset.proofPermissionId
        ? db.collection(SIGNALDESK_COLLECTIONS.PROOF_PERMISSIONS).doc(asset.proofPermissionId)
        : null;
    const ctaRef = asset.ctaId ? db.collection(SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS).doc(asset.ctaId) : null;
    const marketPodRef = asset.marketPodId ? db.collection(SIGNALDESK_COLLECTIONS.MARKET_PODS).doc(asset.marketPodId) : null;
    const [sourceSnap, permissionSnap, ctaSnap, marketPodSnap] = await Promise.all([
        sourceRef ? transaction.get(sourceRef) : Promise.resolve(null),
        permissionRef ? transaction.get(permissionRef) : Promise.resolve(null),
        ctaRef ? transaction.get(ctaRef) : Promise.resolve(null),
        marketPodRef ? transaction.get(marketPodRef) : Promise.resolve(null),
    ]);
    let source: SignalDeskContentSourceSummary | null = null;
    if (sourceRef) {
        if (!sourceSnap?.exists) throw new Error("Content source not found");
        if (sourceSnap.data()?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        source = projectSignalDeskContentSource({
            ...toPlain(sourceSnap.data()),
            [`${SIGNALDESK_COLLECTIONS.CONTENT_SOURCES}DocId`]: sourceRef.id,
        });
        if (!source) throw new Error("CONTENT_SOURCE_SHAPE_INVALID");
        if (source.status !== "active") throw new Error("Content source is not active");
        if (
            source.sourceType !== asset.sourceType
            || source.sourceUrl !== asset.sourceUrl
            || source.defaultAudience !== asset.primaryAudience
            || (source.defaultMarketPodId || null) !== (asset.marketPodId || null)
        ) throw new Error("CONTENT_ASSET_PROVENANCE_INVALID");
    }
    const permission = permissionSnap?.exists && permissionRef
        ? projectSignalDeskProofPermission({
            ...toPlain(permissionSnap.data()),
            [`${SIGNALDESK_COLLECTIONS.PROOF_PERMISSIONS}DocId`]: permissionRef.id,
        })
        : null;
    if (permissionSnap?.data()?.dependentHoldReconciliationPending === true) {
        throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
    }
    if (asset.proofLevel === "customer-proof" && !isProofPermissionActive(permission)) throw new Error("PROOF_PERMISSION_REQUIRED");
    if (asset.proofLevel === "customer-proof" && !isProofPermissionUsable(permission, asset.proofScopes || [])) throw new Error("PROOF_PERMISSION_SCOPE_NOT_ALLOWED");
    let cta: SignalDeskSelfServiceCtaSummary | null = null;
    if (requireReady && !ctaRef) throw new Error("CONTENT_ASSET_ACTIVE_CTA_REQUIRED");
    if (ctaRef) {
        cta = (await readSignalDeskCtaAuthority(db, transaction, {
            ctaId: ctaRef.id,
            existingSnap: ctaSnap,
            requireActive: true,
        })).cta;
    }
    if (marketPodRef) {
        if (!marketPodSnap?.exists) throw new Error("Market pod not found");
        if (marketPodSnap.data()?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        const marketPod = marketPodSnap.data() as AnyRecord;
        if (
            normalizeText(marketPod.pId) !== SIGNALDESK_PRODUCT_CODE
            || marketPod.status !== "active"
            || marketPod.reviewDecision !== "approved"
            || !normalizeText(marketPod.approvedBy)
        ) throw new Error("Market pod is not founder-approved");
    }
    return { asset, cta, permission, source };
};

const readSignalDeskContentDraftAuthority = async (
    db: FirebaseFirestore.Firestore,
    transaction: FirebaseFirestore.Transaction,
    draftRef: FirebaseFirestore.DocumentReference,
    existingDraftSnap?: FirebaseFirestore.DocumentSnapshot | null,
) => {
    const draftSnap = existingDraftSnap || await transaction.get(draftRef);
    if (!draftSnap.exists) throw new Error("Content draft not found");
    const draft = projectSignalDeskContentDraft({
        ...toPlain(draftSnap.data()),
        [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: draftRef.id,
    });
    if (!draft) throw new Error("CONTENT_DRAFT_SHAPE_INVALID");
    const assetRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_ASSETS).doc(draft.contentAssetId);
    const authority = await readSignalDeskContentAssetAuthority(db, transaction, assetRef);
    if (authority.asset.ctaId && draft.ctaId !== authority.asset.ctaId) throw new Error("CONTENT_ASSET_PROVENANCE_INVALID");
    let currentCta = draft.ctaId === authority.asset.ctaId ? authority.cta : null;
    if (draft.ctaId && draft.ctaId !== authority.asset.ctaId) {
        currentCta = (await readSignalDeskCtaAuthority(db, transaction, {
            ctaId: draft.ctaId,
            requireActive: true,
        })).cta;
    }
    const currentCtaFingerprintHash = currentCta
        ? signalDeskCtaFingerprintHash(currentCta)
        : null;
    if ((draft.ctaId || null) !== (currentCta?.ctaId || null) || (draft.ctaFingerprintHash || null) !== currentCtaFingerprintHash) {
        throw new Error("CONTENT_DRAFT_CTA_STALE");
    }
    return { ...authority, draft };
};

const readSignalDeskOfferNestedAuthority = async (
    db: FirebaseFirestore.Firestore,
    transaction: FirebaseFirestore.Transaction,
    offer: SignalDeskOfferCtaSummary,
    requireActive = false,
) => {
    if (requireActive && (!offer.ctaId || !offer.marketPodId)) {
        throw new Error("OFFER_CTA_ACTIVE_AUTHORITY_REQUIRED");
    }
    const ctaRef = offer.ctaId
        ? db.collection(SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS).doc(offer.ctaId)
        : null;
    const marketPodRef = offer.marketPodId
        ? db.collection(SIGNALDESK_COLLECTIONS.MARKET_PODS).doc(offer.marketPodId)
        : null;
    const [ctaSnap, marketPodSnap] = await Promise.all([
        ctaRef ? transaction.get(ctaRef) : Promise.resolve(null),
        marketPodRef ? transaction.get(marketPodRef) : Promise.resolve(null),
    ]);
    let cta: SignalDeskSelfServiceCtaSummary | null = null;
    if (ctaRef) {
        if (!ctaSnap?.exists) throw new Error("Offer CTA self-service CTA not found");
        if (ctaSnap.data()?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        cta = projectSignalDeskSelfServiceCta({
            ...toPlain(ctaSnap.data()),
            [`${SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS}DocId`]: ctaRef.id,
        });
        if (!cta) throw new Error("OFFER_CTA_SELF_SERVICE_CTA_SHAPE_INVALID");
        if (requireActive && cta.status !== "active") throw new Error("Offer CTA self-service CTA is not active");
    }
    let marketPod: SignalDeskMarketPodSummary | null = null;
    if (marketPodRef) {
        if (!marketPodSnap?.exists) throw new Error("Offer CTA market pod not found");
        if (marketPodSnap.data()?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        marketPod = projectSignalDeskMarketPod({
            ...toPlain(marketPodSnap.data()),
            [`${SIGNALDESK_COLLECTIONS.MARKET_PODS}DocId`]: marketPodRef.id,
        });
        if (!marketPod) throw new Error("OFFER_CTA_MARKET_POD_SHAPE_INVALID");
        if (
            requireActive
            && (marketPod.status !== "active" || marketPod.reviewDecision !== "approved" || !marketPod.approvedBy)
        ) throw new Error("Offer CTA market pod is not founder-approved");
    }
    return { cta, marketPod };
};

const readSignalDeskOfferAuthority = async (
    db: FirebaseFirestore.Firestore,
    transaction: FirebaseFirestore.Transaction,
    offerRef: FirebaseFirestore.DocumentReference,
    existingOfferSnap?: FirebaseFirestore.DocumentSnapshot | null,
    requireActive = false,
) => {
    const offerSnap = existingOfferSnap || await transaction.get(offerRef);
    if (!offerSnap.exists) throw new Error("Offer CTA not found");
    if (normalizeText(offerSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
        throw new Error("OFFER_CTA_PRODUCT_MISMATCH");
    }
    if (offerSnap.data()?.dependentHoldReconciliationPending === true) {
        throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
    }
    const offer = projectSignalDeskOfferCta({
        ...toPlain(offerSnap.data()),
        [`${SIGNALDESK_COLLECTIONS.OFFER_CTAS}DocId`]: offerRef.id,
    });
    if (!offer) throw new Error("OFFER_CTA_SHAPE_INVALID");
    if (requireActive && offer.status !== "active") throw new Error("Offer CTA is not active");
    const nestedAuthority = await readSignalDeskOfferNestedAuthority(db, transaction, offer, requireActive);
    return { offer, ...nestedAuthority };
};

const readSignalDeskExperimentAuthority = async (
    db: FirebaseFirestore.Firestore,
    transaction: FirebaseFirestore.Transaction,
    experiment: SignalDeskExperimentCardSummary,
    requireActiveControls: boolean,
) => {
    if (
        requireActiveControls
        && (!experiment.marketPodId || !experiment.sourcePolicyId || !experiment.ctaId)
    ) throw new Error("EXPERIMENT_ACTIVE_AUTHORITY_REQUIRED");
    const offerRef = experiment.ctaId
        ? db.collection(SIGNALDESK_COLLECTIONS.OFFER_CTAS).doc(experiment.ctaId)
        : null;
    const marketPodRef = experiment.marketPodId
        ? db.collection(SIGNALDESK_COLLECTIONS.MARKET_PODS).doc(experiment.marketPodId)
        : null;
    const sourcePolicyRef = experiment.sourcePolicyId
        ? db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(experiment.sourcePolicyId)
        : null;
    const contentAssetRef = experiment.contentAssetId
        ? db.collection(SIGNALDESK_COLLECTIONS.CONTENT_ASSETS).doc(experiment.contentAssetId)
        : null;
    const contentPauseRef = requireActiveControls && (experiment.channel === "content" || contentAssetRef)
        ? db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_content-distribution")
        : null;
    const [offerSnap, marketPodSnap, sourcePolicySnap, contentAssetSnap, contentPauseSnap] = await Promise.all([
        offerRef ? transaction.get(offerRef) : Promise.resolve(null),
        marketPodRef ? transaction.get(marketPodRef) : Promise.resolve(null),
        sourcePolicyRef ? transaction.get(sourcePolicyRef) : Promise.resolve(null),
        contentAssetRef ? transaction.get(contentAssetRef) : Promise.resolve(null),
        contentPauseRef ? transaction.get(contentPauseRef) : Promise.resolve(null),
    ]);
    if (contentPauseSnap?.data()?.status === "active") throw new Error("Content distribution is paused");
    const offerAuthority = offerRef
        ? await readSignalDeskOfferAuthority(db, transaction, offerRef, offerSnap, requireActiveControls)
        : null;
    let marketPod: SignalDeskMarketPodSummary | null = null;
    if (marketPodRef) {
        if (!marketPodSnap?.exists) throw new Error("Experiment market pod not found");
        if (marketPodSnap.data()?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        marketPod = projectSignalDeskMarketPod({
            ...toPlain(marketPodSnap.data()),
            [`${SIGNALDESK_COLLECTIONS.MARKET_PODS}DocId`]: marketPodRef.id,
        });
        if (!marketPod) throw new Error("EXPERIMENT_MARKET_POD_SHAPE_INVALID");
        if (
            requireActiveControls
            && (marketPod.status !== "active" || marketPod.reviewDecision !== "approved" || !marketPod.approvedBy)
        ) throw new Error("Experiment market pod is not founder-approved");
    }
    let sourcePolicy: SignalDeskSourcePolicy | null = null;
    if (sourcePolicyRef) {
        if (!sourcePolicySnap?.exists) throw new Error("Experiment source policy not found");
        const sourcePolicyData = sourcePolicySnap.data() as AnyRecord;
        if (normalizeText(sourcePolicyData.pId) !== SIGNALDESK_PRODUCT_CODE) {
            throw new Error("EXPERIMENT_SOURCE_POLICY_PRODUCT_MISMATCH");
        }
        if (normalizeText(sourcePolicyData.sourcePolicyId) !== sourcePolicyRef.id) {
            throw new Error("EXPERIMENT_SOURCE_POLICY_IDENTITY_MISMATCH");
        }
        sourcePolicy = parseSignalDeskSourcePolicyDocument(sourcePolicyData, sourcePolicyRef.id);
        const sourcePolicyError = sourcePolicyUsabilityError(sourcePolicy, {
            entityId: sourcePolicyRef.id,
            use: "evidence",
        });
        if (sourcePolicyError) throw new Error(sourcePolicyError);
    }
    const contentAssetAuthority = contentAssetRef
        ? await readSignalDeskContentAssetAuthority(db, transaction, contentAssetRef, contentAssetSnap)
        : null;
    if (offerAuthority && (offerAuthority.offer.marketPodId || null) !== (experiment.marketPodId || null)) {
        throw new Error("EXPERIMENT_OFFER_MARKET_POD_MISMATCH");
    }
    if (contentAssetAuthority && (contentAssetAuthority.asset.marketPodId || null) !== (experiment.marketPodId || null)) {
        throw new Error("EXPERIMENT_ASSET_MARKET_POD_MISMATCH");
    }
    if (offerAuthority && contentAssetAuthority && (
        (offerAuthority.offer.ctaId || null) !== (contentAssetAuthority.asset.ctaId || null)
        || (offerAuthority.offer.marketPodId || null) !== (contentAssetAuthority.asset.marketPodId || null)
    )) throw new Error("EXPERIMENT_OFFER_ASSET_PROVENANCE_MISMATCH");
    return {
        asset: contentAssetAuthority?.asset || null,
        marketPod,
        offer: offerAuthority?.offer || null,
        sourcePolicy,
    };
};

const readProofPermission = async (db: any, proofPermissionId?: string | null): Promise<SignalDeskProofPermissionSummary | null> => {
    if (!proofPermissionId) return null;
    const snap = await db.collection(SIGNALDESK_COLLECTIONS.PROOF_PERMISSIONS).doc(proofPermissionId).get();
    return snap.exists ? projectSignalDeskProofPermission({
        ...toPlain(snap.data()),
        [`${SIGNALDESK_COLLECTIONS.PROOF_PERMISSIONS}DocId`]: snap.id,
    }) : null;
};

const contentChannelLabel = (channel: SignalDeskContentChannel) => {
    if (channel === "x") return "X";
    if (channel === "partner-brief") return "Partner brief";
    if (channel === "short-video") return "Short video";
    return channel.charAt(0).toUpperCase() + channel.slice(1);
};

const contentDraftIdFor = (contentAssetId: string, channel: SignalDeskContentChannel, revision = 1) => (
    revision === 1
        ? `content_draft_${hashValue(`${contentAssetId}|${channel}`).slice(0, 24)}`
        : `content_draft_${hashValue(`${contentAssetId}|${channel}|revision:${revision}`).slice(0, 24)}`
);

const contentCalendarItemIdFor = (contentDraftId: string) => `content_calendar_${contentDraftId}`;

const buildContentDraftCopy = (
    asset: SignalDeskContentAssetSummary,
    channel: SignalDeskContentChannel,
    cta: SignalDeskSelfServiceCtaSummary,
) => {
    const ctaCopy = cta.copy;
    const proof = asset.proofLevel === "customer-proof"
        ? "customer proof"
        : asset.proofLevel === "market-research"
            ? "market signal"
            : asset.proofLevel === "internal-note"
                ? "internal operating note"
                : "owned MenuList proof";
    const hook = channel === "email"
        ? `${asset.title}: a cleaner current-list path`
        : channel === "short-video"
            ? `Show the before and after: ${asset.title}`
            : `${asset.title} for restaurant owners`;
    const bodyByChannel: Record<SignalDeskContentChannel, string> = {
        blog: `${asset.canonicalMessage}\n\nUse this as a short internal blog outline backed by ${proof}. Close with: ${ctaCopy}`,
        email: `${asset.canonicalMessage}\n\nIf this is useful, ${ctaCopy}`,
        linkedin: `${asset.canonicalMessage}\n\nWhy it matters: owners need a current list customers can trust without extra admin.\n\n${ctaCopy}`,
        newsletter: `${asset.canonicalMessage}\n\nOperator note: keep the proof specific and avoid broad claims. Approved CTA: ${ctaCopy}`,
        other: `${asset.canonicalMessage}\n\nCTA: ${ctaCopy}`,
        "partner-brief": `Partner angle: explain ${asset.title} in your own voice. Use only this claim: ${asset.canonicalMessage}. Required CTA: ${ctaCopy}`,
        "short-video": `Opening shot: stale or hard-to-find menu.\nMiddle: current-list proof.\nClose: ${ctaCopy}`,
        x: `${asset.canonicalMessage}\n\n${ctaCopy}`,
    };
    return {
        body: bodyByChannel[channel],
        hook,
        title: `${contentChannelLabel(channel)}: ${asset.title}`,
    };
};

const clampScore = (value: number) => Math.max(0, Math.min(100, Math.round(numberOrZero(value))));

const computeTrustScore = (input: Pick<TrustPartnerProfileInput, "audienceFitScore" | "baselineReachScore" | "believableUsageScore" | "commentQualityScore" | "trustFeelScore">) => (
    Math.round((
        clampScore(input.audienceFitScore) +
        clampScore(input.baselineReachScore) +
        clampScore(input.believableUsageScore) +
        clampScore(input.commentQualityScore) +
        clampScore(input.trustFeelScore)
    ) / 5)
);

const channelWindowIdFor = (
    channel: SignalDeskChannelWindowStateSummary["channel"],
    targetId?: string | null,
) => `window_${channel}_${targetId || "global"}`;

const isChannelWindowEligible = (windowState: SignalDeskChannelWindowStateSummary | null) => {
    if (!windowState || !windowState.eligibleForHandoff || windowState.status !== "open") return false;
    if (!windowState.expiresAt) return true;
    return new Date(windowState.expiresAt).getTime() > Date.now();
};

const recommendationFromTrustOutcomes = (metrics: SignalDeskTrustPartnerMetricSummary[]): SignalDeskTrustPartnerRenewalDecisionSummary["recommendation"] => {
    const ownerLeads = metrics.reduce((sum, metric) => sum + numberOrZero(metric.ownerLeads), 0);
    const submissions = metrics.reduce((sum, metric) => sum + numberOrZero(metric.currentListSubmissions), 0);
    const activations = metrics.reduce((sum, metric) => sum + numberOrZero(metric.activations), 0);
    if (activations > 0 || submissions > 0) return "renew";
    if (ownerLeads > 0) return "retest";
    return "cut";
};

const computeLegacyTargetIdentity = (row: SignalDeskTargetImportRow, options: { includeContact: boolean }) => {
    const email = options.includeContact ? normalizeLower(row.email) : "";
    const phone = options.includeContact ? normalizeText(row.phone).replace(/[^\d+]/g, "") : "";
    const website = normalizeUrl(row.website);
    const base = [
        normalizeLower(row.displayName),
        normalizeLower(row.city),
        normalizeLower(row.country),
        email,
        phone,
        website,
    ].filter(Boolean).join("|");
    return hashValue(base || normalizeLower(row.displayName));
};

const canonicalTargetIdentityUrl = (value?: string | null) => {
    const normalized = normalizeText(value);
    if (!normalized) return "";
    try {
        const parsed = new URL(normalized);
        parsed.hash = "";
        return parsed.toString();
    } catch {
        return "";
    }
};

type TargetIdentityVersion = "legacy-business-v1" | "provider-record-v1" | "provider-url-v1" | "provider-business-v1";

const computeTargetIdentity = (
    row: SignalDeskTargetImportRow,
    options: { includeContact: boolean; provider?: string | null },
): {
    identityHash: string;
    identityVersion: TargetIdentityVersion;
    legacyIdentityHash: string;
    providerIdentityKey: string;
} => {
    const legacyIdentityHash = computeLegacyTargetIdentity(row, options);
    const provider = normalizeLower(options.provider);
    if (!provider) {
        return {
            identityHash: legacyIdentityHash,
            identityVersion: "legacy-business-v1" as const,
            legacyIdentityHash,
            providerIdentityKey: "",
        };
    }
    const providerRecordId = normalizeText(row.providerRecordId);
    const providerRecordUrl = canonicalTargetIdentityUrl(row.providerRecordUrl);
    const providerIdentityKey = providerRecordId
        ? `record-id:${providerRecordId}`
        : providerRecordUrl
            ? `record-url:${providerRecordUrl}`
            : "";
    const providerBusinessBasis = JSON.stringify({
        city: normalizeLower(row.city),
        country: normalizeLower(row.country),
        currentListUrl: canonicalTargetIdentityUrl(row.currentListUrl),
        displayName: normalizeLower(row.displayName),
        email: options.includeContact ? normalizeLower(row.email) : "",
        instagram: options.includeContact ? normalizeLower(row.instagram).replace(/^@/, "") : "",
        phone: options.includeContact ? normalizeText(row.phone).replace(/[^\d+]/g, "") : "",
        website: canonicalTargetIdentityUrl(row.website),
    });
    const identityVersion: TargetIdentityVersion = providerRecordId
        ? "provider-record-v1"
        : providerRecordUrl
            ? "provider-url-v1"
            : "provider-business-v1";
    return {
        identityHash: hashValue(`${identityVersion}|${provider}|${providerIdentityKey || providerBusinessBasis}`),
        identityVersion,
        legacyIdentityHash,
        providerIdentityKey,
    };
};

const classifyContactability = (row: SignalDeskTargetImportRow) => {
    if (normalizeText(row.email)) return "ready" as const;
    if (normalizeText(row.phone) || normalizeText(row.instagram) || normalizeText(row.website)) return "limited" as const;
    return "missing" as const;
};

const inferOpportunity = (row: SignalDeskTargetImportRow): SignalDeskTargetSummary["primaryOpportunity"] => {
    const currentListUrl = normalizeText(row.currentListUrl);
    if (currentListUrl && /(?:\.pdf(?:$|[?#])|\/pdf(?:$|[/?#]))/i.test(currentListUrl)) return "pdf-only";
    if (!currentListUrl && normalizeText(row.instagram) && !normalizeText(row.website)) return "instagram-only";
    if (!currentListUrl) return "missing-current-list";
    return "unknown";
};

const inferResearchCategory = (prompt: string) => {
    const text = normalizeLower(prompt);
    if (/\b(cafe|cafes|coffee)\b/.test(text)) return "cafe";
    if (/\b(dessert|bakery|bakeries|sweet)\b/.test(text)) return "dessert";
    if (/\b(takeaway|takeout|cloud kitchen|cloud-kitchen|quick service|qsr)\b/.test(text)) return "quick-service restaurant";
    if (/\b(consultant|photographer|agency|freelancer|creator|partner)\b/.test(text)) return "restaurant partner";
    if (/\b(bar|pub|nightlife)\b/.test(text)) return "bar";
    if (/\b(restaurant|restaurants|food)\b/.test(text)) return "restaurant";
    return "restaurant";
};

const inferResearchLocation = (prompt: string, city?: string, country?: string) => {
    const cityInput = normalizeText(city);
    const countryInput = normalizeText(country);
    if (cityInput || countryInput) return { city: cityInput || null, country: countryInput || null };
    const match = normalizeText(prompt).match(/\bin\s+([^,.]+?)(?:\s+(?:with|who|that|where|having|and)\b|$)/i);
    const inferred = match?.[1]?.trim() || "";
    return { city: inferred || null, country: null };
};

const selectResearchProvider = (
    input: Pick<ResearchAgentInput, "country" | "provider" | "researchType">,
): SignalDeskResearchProviderId => {
    if (input.provider) return input.provider;
    if (normalizeLower(input.country).includes("uk") || normalizeLower(input.country).includes("united kingdom")) return "fhrs-fhis";
    if (input.researchType === "partner-list") return "google-places";
    return "google-places";
};

const buildResearchProviderQuery = (input: {
    category: string;
    city?: string | null;
    prompt: string;
    researchType: SignalDeskResearchRunSummary["researchType"];
}) => {
    const city = normalizeText(input.city);
    if (input.researchType === "partner-list") {
        return normalizeText(`restaurant consultants menu photographers ${city}`.trim()).slice(0, 180);
    }
    const category = normalizeText(input.category || "restaurants");
    return normalizeText(city ? `${category} in ${city}` : category).slice(0, 180) || normalizeText(input.prompt).slice(0, 180);
};

const researchColumnsFor = (researchType: SignalDeskResearchRunSummary["researchType"]) => {
    const base = [
        "business",
        "category",
        "location",
        "website",
        "current-list-gap",
        "contactability",
        "source-ref",
        "fit-decision",
        "next-action",
    ];
    return researchType === "partner-list"
        ? ["partner", "partner-type", "location", "source-ref", "trust-fit", "fit-decision", "next-action"]
        : base;
};

const readUsableResearchSourcePolicy = async (
    db: any,
    access: SignalDeskAccessContext,
    provider: SignalDeskResearchProviderId,
    sourcePolicyId: string,
) => {
    const policy = await readSourcePolicy(db, sourcePolicyId);
    return assertSourcePolicyUsable(db, access, policy, {
        entityId: sourcePolicyId,
        requiredProvider: provider,
        requiredSourceType: "provider",
        use: "provider-run",
    });
};

const buildResearchRow = (input: {
    index: number;
    provider: SignalDeskResearchProviderId;
    providerRecordUrl?: string | null;
    researchRunId: string;
    researchType: SignalDeskResearchRunSummary["researchType"];
    sourcePolicyId?: string | null;
    sourcePolicy?: SignalDeskSourcePolicy | null;
    sourceRunId?: string | null;
    target: SignalDeskTargetSummary;
}): SignalDeskResearchTableRowSummary => {
    const category = normalizeLower(input.target.category);
    const foodFit = /(restaurant|cafe|coffee|dessert|bakery|takeaway|bar|pub|food|menu|service)/.test(category);
    const partnerFit = /(consultant|photographer|agency|freelancer|creator|partner|operator)/.test(category);
    const isPartner = input.researchType === "partner-list";
    const currentListGap = input.target.primaryOpportunity;
    const gapStrong = currentListGap === "missing-current-list" || currentListGap === "pdf-only" || currentListGap === "instagram-only" || currentListGap === "no-link";
    const suppressed = input.target.suppressionStatus !== "clear";
    const policyState = getSourcePolicyState(input.sourcePolicy);
    const contactUseAllowed = Boolean(
        input.sourcePolicy
        && policyState !== "expired"
        && policyState !== "review_required"
        && sourcePolicyUseAllowed(input.sourcePolicy, "contact")
    );
    const fitScore = clampScore(
        (isPartner ? (partnerFit ? 72 : 48) : (foodFit ? 72 : 42)) +
        (gapStrong ? 18 : 5) +
        (input.target.contactability === "ready" ? 8 : input.target.contactability === "limited" ? 5 : 0) -
        (suppressed ? 60 : 0),
    );
    const fitDecision: SignalDeskResearchTableRowSummary["fitDecision"] = suppressed || fitScore < 45
        ? "fail"
        : fitScore >= 72
            ? "pass"
            : "unsure";
    const routePermissionState: SignalDeskResearchTableRowSummary["routePermissionState"] = suppressed
        ? "blocked"
        : policyState === "expired"
            ? "expired"
            : policyState === "review_required"
                ? "review_required"
                : contactUseAllowed
                    ? "permissioned"
                    : "research_only";
    const permissionedReferral = input.sourcePolicy?.accessMethod === "permissioned-referral";
    const hardGateFailures = [
        suppressed ? `suppression:${input.target.suppressionStatus}` : "",
        policyState === "expired" ? "source-policy-expired" : "",
        policyState === "review_required" ? "source-policy-review-required" : "",
        !contactUseAllowed ? "contact-use-not-allowed" : "",
        input.target.contactability === "blocked" ? "contactability-blocked" : "",
        input.target.contactability === "missing" && !permissionedReferral ? "contact-route-missing" : "",
        input.target.contactability === "limited" && !permissionedReferral ? "contact-route-unverified" : "",
    ].filter(Boolean);
    const allowedRoute: SignalDeskResearchTableRowSummary["allowedRoute"] = fitDecision === "fail"
        || routePermissionState !== "permissioned"
        || input.target.contactability === "blocked"
        || (input.target.contactability === "missing" && !permissionedReferral)
        ? "none"
        : permissionedReferral
            ? "partner-intro"
            : input.target.contactability === "ready"
                ? "email-export"
                : "none";
    const actionabilityState: SignalDeskResearchTableRowSummary["actionabilityState"] = fitDecision === "fail" || suppressed
        ? "blocked"
        : allowedRoute !== "none"
            ? "actionable"
            : routePermissionState === "research_only"
                ? "research_only"
                : "verify";
    const recommendedNextAction: SignalDeskResearchTableRowSummary["recommendedNextAction"] = fitDecision === "pass"
        ? isPartner ? "partner-review" : "score"
        : fitDecision === "unsure"
            ? isPartner ? "pod-review" : "evidence"
            : "hold";
    const recommendedChannel: NonNullable<SignalDeskResearchTableRowSummary["recommendedChannel"]> = allowedRoute === "none" ? "hold" : allowedRoute;
    const allowedRouteReason = allowedRoute !== "none"
        ? `Source policy permits contact and the ${allowedRoute} route is available.`
        : routePermissionState === "research_only"
            ? "This source may support research and evidence, but it does not grant contact permission."
            : routePermissionState === "expired"
                ? "The source policy expired; review is required before any action."
                : routePermissionState === "review_required"
                    ? "The source-rights record is incomplete or due for review."
                    : suppressed
                        ? "The identity is suppressed and cannot be contacted."
                        : "No allowed, verified contact route is available.";
    const recommendedCta = isPartner
        ? "Ask for a trusted introduction to owners who need one current customer-ready menu link."
        : currentListGap === "pdf-only"
            ? "Offer a private preview that turns the PDF menu into one mobile current link for QR, WhatsApp, Google/Profile, and Instagram."
            : currentListGap === "instagram-only"
                ? "Offer a private preview that keeps Instagram for discovery but gives customers one reviewed current menu link."
                : currentListGap === "missing-current-list" || currentListGap === "no-link"
                    ? "Offer one reviewed current menu link for QR, WhatsApp, Google/Profile, Instagram, and repeat customers."
                    : currentListGap === "stale-menu"
                        ? "Offer a reviewed current-menu refresh so old links and images stop spreading."
                        : "Use only evidence-backed current-list wording and ask for a private MenuList preview.";
    const recommendedMessageAngle = isPartner
        ? "Trusted local operator intro, not follower-count influencer outreach."
        : currentListGap === "pdf-only"
            ? "Your menu exists, but it is trapped in a file that is hard to update and share on mobile."
            : currentListGap === "instagram-only"
                ? "Instagram is useful for discovery, but it should not be the only current menu source."
                : currentListGap === "missing-current-list" || currentListGap === "no-link"
                    ? "Customers can find the business, but need one current menu link they can open and share."
                    : currentListGap === "stale-menu"
                        ? "A reviewed current MenuList preview can reduce outdated customer-facing menu drift."
                        : "MenuList can prepare a reviewed current-list preview before anything is published.";
    const sourceRefs = [
        input.sourceRunId ? `source-run:${input.sourceRunId}` : "",
        input.sourcePolicyId ? `source-policy:${input.sourcePolicyId}` : "",
        input.providerRecordUrl || "",
    ].filter(Boolean);
    const sourceRef = sourceRefs[0] || null;
    const evidenceSummary = [
        gapStrong ? `current-list gap:${currentListGap}` : `current-list gap needs review:${currentListGap}`,
        input.target.website ? "website present" : "website missing/unknown",
        `contactability:${input.target.contactability}`,
        `route-permission:${routePermissionState}`,
        sourceRefs.length ? "source refs attached" : "source refs missing",
    ].join("; ");

    return {
        category: input.target.category || null,
        city: input.target.city || null,
        contactability: input.target.contactability,
        country: input.target.country || null,
        currentListGap,
        displayName: input.target.displayName,
        evidenceSummary,
        enrichment: [
            {
                key: "website",
                label: "Website",
                sourceRef,
                value: input.target.website || "missing",
                verdict: input.target.website ? "pass" : "unsure",
            },
            {
                key: "current-list-gap",
                label: "Current-list gap",
                sourceRef,
                value: currentListGap,
                verdict: gapStrong ? "pass" : "unsure",
            },
            {
                key: "contactability",
                label: "Contactability",
                sourceRef,
                value: input.target.contactability,
                verdict: input.target.contactability === "blocked" ? "fail" : input.target.contactability === "missing" ? "unsure" : "pass",
            },
            {
                key: "source-transparency",
                label: "Source transparency",
                sourceRef,
                value: sourceRefs.join(" | ") || "missing",
                verdict: sourceRefs.length ? "pass" : "fail",
            },
        ],
        fitDecision,
        fitScore,
        actionabilityState,
        allowedRoute,
        allowedRouteReason,
        hardGateFailures,
        provider: input.provider,
        providerRecordUrl: input.providerRecordUrl || null,
        recommendedChannel,
        recommendedCta,
        recommendedMessageAngle,
        recommendedNextAction,
        researchRowId: researchRowIdFor(input.researchRunId, input.target.targetId, input.index),
        researchRunId: input.researchRunId,
        routePermissionState,
        sourcePolicyId: input.sourcePolicyId || null,
        sourceRefs,
        sourceRunId: input.sourceRunId || null,
        targetId: input.target.targetId,
        updatedAt: null,
        website: input.target.website || null,
    };
};

const revalidateResearchRowRoute = (
    row: SignalDeskResearchTableRowSummary,
    policy?: SignalDeskSourcePolicy | null,
    target?: SignalDeskTargetSummary | null,
): SignalDeskResearchTableRowSummary => {
    const policyState = getSourcePolicyState(policy);
    const suppressed = Boolean(target && target.suppressionStatus !== "clear");
    const contactAllowed = Boolean(
        policy
        && !suppressed
        && policyState !== "expired"
        && policyState !== "review_required"
        && sourcePolicyUseAllowed(policy, "contact")
    );
    const routePermissionState: SignalDeskResearchTableRowSummary["routePermissionState"] = suppressed
        ? "blocked"
        : policyState === "expired"
        ? "expired"
        : policyState === "review_required"
            ? "review_required"
            : contactAllowed
                ? "permissioned"
                : "research_only";
    const intendedRoute: SignalDeskResearchTableRowSummary["allowedRoute"] = policy?.accessMethod === "permissioned-referral"
        ? "partner-intro"
        : row.contactability === "ready"
            ? "email-export"
            : "none";
    const allowedRoute: SignalDeskResearchTableRowSummary["allowedRoute"] = row.fitDecision !== "fail"
        && contactAllowed
        && row.contactability !== "blocked"
        && (row.contactability !== "missing" || policy?.accessMethod === "permissioned-referral")
        ? intendedRoute
        : "none";
    const hardGateFailures = Array.from(new Set([
        ...(row.hardGateFailures || []).filter((failure) => (
            !failure.startsWith("source-policy-")
            && failure !== "contact-use-not-allowed"
            && failure !== "contact-route-missing"
            && failure !== "contact-route-unverified"
        )),
        suppressed ? `suppression:${target?.suppressionStatus}` : "",
        policyState === "expired" ? "source-policy-expired" : "",
        policyState === "review_required" ? "source-policy-review-required" : "",
        !contactAllowed ? "contact-use-not-allowed" : "",
        row.contactability === "missing" && policy?.accessMethod !== "permissioned-referral" ? "contact-route-missing" : "",
        row.contactability === "limited" && policy?.accessMethod !== "permissioned-referral" ? "contact-route-unverified" : "",
    ].filter(Boolean)));
    const actionabilityState: SignalDeskResearchTableRowSummary["actionabilityState"] = row.fitDecision === "fail"
        ? "blocked"
        : allowedRoute !== "none"
            ? "actionable"
            : routePermissionState === "research_only"
                ? "research_only"
                : "verify";
    return {
        ...row,
        actionabilityState,
        allowedRoute,
        allowedRouteReason: allowedRoute !== "none"
            ? `Current source policy permits contact through ${allowedRoute}.`
            : suppressed
                ? "The identity is suppressed and no contact action is allowed."
            : routePermissionState === "research_only"
                ? "Research and evidence use are allowed, but contact use is not."
                : routePermissionState === "expired"
                    ? "The source policy expired; no contact action is allowed."
                    : "The source-rights record requires review before any contact action.",
        hardGateFailures,
        recommendedChannel: allowedRoute === "none" ? "hold" : allowedRoute,
        routePermissionState,
    };
};

const isVerifiedTwoSurfaceOutcome = (outcome: SignalDeskOutcomeSummary) => (
    outcome.outcomeType === "two_surface_activation"
    && (outcome.integrityStatus === "owner-reviewed-manual" || outcome.integrityStatus === "menulist-signed")
    && Boolean(outcome.ownerQualifiedAt)
    && Boolean(outcome.ownerReviewedAt)
    && Boolean(outcome.evidenceRef)
    && new Set(outcome.surfaces || []).size >= 2
);

const deriveActivationOpportunities = (workspace: SignalDeskWorkspaceData): SignalDeskActivationOpportunitySummary[] => {
    const policies = new Map(workspace.policies.map((policy) => [policy.sourcePolicyId, policy]));
    const rowsByTarget = new Map(workspace.researchTableRows.filter((row) => row.targetId).map((row) => [row.targetId as string, row]));
    const conversationsByTarget = new Map(workspace.conversations.map((conversation) => [conversation.targetId, conversation]));
    const outcomesByTarget = new Map<string, SignalDeskOutcomeSummary[]>();
    workspace.outcomes.forEach((outcome) => {
        if (!outcome.targetId) return;
        outcomesByTarget.set(outcome.targetId, [...(outcomesByTarget.get(outcome.targetId) || []), outcome]);
    });
    const nowMillis = Date.now();
    return workspace.targets.map((target) => {
        const policy = target.sourcePolicyId ? policies.get(target.sourcePolicyId) : null;
        const policyState = getSourcePolicyState(policy);
        const researchRow = rowsByTarget.get(target.targetId);
        const routeRow = researchRow ? revalidateResearchRowRoute(researchRow, policy, target) : null;
        const conversation = conversationsByTarget.get(target.targetId);
        const outcomes = outcomesByTarget.get(target.targetId) || [];
        const activation = outcomes.find(isVerifiedTwoSurfaceOutcome);
        const activationStart = outcomes.find((outcome) => outcome.outcomeType === "upload_started" || outcome.outcomeType === "preview_prepared");
        const ownerQualifiedAt = target.ownerQualifiedAt
            || activation?.ownerQualifiedAt
            || outcomes.find((outcome) => outcome.ownerQualifiedAt)?.ownerQualifiedAt
            || (conversation?.state === "interested" ? conversation.lastInboundAt : null);
        const ownerQualifiedMillis = toTimestampMillis(ownerQualifiedAt);
        const activationDeadlineAt = ownerQualifiedMillis ? new Date(ownerQualifiedMillis + (7 * 24 * 60 * 60 * 1000)).toISOString() : null;
        const stalled = Boolean(activationDeadlineAt && !activation && new Date(activationDeadlineAt).getTime() < nowMillis);
        const preparedContact = conversation?.state === "exported" && !target.latestManualContactAt;
        let state: SignalDeskActivationOpportunitySummary["state"] = "candidate";
        if (target.suppressionStatus !== "clear") state = "suppressed";
        else if (policyState === "expired") state = "expired";
        else if (routeRow?.fitDecision === "fail") state = "rejected";
        else if (target.status === "rejected") state = "rejected";
        else if (activation) state = "activated";
        else if (activationStart) state = "activation_started";
        else if (conversation?.state === "interested") state = "engaged";
        else if (target.latestManualContactAt || target.status === "contacted" || conversation?.state === "contacted") state = "contacted";
        else if (routeRow?.actionabilityState === "actionable") state = "actionable";
        else if (target.sourceConfidence === "high" || target.sourceConfidence === "medium") state = "verified";
        const allowedRoute = routeRow?.allowedRoute || "none";
        const hardGateFailures = routeRow?.hardGateFailures || [
            policyState === "expired" ? "source-policy-expired" : "",
            policyState === "review_required" ? "source-policy-review-required" : "",
            target.suppressionStatus !== "clear" ? `suppression:${target.suppressionStatus}` : "",
        ].filter(Boolean);
        const priority = state === "suppressed"
            ? 100
            : conversation?.state === "complaint" || conversation?.state === "privacy_request" || conversation?.state === "legal_request"
                ? 98
                : stalled
                    ? 95
                    : preparedContact
                        ? 82
                    : state === "engaged" || state === "activation_started"
                        ? 90
                        : state === "actionable"
                            ? 70
                            : state === "verified"
                                ? 45
                                : 20;
        return {
            activationOpportunityId: `activation_opportunity_${target.targetId}`,
            targetId: target.targetId,
            displayName: target.displayName,
            category: target.category || null,
            city: target.city || null,
            state,
            truthGap: target.primaryOpportunity,
            sourcePolicyState: policyState,
            evidenceGrade: target.sourceConfidence === "blocked" ? "low" : target.sourceConfidence,
            allowedRoute,
            allowedRouteReason: routeRow?.allowedRouteReason || "No verified contact route is available.",
            routePermissionState: routeRow?.routePermissionState || (policyState === "expired" ? "expired" : policyState === "review_required" ? "review_required" : "research_only"),
            hardGateFailures,
            dimensions: {
                truthGap: target.currentListGapScore ?? (target.primaryOpportunity === "unknown" ? 35 : 75),
                evidence: target.sourceConfidence === "high" ? 90 : target.sourceConfidence === "medium" ? 70 : 35,
                reachability: allowedRoute !== "none" ? 85 : target.contactability === "limited" ? 45 : 15,
                activationFeasibility: activationStart ? 90 : ownerQualifiedAt ? 75 : target.primaryOpportunity === "unknown" ? 35 : 60,
                surfaceLeverage: activation?.surfaces?.length
                    ? Math.min(100, activation.surfaces.length * 35)
                    : 50,
                learningValue: state === "engaged" || state === "activation_started" ? 90 : 60,
            },
            ownerQualifiedAt: ownerQualifiedAt || null,
            activationStartedAt: activationStart?.updatedAt || null,
            activatedAt: activation?.updatedAt || null,
            activationDeadlineAt,
            surfaces: activation?.surfaces || [],
            nextAction: state === "suppressed"
                ? "No contact. Review the suppression or complaint record."
                : stalled
                    ? "Resolve the current activation blocker before researching more businesses."
                    : preparedContact
                        ? "Complete the prepared contact action, then record what actually happened."
                    : state === "engaged" || state === "activation_started"
                        ? "Continue the owner-approved MenuList activation path."
                        : state === "actionable"
                            ? "Review the evidence-bound action packet."
                            : routeRow?.allowedRouteReason || "Verify evidence and source rights.",
            priority,
            updatedAt: target.updatedAt || null,
        };
    }).sort((left, right) => right.priority - left.priority || left.displayName.localeCompare(right.displayName));
};

const classifyReply = (message: string): SignalDeskConversationSummary["state"] => {
    const text = message.toLowerCase();
    if (/\b(stop|unsubscribe|do not contact|don't contact|dnc)\b/.test(text)) return "dnc";
    if (/\b(complaint|report you|spam complaint|harassment|unwanted message)\b/.test(text)) return "complaint";
    if (/\b(delete my data|privacy request|data request|personal data|right to erasure)\b/.test(text)) return "privacy_request";
    if (/\b(legal notice|lawyer|solicitor|cease and desist|legal action)\b/.test(text)) return "legal_request";
    if (/\bwrong (person|contact|number|email)\b/.test(text)) return "wrong_contact";
    if (/\b(yes|interested|pricing|price|demo|call|send|how much)\b/.test(text)) return "interested";
    if (/\b(no|not interested|later)\b/.test(text)) return "not_interested";
    return "needs_review";
};

const buildDraftBody = (
    template: SignalDeskTemplateSummary,
    target: SignalDeskTargetSummary,
    evidence: SignalDeskEvidencePacketSummary,
    cta: SignalDeskSelfServiceCtaSummary,
) => {
    const opportunity = target.primaryOpportunity === "missing-current-list"
        ? "your current list is hard to find from the public surface"
        : "there may be a cleaner way to keep your public list current";
    const ctaCopy = cta.copy;
    const values: Record<string, string> = {
        businessName: target.displayName,
        category: target.category || "business",
        city: target.city || "your area",
        opportunity,
        proofCta: ctaCopy,
    };
    const replaceValue = (text: string) => Object.entries(values).reduce(
        (current, [key, value]) => current.replace(new RegExp(`{{\\s*${key}\\s*}}`, "g"), value),
        text,
    );
    const personalizationEvidenceIds = [
        evidence.evidencePacketId,
        target.sourcePolicyId ? `source-policy:${target.sourcePolicyId}` : "",
        `cta:${cta.ctaId}`,
    ].filter(Boolean);
    return {
        body: replaceValue(template.body),
        personalizationEvidenceIds,
        subject: replaceValue(template.subject || "Quick note for {{businessName}}"),
        unsupportedClaims: [],
    };
};

const computeScore = (target: SignalDeskTargetSummary): SignalDeskAiScoreSummary => {
    const category = normalizeLower(target.category);
    const fitScore = /(restaurant|cafe|salon|spa|bar|bakery|food|menu|service)/.test(category) ? 86 : 64;
    const currentListGapScore = target.currentListUrl ? 38 : 88;
    const contactabilityScore = target.contactability === "ready" ? 84 : target.contactability === "limited" ? 56 : 22;
    const riskScore = target.suppressionStatus === "clear" ? 12 : 92;
    const total = fitScore + currentListGapScore + contactabilityScore - riskScore;
    const segment: SignalDeskSegment = riskScore > 70
        ? "reject"
        : total >= 210
            ? "a"
            : total >= 165
                ? "b"
                : total >= 125
                    ? "c"
                    : "hold";
    const nextAction: SignalDeskNextAction = segment === "reject" || segment === "hold" ? "hold" : "evidence";

    return {
        scoreId: "",
        targetId: target.targetId,
        fitScore,
        currentListGapScore,
        contactabilityScore,
        riskScore,
        segment,
        nextAction,
        reasons: [
            `Fit ${fitScore}`,
            `Current-list gap ${currentListGapScore}`,
            `Contactability ${contactabilityScore}`,
            `Risk ${riskScore}`,
        ],
        createdAt: null,
    };
};

export async function loadSignalDeskWorkspaceServer(
    access: SignalDeskAccessContext,
    section: SignalDeskSection,
): Promise<SignalDeskWorkspaceResponse> {
    const overview = await loadSignalDeskOverviewServer(access);
    const workspace = emptyWorkspace(section);
    const db = getSignalDeskDb();
    if (!db) return { ...overview, workspace };
    // Workspace responses are a public DTO boundary. Shadow the internal raw
    // reader so every generic section read is product/identity validated,
    // allowlisted, projected before limiting, and bounded across bad head rows.
    const readList = readWorkspaceList;

    const readCommon = async () => {
        const [targets, approvals, conversations, outcomes, demandSignals] = await Promise.all([
            readTargetSummaryList(db),
            readList<SignalDeskApprovalItem>(db, SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE),
            readConversationSummaryList(db),
            readOutcomeSummaryList(db, LIST_LIMIT, "workspace-common"),
            readList<SignalDeskDemandSignalSummary>(db, SIGNALDESK_COLLECTIONS.DEMAND_SIGNAL_SUMMARIES),
        ]);
        workspace.targets = targets;
        workspace.approvals = approvals;
        workspace.conversations = conversations;
        workspace.outcomes = outcomes;
        workspace.demandSignals = demandSignals;
    };

    if (section === "dashboard") {
        await readCommon();
        workspace.growthMissions = await readGrowthMissions(db);
        workspace.experimentCards = await readExperimentCards(db);
        workspace.policies = await readSourcePolicyList(db);
        workspace.researchRuns = await readResearchRunList(db);
        workspace.researchTableRows = await readResearchRowList(db);
    } else if (section === "mission") {
        await readCommon();
        workspace.contentAssets = await readContentAssets(db);
        workspace.contentDistributionDrafts = await readContentDrafts(db);
        workspace.experimentCards = await readExperimentCards(db);
        workspace.growthMissions = await readGrowthMissions(db);
        workspace.imports = await readSourceRunList(db);
        workspace.marketPods = await readMarketPods(db);
        workspace.offerCtas = await readOfferCtas(db);
        workspace.policies = await readSourcePolicyList(db);
        workspace.researchRuns = await readResearchRunList(db);
        workspace.researchTableRows = await readResearchRowList(db);
        workspace.replyPlaybooks = await readList<SignalDeskReplyPlaybookSummary>(db, SIGNALDESK_COLLECTIONS.REPLY_PLAYBOOKS);
        workspace.runTimelines = await readList<SignalDeskRunTimelineSummary>(db, SIGNALDESK_COLLECTIONS.RUN_TIMELINES);
        workspace.selfServiceCtas = await readSelfServiceCtas(db);
        workspace.senderDomains = await readSenderDomains(db);
        workspace.sourceQualitySnapshots = await readList<SignalDeskSourceQualitySnapshotSummary>(db, SIGNALDESK_COLLECTIONS.SOURCE_QUALITY_SNAPSHOTS);
        workspace.trustPartnerProfiles = await readList<SignalDeskTrustPartnerProfileSummary>(db, SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES);
    } else if (section === "revenue") {
        await readCommon();
        const [
            activationWatches,
            commercialOffers,
            commercialOpportunities,
            operatingEnvelopes,
            revenueAccounts,
            revenueControlSummaries,
        ] = await Promise.all([
            readList<SignalDeskActivationWatchSummary>(db, SIGNALDESK_COLLECTIONS.ACTIVATION_WATCHES),
            readList<SignalDeskCommercialOfferSummary>(db, SIGNALDESK_COLLECTIONS.COMMERCIAL_OFFERS),
            readList<SignalDeskCommercialOpportunitySummary>(db, SIGNALDESK_COLLECTIONS.COMMERCIAL_OPPORTUNITIES),
            readList<SignalDeskOperatingEnvelopeSummary>(db, SIGNALDESK_COLLECTIONS.OPERATING_ENVELOPES),
            readList<SignalDeskRevenueAccountSummary>(db, SIGNALDESK_COLLECTIONS.REVENUE_ACCOUNTS),
            readList<SignalDeskRevenueControlSummary>(db, SIGNALDESK_COLLECTIONS.REVENUE_CONTROL_SUMMARIES),
        ]);
        workspace.activationWatches = activationWatches.map((watch) => annotateActivationWatch(watch));
        workspace.commercialOffers = commercialOffers;
        workspace.commercialOpportunities = commercialOpportunities;
        workspace.operatingEnvelopes = operatingEnvelopes.map((envelope) => annotateOperatingEnvelope(envelope));
        workspace.revenueAccounts = revenueAccounts;
        workspace.revenueControlSummaries = revenueControlSummaries;
        workspace.budgetPolicies = await readList<SignalDeskBudgetPolicySummary>(db, SIGNALDESK_COLLECTIONS.BUDGET_POLICIES);
        workspace.marketPods = await readMarketPods(db);
        workspace.offerCtas = await readOfferCtas(db);
        workspace.policies = await readSourcePolicyList(db);
        workspace.senderDomains = await readSenderDomains(db);
        workspace.templates = await readList<SignalDeskTemplateSummary>(db, SIGNALDESK_COLLECTIONS.TEMPLATE_SUMMARIES);
    } else if (section === "targets") {
        workspace.targets = await readTargetSummaryList(db);
        workspace.policies = await readSourcePolicyList(db);
    } else if (section === "imports") {
        workspace.imports = await readSourceRunList(db);
        workspace.policies = await readSourcePolicyList(db);
    } else if (section === "approvals") {
        workspace.approvals = await readList<SignalDeskApprovalItem>(db, SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE);
        workspace.approvalPackets = await readList<SignalDeskApprovalPacketSummary>(db, SIGNALDESK_COLLECTIONS.APPROVAL_PACKETS);
        workspace.drafts = await readList<SignalDeskDraftSummary>(db, SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES);
    } else if (section === "templates") {
        workspace.templates = await readList<SignalDeskTemplateSummary>(db, SIGNALDESK_COLLECTIONS.TEMPLATE_SUMMARIES);
        workspace.drafts = await readList<SignalDeskDraftSummary>(db, SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES);
        workspace.targets = await readTargetSummaryList(db);
        workspace.evidencePackets = await readList<SignalDeskEvidencePacketSummary>(db, SIGNALDESK_COLLECTIONS.EVIDENCE_PACKET_SUMMARIES);
        workspace.selfServiceCtas = await readSelfServiceCtas(db);
    } else if (section === "inbox") {
        workspace.conversations = await readConversationSummaryList(db);
        workspace.outcomes = await readOutcomeSummaryList(db, LIST_LIMIT, "workspace-inbox");
        workspace.policies = await readSourcePolicyList(db);
        workspace.researchTableRows = await readResearchRowList(db);
        workspace.targets = await readTargetSummaryList(db);
    } else if (section === "attribution") {
        workspace.outcomes = await readOutcomeSummaryList(db, LIST_LIMIT, "workspace-attribution");
        workspace.conversations = await readConversationSummaryList(db);
        workspace.demandSignals = await readList<SignalDeskDemandSignalSummary>(db, SIGNALDESK_COLLECTIONS.DEMAND_SIGNAL_SUMMARIES);
        workspace.audienceSegments = await readList<SignalDeskAudienceSegmentSummary>(db, SIGNALDESK_COLLECTIONS.AUDIENCE_SEGMENTS);
        workspace.marketPods = await readMarketPods(db);
        workspace.policies = await readSourcePolicyList(db);
        workspace.researchTableRows = await readResearchRowList(db);
        workspace.strategistMemos = await readList<SignalDeskStrategistMemoSummary>(db, SIGNALDESK_COLLECTIONS.STRATEGIST_MEMOS);
        workspace.targets = await readTargetSummaryList(db);
    } else if (section === "policies") {
        workspace.policies = await readSourcePolicyList(db);
        workspace.budgetPolicies = await readList<SignalDeskBudgetPolicySummary>(db, SIGNALDESK_COLLECTIONS.BUDGET_POLICIES);
        workspace.providerAccounts = await readList<SignalDeskProviderAccountSummary>(db, SIGNALDESK_COLLECTIONS.PROVIDER_ACCOUNTS);
        workspace.templates = await readList<SignalDeskTemplateSummary>(db, SIGNALDESK_COLLECTIONS.TEMPLATE_SUMMARIES);
    } else if (section === "sources") {
        workspace.budgetPolicies = await readList<SignalDeskBudgetPolicySummary>(db, SIGNALDESK_COLLECTIONS.BUDGET_POLICIES);
        workspace.enrichmentResults = await readList<SignalDeskEnrichmentResultSummary>(db, SIGNALDESK_COLLECTIONS.ENRICHMENT_RESULTS);
        workspace.enrichmentWaterfalls = await readList<SignalDeskEnrichmentWaterfallSummary>(db, SIGNALDESK_COLLECTIONS.ENRICHMENT_WATERFALLS);
        workspace.imports = await readSourceRunList(db);
        workspace.policies = await readSourcePolicyList(db);
        workspace.providerAccounts = await readList<SignalDeskProviderAccountSummary>(db, SIGNALDESK_COLLECTIONS.PROVIDER_ACCOUNTS);
        workspace.providerEvaluations = await readList<SignalDeskProviderEvaluationSummary>(db, SIGNALDESK_COLLECTIONS.PROVIDER_EVALUATIONS);
        workspace.providerSourceRetentions = await readList<SignalDeskProviderSourceRetentionSummary>(db, SIGNALDESK_COLLECTIONS.PROVIDER_SOURCE_RETENTION);
        workspace.researchRuns = await readResearchRunList(db);
        workspace.researchTableRows = await readResearchRowList(db);
        workspace.targets = await readTargetSummaryList(db);
        workspace.vendorRuns = await readList<SignalDeskVendorRunSummary>(db, SIGNALDESK_COLLECTIONS.VENDOR_RUNS);
    } else if (section === "ai") {
        const aiRuns = await readList<SignalDeskAiWorkerRunSummary & SignalDeskAiVolumeRunSummary & Partial<SignalDeskAiScoreSummary>>(db, SIGNALDESK_COLLECTIONS.AI_WORKER_RUNS, "createdAt");
        workspace.modelEvals = (await readList<SignalDeskModelEvalSummary>(db, SIGNALDESK_COLLECTIONS.MODEL_EVALS))
            .map(annotateModelEvalSummary);
        workspace.modelRoutes = await readList<SignalDeskModelRouteSummary>(db, SIGNALDESK_COLLECTIONS.MODEL_ROUTES);
        workspace.aiWorkerRuns = aiRuns.filter((run) => String(run.workerType || "").startsWith("ai_assist_"));
        workspace.aiVolumeRuns = aiRuns.filter((run) => run.workerType === "ai_volume_batch");
        workspace.scores = aiRuns.filter((run) => Boolean(run.scoreId)) as SignalDeskAiScoreSummary[];
        workspace.targets = await readTargetSummaryList(db);
        workspace.evidencePackets = await readList<SignalDeskEvidencePacketSummary>(db, SIGNALDESK_COLLECTIONS.EVIDENCE_PACKET_SUMMARIES);
    } else if (section === "channels") {
        workspace.approvals = await readList<SignalDeskApprovalItem>(db, SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE);
        workspace.channelHealth = await readList<SignalDeskChannelHealthSummary>(db, SIGNALDESK_COLLECTIONS.CHANNEL_HEALTH_SUMMARIES);
        workspace.channelWindows = await readList<SignalDeskChannelWindowStateSummary>(db, SIGNALDESK_COLLECTIONS.CHANNEL_WINDOW_STATES);
        workspace.connectorSettings = await readList<SignalDeskConnectorSettingSummary>(db, SIGNALDESK_COLLECTIONS.CONNECTOR_SETTINGS);
        workspace.conversations = await readConversationSummaryList(db);
        workspace.drafts = await readList<SignalDeskDraftSummary>(db, SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES);
        workspace.providerEvents = await readList<SignalDeskProviderEventSummary>(db, SIGNALDESK_COLLECTIONS.WEBHOOK_EVENTS);
        workspace.senderDomains = await readSenderDomains(db);
        workspace.sequencerHandoffs = await readList<SignalDeskSequencerHandoffSummary>(db, SIGNALDESK_COLLECTIONS.SEQUENCER_HANDOFFS);
        workspace.sequencerSteps = await readList<SignalDeskSequencerStepSummary>(db, SIGNALDESK_COLLECTIONS.SEQUENCER_STEPS);
        workspace.targets = await readTargetSummaryList(db);
    } else if (section === "content") {
        workspace.contentAssets = await readContentAssets(db);
        workspace.contentCalendarItems = await readContentCalendarItems(db);
        workspace.contentDistributionDrafts = await readContentDrafts(db);
        workspace.contentPerformanceSummaries = await readContentPerformanceSummaries(db);
        workspace.contentSources = await readContentSources(db);
        workspace.proofPermissions = await readProofPermissions(db);
        workspace.marketPods = await readMarketPods(db);
        workspace.selfServiceCtas = await readSelfServiceCtas(db);
    } else if (section === "partners") {
        workspace.budgetPolicies = await readList<SignalDeskBudgetPolicySummary>(db, SIGNALDESK_COLLECTIONS.BUDGET_POLICIES);
        workspace.marketPods = await readMarketPods(db);
        workspace.selfServiceCtas = await readSelfServiceCtas(db);
        workspace.trustPartnerBriefs = await readTrustPartnerBriefs(db);
        workspace.trustPartnerDeals = await readList<SignalDeskTrustPartnerDealSummary>(db, SIGNALDESK_COLLECTIONS.TRUST_PARTNER_DEALS);
        workspace.trustPartnerDeliverables = await readList<SignalDeskTrustPartnerDeliverableSummary>(db, SIGNALDESK_COLLECTIONS.TRUST_PARTNER_DELIVERABLES);
        workspace.trustPartnerMetrics = await readList<SignalDeskTrustPartnerMetricSummary>(db, SIGNALDESK_COLLECTIONS.TRUST_PARTNER_METRICS, "capturedAt");
        workspace.trustPartnerNicheTests = await readList<SignalDeskTrustPartnerNicheTestSummary>(db, SIGNALDESK_COLLECTIONS.TRUST_PARTNER_NICHE_TESTS);
        workspace.trustPartnerProfiles = await readList<SignalDeskTrustPartnerProfileSummary>(db, SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES);
        workspace.trustPartnerRenewalDecisions = await readList<SignalDeskTrustPartnerRenewalDecisionSummary>(db, SIGNALDESK_COLLECTIONS.TRUST_PARTNER_RENEWAL_DECISIONS);
    } else if (section === "settings") {
        workspace.channelHealth = await readList<SignalDeskChannelHealthSummary>(db, SIGNALDESK_COLLECTIONS.CHANNEL_HEALTH_SUMMARIES);
        workspace.connectorSettings = await readList<SignalDeskConnectorSettingSummary>(db, SIGNALDESK_COLLECTIONS.CONNECTOR_SETTINGS);
        workspace.providerAccounts = await readList<SignalDeskProviderAccountSummary>(db, SIGNALDESK_COLLECTIONS.PROVIDER_ACCOUNTS);
        workspace.senderDomains = await readSenderDomains(db);
        if (access.permissions.includes("signaldesk.configure")) {
            workspace.teamMembers = await readList<SignalDeskTeamMemberSummary>(db, SIGNALDESK_COLLECTIONS.TEAM_MEMBERS);
        }
    } else if (section === "control-room") {
        await readCommon();
        workspace.approvalPackets = await readList<SignalDeskApprovalPacketSummary>(db, SIGNALDESK_COLLECTIONS.APPROVAL_PACKETS);
        workspace.audienceSegments = await readList<SignalDeskAudienceSegmentSummary>(db, SIGNALDESK_COLLECTIONS.AUDIENCE_SEGMENTS);
        workspace.budgetPolicies = await readList<SignalDeskBudgetPolicySummary>(db, SIGNALDESK_COLLECTIONS.BUDGET_POLICIES);
        workspace.enrichmentWaterfalls = await readList<SignalDeskEnrichmentWaterfallSummary>(db, SIGNALDESK_COLLECTIONS.ENRICHMENT_WATERFALLS);
        workspace.imports = await readSourceRunList(db);
        workspace.modelRoutes = await readList<SignalDeskModelRouteSummary>(db, SIGNALDESK_COLLECTIONS.MODEL_ROUTES);
        workspace.providerAccounts = await readList<SignalDeskProviderAccountSummary>(db, SIGNALDESK_COLLECTIONS.PROVIDER_ACCOUNTS);
        workspace.providerEvaluations = await readList<SignalDeskProviderEvaluationSummary>(db, SIGNALDESK_COLLECTIONS.PROVIDER_EVALUATIONS);
        workspace.policies = await readSourcePolicyList(db);
        workspace.proofPermissions = await readProofPermissions(db);
        workspace.runTimelines = await readList<SignalDeskRunTimelineSummary>(db, SIGNALDESK_COLLECTIONS.RUN_TIMELINES);
        const aiRuns = await readList<SignalDeskAiWorkerRunSummary & SignalDeskAiVolumeRunSummary & Partial<SignalDeskAiScoreSummary>>(db, SIGNALDESK_COLLECTIONS.AI_WORKER_RUNS, "createdAt");
        workspace.aiWorkerRuns = aiRuns.filter((run) => String(run.workerType || "").startsWith("ai_assist_"));
        workspace.aiVolumeRuns = aiRuns.filter((run) => run.workerType === "ai_volume_batch");
        workspace.scores = aiRuns.filter((run) => Boolean(run.scoreId)) as SignalDeskAiScoreSummary[];
        workspace.selfServiceCtas = await readSelfServiceCtas(db);
        workspace.senderDomains = await readSenderDomains(db);
        workspace.sequencerHandoffs = await readList<SignalDeskSequencerHandoffSummary>(db, SIGNALDESK_COLLECTIONS.SEQUENCER_HANDOFFS);
        workspace.sequencerSteps = await readList<SignalDeskSequencerStepSummary>(db, SIGNALDESK_COLLECTIONS.SEQUENCER_STEPS);
        workspace.strategistMemos = await readList<SignalDeskStrategistMemoSummary>(db, SIGNALDESK_COLLECTIONS.STRATEGIST_MEMOS);
        workspace.contentAssets = await readContentAssets(db);
        workspace.contentCalendarItems = await readContentCalendarItems(db);
        workspace.contentDistributionDrafts = await readContentDrafts(db);
        workspace.experimentCards = await readExperimentCards(db);
        workspace.growthMissions = await readGrowthMissions(db);
        workspace.offerCtas = await readOfferCtas(db);
        workspace.replyPlaybooks = await readList<SignalDeskReplyPlaybookSummary>(db, SIGNALDESK_COLLECTIONS.REPLY_PLAYBOOKS);
        workspace.researchRuns = await readResearchRunList(db);
        workspace.researchTableRows = await readResearchRowList(db);
        workspace.sourceQualitySnapshots = await readList<SignalDeskSourceQualitySnapshotSummary>(db, SIGNALDESK_COLLECTIONS.SOURCE_QUALITY_SNAPSHOTS);
        workspace.trustPartnerProfiles = await readList<SignalDeskTrustPartnerProfileSummary>(db, SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES);
    } else if (section === "audit") {
        workspace.auditEvents = await readList<SignalDeskAuditEvent>(db, SIGNALDESK_COLLECTIONS.AUDIT_EVENTS, "createdAt", 50);
    }
    workspace.policies = workspace.policies.map(annotateSourcePolicy);
    const policyById = new Map(workspace.policies.map((policy) => [policy.sourcePolicyId, policy]));
    const targetById = new Map(workspace.targets.map((target) => [target.targetId, target]));
    const missingPolicyIds = Array.from(new Set(
        workspace.researchTableRows
            .map((row) => normalizeText(row.sourcePolicyId))
            .filter((sourcePolicyId) => sourcePolicyId && !policyById.has(sourcePolicyId)),
    )).slice(0, LIST_LIMIT);
    const missingTargetIds = Array.from(new Set(
        workspace.researchTableRows
            .map((row) => normalizeText(row.targetId))
            .filter((targetId) => targetId && !targetById.has(targetId)),
    )).slice(0, LIST_LIMIT);
    const [referencedPolicySnaps, referencedTargetSnaps] = await Promise.all([
        Promise.all(missingPolicyIds.map((sourcePolicyId) => (
            db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(sourcePolicyId).get()
        ))),
        Promise.all(missingTargetIds.map((targetId) => (
            db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(targetId).get()
        ))),
    ]);
    for (const policySnap of referencedPolicySnaps) {
        if (!policySnap.exists) continue;
        try {
            const policy = annotateSourcePolicy(parseSignalDeskSourcePolicyDocument(policySnap.data(), policySnap.id));
            policyById.set(policy.sourcePolicyId, policy);
        } catch (error) {
            logRuntimeFailure("signaldesk_referenced_source_policy_projection_failed", error, {
                product: "signaldesk",
                ...getBoundedRuntimeStringContext("sourcePolicyId", policySnap.id),
            });
        }
    }
    for (const targetSnap of referencedTargetSnaps) {
        if (!targetSnap.exists) continue;
        try {
            const target = parseSignalDeskTargetSummaryDocument(targetSnap.data(), targetSnap.id);
            targetById.set(target.targetId, target);
        } catch (error) {
            logRuntimeFailure("signaldesk_referenced_target_projection_failed", error, {
                product: "signaldesk",
                ...getBoundedRuntimeStringContext("targetId", targetSnap.id),
            });
        }
    }
    workspace.researchTableRows = workspace.researchTableRows.map((row) => (
        revalidateResearchRowRoute(
            row,
            row.sourcePolicyId ? policyById.get(row.sourcePolicyId) : null,
            row.targetId ? targetById.get(row.targetId) : null,
        )
    ));
    workspace.activationOpportunities = deriveActivationOpportunities({
        ...workspace,
        policies: Array.from(policyById.values()),
        targets: Array.from(targetById.values()),
    });

    return { ...overview, workspace };
}

const SIGNALDESK_SOURCE_POLICY_TYPES = new Set<SignalDeskSourcePolicy["sourceType"]>([
    "manual-csv", "manual-research", "owned-demand", "provider", "other",
]);
const SIGNALDESK_MANUAL_IMPORT_SOURCE_TYPES = new Set<SignalDeskSourcePolicy["sourceType"]>([
    "manual-csv", "manual-research", "owned-demand",
]);
const SIGNALDESK_SOURCE_POLICY_STATUSES = new Set<SignalDeskSourcePolicy["status"]>([
    "active", "approved", "inactive", "review_required", "blocked",
]);
const SIGNALDESK_SOURCE_ACCESS_METHODS = new Set<NonNullable<SignalDeskSourcePolicy["accessMethod"]>>([
    "owner-supplied", "permissioned-referral", "licensed-api", "open-data", "manual-public-research", "other",
]);
const SIGNALDESK_SOURCE_RAW_PAYLOAD_POLICIES = new Set<NonNullable<SignalDeskSourcePolicy["rawPayloadPolicy"]>>([
    "never-store", "transient-only", "retention-bound",
]);
const SIGNALDESK_SOURCE_REFRESH_METHODS = new Set<NonNullable<SignalDeskSourcePolicy["refreshMethod"]>>([
    "manual-review", "provider-refresh", "owner-refresh", "no-refresh",
]);
const SIGNALDESK_OUTBOUND_CHANNELS = new Set<SignalDeskOutboundChannel>([
    "email", "whatsapp", "instagram", "messenger", "manual",
]);
const SIGNALDESK_PROVIDER_USES = new Set<SignalDeskProviderUse>([
    "discovery", "enrichment", "verification", "research", "sender", "sequencer", "ai",
]);
const SIGNALDESK_PROVIDER_STATUSES = new Set<SignalDeskProviderAccountSummary["status"]>([
    "approved", "blocked", "evaluation", "disabled",
]);
const SIGNALDESK_PROVIDER_CREDENTIAL_STATES = new Set<SignalDeskProviderAccountSummary["credentialState"]>([
    "missing", "configured", "not_required",
]);
const SIGNALDESK_BUDGET_SCOPES = new Set<SignalDeskBudgetPolicySummary["scope"]>([
    "global", "provider", "market-pod", "model-route", "sequencer", "trust-partner",
]);
const SIGNALDESK_AI_TASKS = new Set<SignalDeskAiTask>([
    "score", "evidence", "draft", "reply-classification", "approval-packet", "weekly-strategist", "vendor-audit", "quality-critic",
]);
const SIGNALDESK_AI_PROVIDERS = new Set<SignalDeskModelRouteSummary["defaultProvider"]>([
    "gemini", "openai", "anthropic",
]);
const SIGNALDESK_AUDIENCE_TRIGGERS = new Set<SignalDeskAudienceSegmentSummary["triggerType"]>([
    "demand-signal", "source-run", "outcome", "manual", "website-evidence",
]);
const SIGNALDESK_WATERFALL_FIELDS = new Set<SignalDeskEnrichmentWaterfallSummary["requestedField"]>([
    "email", "phone", "company", "website", "evidence",
]);
const SIGNALDESK_WATERFALL_STOP_CONDITIONS = new Set<SignalDeskEnrichmentWaterfallSummary["stopCondition"]>([
    "first-verified", "first-candidate", "manual-review",
]);
const SIGNALDESK_REPLY_INTENTS = new Set<SignalDeskReplyPlaybookSummary["intent"]>([
    "send-details", "pricing", "who-are-you", "not-now", "wrong-person", "stop", "call-me", "interested", "other",
]);
const SIGNALDESK_REPLY_ROUTES = new Set<SignalDeskReplyPlaybookSummary["nextRoute"]>([
    "self-serve-preview", "manual-reply", "suppress", "schedule-follow-up", "founder-review",
]);

const isBoundedSeedText = (value: unknown, minimum: number, maximum: number) => (
    typeof value === "string"
    && value === value.trim()
    && value.length >= minimum
    && value.length <= maximum
);

const isBoundedSeedTextArray = (
    value: unknown,
    minimumItems: number,
    maximumItems: number,
    maximumItemLength: number,
) => Array.isArray(value)
    && value.length >= minimumItems
    && value.length <= maximumItems
    && new Set(value).size === value.length
    && value.every((item) => isBoundedSeedText(item, 1, maximumItemLength));

const isSeedMoney = (value: unknown, maximum: number) => (
    typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= maximum
);

const hasValidSeedMetadata = (value: AnyRecord, allowMissingCreatedAt = false) => (
    (allowMissingCreatedAt ? value.createdAt == null || Boolean(toTimestampMillis(value.createdAt)) : Boolean(toTimestampMillis(value.createdAt)))
    && Boolean(toTimestampMillis(value.updatedAt))
    && isBoundedSeedText(value.updatedBy, 1, 180)
);

const hasOnlySeedKeys = (value: AnyRecord, allowedKeys: readonly string[]) => {
    const allowed = new Set(allowedKeys);
    return Object.keys(value).every((key) => allowed.has(key));
};

const assertSeedDocumentIdentity = (
    value: AnyRecord,
    ref: FirebaseFirestore.DocumentReference,
    idField: string,
    productError: string,
    shapeError: string,
) => {
    if (normalizeText(value.pId) !== SIGNALDESK_PRODUCT_CODE) throw new Error(productError);
    if (normalizeText(value[idField]) !== ref.id) throw new Error(shapeError);
};

const assertSeedSourcePolicy = (value: AnyRecord, ref: FirebaseFirestore.DocumentReference) => {
    assertSeedDocumentIdentity(value, ref, "sourcePolicyId", "SOURCE_POLICY_PRODUCT_MISMATCH", "SOURCE_POLICY_SHAPE_INVALID");
    const allowedUse = value.allowedUse as AnyRecord | null;
    const sourceType = normalizeText(value.sourceType) as SignalDeskSourcePolicy["sourceType"];
    const status = normalizeText(value.status) as SignalDeskSourcePolicy["status"];
    const provider = normalizeText(value.provider) as SignalDeskProviderId | "";
    const accessMethod = normalizeText(value.accessMethod) as NonNullable<SignalDeskSourcePolicy["accessMethod"]>;
    const rawPayloadPolicy = normalizeText(value.rawPayloadPolicy) as NonNullable<SignalDeskSourcePolicy["rawPayloadPolicy"]>;
    const refreshMethod = normalizeText(value.refreshMethod) as NonNullable<SignalDeskSourcePolicy["refreshMethod"]>;
    const approvedAt = toTimestampMillis(value.approvedAt);
    const expiresAt = toTimestampMillis(value.expiresAt);
    let termsUrlValid = value.termsUrl == null;
    if (typeof value.termsUrl === "string") {
        try {
            termsUrlValid = Boolean(canonicalizeContentUrl(value.termsUrl));
        } catch {
            termsUrlValid = false;
        }
    }
    if (
        !isBoundedSeedText(value.name, 2, 120)
        || !SIGNALDESK_SOURCE_POLICY_TYPES.has(sourceType)
        || !SIGNALDESK_SOURCE_POLICY_STATUSES.has(status)
        || !allowedUse
        || typeof allowedUse !== "object"
        || Array.isArray(allowedUse)
        || !["contact", "evidence", "import", "personalization", "providerRun", "storage"].every((field) => typeof allowedUse[field] === "boolean")
        || !Array.isArray(value.allowedContactChannels)
        || value.allowedContactChannels.some((channel: unknown) => !SIGNALDESK_OUTBOUND_CHANNELS.has(channel as SignalDeskOutboundChannel) && channel !== "manual")
        || new Set(value.allowedContactChannels).size !== value.allowedContactChannels.length
        || allowedUse.contact !== (value.allowedContactChannels.length > 0)
        || !Number.isInteger(value.retentionDays)
        || value.retentionDays < 1
        || value.retentionDays > 365
        || !SIGNALDESK_SOURCE_ACCESS_METHODS.has(accessMethod)
        || !isBoundedSeedTextArray(value.allowedFields, 1, 30, 80)
        || !isBoundedSeedTextArray(value.attributionRequirements, 0, 10, 240)
        || !isBoundedSeedTextArray(value.blockedFields, 0, 30, 80)
        || !isBoundedSeedText(value.policyOwner, 2, 180)
        || !isBoundedSeedTextArray(value.prohibitedUses, 1, 20, 240)
        || !SIGNALDESK_SOURCE_RAW_PAYLOAD_POLICIES.has(rawPayloadPolicy)
        || !SIGNALDESK_SOURCE_REFRESH_METHODS.has(refreshMethod)
        || (sourceType === "provider" ? !SIGNALDESK_PROVIDER_IDS.has(provider as SignalDeskProviderId) : Boolean(provider))
        || !Boolean(toTimestampMillis(value.lastReviewedAt))
        || !approvedAt
        || !expiresAt
        || expiresAt <= approvedAt
        || !termsUrlValid
        || (value.termsVersion != null && !isBoundedSeedText(value.termsVersion, 1, 120))
        || (value.notes != null && !isBoundedSeedText(value.notes, 1, 500))
        || (!normalizeText(value.termsUrl) && !normalizeText(value.notes))
        || !hasValidSeedMetadata(value)
    ) throw new Error("SOURCE_POLICY_SHAPE_INVALID");
};

const isExactLegacySeedSourcePolicy = (
    value: AnyRecord,
    expected: AnyRecord,
    ref: FirebaseFirestore.DocumentReference,
) => {
    if (value.allowedContactChannels !== undefined || !hasValidSeedMetadata(value)) return false;
    const expectedKeys = Object.keys(expected).filter((key) => key !== "allowedContactChannels").sort();
    if (JSON.stringify(Object.keys(value).sort()) !== JSON.stringify(expectedKeys)) return false;
    if (value.sourcePolicyId !== ref.id || value.pId !== SIGNALDESK_PRODUCT_CODE) return false;
    const nonLogicalKeys = new Set(["approvedAt", "createdAt", "expiresAt", "lastReviewedAt", "policyOwner", "updatedAt", "updatedBy"]);
    return expectedKeys.every((key) => nonLogicalKeys.has(key) || JSON.stringify(value[key]) === JSON.stringify(expected[key]));
};

const assertSeedTemplate = (value: AnyRecord, ref: FirebaseFirestore.DocumentReference) => {
    assertSeedDocumentIdentity(value, ref, "templateId", "TEMPLATE_PRODUCT_MISMATCH", "TEMPLATE_SHAPE_INVALID");
    const channel = normalizeText(value.channel) as SignalDeskOutboundChannel;
    if (
        !isBoundedSeedText(value.name, 2, 120)
        || !SIGNALDESK_OUTBOUND_CHANNELS.has(channel)
        || !["active", "inactive"].includes(normalizeText(value.status))
        || !isBoundedSeedTextArray(value.approvedVariables, 1, 30, 80)
        || (value.subject != null && !isBoundedSeedText(value.subject, 1, 240))
        || !isBoundedSeedText(value.body, 2, 5000)
        || !hasValidSeedMetadata(value)
    ) throw new Error("TEMPLATE_SHAPE_INVALID");
};

const assertSeedProviderAccount = (value: AnyRecord, ref: FirebaseFirestore.DocumentReference) => {
    assertSeedDocumentIdentity(value, ref, "providerAccountId", "PROVIDER_ACCOUNT_PRODUCT_MISMATCH", "PROVIDER_ACCOUNT_SHAPE_INVALID");
    const provider = normalizeText(value.provider) as SignalDeskProviderId;
    const use = normalizeText(value.use) as SignalDeskProviderUse;
    const status = normalizeText(value.status) as SignalDeskProviderAccountSummary["status"];
    const credentialState = normalizeText(value.credentialState) as SignalDeskProviderAccountSummary["credentialState"];
    if (
        !SIGNALDESK_PROVIDER_IDS.has(provider)
        || !SIGNALDESK_PROVIDER_USES.has(use)
        || ref.id !== providerAccountIdFor(provider, use)
        || !SIGNALDESK_PROVIDER_STATUSES.has(status)
        || !SIGNALDESK_PROVIDER_CREDENTIAL_STATES.has(credentialState)
        || typeof value.ownerApproved !== "boolean"
        || !isSeedMoney(value.dailyBudgetUsd, 10000)
        || !isSeedMoney(value.monthlyBudgetUsd, 100000)
        || !isSeedMoney(value.perRunBudgetUsd, 1000)
        || !isSeedMoney(value.spentTodayUsd, Number.MAX_SAFE_INTEGER)
        || !isSeedMoney(value.spentMonthUsd, Number.MAX_SAFE_INTEGER)
        || (value.disabledReason != null && !isBoundedSeedText(value.disabledReason, 1, 500))
        || !hasValidSeedMetadata(value)
    ) throw new Error("PROVIDER_ACCOUNT_SHAPE_INVALID");
};

const assertSeedBudgetPolicy = (value: AnyRecord, ref: FirebaseFirestore.DocumentReference) => {
    assertSeedDocumentIdentity(value, ref, "budgetPolicyId", "BUDGET_POLICY_PRODUCT_MISMATCH", "BUDGET_POLICY_SHAPE_INVALID");
    const scope = normalizeText(value.scope) as SignalDeskBudgetPolicySummary["scope"];
    const provider = normalizeText(value.provider) as SignalDeskProviderId | "";
    const scopeId = normalizeText(value.scopeId);
    if (
        !isBoundedSeedText(value.name, 2, 120)
        || !SIGNALDESK_BUDGET_SCOPES.has(scope)
        || (provider && !SIGNALDESK_PROVIDER_IDS.has(provider as SignalDeskProviderId))
        || (value.provider != null && !provider)
        || (value.scopeId != null && !isBoundedSeedText(value.scopeId, 1, 160))
        || ref.id !== budgetPolicyIdFor(scope, provider || null, scopeId || null)
        || !CONTENT_SOURCE_STATUSES.has(normalizeText(value.status) as SignalDeskControlStatus)
        || !isSeedMoney(value.dailyBudgetUsd, 10000)
        || !isSeedMoney(value.monthlyBudgetUsd, 100000)
        || !isSeedMoney(value.perRunBudgetUsd, 1000)
        || !isSeedMoney(value.spentTodayUsd, Number.MAX_SAFE_INTEGER)
        || !isSeedMoney(value.spentMonthUsd, Number.MAX_SAFE_INTEGER)
        || !hasValidSeedMetadata(value)
    ) throw new Error("BUDGET_POLICY_SHAPE_INVALID");
};

const assertSeedModelRoute = (value: AnyRecord, ref: FirebaseFirestore.DocumentReference) => {
    assertSeedDocumentIdentity(value, ref, "modelRouteId", "MODEL_ROUTE_PRODUCT_MISMATCH", "MODEL_ROUTE_SHAPE_INVALID");
    const task = normalizeText(value.task) as SignalDeskAiTask;
    const defaultProvider = normalizeText(value.defaultProvider) as SignalDeskModelRouteSummary["defaultProvider"];
    const escalationProvider = normalizeText(value.escalationProvider) as SignalDeskModelRouteSummary["defaultProvider"] | "";
    const escalationModel = normalizeText(value.escalationModel);
    if (
        !SIGNALDESK_AI_TASKS.has(task)
        || ref.id !== `model_route_${task}`
        || !CONTENT_SOURCE_STATUSES.has(normalizeText(value.status) as SignalDeskControlStatus)
        || !SIGNALDESK_AI_PROVIDERS.has(defaultProvider)
        || !isBoundedSeedText(value.defaultModel, 2, 120)
        || Boolean(escalationProvider) !== Boolean(escalationModel)
        || (escalationProvider && !SIGNALDESK_AI_PROVIDERS.has(escalationProvider))
        || (escalationModel && !isBoundedSeedText(value.escalationModel, 2, 120))
        || !SIGNALDESK_CONFIDENCE_VALUES.has(normalizeText(value.confidenceThreshold) as SignalDeskConfidence)
        || !isSeedMoney(value.maxCostUsd, 100)
        || !hasValidSeedMetadata(value, true)
    ) throw new Error("MODEL_ROUTE_SHAPE_INVALID");
};

const assertSeedMarketPod = (value: AnyRecord, ref: FirebaseFirestore.DocumentReference) => {
    assertSeedDocumentIdentity(value, ref, "marketPodId", "MARKET_POD_PRODUCT_MISMATCH", "MARKET_POD_SHAPE_INVALID");
    const projected = projectSignalDeskMarketPod({
        ...value,
        [`${SIGNALDESK_COLLECTIONS.MARKET_PODS}DocId`]: ref.id,
    });
    if (!projected || !hasValidSeedMetadata(value)) throw new Error("MARKET_POD_SHAPE_INVALID");
    return projected;
};

const assertSeedAudienceSegment = (value: AnyRecord, ref: FirebaseFirestore.DocumentReference) => {
    assertSeedDocumentIdentity(value, ref, "audienceSegmentId", "AUDIENCE_SEGMENT_PRODUCT_MISMATCH", "AUDIENCE_SEGMENT_SHAPE_INVALID");
    if (
        !isBoundedSeedText(value.name, 2, 120)
        || !CONTENT_SOURCE_STATUSES.has(normalizeText(value.status) as SignalDeskControlStatus)
        || (value.marketPodId != null && !isBoundedSeedText(value.marketPodId, 1, 160))
        || !SIGNALDESK_AUDIENCE_TRIGGERS.has(normalizeText(value.triggerType) as SignalDeskAudienceSegmentSummary["triggerType"])
        || !isBoundedSeedText(value.criteriaSummary, 2, 500)
        || (value.sourcePolicyId != null && !isBoundedSeedText(value.sourcePolicyId, 1, 160))
        || !hasValidSeedMetadata(value)
    ) throw new Error("AUDIENCE_SEGMENT_SHAPE_INVALID");
};

const assertSeedOfferCta = (value: AnyRecord, ref: FirebaseFirestore.DocumentReference) => {
    assertSeedDocumentIdentity(value, ref, "offerCtaId", "OFFER_CTA_PRODUCT_MISMATCH", "OFFER_CTA_SHAPE_INVALID");
    const projected = projectSignalDeskOfferCta({
        ...value,
        [`${SIGNALDESK_COLLECTIONS.OFFER_CTAS}DocId`]: ref.id,
    });
    if (!projected || !hasValidSeedMetadata(value)) throw new Error("OFFER_CTA_SHAPE_INVALID");
    return projected;
};

const assertSeedReplyPlaybook = (value: AnyRecord, ref: FirebaseFirestore.DocumentReference) => {
    assertSeedDocumentIdentity(value, ref, "playbookId", "REPLY_PLAYBOOK_PRODUCT_MISMATCH", "REPLY_PLAYBOOK_SHAPE_INVALID");
    if (
        !isBoundedSeedText(value.approvedReply, 5, 1000)
        || typeof value.escalationRequired !== "boolean"
        || !SIGNALDESK_REPLY_INTENTS.has(normalizeText(value.intent) as SignalDeskReplyPlaybookSummary["intent"])
        || !SIGNALDESK_REPLY_ROUTES.has(normalizeText(value.nextRoute) as SignalDeskReplyPlaybookSummary["nextRoute"])
        || !CONTENT_SOURCE_STATUSES.has(normalizeText(value.status) as SignalDeskControlStatus)
        || typeof value.suppressionRequired !== "boolean"
        || !isBoundedSeedText(value.title, 2, 160)
        || !hasValidSeedMetadata(value)
    ) throw new Error("REPLY_PLAYBOOK_SHAPE_INVALID");
};

const assertSeedWaterfall = (value: AnyRecord, ref: FirebaseFirestore.DocumentReference) => {
    assertSeedDocumentIdentity(value, ref, "waterfallId", "ENRICHMENT_WATERFALL_PRODUCT_MISMATCH", "ENRICHMENT_WATERFALL_SHAPE_INVALID");
    if (
        !isBoundedSeedText(value.name, 2, 120)
        || !SIGNALDESK_WATERFALL_FIELDS.has(normalizeText(value.requestedField) as SignalDeskEnrichmentWaterfallSummary["requestedField"])
        || !Array.isArray(value.providerOrder)
        || value.providerOrder.length < 1
        || value.providerOrder.length > 12
        || new Set(value.providerOrder).size !== value.providerOrder.length
        || !value.providerOrder.every((provider: unknown) => SIGNALDESK_PROVIDER_IDS.has(normalizeText(provider) as SignalDeskProviderId))
        || !CONTENT_SOURCE_STATUSES.has(normalizeText(value.status) as SignalDeskControlStatus)
        || !Number.isInteger(value.maxCredits)
        || value.maxCredits < 1
        || value.maxCredits > 50
        || !isSeedMoney(value.maxCostUsd, 1000)
        || !SIGNALDESK_WATERFALL_STOP_CONDITIONS.has(normalizeText(value.stopCondition) as SignalDeskEnrichmentWaterfallSummary["stopCondition"])
        || typeof value.verificationRequired !== "boolean"
        || (value.sourcePolicyId != null && !isBoundedSeedText(value.sourcePolicyId, 1, 160))
        || !Number.isInteger(value.retentionDays)
        || value.retentionDays < 1
        || value.retentionDays > 365
        || !hasValidSeedMetadata(value)
    ) throw new Error("ENRICHMENT_WATERFALL_SHAPE_INVALID");
};

const assertSeedContentSource = (value: AnyRecord, ref: FirebaseFirestore.DocumentReference) => {
    assertSeedDocumentIdentity(value, ref, "contentSourceId", "CONTENT_SOURCE_PRODUCT_MISMATCH", "CONTENT_SOURCE_SHAPE_INVALID");
    const projected = projectSignalDeskContentSource({
        ...value,
        [`${SIGNALDESK_COLLECTIONS.CONTENT_SOURCES}DocId`]: ref.id,
    });
    if (
        !projected
        || !hasValidSeedMetadata(value)
        || projected.sourceType !== "proof-page"
        || projected.sourceUrl !== canonicalizeContentUrl("https://menulist.ai")
    ) throw new Error("CONTENT_SOURCE_SHAPE_INVALID");
    return projected;
};

const EXACT_LEGACY_MODEL_ROUTE_KEYS = [
    "confidenceThreshold", "createdAt", "defaultModel", "defaultProvider", "escalationModel", "escalationProvider",
    "maxCostUsd", "modelRouteId", "pId", "status", "task", "updatedAt", "updatedBy",
] as const;

const isExactLegacyModelRoute = (value: AnyRecord, task: SignalDeskAiTask) => (
    (task === "score" || task === "evidence")
    && hasOnlySeedKeys(value, EXACT_LEGACY_MODEL_ROUTE_KEYS)
    && value.modelRouteId === `model_route_${task}`
    && value.pId === SIGNALDESK_PRODUCT_CODE
    && value.task === task
    && value.status === "active"
    && value.defaultProvider === "gemini"
    && value.defaultModel === SIGNALDESK_DEFAULT_AI_MODEL
    && value.escalationProvider === "openai"
    && value.escalationModel === "gpt-5-mini"
    && value.confidenceThreshold === "medium"
    && value.maxCostUsd === 0.05
    && hasValidSeedMetadata(value)
);

const EXACT_LEGACY_MARKET_POD_KEYS = [
    "category", "city", "country", "createdAt", "marketPodId", "monthlyBudgetUsd", "name", "offerAngle",
    "pId", "status", "successMetric", "updatedAt", "updatedBy",
] as const;

const isExactLegacyMarketPod = (value: AnyRecord, ref: FirebaseFirestore.DocumentReference) => (
    hasOnlySeedKeys(value, EXACT_LEGACY_MARKET_POD_KEYS)
    && value.marketPodId === ref.id
    && value.pId === SIGNALDESK_PRODUCT_CODE
    && value.status === "hold"
    && value.name === "First local proof pod"
    && value.city === "Mumbai"
    && value.country === "India"
    && value.category === "restaurant"
    && value.offerAngle === "Current-list proof and private preview."
    && value.monthlyBudgetUsd === 300
    && value.successMetric === "preview_prepared"
    && hasValidSeedMetadata(value)
);

const EXACT_LEGACY_OFFER_CTA_KEYS = [
    "activationSurface", "approvedAsk", "blockedClaims", "createdAt", "ctaId", "marketPodId", "offerCtaId", "pId",
    "proofMatchRule", "segment", "status", "title", "updatedAt", "updatedBy",
] as const;

const isExactLegacyOfferCta = (
    value: AnyRecord,
    offerCtaRef: FirebaseFirestore.DocumentReference,
    ctaId: string,
    marketPodId: string,
) => (
    hasOnlySeedKeys(value, EXACT_LEGACY_OFFER_CTA_KEYS)
    && value.offerCtaId === offerCtaRef.id
    && value.pId === SIGNALDESK_PRODUCT_CODE
    && value.title === "Current list upload and private preview"
    && value.segment === "restaurant-owner"
    && value.activationSurface === "upload"
    && value.approvedAsk === "Upload the current menu or service list so MenuList can prepare a private preview for review before publishing."
    && JSON.stringify(value.blockedClaims) === JSON.stringify(["AI will increase sales", "Guaranteed Google ranking", "Fully automatic public publishing"])
    && value.ctaId === ctaId
    && value.marketPodId === marketPodId
    && value.proofMatchRule === "Use only with owned MenuList proof or a target evidence packet showing a current-list gap."
    && value.status === "active"
    && hasValidSeedMetadata(value)
);

