export async function upsertSignalDeskSenderDomainServer(access: SignalDeskAccessContext, input: SenderDomainInput) {
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) {
        throw new Error("SENDER_DOMAIN_IDEMPOTENCY_KEY_REQUIRED");
    }
    const domain = canonicalizeSenderDomain(input.domain);
    const senderRef = db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(senderDomainIdFor(domain));
    const requestFingerprintHash = hashValue(JSON.stringify({
        authenticationState: input.authenticationState,
        bounceRate: input.bounceRate,
        brandRisk: input.brandRisk,
        complaintRate: input.complaintRate,
        domain,
        provider: input.provider || null,
        status: input.status,
        unsubscribeReady: input.unsubscribeReady,
        volumeRampState: input.volumeRampState,
    }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`sender_domain_${operationHash}`);

    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const [claimSnap, senderSnap] = await Promise.all([
            transaction.get(claimRef),
            transaction.get(senderRef),
        ]);
        if (claimSnap.exists) {
            const claim = toPlain(claimSnap.data()) as AnyRecord;
            if (
                normalizeText(claim.pId) !== SIGNALDESK_PRODUCT_CODE
                || claim.operation !== "sender_domain_upsert"
                || claim.entityId !== senderRef.id
                || claim.requestFingerprintHash !== requestFingerprintHash
            ) {
                throw new Error("SENDER_DOMAIN_IDEMPOTENCY_CONFLICT");
            }
            const replay = projectSignalDeskSenderDomain({
                ...(claim.result || {}),
                pId: SIGNALDESK_PRODUCT_CODE,
                [`${SIGNALDESK_COLLECTIONS.SENDER_DOMAINS}DocId`]: senderRef.id,
            });
            if (!replay) throw new Error("SENDER_DOMAIN_REPLAY_MISSING");
            return replay;
        }
        const current = senderSnap.exists ? toPlain(senderSnap.data()) as AnyRecord : null;
        if (current && normalizeText(current.pId) !== SIGNALDESK_PRODUCT_CODE) {
            throw new Error("SENDER_DOMAIN_PRODUCT_MISMATCH");
        }
        if (current && !projectSenderDomainDocument(senderSnap)) {
            throw new Error("SENDER_DOMAIN_SHAPE_INVALID");
        }
        const timestamp = now();
        const sender = {
            senderDomainId: senderRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            domain,
            status: input.status,
            provider: input.provider || null,
            authenticationState: input.authenticationState,
            volumeRampState: input.volumeRampState,
            bounceRate: input.bounceRate,
            complaintRate: input.complaintRate,
            unsubscribeReady: input.unsubscribeReady,
            brandRisk: input.brandRisk,
            createdAt: current?.createdAt || timestamp,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        const projected = projectSignalDeskSenderDomain({
            ...toPlain(sender),
            [`${SIGNALDESK_COLLECTIONS.SENDER_DOMAINS}DocId`]: senderRef.id,
        });
        if (!projected) throw new Error("SENDER_DOMAIN_SHAPE_INVALID");
        transaction.set(senderRef, sanitizeForFirestore(sender));
        transaction.create(claimRef, sanitizeForFirestore({
            actorId: access.userId,
            entityId: senderRef.id,
            operation: "sender_domain_upsert",
            pId: SIGNALDESK_PRODUCT_CODE,
            requestFingerprintHash,
            result: projected,
            updatedAt: timestamp,
        }));
        appendAudit(db, transaction, access, "sender_domain_upsert", "senderDomain", senderRef.id, domain);
        updateDailyCost(db, transaction, 2, 0);
        return projected;
    });
}

export async function upsertSignalDeskConnectorSettingServer(access: SignalDeskAccessContext, input: ConnectorSettingInput) {
    const db = requireDb();
    const batch = db.batch();
    const timestamp = now();
    const runtime = resolveConnectorRuntime(input);
    const connectorRef = db.collection(SIGNALDESK_COLLECTIONS.CONNECTOR_SETTINGS).doc(connectorIdFor(input));
    const connector = {
        connectorId: connectorRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        connectorKind: input.connectorKind,
        displayName: input.displayName,
        status: input.status,
        channel: runtime.channel,
        provider: runtime.provider,
        senderEmail: normalizeLower(input.senderEmail) || null,
        replyToEmail: normalizeLower(input.replyToEmail) || null,
        fromName: normalizeText(input.fromName) || null,
        senderDomain: normalizeLower(input.senderDomain) || null,
        phoneNumber: normalizeText(input.phoneNumber) || null,
        phoneNumberId: normalizeText(input.phoneNumberId) || null,
        instagramPageId: normalizeText(input.instagramPageId) || null,
        messengerPageId: normalizeText(input.messengerPageId) || null,
        appId: normalizeText(input.appId) || null,
        accessTokenState: runtime.accessTokenState,
        apiKeyState: runtime.apiKeyState,
        appSecretState: runtime.appSecretState,
        envReadiness: runtime.envReadiness,
        missingEnv: runtime.missingEnv,
        notes: normalizeText(input.notes) || null,
        smtpCredentialState: runtime.smtpCredentialState,
        webhookSecretState: runtime.webhookSecretState,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };

    batch.set(connectorRef, sanitizeForFirestore(connector), { merge: true });
    if (runtime.channel !== "sequencer" && runtime.channel !== "source") {
        batch.set(db.collection(SIGNALDESK_COLLECTIONS.CHANNEL_HEALTH_SUMMARIES).doc(runtime.channel), sanitizeForFirestore({
            channel: runtime.channel,
            configured: input.status === "active" && runtime.envReadiness === "ready",
            lastError: runtime.missingEnv.length ? `Missing ${runtime.missingEnv.join(", ")}` : null,
            status: channelHealthStatusForConnector(input.status, runtime.envReadiness),
            updatedAt: timestamp,
        }), { merge: true });
    }
    appendAudit(db, batch, access, "connector_setting_upsert", "connectorSetting", connectorRef.id, `${input.connectorKind} ${runtime.envReadiness}`);
    updateControlSummary(db, batch, runtime.channel === "source"
        ? { sourceStatus: runtime.envReadiness === "ready" && input.status === "active" ? "healthy" : "warning" }
        : { channelStatus: runtime.envReadiness === "ready" && input.status === "active" ? "healthy" : "warning" });
    updateDailyCost(db, batch, runtime.channel === "sequencer" ? 3 : 4, 0, 0);
    await batch.commit();

    return toPlain(connector) as SignalDeskConnectorSettingSummary;
}

export async function upsertSignalDeskTeamMemberServer(access: SignalDeskAccessContext, input: TeamMemberInput) {
    const db = requireDb();
    const emailLower = normalizeLower(input.email);
    const userId = normalizeText(input.userId) || null;
    const teamMemberId = normalizeText(input.teamMemberId);

    if (!emailLower || !emailLower.includes("@")) {
        throw new Error("SignalDesk team member email is required");
    }
    if (!input.active && (
        (userId && userId === access.userId)
        || emailLower === normalizeLower(access.email)
        || teamMemberId === access.userId
    )) {
        throw new Error("SignalDesk team member cannot deactivate own access");
    }

    const explicitSnap = teamMemberId
        ? await db.collection(SIGNALDESK_COLLECTIONS.TEAM_MEMBERS).doc(teamMemberId).get()
        : null;
    const userSnap = !explicitSnap?.exists && userId
        ? await db.collection(SIGNALDESK_COLLECTIONS.TEAM_MEMBERS).doc(userId).get()
        : null;
    const emailSnap = !explicitSnap?.exists && !userSnap?.exists
        ? await db.collection(SIGNALDESK_COLLECTIONS.TEAM_MEMBERS)
            .where("emailLower", "==", emailLower)
            .limit(1)
            .get()
        : null;

    const existingSnap = explicitSnap?.exists
        ? explicitSnap
        : userSnap?.exists
            ? userSnap
            : emailSnap?.docs?.[0] || null;
    const memberRef = existingSnap?.ref || db.collection(SIGNALDESK_COLLECTIONS.TEAM_MEMBERS)
        .doc(userId || `member_${hashValue(emailLower).slice(0, 24)}`);
    const existing = existingSnap?.exists ? toPlain(existingSnap.data()) : {};
    const timestamp = now();
    const preservedPermissions = Array.isArray(existing.permissions)
        ? existing.permissions.filter((permission: unknown): permission is SignalDeskPermission => typeof permission === "string")
        : [];
    const member = {
        teamMemberId: memberRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        userId,
        email: emailLower,
        emailLower,
        name: normalizeText(input.name) || null,
        role: input.role,
        permissions: preservedPermissions,
        active: input.active,
        status: input.active ? "active" : "inactive",
        createdAt: existing.createdAt || timestamp,
        createdBy: existing.createdBy || access.userId,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };

    const batch = db.batch();
    batch.set(memberRef, sanitizeForFirestore(member), { merge: true });
    appendAudit(
        db,
        batch,
        access,
        input.active ? "team_member_upsert" : "team_member_deactivate",
        "teamMember",
        memberRef.id,
        `${member.email} / ${member.role}`,
    );
    updateDailyCost(db, batch, 2, 0);
    await batch.commit();
    return toPlain(member) as SignalDeskTeamMemberSummary;
}

export async function upsertSignalDeskSelfServiceCtaServer(access: SignalDeskAccessContext, input: SelfServiceCtaInput) {
    requireContentDistributionRail();
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("CONTENT_CTA_IDEMPOTENCY_KEY_REQUIRED");
    const ctaRef = db.collection(SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS).doc(selfServiceCtaIdFor(input.ctaType));
    let previewMigration: PreviewCtaIdentityMigrationResult | null = null;
    if (input.ctaType === "preview") {
        const knownPreviewRefs = [
            ctaRef,
            ...SIGNALDESK_LEGACY_PREVIEW_CTA_IDS.map((legacyId) => (
                db.collection(SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS).doc(legacyId)
            )),
        ];
        const knownPreviewSnaps = await Promise.all(knownPreviewRefs.map((ref) => ref.get()));
        if (knownPreviewSnaps.some((snap) => snap.exists)) {
            previewMigration = await migrateSignalDeskPreviewCtaIdentity(db, access, {
                createIfMissing: false,
                rejectAmbiguous: false,
            });
        }
    }
    const requestFingerprintHash = hashValue(JSON.stringify({
        copy: normalizeText(input.copy),
        ctaType: input.ctaType,
        label: normalizeText(input.label),
        status: input.status,
    }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`content_cta_${operationHash}`);
    await resumePendingContentAuthorityReconciliation(db, access, {
        action: "self_service_cta_dependency_reconcile_recovery",
        assetField: "ctaId",
        assetValue: ctaRef.id,
        authorityRef: ctaRef,
        entityType: "selfServiceCta",
        reason: "CTA authority changed. Review and regenerate the draft before distribution.",
        shouldHoldAsset: () => true,
    });
    const transactionResult = await db.runTransaction(async (transaction) => {
        const pauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_content-distribution");
        const activePreviewQuery = input.ctaType === "preview"
            ? db.collection(SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS)
                .where("ctaType", "==", "preview")
                .where("status", "==", "active")
                .limit(3)
            : null;
        const [claimSnap, existingSnap, pauseSnap, activePreviewSnap] = await Promise.all([
            transaction.get(claimRef),
            transaction.get(ctaRef),
            transaction.get(pauseRef),
            activePreviewQuery ? transaction.get(activePreviewQuery) : Promise.resolve(null),
        ]);
        const existingData = existingSnap.exists ? existingSnap.data() as AnyRecord : null;
        if (existingData && normalizeText(existingData.pId) !== SIGNALDESK_PRODUCT_CODE) {
            throw new Error("CONTENT_CTA_PRODUCT_MISMATCH");
        }
        if (activePreviewSnap) {
            const nonAuthoritativeActive = activePreviewSnap.docs.find((doc) => doc.id !== ctaRef.id);
            if (nonAuthoritativeActive) {
                if (normalizeText(nonAuthoritativeActive.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
                    throw new Error("CONTENT_CTA_PRODUCT_MISMATCH");
                }
                throw new Error("CONTENT_CTA_ACTIVE_AMBIGUOUS");
            }
        }
        const existing = existingData ? projectSignalDeskSelfServiceCta({
            ...toPlain(existingData),
            [`${SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS}DocId`]: ctaRef.id,
        }) : null;
        if (existingData && !existing) throw new Error("CONTENT_CTA_SHAPE_INVALID");
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) {
                throw new Error("CONTENT_CTA_IDEMPOTENCY_CONFLICT");
            }
            if (!existing) throw new Error("CONTENT_CTA_REPLAY_MISSING");
            const replayReconciliationToken = normalizeText(existingData?.dependentHoldReconciliationToken);
            return {
                applied: false,
                cta: existing,
                reconciliationRequired: existingData?.dependentHoldReconciliationPending === true
                    && replayReconciliationToken === claimRef.id,
                reconciliationToken: replayReconciliationToken,
            };
        }
        if (pauseSnap.data()?.status === "active" && input.status === "active") {
            throw new Error("Content distribution is paused");
        }
        if (existingData?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        const timestamp = now();
        const cta = {
            ctaId: ctaRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            label: normalizeText(input.label),
            ctaType: input.ctaType,
            status: input.status,
            copy: normalizeText(input.copy),
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        const projectedCta = projectSignalDeskSelfServiceCta({
            ...toPlain(cta),
            [`${SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS}DocId`]: ctaRef.id,
        });
        if (!projectedCta) throw new Error("CONTENT_CTA_SHAPE_INVALID");
        const reconciliationRequired = Boolean(existing && (
            existing.copy !== projectedCta.copy
            || existing.ctaType !== projectedCta.ctaType
            || existing.label !== projectedCta.label
            || existing.status !== projectedCta.status
        ));
        const reconciliationToken = reconciliationRequired ? claimRef.id : "";
        transaction.set(ctaRef, sanitizeForFirestore({
            ...cta,
            dependentHoldReconciliationKind: reconciliationRequired
                ? CONTENT_AUTHORITY_RECONCILIATION_KIND
                : null,
            dependentHoldReconciliationPending: reconciliationRequired,
            dependentHoldReconciliationProgress: reconciliationRequired
                ? emptyContentAuthorityReconciliationResult()
                : null,
            dependentHoldReconciliationToken: reconciliationToken || null,
        }), { merge: true });
        transaction.create(claimRef, sanitizeForFirestore({
            actorId: access.userId,
            entityId: ctaRef.id,
            operation: "self_service_cta_upsert",
            pId: SIGNALDESK_PRODUCT_CODE,
            requestFingerprintHash,
            resultSnapshot: { ...toPlain(projectedCta), pId: SIGNALDESK_PRODUCT_CODE },
            updatedAt: timestamp,
        }));
        appendAudit(db, transaction, access, "self_service_cta_upsert", "selfServiceCta", ctaRef.id, input.label);
        updateDailyCost(db, transaction, 3, 0);
        return { applied: true, cta: projectedCta, reconciliationRequired, reconciliationToken };
    });
    if (transactionResult.reconciliationRequired) {
        if (!transactionResult.reconciliationToken) throw new Error("CONTENT_AUTHORITY_RECONCILIATION_TOKEN_MISSING");
        const reconciliationResult = await reconcileContentAuthorityHolds(db, {
            actorId: access.userId,
            assetField: "ctaId",
            assetValue: ctaRef.id,
            authorityRef: ctaRef,
            reason: "CTA authority changed. Review and regenerate the draft before distribution.",
            reconciliationToken: transactionResult.reconciliationToken,
            shouldHoldAsset: () => true,
        });
        await completeContentAuthorityReconciliation(db, access, {
            action: "self_service_cta_dependency_reconcile",
            authorityRef: ctaRef,
            entityType: "selfServiceCta",
            reconciliationToken: transactionResult.reconciliationToken,
        }, reconciliationResult);
    }
    const expectedPreviewFingerprintHash = input.ctaType === "preview"
        ? signalDeskCtaFingerprintHash(transactionResult.cta)
        : "";
    const currentPreviewMatchesRequest = input.ctaType === "preview"
        && transactionResult.cta.copy === normalizeText(input.copy)
        && transactionResult.cta.ctaType === input.ctaType
        && transactionResult.cta.label === normalizeText(input.label)
        && transactionResult.cta.status === input.status;
    if (currentPreviewMatchesRequest) {
        await resolveSignalDeskPreviewCtaIdentityIncident(
            db,
            access,
            previewMigration?.incidentId || null,
            expectedPreviewFingerprintHash,
        );
    }
    return transactionResult.cta;
}

export async function upsertSignalDeskOfferCtaServer(access: SignalDeskAccessContext, input: OfferCtaInput) {
    requireOperatingLayer();
    const db = requireDb();
    const offerRef = db.collection(SIGNALDESK_COLLECTIONS.OFFER_CTAS).doc(input.offerCtaId || offerCtaIdFor(input));
    const preflightSnap = await offerRef.get();
    if (preflightSnap.exists && normalizeText(preflightSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
        throw new Error("OFFER_CTA_PRODUCT_MISMATCH");
    }
    await resumePendingContentAuthorityReconciliation(db, access, {
        action: "offer_cta_dependency_reconcile_recovery",
        assetField: "offerCtaId",
        assetValue: offerRef.id,
        authorityRef: offerRef,
        entityType: "offerCta",
        reason: "Offer authority changed. Review the experiment before continuing.",
        shouldHoldAsset: () => false,
    });
    const reconciliationTokenCandidate = `offer_reconcile_${randomBytes(16).toString("hex")}`;
    const transactionResult = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const existingSnap = await transaction.get(offerRef);
        const existingData = existingSnap.exists ? existingSnap.data() as AnyRecord : null;
        if (existingData && normalizeText(existingData.pId) !== SIGNALDESK_PRODUCT_CODE) {
            throw new Error("OFFER_CTA_PRODUCT_MISMATCH");
        }
        if (existingData?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        const existing = existingData ? projectSignalDeskOfferCta({
            ...toPlain(existingData),
            [`${SIGNALDESK_COLLECTIONS.OFFER_CTAS}DocId`]: offerRef.id,
        }) : null;
        if (existingData && !existing) throw new Error("OFFER_CTA_SHAPE_INVALID");
        const timestamp = now();
        const offerData = {
            activationSurface: input.activationSurface,
            approvedAsk: normalizeText(input.approvedAsk),
            blockedClaims: Array.from(new Set(input.blockedClaims.map(normalizeText).filter(Boolean))),
            createdAt: existingData?.createdAt || timestamp,
            ctaId: normalizeText(input.ctaId) || null,
            marketPodId: normalizeText(input.marketPodId) || null,
            offerCtaId: offerRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            proofMatchRule: normalizeText(input.proofMatchRule),
            segment: input.segment,
            status: input.status,
            title: normalizeText(input.title),
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        const offer = projectSignalDeskOfferCta({
            ...toPlain(offerData),
            [`${SIGNALDESK_COLLECTIONS.OFFER_CTAS}DocId`]: offerRef.id,
        });
        if (!offer) throw new Error("OFFER_CTA_SHAPE_INVALID");
        await readSignalDeskOfferNestedAuthority(db, transaction, offer, offer.status === "active");
        const existingComparable = existing ? {
            activationSurface: existing.activationSurface,
            approvedAsk: existing.approvedAsk,
            blockedClaims: existing.blockedClaims,
            ctaId: existing.ctaId || null,
            marketPodId: existing.marketPodId || null,
            proofMatchRule: existing.proofMatchRule,
            segment: existing.segment,
            status: existing.status,
            title: existing.title,
        } : null;
        const nextComparable = {
            activationSurface: offer.activationSurface,
            approvedAsk: offer.approvedAsk,
            blockedClaims: offer.blockedClaims,
            ctaId: offer.ctaId || null,
            marketPodId: offer.marketPodId || null,
            proofMatchRule: offer.proofMatchRule,
            segment: offer.segment,
            status: offer.status,
            title: offer.title,
        };
        if (existing && existingComparable && JSON.stringify(existingComparable) === JSON.stringify(nextComparable)) {
            return { offer: existing, reconciliationRequired: false, reconciliationToken: "" };
        }
        const reconciliationRequired = Boolean(existingComparable && JSON.stringify(existingComparable) !== JSON.stringify(nextComparable));
        const reconciliationToken = reconciliationRequired ? reconciliationTokenCandidate : "";
        transaction.set(offerRef, sanitizeForFirestore({
            ...offerData,
            authorityHeldAt: null,
            authorityHeldBy: null,
            authorityHoldReason: null,
            dependentHoldReconciliationKind: reconciliationRequired
                ? CONTENT_AUTHORITY_RECONCILIATION_KIND
                : null,
            dependentHoldReconciliationPending: reconciliationRequired,
            dependentHoldReconciliationProgress: reconciliationRequired
                ? emptyContentAuthorityReconciliationResult()
                : null,
            dependentHoldReconciliationToken: reconciliationToken || null,
        }), { merge: true });
        appendAudit(db, transaction, access, "offer_cta_upsert", "offerCta", offerRef.id, offer.title);
        writeRunTimeline(db, transaction, {
            entityId: offerRef.id,
            entityType: "mission",
            label: `Offer CTA: ${offer.title}`,
            status: offer.status === "active" ? "ready" : offer.status === "blocked" ? "blocked" : "held",
            steps: [
                { label: "Approved ask saved", status: "completed", at: toIso(timestamp) },
                { label: "Blocked claims attached", status: offer.blockedClaims.length ? "completed" : "held", at: toIso(timestamp) },
                { label: "Proof match rule attached", status: "completed", at: toIso(timestamp) },
            ],
        });
        updateDailyCost(db, transaction, 4, 0);
        return { offer, reconciliationRequired, reconciliationToken };
    });
    if (transactionResult.reconciliationRequired) {
        const reconciliationResult = await reconcileContentAuthorityHolds(db, {
            actorId: access.userId,
            assetField: "offerCtaId",
            assetValue: offerRef.id,
            authorityRef: offerRef,
            reason: "Offer authority changed. Review the experiment before continuing.",
            reconciliationToken: transactionResult.reconciliationToken,
            shouldHoldAsset: () => false,
        });
        await completeContentAuthorityReconciliation(db, access, {
            action: "offer_cta_dependency_reconcile",
            authorityRef: offerRef,
            entityType: "offerCta",
            reconciliationToken: transactionResult.reconciliationToken,
        }, reconciliationResult);
    }
    return transactionResult.offer;
}

export async function upsertSignalDeskReplyPlaybookServer(access: SignalDeskAccessContext, input: ReplyPlaybookInput) {
    requireOperatingLayer();
    const db = requireDb();
    const batch = db.batch();
    const timestamp = now();
    const playbookRef = db.collection(SIGNALDESK_COLLECTIONS.REPLY_PLAYBOOKS).doc(input.playbookId || replyPlaybookIdFor(input));
    const playbook = {
        playbookId: playbookRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        title: input.title,
        intent: input.intent,
        approvedReply: input.approvedReply,
        nextRoute: input.nextRoute,
        suppressionRequired: input.suppressionRequired,
        escalationRequired: input.escalationRequired,
        status: input.status,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };
    batch.set(playbookRef, sanitizeForFirestore(playbook), { merge: true });
    appendAudit(db, batch, access, "reply_playbook_upsert", "replyPlaybook", playbookRef.id, input.intent);
    writeRunTimeline(db, batch, {
        entityId: playbookRef.id,
        entityType: "mission",
        label: `Reply playbook: ${input.title}`,
        status: input.status === "active" ? "ready" : input.status === "blocked" ? "blocked" : "held",
        steps: [
            { label: "Approved reply saved", status: "completed", at: toIso(timestamp) },
            { label: input.suppressionRequired ? "Suppression route required" : "No suppression route required", status: input.suppressionRequired ? "ready" : "completed", at: toIso(timestamp) },
            { label: input.escalationRequired ? "Founder review required" : "Founder review not required", status: input.escalationRequired ? "held" : "completed", at: toIso(timestamp) },
        ],
    });
    updateDailyCost(db, batch, 4, 0);
    await batch.commit();
    return toPlain(playbook) as SignalDeskReplyPlaybookSummary;
}

export async function qualifySignalDeskRevenueAccountServer(
    access: SignalDeskAccessContext,
    input: RevenueAccountQualificationInput,
) {
    requireRevenueOperatingLayer();
    const db = requireDb();
    const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(input.targetId);
    const accountRef = db.collection(SIGNALDESK_COLLECTIONS.REVENUE_ACCOUNTS).doc(revenueAccountIdFor(input.targetId));
    const opportunityRef = db.collection(SIGNALDESK_COLLECTIONS.COMMERCIAL_OPPORTUNITIES).doc(opportunityIdFor(accountRef.id));
    const summaryRef = db.collection(SIGNALDESK_COLLECTIONS.REVENUE_CONTROL_SUMMARIES).doc(SIGNALDESK_SUMMARY_DOCS.REVENUE);
    const activationOutcomeQuery = db.collection(SIGNALDESK_COLLECTIONS.OUTCOME_SUMMARIES)
        .where("targetId", "==", input.targetId)
        .where("outcomeType", "==", "two_surface_activation");
    const qualification = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const [currentTargetSnap, accountSnap, opportunitySnap] = await Promise.all([
            transaction.get(targetRef),
            transaction.get(accountRef),
            transaction.get(opportunityRef),
        ]);
        if (!currentTargetSnap.exists) throw new Error("Target not found");
        const targetAuthority = parseSignalDeskOutcomeTargetAuthority(
            currentTargetSnap.data(),
            currentTargetSnap.id,
        );
        const currentTarget = targetAuthority.target;
        const sourcePolicySnap = await transaction.get(
            db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(currentTarget.sourcePolicyId),
        );
        const sourcePolicy = readSourcePolicySnapshot(sourcePolicySnap);
        const policyError = sourcePolicyUsabilityError(sourcePolicy, {
            entityId: currentTarget.targetId,
            use: "evidence",
        });
        if (policyError) throw new Error(policyError);
        const activationOutcomes = await readStrictOutcomeSummaryQueryInTransaction(
            db,
            transaction,
            activationOutcomeQuery,
            "revenue-account-qualification",
        );
        const hasTwoSurfaceActivation = activationOutcomes.some(isVerifiedTwoSurfaceOutcome);
        const timestamp = now();
        const existingAccountRaw = accountSnap.exists ? accountSnap.data() as AnyRecord : null;
        const existingOpportunityRaw = opportunitySnap.exists ? opportunitySnap.data() as AnyRecord : null;
        const existingAccount = existingAccountRaw ? toPlain(existingAccountRaw) as SignalDeskRevenueAccountSummary : null;
        const existingOpportunity = existingOpportunityRaw ? toPlain(existingOpportunityRaw) as SignalDeskCommercialOpportunitySummary : null;
        const accountHasIndependentRetention = revenueAccountHasIndependentRetentionBasis(existingAccountRaw);
        if (existingAccountRaw && !accountHasIndependentRetention) {
            assertVerifiedFreshSourceObservation(
                existingAccountRaw,
                targetAuthority.sourceRunId,
                Date.parse(targetAuthority.sourceDataObservedAt),
                "REVENUE_ACCOUNT_FRESH_LINEAGE_REQUIRED",
            );
        }
        const resetAccountTombstone = existingAccountRaw?.sourceDataLifecycleState === "completed"
            && !accountHasIndependentRetention;
        const terminalOpportunity = existingOpportunity?.status === "won" || existingOpportunity?.status === "lost";
        if (existingOpportunityRaw && !terminalOpportunity && !accountHasIndependentRetention) {
            assertVerifiedFreshSourceObservation(
                existingOpportunityRaw,
                targetAuthority.sourceRunId,
                Date.parse(targetAuthority.sourceDataObservedAt),
                "COMMERCIAL_OPPORTUNITY_FRESH_LINEAGE_REQUIRED",
            );
        }
        const resetOpportunityTombstone = existingOpportunityRaw?.sourceDataLifecycleState === "completed"
            && !terminalOpportunity
            && !accountHasIndependentRetention;
        const activated = hasTwoSurfaceActivation;
        const commerciallyEngaged = currentTarget.status === "replied" || currentTarget.status === "converted";
        const hasRecordedOutcome = Boolean(currentTarget.latestOutcomeAt);
        const eligible = currentTarget.suppressionStatus === "clear"
            && currentTarget.contactability !== "blocked"
            && (
                commerciallyEngaged
                || ((currentTarget.segment === "a" || currentTarget.segment === "b") && numberOrZero(currentTarget.fitScore) >= 70)
            );
        const complianceState: SignalDeskRevenueAccountSummary["complianceState"] = currentTarget.suppressionStatus !== "clear"
            ? "suppressed"
            : currentTarget.contactability === "blocked"
                ? "blocked"
                : eligible
                    ? "eligible"
                    : "review-required";
        const engagementState: SignalDeskRevenueAccountSummary["engagementState"] = currentTarget.suppressionStatus !== "clear"
            ? "opted-out"
            : commerciallyEngaged
                ? "replied"
                : currentTarget.status === "contacted"
                    ? "contacted"
                    : currentTarget.contactability === "ready"
                        ? "contactable"
                        : "none";
        const organizationName = normalizeText(input.organizationName) || currentTarget.displayName;
        const accountSourceLifecycle = existingAccountRaw?.sourceDataLifecycleState === "completed"
            && accountHasIndependentRetention
            ? {}
            : activeSourceDataLifecycleForTargetAuthority(targetAuthority);
        const account = {
            ...accountSourceLifecycle,
            activationState: existingAccount?.activationState || (hasRecordedOutcome ? "in-progress" : "not-started"),
            automationState: existingAccount?.automationState || "manual",
            category: currentTarget.category || null,
            city: currentTarget.city || null,
            complianceState,
            country: currentTarget.country || null,
            displayName: currentTarget.displayName,
            engagementState,
            lifecycleStage: activated ? "customer" : eligible ? "opportunity" : "nurture",
            locationType: input.locationType,
            nextAction: activated
                ? "Refresh the activation watch from recorded outcomes."
                : eligible
                    ? "Review commercial fit and standard offer."
                    : "Hold until qualification evidence is sufficient.",
            organizationId: organizationIdFor(organizationName),
            pId: SIGNALDESK_PRODUCT_CODE,
            primaryTargetId: currentTarget.targetId,
            revenueAccountId: accountRef.id,
            targetIds: Array.from(new Set([...(existingAccount?.targetIds || []), currentTarget.targetId])),
            updatedAt: timestamp,
            updatedBy: access.userId,
        };

        transaction.set(accountRef, sanitizeForFirestore(account), { merge: true });
        let opportunity: SignalDeskCommercialOpportunitySummary | null = existingOpportunity;
        const materializeOpportunity = eligible && (!existingOpportunity || resetOpportunityTombstone);
        if (materializeOpportunity) {
            opportunity = {
                commercialOfferId: null,
                currency: null,
                expectedCloseAt: null,
                founderAttentionMinutes: 0,
                nextAction: activated ? "Refresh activation and proof state." : "Confirm the standard offer and next customer action.",
                nextActionDueAt: null,
                opportunityId: opportunityRef.id,
                probabilityPercent: activated ? 100 : commerciallyEngaged ? 40 : 20,
                revenueAccountId: accountRef.id,
                stage: activated ? "won" : "qualified",
                stalledReason: null,
                status: activated ? "won" : "open",
                targetId: currentTarget.targetId,
                title: `${currentTarget.displayName} - MenuList standard path`,
                updatedAt: toIso(timestamp),
                valueMinor: 0,
                winLossReason: activated ? "Existing two-surface activation outcome." : null,
            };
            transaction.set(opportunityRef, sanitizeForFirestore({
                ...opportunity,
                ...activeSourceDataLifecycleForTargetAuthority(targetAuthority),
                pId: SIGNALDESK_PRODUCT_CODE,
                createdAt: existingOpportunityRaw?.createdAt || timestamp,
                updatedAt: timestamp,
                updatedBy: access.userId,
            }));
        } else if (existingOpportunity && !terminalOpportunity && existingOpportunityRaw?.sourceDataLifecycleState !== "completed") {
            transaction.set(opportunityRef, sanitizeForFirestore({
                ...activeSourceDataLifecycleForTargetAuthority(targetAuthority),
                updatedAt: timestamp,
                updatedBy: access.userId,
            }), { merge: true });
        }
        transaction.set(summaryRef, sanitizeForFirestore({
            activatedAccountCount: increment(0),
            founderAttentionMinutes: increment(0),
            lostOpportunityCount: increment(0),
            openOpportunityCount: increment(materializeOpportunity && !activated ? 1 : 0),
            pId: SIGNALDESK_PRODUCT_CODE,
            pipelineValueMinor: increment(0),
            revenueAccountCount: increment(existingAccount ? 0 : 1),
            revenueControlSummaryId: summaryRef.id,
            stalledActivationCount: increment(0),
            updatedAt: timestamp,
            weightedPipelineValueMinor: increment(0),
            wonOpportunityCount: increment(materializeOpportunity && activated ? 1 : 0),
        }), { merge: true });
        appendAudit(db, transaction, access, "revenue_account_qualify", "revenueAccount", accountRef.id, activated ? "activated" : eligible ? "qualified" : complianceState);
        writeRunTimeline(db, transaction, {
            entityId: accountRef.id,
            entityType: "revenue-account",
            label: "Revenue account qualification",
            status: activated ? "completed" : eligible ? "ready" : complianceState === "suppressed" || complianceState === "blocked" ? "blocked" : "held",
            steps: [
                { label: "Existing target linked", status: "completed", at: toIso(timestamp) },
                { label: "Source policy checked", status: "completed", at: toIso(timestamp) },
                { label: activated ? "Existing two-surface activation preserved" : eligible ? "Commercial qualification passed" : "Commercial qualification held", status: activated || eligible ? "completed" : "held", at: toIso(timestamp) },
            ],
        });
        updateDailyCost(db, transaction, materializeOpportunity ? 6 : 5, 0);
        return {
            account: toPlain(account) as SignalDeskRevenueAccountSummary,
            hasRecordedOutcome,
            hasTwoSurfaceActivation,
            opportunity: opportunity ? toPlain(opportunity) : null,
            qualified: eligible,
        };
    }).catch(async (error: unknown) => {
        const code = error instanceof Error ? error.message : "";
        if ([SOURCE_POLICY_EXPIRED, SOURCE_POLICY_REVIEW_REQUIRED, SOURCE_POLICY_RETENTION_MISSING, SOURCE_POLICY_USE_NOT_ALLOWED].includes(code)) {
            await appendSourcePolicyBlockedAudit(db, access, null, { entityId: input.targetId, use: "evidence" }, code);
        }
        throw error;
    });
    const { hasRecordedOutcome, hasTwoSurfaceActivation, ...qualificationResult } = qualification;
    let activationWatch: SignalDeskActivationWatchSummary | null = null;
    if (hasRecordedOutcome || hasTwoSurfaceActivation) {
        try {
            activationWatch = await refreshSignalDeskActivationWatchServer(access, { targetId: input.targetId });
        } catch (error) {
            logRuntimeFailure(SIGNALDESK_ACTIVATION_WATCH_AUTO_SYNC_FAILED, error, {
                product: "signaldesk",
                reconciliation: "qualification-after-outcome",
                targetIdPresent: true,
            });
        }
    }
    return { ...qualificationResult, activationWatch };
}

export async function upsertSignalDeskCommercialOpportunityServer(
    access: SignalDeskAccessContext,
    input: CommercialOpportunityInput,
) {
    requireRevenueOperatingLayer();
    const terminalStageByStatus: Partial<Record<SignalDeskCommercialOpportunitySummary["status"], SignalDeskCommercialOpportunitySummary["stage"]>> = {
        lost: "lost",
        nurture: "nurture",
        won: "won",
    };
    const terminalStage = terminalStageByStatus[input.status];
    const openStage = input.stage === "qualified" || input.stage === "discovery" || input.stage === "offer" || input.stage === "decision";
    if ((input.status === "open" && !openStage) || (terminalStage && input.stage !== terminalStage)) {
        throw new Error("Commercial opportunity stage and status do not match");
    }
    if ((input.status === "won" || input.status === "lost") && !normalizeText(input.winLossReason)) {
        throw new Error("Commercial opportunity win or loss reason is required");
    }
    const db = requireDb();
    const opportunityRef = db.collection(SIGNALDESK_COLLECTIONS.COMMERCIAL_OPPORTUNITIES).doc(input.opportunityId);
    const summaryRef = db.collection(SIGNALDESK_COLLECTIONS.REVENUE_CONTROL_SUMMARIES).doc(SIGNALDESK_SUMMARY_DOCS.REVENUE);
    return db.runTransaction(async (transaction: any) => {
        const opportunitySnap = await transaction.get(opportunityRef);
        if (!opportunitySnap.exists) throw new Error("Commercial opportunity not found");
        const existing = toPlain(opportunitySnap.data()) as SignalDeskCommercialOpportunitySummary;
        const existingRaw = opportunitySnap.data() as AnyRecord;
        const accountRef = db.collection(SIGNALDESK_COLLECTIONS.REVENUE_ACCOUNTS).doc(existing.revenueAccountId);
        const accountSnap = await transaction.get(accountRef);
        if (!accountSnap.exists) throw new Error("Revenue account not found");
        const accountRaw = accountSnap.data() as AnyRecord;
        const targetId = normalizeText(existing.targetId);
        if (!targetId || normalizeText(accountRaw.primaryTargetId) !== targetId) {
            throw new Error("COMMERCIAL_OPPORTUNITY_ACCOUNT_LINEAGE_MISMATCH");
        }
        const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(targetId);
        const targetSnap = await transaction.get(targetRef);
        if (!targetSnap.exists) throw new Error("Target not found");
        const terminalIndependentRecord = existing.status === "won" || existing.status === "lost";
        if (terminalIndependentRecord && (input.status !== existing.status || input.stage !== existing.stage)) {
            throw new Error("COMMERCIAL_OPPORTUNITY_TERMINAL_RECORD_PRESERVED");
        }
        if (!terminalIndependentRecord) {
            const targetAuthority = parseSignalDeskOutcomeTargetAuthority(targetSnap.data(), targetSnap.id);
            if (
                existingRaw.sourceDataLifecycleState !== "active"
                || accountRaw.sourceDataLifecycleState !== "active"
                || normalizeText(existingRaw.sourcePolicyId) !== targetAuthority.sourcePolicyId
                || normalizeText(existingRaw.sourceRunId) !== targetAuthority.sourceRunId
                || normalizeText(accountRaw.sourcePolicyId) !== targetAuthority.sourcePolicyId
                || normalizeText(accountRaw.sourceRunId) !== targetAuthority.sourceRunId
            ) throw new Error("COMMERCIAL_OPPORTUNITY_SOURCE_LINEAGE_INACTIVE");
        }
        const commercialOfferId = input.commercialOfferId || existing.commercialOfferId || null;
        const offerRef = commercialOfferId
            ? db.collection(SIGNALDESK_COLLECTIONS.COMMERCIAL_OFFERS).doc(commercialOfferId)
            : null;
        const [offerSnap, summarySnap] = await Promise.all([
            offerRef ? transaction.get(offerRef) : Promise.resolve(null),
            transaction.get(summaryRef),
        ]);
        if (input.commercialOfferId && (!offerSnap?.exists || offerSnap.data()?.status !== "active")) {
            throw new Error("Commercial offer is not active");
        }
        const valueMinor = Math.max(0, Math.round(input.valueMinor));
        if (valueMinor > 0 && !offerSnap?.exists) throw new Error("Commercial offer is required for valued opportunity");
        const offer = offerSnap?.exists ? toPlain(offerSnap.data()) as SignalDeskCommercialOfferSummary : null;
        const currency = offer?.currency || existing.currency || null;
        const summary = summarySnap.exists ? toPlain(summarySnap.data()) as SignalDeskRevenueControlSummary : null;
        if (existing.currency && currency && existing.currency !== currency) {
            throw new Error("Commercial opportunity currency does not match revenue pipeline");
        }
        if (input.status === "open" && valueMinor > 0 && summary?.pipelineCurrency && summary.pipelineCurrency !== currency) {
            throw new Error("Commercial opportunity currency does not match revenue pipeline");
        }
        const timestamp = now();
        const probabilityPercent = Math.max(0, Math.min(100, Math.round(input.probabilityPercent)));
        const founderAttentionMinutes = Math.max(0, Math.round(input.founderAttentionMinutes));
        const oldOpen = existing.status === "open" ? 1 : 0;
        const newOpen = input.status === "open" ? 1 : 0;
        const oldPipelineValue = oldOpen ? numberOrZero(existing.valueMinor) : 0;
        const newPipelineValue = newOpen ? valueMinor : 0;
        const oldWeightedValue = oldOpen ? Math.round(numberOrZero(existing.valueMinor) * numberOrZero(existing.probabilityPercent) / 100) : 0;
        const newWeightedValue = newOpen ? Math.round(valueMinor * probabilityPercent / 100) : 0;
        const opportunity = {
            ...existing,
            commercialOfferId,
            currency,
            expectedCloseAt: input.expectedCloseAt === undefined ? existing.expectedCloseAt || null : new Date(input.expectedCloseAt),
            founderAttentionMinutes,
            nextAction: input.nextAction,
            nextActionDueAt: input.nextActionDueAt === undefined ? existing.nextActionDueAt || null : new Date(input.nextActionDueAt),
            probabilityPercent,
            stage: input.stage,
            stalledReason: input.stalledReason === undefined ? existing.stalledReason || null : normalizeText(input.stalledReason) || null,
            status: input.status,
            updatedAt: timestamp,
            updatedBy: access.userId,
            valueMinor,
            winLossReason: normalizeText(input.winLossReason) || null,
        };
        const accountLifecycle: SignalDeskRevenueAccountSummary["lifecycleStage"] = input.status === "won"
            ? "customer"
            : input.status === "lost"
                ? "lost"
                : input.status === "nurture"
                    ? "nurture"
                    : "opportunity";
        transaction.set(opportunityRef, sanitizeForFirestore(opportunity), { merge: true });
        transaction.set(accountRef, sanitizeForFirestore({
            lifecycleStage: accountLifecycle,
            nextAction: input.nextAction,
            updatedAt: timestamp,
            updatedBy: access.userId,
        }), { merge: true });
        transaction.set(summaryRef, sanitizeForFirestore({
            founderAttentionMinutes: increment(founderAttentionMinutes - numberOrZero(existing.founderAttentionMinutes)),
            lostOpportunityCount: increment((input.status === "lost" ? 1 : 0) - (existing.status === "lost" ? 1 : 0)),
            openOpportunityCount: increment(newOpen - oldOpen),
            pId: SIGNALDESK_PRODUCT_CODE,
            pipelineCurrency: summary?.pipelineCurrency || (newOpen && valueMinor > 0 ? currency : null),
            pipelineValueMinor: increment(newPipelineValue - oldPipelineValue),
            revenueControlSummaryId: summaryRef.id,
            updatedAt: timestamp,
            weightedPipelineValueMinor: increment(newWeightedValue - oldWeightedValue),
            wonOpportunityCount: increment((input.status === "won" ? 1 : 0) - (existing.status === "won" ? 1 : 0)),
        }), { merge: true });
        appendAudit(db, transaction, access, "commercial_opportunity_upsert", "commercialOpportunity", opportunityRef.id, `${input.stage}:${input.status}`);
        writeRunTimeline(db, transaction, {
            entityId: opportunityRef.id,
            entityType: "commercial-opportunity",
            label: "Commercial opportunity update",
            status: input.status === "open" ? "ready" : input.status === "lost" ? "blocked" : "completed",
            steps: [
                { label: `Stage: ${input.stage}`, status: "completed", at: toIso(timestamp) },
                { label: "Next action recorded", status: input.status === "open" ? "ready" : "completed", at: toIso(timestamp) },
                { label: `${founderAttentionMinutes} founder minutes recorded`, status: "completed", at: toIso(timestamp) },
            ],
        });
        updateDailyCost(db, transaction, 6, 0);
        return toPlain(opportunity) as SignalDeskCommercialOpportunitySummary;
    });
}

export async function upsertSignalDeskCommercialOfferServer(
    access: SignalDeskAccessContext,
    input: CommercialOfferInput,
) {
    requireRevenueOperatingLayer();
    if (!input.founderApprovalConditions.length) throw new Error("Commercial offer approval conditions are required");
    const db = requireDb();
    const expectedOfferId = commercialOfferIdFor(input.name, input.version);
    if (input.commercialOfferId && input.commercialOfferId !== expectedOfferId) {
        throw new Error("Commercial offer ID does not match name and version");
    }
    const offerRef = db.collection(SIGNALDESK_COLLECTIONS.COMMERCIAL_OFFERS).doc(expectedOfferId);
    const offerCtaRef = input.offerCtaId ? db.collection(SIGNALDESK_COLLECTIONS.OFFER_CTAS).doc(input.offerCtaId) : null;
    const normalizedTerms = {
        allowedDiscountBps: Math.max(0, Math.min(10000, Math.round(input.allowedDiscountBps))),
        billingCadence: input.billingCadence,
        contents: input.contents,
        currency: input.currency.toUpperCase(),
        eligibilitySummary: input.eligibilitySummary,
        founderApprovalConditions: input.founderApprovalConditions,
        name: input.name,
        offerCtaId: input.offerCtaId || null,
        priceMinor: Math.max(0, Math.round(input.priceMinor)),
        version: Math.max(1, Math.round(input.version)),
    };
    return db.runTransaction(async (transaction: any) => {
        const [existingOfferSnap, offerCtaSnap] = await Promise.all([
            transaction.get(offerRef),
            offerCtaRef ? transaction.get(offerCtaRef) : Promise.resolve(null),
        ]);
        if (offerCtaRef) {
            await readSignalDeskOfferAuthority(db, transaction, offerCtaRef, offerCtaSnap, true);
        }
        if (existingOfferSnap.exists) {
            const existing = toPlain(existingOfferSnap.data()) as SignalDeskCommercialOfferSummary;
            const existingTerms = {
                allowedDiscountBps: existing.allowedDiscountBps,
                billingCadence: existing.billingCadence,
                contents: existing.contents,
                currency: existing.currency,
                eligibilitySummary: existing.eligibilitySummary,
                founderApprovalConditions: existing.founderApprovalConditions,
                name: existing.name,
                offerCtaId: existing.offerCtaId || null,
                priceMinor: existing.priceMinor,
                version: existing.version,
            };
            if (JSON.stringify(existingTerms) !== JSON.stringify(normalizedTerms)) {
                throw new Error("Commercial offer version already exists with different terms");
            }
        }
        const timestamp = now();
        const offer = {
            ...normalizedTerms,
            commercialOfferId: offerRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            status: input.status,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        transaction.set(offerRef, sanitizeForFirestore(offer), { merge: true });
        appendAudit(db, transaction, access, "commercial_offer_upsert", "commercialOffer", offerRef.id, `${offer.name}:v${offer.version}`);
        writeRunTimeline(db, transaction, {
            entityId: offerRef.id,
            entityType: "commercial-offer",
            label: `Commercial offer: ${offer.name}`,
            status: offer.status === "active" ? "ready" : offer.status === "blocked" ? "blocked" : "held",
            steps: [
                { label: `Version ${offer.version} stored`, status: "completed", at: toIso(timestamp) },
                { label: "Price and discount authority recorded", status: "completed", at: toIso(timestamp) },
                { label: "Founder approval conditions recorded", status: offer.founderApprovalConditions.length ? "completed" : "held", at: toIso(timestamp) },
            ],
        });
        updateDailyCost(db, transaction, 4, 0);
        return toPlain(offer) as SignalDeskCommercialOfferSummary;
    });
}

export async function upsertSignalDeskOperatingEnvelopeServer(
    access: SignalDeskAccessContext,
    input: OperatingEnvelopeInput,
) {
    requireRevenueOperatingLayer();
    if (input.status === "approved" && (access.role !== "founder-admin" || !access.permissions.includes("policy.approve"))) {
        throw new Error("Founder approval is required for operating envelopes");
    }
    const db = requireDb();
    const startsAt = new Date(input.startsAt);
    const expiresAt = new Date(input.expiresAt);
    if (!Number.isFinite(startsAt.getTime()) || !Number.isFinite(expiresAt.getTime()) || expiresAt <= startsAt || expiresAt <= new Date()) {
        throw new Error("Operating envelope dates are invalid");
    }
    if (input.totalVolumeCap < input.dailyVolumeCap) throw new Error("Operating envelope total volume must cover the daily cap");
    if (!input.marketPodId) throw new Error("Market pod is required for operating envelope");
    const sourcePolicyRefs = input.sourcePolicyIds.map((sourcePolicyId) => db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(sourcePolicyId));
    const offerRef = db.collection(SIGNALDESK_COLLECTIONS.COMMERCIAL_OFFERS).doc(input.commercialOfferId);
    const marketPodRef = db.collection(SIGNALDESK_COLLECTIONS.MARKET_PODS).doc(input.marketPodId);
    const budgetRef = input.budgetPolicyId
        ? db.collection(SIGNALDESK_COLLECTIONS.BUDGET_POLICIES).doc(input.budgetPolicyId)
        : null;
    const senderRef = input.senderDomainId
        ? db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(input.senderDomainId)
        : null;
    const templateRefs = input.templateIds.map((templateId) => db.collection(SIGNALDESK_COLLECTIONS.TEMPLATE_SUMMARIES).doc(templateId));
    const sourcePolicies = await Promise.all(input.sourcePolicyIds.map((sourcePolicyId) => readSourcePolicy(db, sourcePolicyId)));
    for (const policy of sourcePolicies) {
        await assertSourcePolicyUsable(db, access, policy, {
            entityId: input.operatingEnvelopeId || input.name,
            use: input.channel === "email" || input.channel === "manual" ? "contact" : "evidence",
        });
    }
    const offerSnap = await offerRef.get();
    if (!offerSnap.exists || offerSnap.data()?.status !== "active") throw new Error("Commercial offer is not active");
    const podSnap = await marketPodRef.get();
    const marketPod = podSnap.exists && podSnap.data()?.dependentHoldReconciliationPending !== true
        ? projectSignalDeskMarketPod({
            ...toPlain(podSnap.data()),
            [`${SIGNALDESK_COLLECTIONS.MARKET_PODS}DocId`]: marketPodRef.id,
        })
        : null;
    if (!marketPod || marketPod.status !== "active" || marketPod.reviewDecision !== "approved" || !marketPod.approvedBy) {
        throw new Error("Market pod is not founder-approved");
    }
    if (input.channel === "email") {
        if (!input.senderDomainId) throw new Error("Sender domain is required for email envelope");
        const sender = await readReadySenderDomain(db, input.senderDomainId);
        if (!isSenderDomainReady(sender)) throw new Error("Sender domain is not ready");
    }
    const templateSnaps = await Promise.all(templateRefs.map((templateRef) => templateRef.get()));
    if (templateSnaps.some((snap: any) => !snap.exists || snap.data()?.status !== "active")) throw new Error("Active template is required");

    const requestedApprovalMode = input.requestedApprovalMode;
    const exceptionOnlyHeld = requestedApprovalMode === "exception-only";
    const approvalMode: SignalDeskOperatingEnvelopeSummary["approvalMode"] = exceptionOnlyHeld
        ? "prepare-and-approve-each"
        : requestedApprovalMode;
    const executionState: SignalDeskOperatingEnvelopeSummary["executionState"] = exceptionOnlyHeld
        ? "held"
        : input.status === "paused"
            ? "paused"
            : input.status === "draft" || input.status === "held" || input.status === "expired"
                ? "held"
                : input.status === "shadow" || approvalMode === "manual" || approvalMode === "recommendation-only"
                ? "shadow"
                : "approval-only";
    const status: SignalDeskOperatingEnvelopeSummary["status"] = exceptionOnlyHeld ? "held" : input.status;
    const expectedEnvelopeId = operatingEnvelopeIdFor(input.name, input.version);
    if (input.operatingEnvelopeId && input.operatingEnvelopeId !== expectedEnvelopeId) {
        throw new Error("Operating envelope ID does not match name and version");
    }
    const envelopeRef = db.collection(SIGNALDESK_COLLECTIONS.OPERATING_ENVELOPES).doc(expectedEnvelopeId);
    const timestamp = now();
    const immutableTerms = {
        approvalMode,
        budgetPolicyId: input.budgetPolicyId || null,
        channel: input.channel,
        commercialOfferId: input.commercialOfferId,
        dailyVolumeCap: Math.max(1, Math.min(500, Math.round(input.dailyVolumeCap))),
        expiresAt: expiresAt.toISOString(),
        fallbackAction: input.fallbackAction,
        marketPodId: input.marketPodId || null,
        maxCostUsd: Math.max(0, input.maxCostUsd),
        name: input.name,
        requestedApprovalMode,
        senderDomainId: input.senderDomainId || null,
        sourcePolicyIds: input.sourcePolicyIds,
        startsAt: startsAt.toISOString(),
        stopConditions: input.stopConditions,
        templateIds: input.templateIds,
        totalVolumeCap: Math.max(1, Math.min(5000, Math.round(input.totalVolumeCap))),
        version: Math.max(1, Math.round(input.version)),
    };
    const envelope = {
        ...immutableTerms,
        approvedAt: status === "approved" ? timestamp : null,
        approvedBy: status === "approved" ? access.userId : null,
        executionState,
        expiresAt,
        operatingEnvelopeId: envelopeRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        startsAt,
        status,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };
    return db.runTransaction(async (transaction: any) => {
        const [
            existingEnvelopeSnap,
            currentOfferSnap,
            currentMarketPodSnap,
            currentBudgetSnap,
            currentSenderSnap,
            currentSourcePolicySnaps,
            currentTemplateSnaps,
        ] = await Promise.all([
            transaction.get(envelopeRef),
            transaction.get(offerRef),
            transaction.get(marketPodRef),
            budgetRef ? transaction.get(budgetRef) : Promise.resolve(null),
            senderRef ? transaction.get(senderRef) : Promise.resolve(null),
            Promise.all(sourcePolicyRefs.map((sourcePolicyRef) => transaction.get(sourcePolicyRef))),
            Promise.all(templateRefs.map((templateRef) => transaction.get(templateRef))),
        ]);
        if (!currentOfferSnap.exists || currentOfferSnap.data()?.status !== "active") {
            throw new Error("Commercial offer is not active");
        }
        const currentMarketPod = currentMarketPodSnap.exists
            && currentMarketPodSnap.data()?.dependentHoldReconciliationPending !== true
            ? projectSignalDeskMarketPod({
                ...toPlain(currentMarketPodSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.MARKET_PODS}DocId`]: marketPodRef.id,
            })
            : null;
        if (!currentMarketPod || currentMarketPod.status !== "active" || currentMarketPod.reviewDecision !== "approved" || !currentMarketPod.approvedBy) {
            throw new Error("Market pod is not founder-approved");
        }
        currentSourcePolicySnaps.forEach((currentSourcePolicySnap: any) => {
            const currentSourcePolicy = readSourcePolicySnapshot(currentSourcePolicySnap);
            const errorCode = sourcePolicyUsabilityError(currentSourcePolicy, {
                entityId: input.operatingEnvelopeId || input.name,
                use: input.channel === "email" || input.channel === "manual" ? "contact" : "evidence",
            });
            if (errorCode) throw new Error(errorCode);
        });
        if (budgetRef) {
            if (!currentBudgetSnap?.exists) {
                throw new Error("Revenue budget policy is not active");
            }
            const currentBudget = parseSignalDeskBudgetPolicyDocument(
                currentBudgetSnap.data(),
                budgetRef.id,
                getSignalDeskSpendPeriod(timestamp.toMillis()),
            );
            if (currentBudget.status !== "active") throw new Error("Revenue budget policy is not active");
            const eligibleBudget = currentBudget.scope === "global"
                || (currentBudget.scope === "market-pod" && currentBudget.scopeId === input.marketPodId);
            if (!eligibleBudget) throw new Error("Budget policy is not eligible for revenue envelope");
            const remainingMonthlyBudgetUsd = Math.max(0, numberOrZero(currentBudget.monthlyBudgetUsd) - numberOrZero(currentBudget.spentMonthUsd));
            if (input.maxCostUsd > remainingMonthlyBudgetUsd) {
                throw new Error("Operating envelope exceeds the remaining budget policy");
            }
        }
        if (input.channel === "email") {
            const currentSender = projectSenderDomainDocument(currentSenderSnap);
            if (!isSenderDomainReady(currentSender)) throw new Error("Sender domain is not ready");
        }
        if (currentTemplateSnaps.some((currentTemplateSnap: any) => !currentTemplateSnap.exists || currentTemplateSnap.data()?.status !== "active")) {
            throw new Error("Active template is required");
        }
        const existingEnvelope = existingEnvelopeSnap.exists
            ? toPlain(existingEnvelopeSnap.data()) as SignalDeskOperatingEnvelopeSummary
            : null;
        if (existingEnvelopeSnap.exists) {
            const existingTerms = {
                approvalMode: existingEnvelope?.approvalMode,
                budgetPolicyId: existingEnvelope?.budgetPolicyId || null,
                channel: existingEnvelope?.channel,
                commercialOfferId: existingEnvelope?.commercialOfferId,
                dailyVolumeCap: existingEnvelope?.dailyVolumeCap,
                expiresAt: existingEnvelope?.expiresAt,
                fallbackAction: existingEnvelope?.fallbackAction,
                marketPodId: existingEnvelope?.marketPodId || null,
                maxCostUsd: existingEnvelope?.maxCostUsd,
                name: existingEnvelope?.name,
                requestedApprovalMode: existingEnvelope?.requestedApprovalMode,
                senderDomainId: existingEnvelope?.senderDomainId || null,
                sourcePolicyIds: existingEnvelope?.sourcePolicyIds,
                startsAt: existingEnvelope?.startsAt,
                stopConditions: existingEnvelope?.stopConditions,
                templateIds: existingEnvelope?.templateIds,
                totalVolumeCap: existingEnvelope?.totalVolumeCap,
                version: existingEnvelope?.version,
            };
            if (JSON.stringify(existingTerms) !== JSON.stringify(immutableTerms)) {
                throw new Error("Operating envelope version already exists with different terms");
            }
        }
        const storedEnvelope = {
            ...envelope,
            approvedAt: status === "approved" ? timestamp : existingEnvelope?.approvedAt || null,
            approvedBy: status === "approved" ? access.userId : existingEnvelope?.approvedBy || null,
        };
        transaction.set(envelopeRef, sanitizeForFirestore(storedEnvelope), { merge: true });
        appendAudit(db, transaction, access, "operating_envelope_upsert", "operatingEnvelope", envelopeRef.id, `${requestedApprovalMode}:${executionState}`);
        writeRunTimeline(db, transaction, {
            entityId: envelopeRef.id,
            entityType: "operating-envelope",
            label: `Operating envelope: ${input.name}`,
            status: executionState === "approval-only" ? "ready" : executionState === "held" || executionState === "paused" ? "held" : "completed",
            steps: [
                { label: "Existing policy references validated", status: "completed", at: toIso(timestamp) },
                { label: `${input.dailyVolumeCap} daily / ${input.totalVolumeCap} total cap`, status: "completed", at: toIso(timestamp) },
                { label: exceptionOnlyHeld ? "Exception-only execution held until operating proof" : `Execution remains ${executionState}`, status: exceptionOnlyHeld ? "held" : "completed", at: toIso(timestamp) },
            ],
        });
        updateDailyCost(db, transaction, 4, 0);
        return toPlain(storedEnvelope) as SignalDeskOperatingEnvelopeSummary;
    });
}

export async function refreshSignalDeskActivationWatchServer(
    access: SignalDeskAccessContext,
    input: ActivationWatchInput,
) {
    requireRevenueOperatingLayer();
    const db = requireDb();
    const accountRef = db.collection(SIGNALDESK_COLLECTIONS.REVENUE_ACCOUNTS).doc(revenueAccountIdFor(input.targetId));
    const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(input.targetId);
    const watchRef = db.collection(SIGNALDESK_COLLECTIONS.ACTIVATION_WATCHES).doc(activationWatchIdFor(input.targetId));
    const opportunityRef = db.collection(SIGNALDESK_COLLECTIONS.COMMERCIAL_OPPORTUNITIES).doc(opportunityIdFor(accountRef.id));
    const summaryRef = db.collection(SIGNALDESK_COLLECTIONS.REVENUE_CONTROL_SUMMARIES).doc(SIGNALDESK_SUMMARY_DOCS.REVENUE);
    const outcomeCollection = db.collection(SIGNALDESK_COLLECTIONS.OUTCOME_SUMMARIES);
    const latestOutcomeQuery = outcomeCollection
        .where("targetId", "==", input.targetId)
        .orderBy("updatedAt", "desc");
    const activationOutcomeQuery = outcomeCollection
        .where("targetId", "==", input.targetId)
        .where("outcomeType", "==", "two_surface_activation");
    return db.runTransaction(async (transaction: any) => {
        const [accountSnap, targetSnap, existingSnap, opportunitySnap] = await Promise.all([
            transaction.get(accountRef),
            transaction.get(targetRef),
            transaction.get(watchRef),
            transaction.get(opportunityRef),
        ]);
        if (!accountSnap.exists) throw new Error("Revenue account not found");
        if (!targetSnap.exists) throw new Error("Target not found");
        const account = toPlain(accountSnap.data()) as SignalDeskRevenueAccountSummary;
        const target = parseSignalDeskTargetSummaryDocument(targetSnap.data(), targetSnap.id);
        const existing = existingSnap.exists ? toPlain(existingSnap.data()) as SignalDeskActivationWatchSummary : null;
        const [outcomes, activationOutcomes] = await Promise.all([
            readStrictOutcomeSummaryQueryInTransaction(
                db,
                transaction,
                latestOutcomeQuery,
                "activation-watch-latest",
            ),
            readStrictOutcomeSummaryQueryInTransaction(
                db,
                transaction,
                activationOutcomeQuery,
                "activation-watch-activation",
            ),
        ]);
        const outcomeTypes = Array.from(new Set(outcomes
            .filter((outcome) => numberOrZero(outcome.count) > 0 && (outcome.outcomeType !== "two_surface_activation" || isVerifiedTwoSurfaceOutcome(outcome)))
            .map((outcome) => outcome.outcomeType)));
        const activationRecorded = activationOutcomes.some(isVerifiedTwoSurfaceOutcome);
        if (activationRecorded && !outcomeTypes.includes("two_surface_activation")) outcomeTypes.push("two_surface_activation");
        const outcomeTimes = outcomes.map((outcome) => toTimestampMillis(outcome.updatedAt) || new Date(`${outcome.day}T00:00:00.000Z`).getTime()).filter(Number.isFinite);
        const ownerQualifiedTimes = [
            toTimestampMillis(target.ownerQualifiedAt),
            ...outcomes.map((outcome) => toTimestampMillis(outcome.ownerQualifiedAt)),
        ].filter((value): value is number => Boolean(value));
        const ownerQualifiedMillis = ownerQualifiedTimes.length ? Math.min(...ownerQualifiedTimes) : null;
        const lastOutcomeMillis = outcomeTimes.length ? Math.max(...outcomeTimes) : null;
        const deadlineMillis = ownerQualifiedMillis ? ownerQualifiedMillis + (7 * 24 * 60 * 60 * 1000) : null;
        let status: SignalDeskActivationWatchSummary["status"] = "not-started";
        if (activationRecorded) status = "activated";
        else if (outcomeTypes.includes("published")) status = "published";
        else if (outcomeTypes.includes("upload_started") || outcomeTypes.includes("preview_prepared")) status = "in-progress";
        else if (outcomeTypes.includes("route_created")) status = "routed";
        if (status !== "activated" && status !== "not-started" && deadlineMillis && deadlineMillis < Date.now()) status = "stalled";
        const activationState: SignalDeskRevenueAccountSummary["activationState"] = status === "activated"
            ? "activated"
            : status === "stalled"
                ? "stalled"
                : status === "routed"
                    ? "routed"
                    : status === "not-started"
                        ? "not-started"
                        : "in-progress";
        const opportunity = opportunitySnap.exists ? toPlain(opportunitySnap.data()) as SignalDeskCommercialOpportunitySummary : null;
        const closeOpportunity = status === "activated" && opportunity && opportunity.status !== "won";
        const timestamp = now();
        const nextAction = status === "activated"
            ? "Request approved proof or referral only when eligible."
            : status === "stalled"
                ? "Review the stalled MenuList route without changing MenuList truth."
                : status === "not-started"
                    ? "Create or attach an approved MenuList route."
                    : "Wait for the next MenuList-owned activation outcome.";
        const watch = {
            activationWatchId: watchRef.id,
            deadlineAt: deadlineMillis ? new Date(deadlineMillis) : null,
            lastOutcomeAt: lastOutcomeMillis ? new Date(lastOutcomeMillis) : null,
            nextAction,
            ownerQualifiedAt: ownerQualifiedMillis ? new Date(ownerQualifiedMillis) : null,
            outcomeTypes,
            pId: SIGNALDESK_PRODUCT_CODE,
            revenueAccountId: account.revenueAccountId,
            source: "signaldesk-outcome-summaries",
            status,
            targetId: input.targetId,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        const oldOpen = closeOpportunity && opportunity?.status === "open" ? 1 : 0;
        const oldPipelineValue = oldOpen ? numberOrZero(opportunity?.valueMinor) : 0;
        const oldWeightedValue = oldOpen ? Math.round(numberOrZero(opportunity?.valueMinor) * numberOrZero(opportunity?.probabilityPercent) / 100) : 0;
        transaction.set(watchRef, sanitizeForFirestore(watch), { merge: true });
        transaction.set(accountRef, sanitizeForFirestore({
            activationState,
            lifecycleStage: status === "activated" ? "customer" : account.lifecycleStage,
            nextAction,
            updatedAt: timestamp,
            updatedBy: access.userId,
        }), { merge: true });
        if (closeOpportunity && opportunity) {
            transaction.set(opportunityRef, sanitizeForFirestore({
                nextAction,
                probabilityPercent: 100,
                stage: "won",
                status: "won",
                updatedAt: timestamp,
                updatedBy: access.userId,
                winLossReason: "Two-surface activation outcome recorded.",
            }), { merge: true });
        }
        transaction.set(summaryRef, sanitizeForFirestore({
            activatedAccountCount: increment((status === "activated" ? 1 : 0) - (existing?.status === "activated" ? 1 : 0)),
            lostOpportunityCount: increment(closeOpportunity && opportunity?.status === "lost" ? -1 : 0),
            openOpportunityCount: increment(-oldOpen),
            pId: SIGNALDESK_PRODUCT_CODE,
            pipelineValueMinor: increment(-oldPipelineValue),
            revenueControlSummaryId: summaryRef.id,
            stalledActivationCount: increment((status === "stalled" ? 1 : 0) - (existing?.status === "stalled" ? 1 : 0)),
            updatedAt: timestamp,
            weightedPipelineValueMinor: increment(-oldWeightedValue),
            wonOpportunityCount: increment(closeOpportunity ? 1 : 0),
        }), { merge: true });
        appendAudit(db, transaction, access, "activation_watch_refresh", "activationWatch", watchRef.id, status);
        writeRunTimeline(db, transaction, {
            entityId: watchRef.id,
            entityType: "activation-watch",
            label: "Activation watch refresh",
            status: status === "activated" ? "completed" : status === "stalled" ? "held" : status === "not-started" ? "held" : "ready",
            steps: [
                { label: "SignalDesk outcome summaries read", status: "completed", at: toIso(timestamp) },
                { label: outcomeTypes.length ? outcomeTypes.join(", ") : "No activation outcomes yet", status: outcomeTypes.length ? "completed" : "held", at: toIso(timestamp) },
                { label: `Activation state: ${status}`, status: status === "activated" ? "completed" : status === "stalled" ? "held" : "ready", at: toIso(timestamp) },
            ],
        });
        updateDailyCost(db, transaction, closeOpportunity ? 7 : 6, 0);
        return toPlain(watch) as SignalDeskActivationWatchSummary;
    });
}

export async function createSignalDeskExperimentCardServer(access: SignalDeskAccessContext, input: ExperimentCardInput) {
    requireOperatingLayer();
    const readbackPlan = projectSignalDeskExperimentReadbackPlan({
        ...input.readbackPlan,
        version: EXPERIMENT_READBACK_VERSION,
    });
    if (!readbackPlan) throw new Error("EXPERIMENT_READBACK_PLAN_INVALID");
    const db = requireDb();
    const experimentRef = db.collection(SIGNALDESK_COLLECTIONS.EXPERIMENT_CARDS).doc(experimentCardIdFor(input));
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const existingSnap = await transaction.get(experimentRef);
        if (existingSnap.exists && normalizeText(existingSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
            throw new Error("EXPERIMENT_CARD_PRODUCT_MISMATCH");
        }
        const status = input.status || "planned";
        if (status === "completed" || status === "stopped") throw new Error("EXPERIMENT_CREATE_STATUS_INVALID");
        const timestamp = now();
        const experimentData = {
            experimentCardId: experimentRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            hypothesis: normalizeText(input.hypothesis),
            marketPodId: normalizeText(input.marketPodId) || null,
            sourcePolicyId: normalizeText(input.sourcePolicyId) || null,
            ctaId: normalizeText(input.ctaId) || null,
            contentAssetId: normalizeText(input.contentAssetId) || null,
            channel: input.channel,
            targetCount: input.targetCount,
            expectedOutcome: normalizeText(input.expectedOutcome),
            stopRule: normalizeText(input.stopRule),
            proofAssetSummary: normalizeText(input.proofAssetSummary) || null,
            readbackPlan,
            resultSummary: null,
            ownerDecision: "pending" as const,
            status,
            createdAt: timestamp,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        const candidate = projectSignalDeskExperimentCard({
            ...toPlain(experimentData),
            [`${SIGNALDESK_COLLECTIONS.EXPERIMENT_CARDS}DocId`]: experimentRef.id,
        });
        if (!candidate) throw new Error("EXPERIMENT_CARD_SHAPE_INVALID");
        const authority = await readSignalDeskExperimentAuthority(db, transaction, candidate, status === "active");
        const experiment = {
            ...experimentData,
            proofAssetSummary: authority.asset?.title || candidate.proofAssetSummary || null,
        };
        const projectedExperiment = projectSignalDeskExperimentCard({
            ...toPlain(experiment),
            [`${SIGNALDESK_COLLECTIONS.EXPERIMENT_CARDS}DocId`]: experimentRef.id,
        });
        if (!projectedExperiment) throw new Error("EXPERIMENT_CARD_SHAPE_INVALID");
        if (existingSnap.exists) {
            const existing = projectSignalDeskExperimentCard({
                ...toPlain(existingSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.EXPERIMENT_CARDS}DocId`]: experimentRef.id,
            });
            if (!existing) throw new Error("EXPERIMENT_CARD_SHAPE_INVALID");
            const comparableExisting = {
                channel: existing.channel,
                contentAssetId: existing.contentAssetId || null,
                ctaId: existing.ctaId || null,
                expectedOutcome: existing.expectedOutcome,
                hypothesis: existing.hypothesis,
                marketPodId: existing.marketPodId || null,
                proofAssetSummary: existing.proofAssetSummary || null,
                readbackPlan: existing.readbackPlan,
                sourcePolicyId: existing.sourcePolicyId || null,
                status: existing.status,
                stopRule: existing.stopRule,
                targetCount: existing.targetCount,
            };
            const comparableInput = {
                channel: projectedExperiment.channel,
                contentAssetId: projectedExperiment.contentAssetId || null,
                ctaId: projectedExperiment.ctaId || null,
                expectedOutcome: projectedExperiment.expectedOutcome,
                hypothesis: projectedExperiment.hypothesis,
                marketPodId: projectedExperiment.marketPodId || null,
                proofAssetSummary: projectedExperiment.proofAssetSummary || null,
                readbackPlan: projectedExperiment.readbackPlan,
                sourcePolicyId: projectedExperiment.sourcePolicyId || null,
                status: projectedExperiment.status,
                stopRule: projectedExperiment.stopRule,
                targetCount: projectedExperiment.targetCount,
            };
            if (JSON.stringify(comparableExisting) !== JSON.stringify(comparableInput)) throw new Error("EXPERIMENT_CARD_IDENTITY_CONFLICT");
            return existing;
        }
        transaction.create(experimentRef, sanitizeForFirestore(experiment));
        appendAudit(db, transaction, access, "experiment_card_create", "experimentCard", experimentRef.id, input.channel);
        writeRunTimeline(db, transaction, {
            entityId: experimentRef.id,
            entityType: "experiment",
            label: `Experiment: ${projectedExperiment.hypothesis.slice(0, 80)}`,
            status: projectedExperiment.status === "active" ? "ready" : "held",
            steps: [
                { label: "Hypothesis recorded", status: "completed", at: toIso(timestamp) },
                { label: "Stop rule attached", status: "completed", at: toIso(timestamp) },
                { label: "Readback plan attached", status: "completed", at: toIso(timestamp) },
                { label: "Owner decision pending", status: "held", at: toIso(timestamp) },
            ],
        });
        updateDailyCost(db, transaction, 4, 0);
        return projectedExperiment;
    });
}

export async function reviewSignalDeskExperimentCardServer(access: SignalDeskAccessContext, input: ExperimentReviewInput) {
    requireOperatingLayer();
    const db = requireDb();
    const experimentRef = db.collection(SIGNALDESK_COLLECTIONS.EXPERIMENT_CARDS).doc(input.experimentCardId);
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const experimentSnap = await transaction.get(experimentRef);
        if (!experimentSnap.exists) throw new Error("Experiment card not found");
        if (normalizeText(experimentSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
            throw new Error("EXPERIMENT_CARD_PRODUCT_MISMATCH");
        }
        const prior = projectSignalDeskExperimentCard({
            ...toPlain(experimentSnap.data()),
            [`${SIGNALDESK_COLLECTIONS.EXPERIMENT_CARDS}DocId`]: experimentRef.id,
        });
        if (!prior) throw new Error("EXPERIMENT_CARD_SHAPE_INVALID");
        if (input.ownerDecision === "pending") throw new Error("EXPERIMENT_REVIEW_DECISION_INVALID");
        const status: SignalDeskExperimentCardSummary["status"] = input.ownerDecision === "stop"
            ? "stopped"
            : input.ownerDecision === "complete"
                ? "completed"
                : input.ownerDecision === "hold"
                    ? "paused"
                    : "active";
        if (input.status && input.status !== status) throw new Error("EXPERIMENT_REVIEW_STATUS_MISMATCH");
        const resultSummary = normalizeText(input.resultSummary);
        if (resultSummary.length < 2 || resultSummary.length > 1000) {
            throw new Error("EXPERIMENT_REVIEW_RESULT_REQUIRED");
        }
        if (["completed", "stopped"].includes(prior.status) && prior.status !== status) {
            throw new Error("EXPERIMENT_TERMINAL_REOPEN_NOT_ALLOWED");
        }
        if (["completed", "stopped"].includes(prior.status)) {
            if (prior.ownerDecision !== input.ownerDecision || (prior.resultSummary || null) !== resultSummary) {
                throw new Error("EXPERIMENT_TERMINAL_MUTATION_NOT_ALLOWED");
            }
            return prior;
        }
        if (status === "active") await readSignalDeskExperimentAuthority(db, transaction, prior, true);
        if (
            prior.ownerDecision === input.ownerDecision
            && prior.status === status
            && (prior.resultSummary || null) === resultSummary
        ) return prior;
        const timestamp = now();
        const updates = {
            ...(status === "active" ? { authorityHeldAt: null, authorityHeldBy: null, authorityHoldReason: null } : {}),
            ownerDecision: input.ownerDecision,
            resultSummary,
            status,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        const reviewed = projectSignalDeskExperimentCard({
            ...prior,
            ...updates,
            pId: SIGNALDESK_PRODUCT_CODE,
            [`${SIGNALDESK_COLLECTIONS.EXPERIMENT_CARDS}DocId`]: experimentRef.id,
        });
        if (!reviewed) throw new Error("EXPERIMENT_CARD_SHAPE_INVALID");
        transaction.set(experimentRef, sanitizeForFirestore(updates), { merge: true });
        appendAudit(db, transaction, access, "experiment_card_review", "experimentCard", input.experimentCardId, input.ownerDecision);
        writeRunTimeline(db, transaction, {
            entityId: input.experimentCardId,
            entityType: "experiment",
            label: `Experiment reviewed: ${prior.hypothesis.slice(0, 80)}`,
            status: status === "completed" ? "completed" : status === "stopped" ? "blocked" : status === "active" ? "ready" : "held",
            steps: [
                { label: "Owner decision recorded", status: "completed", at: toIso(timestamp) },
                { label: `Decision: ${input.ownerDecision}`, status: input.ownerDecision === "stop" ? "blocked" : input.ownerDecision === "hold" ? "held" : "ready", at: toIso(timestamp) },
            ],
        });
        updateDailyCost(db, transaction, 3, 0);
        return reviewed;
    });
}

export async function createSignalDeskDailyGrowthMissionServer(access: SignalDeskAccessContext, input: DailyGrowthMissionInput = {}) {
    requireOperatingLayer();
    const db = requireDb();
    const timestamp = now();
    const day = input.day || todayKey();
    if (!isValidIsoDay(day)) throw new Error("GROWTH_MISSION_DAY_INVALID");
    const requestedMarketPodId = normalizeText(input.marketPodId) || null;
    if ((requestedMarketPodId?.length || 0) > 160) throw new Error("GROWTH_MISSION_MARKET_POD_INVALID");
    const generationRequestFingerprintHash = hashValue(JSON.stringify({
        day,
        marketPodId: requestedMarketPodId,
    }));
    const missionRef = db.collection(SIGNALDESK_COLLECTIONS.GROWTH_MISSIONS).doc(growthMissionIdFor(day));
    const resolveExistingMission = (currentSnap: FirebaseFirestore.DocumentSnapshot) => {
        if (!currentSnap.exists) return null;
        const current = toPlain(currentSnap.data()) as AnyRecord;
        const currentProduct = normalizeText(current.pId);
        if (currentProduct && currentProduct !== SIGNALDESK_PRODUCT_CODE) {
            throw new Error("GROWTH_MISSION_PRODUCT_MISMATCH");
        }
        const currentMission = projectSignalDeskGrowthMission({
            ...current,
            [`${SIGNALDESK_COLLECTIONS.GROWTH_MISSIONS}DocId`]: currentSnap.id,
        });
        if (!currentMission) throw new Error("GROWTH_MISSION_SHAPE_INVALID");
        const storedFingerprintHash = normalizeText(current.generationRequestFingerprintHash);
        const hasStoredRequestedPod = Object.prototype.hasOwnProperty.call(current, "generationRequestedMarketPodId");
        const storedRequestedMarketPodId = normalizeText(current.generationRequestedMarketPodId) || null;
        const legacyReplayMatches = !storedFingerprintHash && (
            requestedMarketPodId === null
            || (hasStoredRequestedPod && storedRequestedMarketPodId === requestedMarketPodId)
            || (!hasStoredRequestedPod && currentMission.recommendedMarketPodId === requestedMarketPodId)
        );
        if (
            (storedFingerprintHash && storedFingerprintHash !== generationRequestFingerprintHash)
            || (!storedFingerprintHash && !legacyReplayMatches)
        ) throw new Error("GROWTH_MISSION_REQUEST_CONFLICT");
        return currentMission;
    };
    const existingMission = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => (
        resolveExistingMission(await transaction.get(missionRef))
    ));
    if (existingMission) return existingMission;
    const [
        approvals,
        conversations,
        sourceRuns,
        senderDomains,
        contentAssets,
        contentDrafts,
        contentSources,
        proofPermissions,
        selfServiceCtas,
        contentPauseSnap,
        marketPods,
        experiments,
        offerCtas,
        trustPartners,
        outcomes,
        demandSignals,
        commercialOpportunities,
        activationWatches,
        revenueControlSummaries,
        costSnap,
    ] = await Promise.all([
        readList<SignalDeskApprovalItem>(db, SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE),
        readConversationSummaryList(db),
        readSourceRunList(db),
        readSenderDomains(db),
        readContentAssets(db),
        readContentDrafts(db),
        readContentSources(db, true),
        readProofPermissions(db, true),
        readSelfServiceCtas(db, true),
        db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_content-distribution").get(),
        readMarketPods(db, true),
        readExperimentCards(db, true),
        readOfferCtas(db, true),
        readList<SignalDeskTrustPartnerProfileSummary>(db, SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES),
        readOutcomeSummaryList(db, LIST_LIMIT, "growth-mission"),
        readList<SignalDeskDemandSignalSummary>(db, SIGNALDESK_COLLECTIONS.DEMAND_SIGNAL_SUMMARIES),
        readList<SignalDeskCommercialOpportunitySummary>(db, SIGNALDESK_COLLECTIONS.COMMERCIAL_OPPORTUNITIES),
        readList<SignalDeskActivationWatchSummary>(db, SIGNALDESK_COLLECTIONS.ACTIVATION_WATCHES),
        readList<SignalDeskRevenueControlSummary>(db, SIGNALDESK_COLLECTIONS.REVENUE_CONTROL_SUMMARIES),
        db.collection(SIGNALDESK_COLLECTIONS.COST_DAILY_SUMMARIES).doc(day).get(),
    ]);

    type MissionAction = SignalDeskGrowthMissionSummary["missionActions"][number];
    const missionActions: MissionAction[] = [];
    const pushAction = (action: Omit<MissionAction, "actionId" | "rank" | "status">) => {
        if (missionActions.length >= 5) return;
        const rank = missionActions.length + 1;
        missionActions.push({
            ...action,
            actionId: `mission_${day}_${rank}`,
            rank,
            // Missions outlive ordinary source retention. Never copy source or
            // operator prose into the durable reason field.
            reason: `${action.entityType}:${action.actionType}:${action.riskLevel}`,
            status: "pending",
        });
    };

    const criticalReplies = conversations.filter((conversation) => (
        conversation.state === "complaint"
        || conversation.state === "privacy_request"
        || conversation.state === "legal_request"
    ));
    if (criticalReplies.length) {
        const conversation = criticalReplies[0];
        pushAction({
            actionType: "pause",
            entityId: conversation.conversationId,
            entityType: "reply",
            expectedOutcome: "The complaint or rights request remains suppressed, paused, and under founder review.",
            label: `Resolve ${criticalReplies.length} critical reply exception${criticalReplies.length === 1 ? "" : "s"}`,
            reason: conversation.lastMessagePreview || conversation.state,
            riskLevel: "high",
        });
    }

    const replyQueue = conversations.filter((conversation) => conversation.state === "interested" || conversation.state === "needs_review");
    if (replyQueue.length) {
        const conversation = replyQueue[0];
        pushAction({
            actionType: "review",
            entityId: conversation.conversationId,
            entityType: "reply",
            expectedOutcome: "Interested or unclear reply routed to the correct self-serve, manual reply, or suppression path.",
            label: `Handle ${replyQueue.length} reply exception${replyQueue.length === 1 ? "" : "s"}`,
            reason: conversation.lastMessagePreview || "Reply state needs founder review.",
            riskLevel: conversation.state === "interested" ? "medium" : "high",
        });
    }

    const nowMillis = Date.now();
    const currentActivationWatches = activationWatches.map((watch) => annotateActivationWatch(watch, nowMillis));
    const stalledActivationWatches = currentActivationWatches
        .filter((watch) => watch.status === "stalled")
        .sort((left, right) => (
            (toTimestampMillis(left.deadlineAt) || Number.POSITIVE_INFINITY)
            - (toTimestampMillis(right.deadlineAt) || Number.POSITIVE_INFINITY)
        ));
    if (stalledActivationWatches.length) {
        const watch = stalledActivationWatches[0];
        pushAction({
            actionType: "review",
            entityId: watch.targetId,
            entityType: "target",
            expectedOutcome: "Stalled activation receives one bounded recovery action without changing MenuList truth.",
            label: `Recover ${stalledActivationWatches.length} stalled activation${stalledActivationWatches.length === 1 ? "" : "s"}`,
            reason: watch.nextAction,
            riskLevel: "high",
        });
    }

    const pendingApprovals = approvals.filter((approval) => approval.status === "pending");
    if (pendingApprovals.length) {
        const approval = pendingApprovals[0];
        pushAction({
            actionType: "approve",
            entityId: approval.approvalId,
            entityType: "approval",
            expectedOutcome: "Approved or held outreach packet with evidence trace intact.",
            label: `Review ${pendingApprovals.length} pending approval${pendingApprovals.length === 1 ? "" : "s"}`,
            reason: approval.reviewReason || "Approval queue has founder-visible work.",
            riskLevel: approval.priority === "high" ? "high" : "medium",
        });
    }

    const overdueOpportunities = commercialOpportunities
        .filter((opportunity) => (
            opportunity.status === "open"
            && (
                Boolean(opportunity.stalledReason)
                || (toTimestampMillis(opportunity.nextActionDueAt) || Number.POSITIVE_INFINITY) < nowMillis
            )
        ))
        .sort((left, right) => (
            (toTimestampMillis(left.nextActionDueAt) || Number.POSITIVE_INFINITY)
            - (toTimestampMillis(right.nextActionDueAt) || Number.POSITIVE_INFINITY)
        ));
    if (overdueOpportunities.length) {
        const opportunity = overdueOpportunities[0];
        pushAction({
            actionType: "review",
            entityId: opportunity.targetId,
            entityType: "target",
            expectedOutcome: "The opportunity is advanced, moved to nurture, or held with a current next action.",
            label: `Resolve ${overdueOpportunities.length} overdue revenue next action${overdueOpportunities.length === 1 ? "" : "s"}`,
            reason: opportunity.stalledReason || opportunity.nextAction,
            riskLevel: opportunity.stalledReason ? "high" : "medium",
        });
    }

    const selectedPod = requestedMarketPodId
        ? marketPods.find((pod) => pod.marketPodId === requestedMarketPodId)
        : marketPods.find((pod) => pod.status === "active") || marketPods[0];
    if (requestedMarketPodId && !selectedPod) throw new Error("Market pod not found");
    const blockedSources = sourceRuns.filter((run) => run.status !== "completed" || numberOrZero(run.suppressedCount) > 0 || numberOrZero(run.duplicateCount) > 0);
    if (blockedSources.length) {
        const source = blockedSources[0];
        pushAction({
            actionType: "review",
            entityId: source.sourceRunId,
            entityType: "source",
            expectedOutcome: "Source quality decision recorded before more targets are approved.",
            label: `Review source quality for ${source.sourceName}`,
            reason: `${source.duplicateCount} duplicates, ${source.suppressedCount} suppressed, ${source.blockedCount} blocked.`,
            riskLevel: source.status === "blocked" ? "high" : "medium",
        });
    }

    const readySender = senderDomains.find(isSenderDomainReady);
    if (!readySender) {
        pushAction({
            actionType: "hold",
            entityId: senderDomains[0]?.senderDomainId || null,
            entityType: "sender",
            expectedOutcome: "Outbound remains export/manual-only until sender identity, unsubscribe, bounce, and complaint handling are ready.",
            label: "Keep sender gate held",
            reason: "No active sender domain is fully authenticated and unsubscribe-ready.",
            riskLevel: "high",
        });
    }

    const contentAssetById = new Map(contentAssets.map((asset) => [asset.contentAssetId, asset]));
    const contentSourceById = new Map(contentSources.map((source) => [source.contentSourceId, source]));
    const proofPermissionById = new Map(proofPermissions.map((permission) => [permission.proofPermissionId, permission]));
    const selfServiceCtaById = new Map(selfServiceCtas.map((cta) => [cta.ctaId, cta]));
    const marketPodById = new Map(marketPods.map((pod) => [pod.marketPodId, pod]));
    const hasCurrentContentAuthority = (draft: SignalDeskContentDistributionDraftSummary) => {
        if (contentPauseSnap.data()?.status === "active" || draft.approvalStatus !== "approved") return false;
        const asset = contentAssetById.get(draft.contentAssetId);
        if (!asset || (asset.status !== "ready" && asset.status !== "distributed")) return false;
        if (asset.sourceId) {
            const source = contentSourceById.get(asset.sourceId);
            if (
                !source
                || source.status !== "active"
                || source.sourceType !== asset.sourceType
                || source.sourceUrl !== asset.sourceUrl
                || source.defaultAudience !== asset.primaryAudience
                || (source.defaultMarketPodId || null) !== (asset.marketPodId || null)
            ) return false;
        }
        if (asset.proofLevel === "customer-proof") {
            const permission = asset.proofPermissionId ? proofPermissionById.get(asset.proofPermissionId) : null;
            if (!isProofPermissionUsable(permission, asset.proofScopes || [])) return false;
        }
        const requiredCtaIds = Array.from(new Set([asset.ctaId, draft.ctaId].filter((value): value is string => Boolean(value))));
        if (!asset.ctaId || !draft.ctaId) return false;
        if (requiredCtaIds.some((ctaId) => selfServiceCtaById.get(ctaId)?.status !== "active")) return false;
        if (asset.ctaId && draft.ctaId !== asset.ctaId) return false;
        const draftCta = draft.ctaId ? selfServiceCtaById.get(draft.ctaId) : null;
        if (draftCta) {
            if (typeof draftCta.copy !== "string" || !normalizeText(draftCta.copy)) return false;
            const currentCtaFingerprintHash = signalDeskCtaFingerprintHash(draftCta);
            if (draft.ctaFingerprintHash !== currentCtaFingerprintHash) return false;
        } else if (draft.ctaFingerprintHash) {
            return false;
        }
        if (asset.marketPodId) {
            const pod = marketPodById.get(asset.marketPodId) as (SignalDeskMarketPodSummary & { approvedBy?: string | null; reviewDecision?: string | null }) | undefined;
            if (!pod || pod.status !== "active" || pod.reviewDecision !== "approved" || !normalizeText(pod.approvedBy)) return false;
        }
        return true;
    };
    const publishableDrafts = contentDrafts.filter((draft) => (
        (draft.status === "approved" || draft.status === "queued") && hasCurrentContentAuthority(draft)
    ));
    if (publishableDrafts.length) {
        const draft = publishableDrafts[0];
        pushAction({
            actionType: "manual-publish",
            entityId: draft.contentDraftId,
            entityType: "content",
            expectedOutcome: "Approved proof content is manually published or held with a reason.",
            label: `Use ${publishableDrafts.length} approved content draft${publishableDrafts.length === 1 ? "" : "s"}`,
            reason: draft.reviewReason || draft.hook || "Approved proof content is ready for manual distribution.",
            riskLevel: "medium",
        });
    }

    const activeExperiment = experiments.find((experiment) => experiment.status === "active");
    if (activeExperiment) {
        pushAction({
            actionType: "review",
            entityId: activeExperiment.experimentCardId,
            entityType: "experiment",
            expectedOutcome: "Experiment is repeated, narrowed, stopped, held, or marked complete.",
            label: "Review active experiment",
            reason: activeExperiment.stopRule,
            riskLevel: activeExperiment.status === "active" ? "medium" : "low",
        });
    }

    const partnerCandidate = trustPartners.find((partner) => partner.status === "candidate" || partner.status === "approved");
    if (partnerCandidate) {
        pushAction({
            actionType: "review",
            entityId: partnerCandidate.partnerId,
            entityType: "partner",
            expectedOutcome: "Trust partner is advanced only if audience fit, disclosure, and flat-fee gates are clean.",
            label: `Review trust partner ${partnerCandidate.displayName}`,
            reason: partnerCandidate.sourceNotes,
            riskLevel: partnerCandidate.partnerType === "generic-creator" ? "high" : "medium",
        });
    }

    if (!missionActions.length) {
        pushAction({
            actionType: "redirect",
            entityId: selectedPod?.marketPodId || null,
            entityType: "market-pod",
            expectedOutcome: "One narrow 7-day operating trial is selected before any scale-up.",
            label: "Start one controlled market pod",
            reason: selectedPod
                ? `${selectedPod.name}: ${selectedPod.offerAngle}`
                : "No active work queue exists; pick one city, one category, one source, one CTA, and one sender identity.",
            riskLevel: "low",
        });
    }

    const activeOfferCount = offerCtas.filter((offer) => offer.status === "active").length;
    const weekActivationCount = outcomes.filter((outcome) => outcome.day >= day.slice(0, 8)).reduce((sum, outcome) => sum + numberOrZero(outcome.count), 0);
    const demandSignalCount = demandSignals.reduce((sum, signal) => sum + numberOrZero(signal.count), 0);
    const revenueSummary = revenueControlSummaries[0];
    const cost = costSnap.exists ? projectSignalDeskCostDocument(costSnap.data(), costSnap.id) : null;
    if (costSnap.exists && !cost) throw new Error("SIGNALDESK_DAILY_COST_SHAPE_INVALID");
    const estimatedSpendToday = numberOrZero(cost?.aiCostEstimate) + numberOrZero(cost?.providerCostEstimate);
    const mission = {
        growthMissionId: missionRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        day,
        title: `Daily Growth Mission - ${day}`,
        summary: `${missionActions.length} founder decision${missionActions.length === 1 ? "" : "s"}; ${numberOrZero(revenueSummary?.openOpportunityCount)} open opportunities; ${stalledActivationWatches.length} stalled activations; ${numberOrZero(revenueSummary?.founderAttentionMinutes)} founder minutes; $${estimatedSpendToday.toFixed(2)} estimated spend today.`,
        expectedOutcome: stalledActivationWatches.length
            ? "Recover the oldest stalled activation before adding more targets or send volume."
            : overdueOpportunities.length
                ? "Resolve the oldest overdue revenue next action before widening the pod."
                : activeOfferCount
            ? "Move one narrow pod toward current-list upload, preview, or two-surface activation without expanding send volume."
            : "Create at least one approved offer CTA before outbound or partner work continues.",
        recommendedMarketPodId: selectedPod?.marketPodId || null,
        missionActions,
        approvalActionCount: missionActions.filter((action) => action.actionType === "approve").length,
        blockedActionCount: missionActions.filter((action) => action.riskLevel === "high" || action.actionType === "hold").length,
        ownerDecision: "pending",
        ownerDecisionNote: null,
        status: "ready",
        generationRequestFingerprintHash,
        generationRequestVersion: 1,
        generationRequestedMarketPodId: requestedMarketPodId,
        signalContext: {
            activeOfferCount,
            demandSignalCount,
            weekActivationCount,
        },
        createdAt: timestamp,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };

    const projectedMission = projectSignalDeskGrowthMission({
        ...toPlain(mission),
        [`${SIGNALDESK_COLLECTIONS.GROWTH_MISSIONS}DocId`]: missionRef.id,
    });
    if (!projectedMission) throw new Error("GROWTH_MISSION_SHAPE_INVALID");

    return await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const currentSnap = await transaction.get(missionRef);
        const currentMission = resolveExistingMission(currentSnap);
        if (currentMission) return currentMission;

        transaction.create(missionRef, sanitizeForFirestore(mission));
        appendAudit(db, transaction, access, "growth_mission_create", "growthMission", missionRef.id, day);
        writeRunTimeline(db, transaction, {
            entityId: missionRef.id,
            entityType: "mission",
            label: mission.title,
            status: "ready",
            steps: missionActions.map((action) => ({
                label: action.label,
                status: action.riskLevel === "high" ? "held" : "ready",
                at: toIso(timestamp),
            })),
        });
        updateDailyCost(db, transaction, 8 + missionActions.length, 0);
        return projectedMission;
    });
}

export async function reviewSignalDeskGrowthMissionServer(access: SignalDeskAccessContext, input: GrowthMissionReviewInput) {
    requireOperatingLayer();
    const db = requireDb();
    const growthMissionId = normalizeText(input.growthMissionId);
    const missionDay = growthMissionId.startsWith("growth_mission_")
        ? growthMissionId.slice("growth_mission_".length)
        : "";
    if (!isValidIsoDay(missionDay) || growthMissionId !== growthMissionIdFor(missionDay)) {
        throw new Error("GROWTH_MISSION_ID_INVALID");
    }
    if (!GROWTH_MISSION_OWNER_DECISIONS.has(input.ownerDecision)) {
        throw new Error("GROWTH_MISSION_DECISION_INVALID");
    }
    const status = growthMissionStatusForDecision(input.ownerDecision);
    if (input.status && input.status !== status) throw new Error("GROWTH_MISSION_STATE_CONFLICT");
    const ownerDecisionNote = normalizeText(input.ownerDecisionNote) || null;
    if ((ownerDecisionNote?.length || 0) > 800) throw new Error("GROWTH_MISSION_DECISION_NOTE_INVALID");
    const missionRef = db.collection(SIGNALDESK_COLLECTIONS.GROWTH_MISSIONS).doc(growthMissionId);

    return await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const missionSnap = await transaction.get(missionRef);
        if (!missionSnap.exists) throw new Error("Growth mission not found");
        const current = toPlain(missionSnap.data()) as AnyRecord;
        const currentProduct = normalizeText(current.pId);
        if (currentProduct && currentProduct !== SIGNALDESK_PRODUCT_CODE) {
            throw new Error("GROWTH_MISSION_PRODUCT_MISMATCH");
        }
        const prior = projectSignalDeskGrowthMission({
            ...current,
            [`${SIGNALDESK_COLLECTIONS.GROWTH_MISSIONS}DocId`]: missionSnap.id,
        });
        if (!prior) throw new Error("GROWTH_MISSION_SHAPE_INVALID");
        const exactReplay = prior.ownerDecision === input.ownerDecision
            && prior.status === status
            && (prior.ownerDecisionNote || null) === ownerDecisionNote;
        if (exactReplay) return prior;
        if (prior.status === "completed" || prior.ownerDecision === "completed") {
            throw new Error("GROWTH_MISSION_TERMINAL");
        }

        const timestamp = now();
        const actionStatus = growthMissionActionStatusForDecision(input.ownerDecision);
        const updates = {
            ownerDecision: input.ownerDecision,
            ownerDecisionNote,
            missionActions: prior.missionActions.map((action) => ({ ...action, status: actionStatus })),
            status,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        const projected = projectSignalDeskGrowthMission({
            ...current,
            ...toPlain(updates),
            [`${SIGNALDESK_COLLECTIONS.GROWTH_MISSIONS}DocId`]: missionSnap.id,
        });
        if (!projected) throw new Error("GROWTH_MISSION_STATE_CONFLICT");

        transaction.set(missionRef, sanitizeForFirestore(updates), { merge: true });
        appendAudit(db, transaction, access, "growth_mission_review", "growthMission", growthMissionId, input.ownerDecision);
        writeRunTimeline(db, transaction, {
            entityId: growthMissionId,
            entityType: "mission",
            label: `Mission reviewed: ${prior.title}`,
            status: status === "completed" ? "completed" : status === "held" ? "held" : "ready",
            steps: [
                { label: "Owner decision recorded", status: "completed", at: toIso(timestamp) },
                { label: `Decision: ${input.ownerDecision}`, status: input.ownerDecision === "hold" ? "held" : "ready", at: toIso(timestamp) },
            ],
        });
        updateDailyCost(db, transaction, 3, 0);
        return projected;
    });
}

export async function createSignalDeskSourceQualitySnapshotServer(access: SignalDeskAccessContext, input: SourceQualitySnapshotInput = {}) {
    requireOperatingLayer();
    const db = requireDb();
    const batch = db.batch();
    const timestamp = now();
    const [sourceRuns, targets, outcomes] = await Promise.all([
        readSourceRunList(db),
        readTargetSummaryList(db, 100),
        readOutcomeSummaryList(db, LIST_LIMIT, "source-quality"),
    ]);
    const sourceRun = input.sourceRunId
        ? sourceRuns.find((run) => run.sourceRunId === input.sourceRunId)
        : sourceRuns.find((run) => !input.sourcePolicyId || run.sourcePolicyId === input.sourcePolicyId) || sourceRuns[0];
    const policy = await readSourcePolicy(db, input.sourcePolicyId || sourceRun?.sourcePolicyId || null);
    const policyState = getSourcePolicyState(policy);
    const relatedTargets = targets.filter((target) => (
        (sourceRun?.sourceRunId && target.sourceRunId === sourceRun.sourceRunId) ||
        (policy?.sourcePolicyId && target.sourcePolicyId === policy.sourcePolicyId)
    ));
    const targetCount = numberOrZero(sourceRun?.importedCount) || relatedTargets.length;
    const duplicateRate = targetCount ? numberOrZero(sourceRun?.duplicateCount) / targetCount : 0;
    const usableTargetCount = relatedTargets.filter((target) => target.suppressionStatus === "clear" && target.status !== "rejected").length;
    const usableTargetRate = relatedTargets.length ? usableTargetCount / relatedTargets.length : targetCount ? Math.max(0, 1 - duplicateRate) : 0;
    const targetIds = new Set(relatedTargets.map((target) => target.targetId));
    const activationCount = outcomes
        .filter((outcome) => isVerifiedTwoSurfaceOutcome(outcome) && (!targetIds.size || (outcome.targetId && targetIds.has(outcome.targetId))))
        .reduce((sum, outcome) => sum + numberOrZero(outcome.count), 0);
    const activationRate = targetCount ? activationCount / targetCount : 0;
    const evidenceQualityScore = relatedTargets.length
        ? Math.round(relatedTargets.reduce((sum, target) => {
            if (target.sourceConfidence === "high") return sum + 90;
            if (target.sourceConfidence === "medium") return sum + 70;
            if (target.sourceConfidence === "low") return sum + 45;
            return sum + 10;
        }, 0) / relatedTargets.length)
        : policy ? 65 : 35;
    const complaintOrBounceRisk: SignalDeskSourceQualitySnapshotSummary["complaintOrBounceRisk"] = duplicateRate > 0.35 || numberOrZero(sourceRun?.suppressedCount) > 2
        ? "high"
        : duplicateRate > 0.15 || numberOrZero(sourceRun?.suppressedCount) > 0
            ? "medium"
            : "low";
    const recommendation: SignalDeskSourceQualitySnapshotSummary["recommendation"] = !policy
        ? "needs-policy"
        : policyState === "expired"
            ? "stop"
            : policyState === "review_required"
                ? "needs-policy"
        : complaintOrBounceRisk === "high"
            ? "stop"
            : usableTargetRate < 0.5
                ? "narrow"
                : evidenceQualityScore < 55
                    ? "refresh"
                    : "continue";
    const snapshotRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_QUALITY_SNAPSHOTS).doc(sourceQualitySnapshotIdFor({
        sourcePolicyId: policy?.sourcePolicyId || input.sourcePolicyId,
        sourceRunId: sourceRun?.sourceRunId || input.sourceRunId,
    }));
    const snapshot = {
        sourceQualitySnapshotId: snapshotRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        sourcePolicyId: policy?.sourcePolicyId || input.sourcePolicyId || null,
        sourceRunId: sourceRun?.sourceRunId || input.sourceRunId || null,
        sourceName: sourceRun?.sourceName || policy?.name || "Unselected source",
        targetCount,
        usableTargetRate,
        duplicateRate,
        activationRate,
        evidenceQualityScore,
        complaintOrBounceRisk: policyState === "expired" || policyState === "review_required" ? "high" : complaintOrBounceRisk,
        recommendation,
        createdAt: timestamp,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };
    batch.set(snapshotRef, sanitizeForFirestore(snapshot), { merge: true });
    appendAudit(db, batch, access, "source_quality_snapshot_create", "sourceQualitySnapshot", snapshotRef.id, recommendation);
    writeRunTimeline(db, batch, {
        entityId: snapshotRef.id,
        entityType: "source-quality",
        label: `Source quality: ${snapshot.sourceName}`,
        status: recommendation === "continue" ? "ready" : recommendation === "stop" || recommendation === "needs-policy" ? "blocked" : "held",
        steps: [
            { label: `Usable rate ${Math.round(usableTargetRate * 100)}%`, status: usableTargetRate >= 0.5 ? "completed" : "held", at: toIso(timestamp) },
            { label: `Duplicate rate ${Math.round(duplicateRate * 100)}%`, status: duplicateRate <= 0.15 ? "completed" : "held", at: toIso(timestamp) },
            { label: `Recommendation: ${recommendation}`, status: recommendation === "continue" ? "ready" : "held", at: toIso(timestamp) },
        ],
    });
    updateDailyCost(db, batch, 6, 0);
    await batch.commit();
    return toPlain(snapshot) as SignalDeskSourceQualitySnapshotSummary;
}

export async function upsertSignalDeskChannelWindowStateServer(access: SignalDeskAccessContext, input: ChannelWindowStateInput) {
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("CHANNEL_WINDOW_IDEMPOTENCY_KEY_REQUIRED");
    const requestFingerprintHash = hashValue(JSON.stringify({
        channel: input.channel,
        expiresAt: normalizeText(input.expiresAt),
        reason: normalizeText(input.reason),
        source: input.source,
        status: input.status,
        targetId: input.targetId || null,
    }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const defaultDays = input.source === "ad-click" ? 3 : input.source === "template" ? 0 : 1;
    const windowRef = db.collection(SIGNALDESK_COLLECTIONS.CHANNEL_WINDOW_STATES).doc(channelWindowIdFor(input.channel, input.targetId));
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`channel_window_${operationHash}`);
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const [claimSnap, targetSnap, windowSnap] = await Promise.all([
            transaction.get(claimRef),
            input.targetId ? transaction.get(db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(input.targetId)) : Promise.resolve(null),
            transaction.get(windowRef),
        ]);
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) throw new Error("CHANNEL_WINDOW_IDEMPOTENCY_CONFLICT");
            if (!windowSnap.exists) throw new Error("CHANNEL_WINDOW_REPLAY_MISSING");
            return toPlain(windowSnap.data()) as SignalDeskChannelWindowStateSummary;
        }
        if (input.targetId && !targetSnap?.exists) throw new Error("Target not found");
        const timestamp = now();
        const expiresAt = input.status === "open"
            ? timestampFromIsoOrDefault(input.expiresAt, defaultDays)
            : input.expiresAt ? timestampFromIsoOrDefault(input.expiresAt, defaultDays) : null;
        const eligibleForHandoff = input.status === "open" && input.source !== "template" && (!expiresAt || new Date(toIso(expiresAt) || "").getTime() > Date.now());
        const windowState = {
            channelWindowId: windowRef.id, pId: SIGNALDESK_PRODUCT_CODE, channel: input.channel,
            targetId: input.targetId || null, targetName: targetSnap?.exists ? normalizeText(targetSnap.data()?.displayName) : null,
            source: input.source, status: input.status, eligibleForHandoff, reason: input.reason || null,
            openedAt: input.status === "open" ? timestamp : null, lastInteractionAt: timestamp, expiresAt,
            updatedAt: timestamp, updatedBy: access.userId,
        };
        transaction.set(windowRef, sanitizeForFirestore(windowState), { merge: true });
        transaction.set(db.collection(SIGNALDESK_COLLECTIONS.CHANNEL_HEALTH_SUMMARIES).doc(input.channel), sanitizeForFirestore({
            channel: input.channel, configured: true, lastEventAt: timestamp,
            status: eligibleForHandoff ? "healthy" : input.status === "blocked" ? "warning" : "paused",
            lastError: eligibleForHandoff ? null : input.reason || "Channel window is not ready.", updatedAt: timestamp,
        }), { merge: true });
        transaction.create(claimRef, sanitizeForFirestore({ actorId: access.userId, entityId: windowRef.id, operation: "channel_window_upsert", pId: SIGNALDESK_PRODUCT_CODE, requestFingerprintHash, updatedAt: timestamp }));
        writeRunTimeline(db, transaction, {
        entityId: windowRef.id,
        entityType: "channel-window",
        label: `${input.channel} channel window`,
        status: eligibleForHandoff ? "ready" : input.status === "blocked" ? "blocked" : "held",
        steps: [
            { label: `${input.source} source recorded`, status: "completed", at: toIso(timestamp) },
            { label: "Window eligibility checked", status: eligibleForHandoff ? "completed" : "held", at: toIso(timestamp) },
        ],
        });
        appendAudit(db, transaction, access, "channel_window_upsert", "channelWindow", windowRef.id, input.channel);
        updateDailyCost(db, transaction, 4, 0, 0);
        return toPlain(windowState) as SignalDeskChannelWindowStateSummary;
    });
}

export async function refreshSignalDeskProviderSourceRetentionServer(
    access: SignalDeskAccessContext,
    input: ProviderSourceRetentionRefreshInput,
) {
    const db = requireDb();
    const retentionRef = db.collection(SIGNALDESK_COLLECTIONS.PROVIDER_SOURCE_RETENTION).doc(input.providerSourceRetentionId);
    const retentionSnap = await retentionRef.get();
    if (!retentionSnap.exists) throw new Error("Provider source retention record not found");
    const existing = toPlain(retentionSnap.data()) as SignalDeskProviderSourceRetentionSummary;
    await assertSourcePolicyUsable(db, access, await readSourcePolicy(db, existing.sourcePolicyId), {
        entityId: input.providerSourceRetentionId,
        use: "retention-refresh",
    });
    const batch = db.batch();
    const timestamp = now();
    const refreshed = input.status === "refreshed";
    const updates = {
        status: input.status,
        lastRefreshedAt: refreshed ? timestamp : existing.lastRefreshedAt || null,
        refreshDueAt: refreshed && existing.provider === "google-places" ? timestampAfterDays(365) : existing.refreshDueAt || null,
        retentionExpiresAt: refreshed ? timestampAfterDays(365) : existing.retentionExpiresAt || null,
        notes: input.notes || null,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };
    batch.set(retentionRef, sanitizeForFirestore(updates), { merge: true });
    writeRunTimeline(db, batch, {
        entityId: retentionRef.id,
        entityType: "provider",
        label: `${existing.provider} retention refresh`,
        status: refreshed ? "completed" : input.status === "blocked" ? "blocked" : "held",
        steps: [
            { label: "Provider source record loaded", status: "completed", at: toIso(timestamp) },
            { label: refreshed ? "Refresh state updated" : `Marked ${input.status}`, status: refreshed ? "completed" : "held", at: toIso(timestamp) },
        ],
    });
    appendAudit(db, batch, access, "provider_source_retention_refresh", "providerSourceRetention", retentionRef.id, input.status);
    updateDailyCost(db, batch, 3, 0, 0);
    await batch.commit();
    return { ...existing, ...toPlain(updates), providerSourceRetentionId: retentionRef.id } as SignalDeskProviderSourceRetentionSummary;
}

export async function recommendSignalDeskMarketPodPlanServer(
    access: SignalDeskAccessContext,
    input: MarketPodRecommendationInput,
) {
    const db = requireDb();
    const [targetSnap, outcomeSnap, demandSnap] = await Promise.all([
        db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).orderBy("updatedAt", "desc").limit(30).get(),
        db.collection(SIGNALDESK_COLLECTIONS.OUTCOME_SUMMARIES).orderBy("updatedAt", "desc").limit(30).get(),
        db.collection(SIGNALDESK_COLLECTIONS.DEMAND_SIGNAL_SUMMARIES).orderBy("updatedAt", "desc").limit(30).get(),
    ]);
    const targets = targetSnap.docs
        .filter((doc: any) => normalizeText(doc.data()?.pId) === SIGNALDESK_PRODUCT_CODE)
        .map((doc: any) => toPlain(doc.data()) as SignalDeskTargetSummary);
    const outcomes = await projectStrictOutcomeSummaryDocuments(
        db,
        outcomeSnap.docs,
        (reference) => reference.get(),
        "market-pod-recommendation",
    );
    const demand = demandSnap.docs
        .filter((doc: any) => normalizeText(doc.data()?.pId) === SIGNALDESK_PRODUCT_CODE)
        .map((doc: any) => toPlain(doc.data()) as SignalDeskDemandSignalSummary);
    const grouped = new Map<string, { category: string; city: string; count: number }>();
    targets.forEach((target) => {
        const city = target.city || "Unknown city";
        const category = target.category || "restaurant";
        const key = `${city}|${category}`;
        const current = grouped.get(key) || { category, city, count: 0 };
        current.count += 1;
        grouped.set(key, current);
    });
    const best = Array.from(grouped.values()).sort((a, b) => b.count - a.count)[0] || { category: "restaurant", city: "First city", count: 0 };
    const outcomeCount = outcomes.reduce((sum, outcome) => sum + numberOrZero(outcome.count), 0);
    const demandCount = demand.reduce((sum, signal) => sum + numberOrZero(signal.count), 0);
    const confidence: SignalDeskConfidence = best.count >= 5 && (outcomeCount || demandCount) ? "high" : best.count >= 3 ? "medium" : "low";
    const recommendation: NonNullable<SignalDeskMarketPodSummary["recommendation"]> = confidence === "low" ? "hold" : outcomeCount ? "expand" : "activate";
    const timestamp = now();
    const podRef = db.collection(SIGNALDESK_COLLECTIONS.MARKET_PODS).doc(input.marketPodId || `market_pod_${hashValue(`${best.city}|${best.category}`).slice(0, 18)}`);
    const recommendationReason = `${best.count} matching targets, ${demandCount} demand signals, ${outcomeCount} outcomes.`;
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const existingPodSnap = await transaction.get(podRef);
        if (existingPodSnap.exists && normalizeText(existingPodSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
            throw new Error("MARKET_POD_PRODUCT_MISMATCH");
        }
        const existingPod = existingPodSnap.exists
            ? toPlain(existingPodSnap.data()) as SignalDeskMarketPodSummary
            : null;
        const recommendationUpdates = {
            confidence,
            marketPodId: podRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            recommendation,
            recommendationReason,
            recommendedActions: [
                "Keep source policy approved before imports.",
                "Prepare evidence packets before outbound.",
                "Use one CTA until outcomes prove another angle.",
            ],
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        const createOnlyFields = existingPod ? {} : {
            approvedAt: null,
            approvedBy: null,
            category: best.category,
            city: best.city,
            country: "India",
            monthlyBudgetUsd: 0,
            name: `${best.city} ${best.category} pod`,
            offerAngle: "Current-list proof and private preview.",
            reviewDecision: null,
            reviewedAt: null,
            reviewedBy: null,
            reviewReason: null,
            status: "hold" as const,
            successMetric: outcomeCount ? "two_surface_activation" : "preview_prepared",
        };
        const pod = { ...existingPod, ...createOnlyFields, ...recommendationUpdates };
        transaction.set(podRef, sanitizeForFirestore({ ...createOnlyFields, ...recommendationUpdates }), { merge: true });
        writeRunTimeline(db, transaction, {
            entityId: podRef.id,
            entityType: "market-pod",
            label: "Market pod recommendation",
            status: recommendation === "hold" ? "held" : "ready",
            steps: [
                { label: `${best.count} targets scanned`, status: best.count ? "completed" : "held", at: toIso(timestamp) },
                { label: `${demandCount} demand signals checked`, status: demandCount ? "completed" : "held", at: toIso(timestamp) },
                { label: `${recommendation} recommendation`, status: recommendation === "hold" ? "held" : "ready", at: toIso(timestamp) },
            ],
        });
        appendAudit(db, transaction, access, "market_pod_recommend", "marketPod", podRef.id, recommendationReason);
        updateDailyCost(db, transaction, 4, 0, 0);
        const projectedPod = projectSignalDeskMarketPod({
            ...toPlain(pod),
            [`${SIGNALDESK_COLLECTIONS.MARKET_PODS}DocId`]: podRef.id,
        });
        if (!projectedPod) throw new Error("MARKET_POD_SHAPE_INVALID");
        return projectedPod;
    });
}

export async function reviewSignalDeskMarketPodServer(
    access: SignalDeskAccessContext,
    input: MarketPodReviewInput,
) {
    requireOperatingLayer();
    if (access.role !== "founder-admin" || !access.permissions.includes("signaldesk.configure")) {
        throw new Error("Founder approval is required for market pod decisions");
    }
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("MARKET_POD_REVIEW_IDEMPOTENCY_KEY_REQUIRED");
    const podRef = db.collection(SIGNALDESK_COLLECTIONS.MARKET_PODS).doc(input.marketPodId);
    const requestFingerprintHash = hashValue(JSON.stringify({
        decision: input.decision,
        marketPodId: input.marketPodId,
        reason: normalizeText(input.reason),
    }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`market_pod_review_${operationHash}`);
    await resumePendingContentAuthorityReconciliation(db, access, {
        action: "market_pod_dependency_reconcile_recovery",
        assetField: "marketPodId",
        assetValue: input.marketPodId,
        authorityRef: podRef,
        entityType: "marketPod",
        reason: "Market pod authority changed. Review before distribution.",
        shouldHoldAsset: () => true,
    });
    const transactionResult = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const [claimSnap, podSnap] = await Promise.all([
            transaction.get(claimRef),
            transaction.get(podRef),
        ]);
        if (!podSnap.exists) throw new Error("Market pod not found");
        if (normalizeText(podSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) throw new Error("MARKET_POD_PRODUCT_MISMATCH");
        const existing = projectSignalDeskMarketPod({
            ...toPlain(podSnap.data()),
            [`${SIGNALDESK_COLLECTIONS.MARKET_PODS}DocId`]: podRef.id,
        });
        if (!existing) throw new Error("MARKET_POD_SHAPE_INVALID");
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) {
                throw new Error("MARKET_POD_REVIEW_IDEMPOTENCY_CONFLICT");
            }
            const replay = claimSnap.data()?.resultSnapshot
                ? projectSignalDeskMarketPod({
                    ...toPlain(claimSnap.data()?.resultSnapshot),
                    pId: SIGNALDESK_PRODUCT_CODE,
                    [`${SIGNALDESK_COLLECTIONS.MARKET_PODS}DocId`]: podRef.id,
                })
                : existing;
            if (!replay) throw new Error("MARKET_POD_REVIEW_REPLAY_MISSING");
            const reconciliationToken = normalizeText(podSnap.data()?.dependentHoldReconciliationToken);
            return {
                pod: replay,
                reconciliationRequired: podSnap.data()?.dependentHoldReconciliationPending === true
                    && reconciliationToken === claimRef.id,
                reconciliationToken,
            };
        }
        if (podSnap.data()?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        const timestamp = now();
        const status: SignalDeskMarketPodSummary["status"] = input.decision === "approved"
            ? "active"
            : input.decision === "rejected"
                ? "blocked"
                : "hold";
        const reconciliationRequired = input.decision !== "approved"
            && (existing.status === "active" || existing.reviewDecision === "approved");
        const reconciliationToken = reconciliationRequired ? claimRef.id : "";
        const updates = {
            approvedAt: input.decision === "approved" ? timestamp : existing.approvedAt || null,
            approvedBy: input.decision === "approved" ? access.userId : existing.approvedBy || null,
            reviewDecision: input.decision,
            reviewedAt: timestamp,
            reviewedBy: access.userId,
            reviewReason: normalizeText(input.reason),
            status,
            dependentHoldReconciliationKind: reconciliationRequired
                ? CONTENT_AUTHORITY_RECONCILIATION_KIND
                : null,
            dependentHoldReconciliationPending: reconciliationRequired,
            dependentHoldReconciliationProgress: reconciliationRequired
                ? emptyContentAuthorityReconciliationResult()
                : null,
            dependentHoldReconciliationToken: reconciliationToken || null,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        transaction.set(podRef, sanitizeForFirestore(updates), { merge: true });
        const result = projectSignalDeskMarketPod({
            ...toPlain({ ...existing, ...updates, pId: SIGNALDESK_PRODUCT_CODE }),
            [`${SIGNALDESK_COLLECTIONS.MARKET_PODS}DocId`]: podRef.id,
        });
        if (!result) throw new Error("MARKET_POD_SHAPE_INVALID");
        transaction.create(claimRef, sanitizeForFirestore({
            actorId: access.userId,
            entityId: input.marketPodId,
            operation: "market_pod_review",
            pId: SIGNALDESK_PRODUCT_CODE,
            requestFingerprintHash,
            resultSnapshot: { ...toPlain(result), pId: SIGNALDESK_PRODUCT_CODE },
            updatedAt: timestamp,
        }));
        appendAudit(db, transaction, access, "market_pod_review", "marketPod", input.marketPodId, `${input.decision}: ${normalizeText(input.reason)}`);
        writeRunTimeline(db, transaction, {
            entityId: input.marketPodId,
            entityType: "market-pod",
            label: `Market pod reviewed: ${existing.name}`,
            status: input.decision === "approved" ? "ready" : input.decision === "rejected" ? "blocked" : "held",
            steps: [
                { label: "Founder decision recorded", status: "completed", at: toIso(timestamp) },
                { label: `Decision: ${input.decision}`, status: input.decision === "approved" ? "ready" : input.decision === "rejected" ? "blocked" : "held", at: toIso(timestamp) },
            ],
        });
        updateDailyCost(db, transaction, 5, 0);
        return { pod: result, reconciliationRequired, reconciliationToken };
    });
    if (transactionResult.reconciliationRequired) {
        if (!transactionResult.reconciliationToken) throw new Error("CONTENT_AUTHORITY_RECONCILIATION_TOKEN_MISSING");
        const reconciliationResult = await reconcileContentAuthorityHolds(db, {
            actorId: access.userId,
            assetField: "marketPodId",
            assetValue: input.marketPodId,
            authorityRef: podRef,
            reason: "Market pod authority changed. Review before distribution.",
            reconciliationToken: transactionResult.reconciliationToken,
            shouldHoldAsset: () => true,
        });
        await completeContentAuthorityReconciliation(db, access, {
            action: "market_pod_dependency_reconcile",
            authorityRef: podRef,
            entityType: "marketPod",
            reconciliationToken: transactionResult.reconciliationToken,
        }, reconciliationResult);
    }
    return transactionResult.pod;
}

export async function createSignalDeskWeeklyStrategistMemoServer(
    access: SignalDeskAccessContext,
    input: WeeklyStrategistMemoInput,
) {
    const db = requireDb();
    const weekStart = firstDayOfWeekKey(input.weekStart);
    const [targetSnap, outcomeSnap, demandSnap, costSnap, providerEvalSnap, podSnap] = await Promise.all([
        db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).orderBy("updatedAt", "desc").limit(30).get(),
        db.collection(SIGNALDESK_COLLECTIONS.OUTCOME_SUMMARIES).orderBy("updatedAt", "desc").limit(30).get(),
        db.collection(SIGNALDESK_COLLECTIONS.DEMAND_SIGNAL_SUMMARIES).orderBy("updatedAt", "desc").limit(30).get(),
        db.collection(SIGNALDESK_COLLECTIONS.COST_DAILY_SUMMARIES).doc(todayKey()).get(),
        db.collection(SIGNALDESK_COLLECTIONS.PROVIDER_EVALUATIONS).orderBy("updatedAt", "desc").limit(10).get(),
        db.collection(SIGNALDESK_COLLECTIONS.MARKET_PODS).orderBy("updatedAt", "desc").limit(1).get(),
    ]);
    const targetCount = targetSnap.size;
    const outcomes = await projectStrictOutcomeSummaryDocuments(
        db,
        outcomeSnap.docs,
        (reference) => reference.get(),
        "weekly-strategist-memo",
    );
    const outcomeCount = outcomes.reduce((sum, outcome) => sum + numberOrZero(outcome.count), 0);
    const demandCount = demandSnap.docs.reduce((sum: number, doc: any) => sum + numberOrZero(doc.data()?.count), 0);
    const cost = costSnap.exists ? projectSignalDeskCostDocument(costSnap.data(), costSnap.id) : null;
    if (costSnap.exists && !cost) throw new Error("SIGNALDESK_DAILY_COST_SHAPE_INVALID");
    const providerEvaluations = providerEvalSnap.docs.map((doc: any) => toPlain(doc.data()) as SignalDeskProviderEvaluationSummary);
    const bestProvider = providerEvaluations.find((item) => item.recommendation === "approve") || providerEvaluations[0] || null;
    const podDoc = podSnap.docs[0] || null;
    const pod = podDoc && podDoc.data()?.dependentHoldReconciliationPending !== true
        ? projectSignalDeskMarketPod({
            ...toPlain(podDoc.data()),
            [`${SIGNALDESK_COLLECTIONS.MARKET_PODS}DocId`]: podDoc.id,
        })
        : null;
    const status: SignalDeskStrategistMemoSummary["status"] = targetCount && (demandCount || outcomeCount) ? "ready" : "held";
    const timestamp = now();
    const memoRef = db.collection(SIGNALDESK_COLLECTIONS.STRATEGIST_MEMOS).doc(`strategist_${weekStart}`);
    const memo = {
        strategistMemoId: memoRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        weekStart,
        title: `SignalDesk weekly memo ${weekStart}`,
        status,
        summary: `${targetCount} targets, ${demandCount} demand signals, ${outcomeCount} outcomes. ${status === "ready" ? "Use the strongest pod and keep send gates closed until sender policy is complete." : "Hold scale until one pod/source/CTA has enough proof."}`,
        nextDecisions: [
            pod ? `Review pod: ${pod.name}` : "Choose first market pod.",
            bestProvider ? `Review provider eval: ${bestProvider.provider}/${bestProvider.use}` : "Run provider evaluation after first provider run.",
            "Keep provider send disabled until sender readiness is complete.",
        ],
        riskNotes: [
            "No generic lead blasting.",
            "No provider send without source, suppression, unsubscribe, and sender-domain readiness.",
        ],
        costSummary: `$${(numberOrZero(cost?.aiCostEstimate) + numberOrZero(cost?.providerCostEstimate)).toFixed(2)} estimated today.`,
        providerQualitySummary: bestProvider ? `${bestProvider.provider}: ${bestProvider.recommendation}` : "No provider evaluation yet.",
        recommendedMarketPodId: pod?.marketPodId || null,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };
    const batch = db.batch();
    batch.set(memoRef, sanitizeForFirestore(memo), { merge: true });
    writeRunTimeline(db, batch, {
        entityId: memoRef.id,
        entityType: "model",
        label: "Weekly strategist memo",
        status: status === "ready" ? "ready" : "held",
        steps: [
            { label: "Outcomes checked", status: outcomeCount ? "completed" : "held", at: toIso(timestamp) },
            { label: "Demand checked", status: demandCount ? "completed" : "held", at: toIso(timestamp) },
            { label: "Next decisions prepared", status: "completed", at: toIso(timestamp) },
        ],
    });
    appendAudit(db, batch, access, "weekly_strategist_memo_create", "strategistMemo", memoRef.id, memo.status);
    updateDailyCost(db, batch, 3, 0, 0);
    await batch.commit();
    return toPlain(memo) as SignalDeskStrategistMemoSummary;
}

export async function createSignalDeskProviderEvaluationServer(
    access: SignalDeskAccessContext,
    input: ProviderEvaluationInput,
) {
    const db = requireDb();
    const currentPeriod = getSignalDeskSpendPeriod();
    const populationLimit = 101;
    const [account, vendorRunSnapshot, enrichmentResultSnapshot] = await Promise.all([
        readProviderAccount(db, input.provider, input.use, currentPeriod),
        db.collection(SIGNALDESK_COLLECTIONS.VENDOR_RUNS)
            .where("provider", "==", input.provider)
            .where("providerUse", "==", input.use)
            .where("accountingMonth", "==", currentPeriod.spendMonthKey)
            .limit(populationLimit)
            .get(),
        db.collection(SIGNALDESK_COLLECTIONS.ENRICHMENT_RESULTS)
            .where("provider", "==", input.provider)
            .where("providerUse", "==", input.use)
            .where("accountingMonth", "==", currentPeriod.spendMonthKey)
            .limit(populationLimit)
            .get(),
    ]);
    const populationTruncated = vendorRunSnapshot.size >= populationLimit
        || enrichmentResultSnapshot.size >= populationLimit;
    const projectedVendorRuns = vendorRunSnapshot.docs.slice(0, populationLimit - 1).flatMap((document) => {
        const projected = projectSignalDeskWorkspaceDocument(
            SIGNALDESK_COLLECTIONS.VENDOR_RUNS,
            document.data(),
            document.id,
            currentPeriod,
        );
        return projected ? [projected as SignalDeskVendorRunSummary] : [];
    });
    const providerRuns = projectedVendorRuns.filter((run) => (
        run.status === "completed" || run.status === "failed" || run.status === "blocked"
    ));
    const resultRows = enrichmentResultSnapshot.docs.slice(0, populationLimit - 1).flatMap((document) => {
        const projected = projectSignalDeskWorkspaceDocument(
            SIGNALDESK_COLLECTIONS.ENRICHMENT_RESULTS,
            document.data(),
            document.id,
            currentPeriod,
        );
        return projected ? [projected as SignalDeskEnrichmentResultSummary] : [];
    });
    const rejectedPopulationRows = Math.min(populationLimit - 1, vendorRunSnapshot.size) - projectedVendorRuns.length
        + Math.min(populationLimit - 1, enrichmentResultSnapshot.size) - resultRows.length;
    if (rejectedPopulationRows > 0) {
        logRuntimeFailure(
            "signaldesk_provider_evaluation_population_rejected",
            new Error("SIGNALDESK_PROVIDER_EVALUATION_POPULATION_INVALID"),
            {
                provider: input.provider,
                rejectedPopulationRows,
                spendMonthKey: currentPeriod.spendMonthKey,
                use: input.use,
            },
        );
    }
    const sampleSize = Math.max(providerRuns.length, resultRows.length);
    const blockedRuns = providerRuns.filter((run) => run.status === "blocked" || run.status === "failed").length;
    const verified = resultRows.filter((result) => result.status === "verified").length;
    const usefulResults = Math.max(
        verified,
        providerRuns.reduce((sum, run) => sum + (
            run.status === "completed" ? numberOrZero(run.resultCount) : 0
        ), 0),
    );
    const providerSpend = numberOrZero(account?.spentMonthUsd);
    const verifiedContactRate = sampleSize ? verified / sampleSize : 0;
    const blockedRate = sampleSize ? blockedRuns / sampleSize : account && account.status !== "approved" ? 1 : 0;
    const evidenceQualityScore = sampleSize ? Math.round(Math.min(100, (usefulResults / Math.max(1, sampleSize)) * 100)) : 0;
    const recommendation: SignalDeskProviderEvaluationSummary["recommendation"] = populationTruncated || rejectedPopulationRows > 0
        ? "hold"
        : !account || account.status === "disabled" || account.status === "blocked"
        ? "hold"
        : blockedRate > 0.4
            ? "reject"
            : sampleSize < 3
                ? "test-more"
                : evidenceQualityScore >= 60
                    ? "approve"
                    : "hold";
    const status: SignalDeskProviderEvaluationSummary["status"] = recommendation === "approve"
        ? "passed"
        : recommendation === "reject"
            ? "failed"
            : !account
                ? "blocked"
                : "needs-review";
    const timestamp = now();
    const evalRef = db.collection(SIGNALDESK_COLLECTIONS.PROVIDER_EVALUATIONS).doc(`provider_eval_${input.provider}_${input.use}`);
    const evaluation = {
        providerEvaluationId: evalRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        accountingMonth: currentPeriod.spendMonthKey,
        populationTruncated,
        provider: input.provider,
        use: input.use,
        status,
        sampleSize,
        verifiedContactRate,
        evidenceQualityScore,
        replyOutcomeScore: 0,
        costPerUsefulResultUsd: usefulResults ? providerSpend / usefulResults : 0,
        blockedRate,
        suppressionRisk: blockedRate > 0.4 ? "high" : blockedRate > 0.15 ? "medium" : "low",
        recommendation,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };
    const batch = db.batch();
    batch.set(evalRef, sanitizeForFirestore(evaluation), { merge: true });
    writeRunTimeline(db, batch, {
        entityId: evalRef.id,
        entityType: "provider",
        label: `${input.provider} provider evaluation`,
        status: status === "passed" ? "completed" : status === "blocked" || status === "failed" ? "blocked" : "held",
        steps: [
            { label: `${sampleSize} sample rows`, status: sampleSize ? "completed" : "held", at: toIso(timestamp) },
            { label: `${Math.round(blockedRate * 100)}% blocked rate`, status: blockedRate > 0.4 ? "blocked" : "completed", at: toIso(timestamp) },
            { label: `${recommendation} recommendation`, status: recommendation === "approve" ? "completed" : "held", at: toIso(timestamp) },
        ],
    });
    appendAudit(db, batch, access, "provider_evaluation_create", "providerEvaluation", evalRef.id, `${input.provider}/${input.use}`);
    updateDailyCost(db, batch, 3, 0, 0);
    await batch.commit();
    return toPlain(evaluation) as SignalDeskProviderEvaluationSummary;
}

export async function upsertSignalDeskTrustPartnerProfileServer(
    access: SignalDeskAccessContext,
    input: TrustPartnerProfileInput,
) {
    requireTrustPartnerRail();
    const db = requireDb();
    const batch = db.batch();
    const timestamp = now();
    const partnerId = trustPartnerIdFor(input.displayName, input.channel);
    const trustScore = computeTrustScore(input);
    const status = input.status || (input.partnerType === "generic-creator" || trustScore < 45 ? "rejected" : trustScore >= 70 ? "candidate" : "hold");
    const profileRef = db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES).doc(partnerId);
    const profile = {
        partnerId,
        pId: SIGNALDESK_PRODUCT_CODE,
        displayName: input.displayName,
        partnerType: input.partnerType,
        channel: input.channel,
        geography: input.geography || null,
        baselineReachScore: clampScore(input.baselineReachScore),
        commentQualityScore: clampScore(input.commentQualityScore),
        audienceFitScore: clampScore(input.audienceFitScore),
        believableUsageScore: clampScore(input.believableUsageScore),
        trustFeelScore: clampScore(input.trustFeelScore),
        trustScore,
        sourceNotes: input.sourceNotes,
        status,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };
    batch.set(profileRef, sanitizeForFirestore(profile), { merge: true });
    writeRunTimeline(db, batch, {
        entityId: partnerId,
        entityType: "trust-partner",
        label: "Trust partner profile",
        status: status === "rejected" ? "blocked" : status === "hold" ? "held" : "ready",
        steps: [
            { label: "20-second trust scores captured", status: "completed", at: toIso(timestamp) },
            { label: `${trustScore} trust score`, status: trustScore >= 70 ? "completed" : "held", at: toIso(timestamp) },
        ],
    });
    appendAudit(db, batch, access, "trust_partner_profile_upsert", "trustPartnerProfile", partnerId, `${input.displayName}: ${trustScore}`);
    updateDailyCost(db, batch, 3, 0, 0);
    await batch.commit();
    return toPlain(profile) as SignalDeskTrustPartnerProfileSummary;
}

export async function createSignalDeskTrustPartnerNicheTestServer(
    access: SignalDeskAccessContext,
    input: TrustPartnerNicheTestInput,
) {
    requireTrustPartnerRail();
    const db = requireDb();
    const batch = db.batch();
    const timestamp = now();
    const partnerSnaps = await Promise.all(input.partnerIds.map((partnerId) => (
        db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES).doc(partnerId).get()
    )));
    const approvedPartners = partnerSnaps.filter((snap: any) => {
        const status = snap.data()?.status;
        return snap.exists && status !== "rejected";
    });
    const attemptCount = Math.max(input.intendedAttempts, approvedPartners.length);
    const recommendation: SignalDeskTrustPartnerNicheTestSummary["recommendation"] = attemptCount < 3 ? "underpowered" : "hold";
    const nicheRef = db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_NICHE_TESTS).doc(`niche_${hashValue(`${input.nicheName}|${input.marketPodId || "pod"}`).slice(0, 18)}`);
    const nicheTest = {
        nicheTestId: nicheRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        nicheName: input.nicheName,
        marketPodId: input.marketPodId || null,
        angle: input.angle,
        intendedAttempts: input.intendedAttempts,
        partnerIds: input.partnerIds,
        partnerCount: approvedPartners.length,
        status: "planned",
        recommendation,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };
    batch.set(nicheRef, sanitizeForFirestore(nicheTest), { merge: true });
    writeRunTimeline(db, batch, {
        entityId: nicheRef.id,
        entityType: "trust-partner",
        label: "Trust partner niche test",
        status: recommendation === "underpowered" ? "held" : "ready",
        steps: [
            { label: `${input.intendedAttempts} intended attempts`, status: input.intendedAttempts >= 3 ? "completed" : "held", at: toIso(timestamp) },
            { label: `${approvedPartners.length} partner profiles attached`, status: approvedPartners.length ? "completed" : "held", at: toIso(timestamp) },
        ],
    });
    appendAudit(db, batch, access, "trust_partner_niche_test_create", "trustPartnerNicheTest", nicheRef.id, input.nicheName);
    updateDailyCost(db, batch, 3 + input.partnerIds.length, 0, 0);
    await batch.commit();
    return toPlain(nicheTest) as SignalDeskTrustPartnerNicheTestSummary;
}

export async function reviewSignalDeskTrustPartnerDealServer(
    access: SignalDeskAccessContext,
    input: TrustPartnerDealInput,
) {
    requireTrustPartnerRail();
    const db = requireDb();
    if (input.pricingModel === "per-view") throw new Error("Trust partner per-view pricing is blocked");
    if (input.approvalStatus === "approved" && !input.founderApproved) throw new Error("Trust partner budget is not approved");
    if (!Number.isFinite(input.flatFeeUsd) || input.flatFeeUsd < 0) {
        throw new Error("TRUST_PARTNER_DEAL_COST_INVALID");
    }
    if (!Number.isSafeInteger(input.deliverableCount) || input.deliverableCount < 1 || input.deliverableCount > 100) {
        throw new Error("TRUST_PARTNER_DEAL_DELIVERABLE_COUNT_INVALID");
    }
    if (input.pricingModel === "barter" && input.flatFeeUsd !== 0) {
        throw new Error("TRUST_PARTNER_BARTER_COST_INVALID");
    }
    if (input.dueDate) {
        const dueDate = new Date(`${input.dueDate}T00:00:00.000Z`);
        if (
            !/^\d{4}-\d{2}-\d{2}$/.test(input.dueDate)
            || !Number.isFinite(dueDate.getTime())
            || dueDate.toISOString().slice(0, 10) !== input.dueDate
        ) throw new Error("TRUST_PARTNER_DEAL_DUE_DATE_INVALID");
    }
    const timestamp = now();
    const currentPeriod = getSignalDeskSpendPeriod(timestamp.toMillis());
    const dealRef = db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_DEALS).doc(`deal_${input.partnerId}_${hashValue(`${input.nicheTestId || "direct"}|${input.flatFeeUsd}|${input.dueDate || ""}`).slice(0, 12)}`);
    const partnerRef = db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES).doc(input.partnerId);
    const nicheTestRef = input.nicheTestId
        ? db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_NICHE_TESTS).doc(input.nicheTestId)
        : null;
    const budgetRef = db.collection(SIGNALDESK_COLLECTIONS.BUDGET_POLICIES).doc(
        input.budgetPolicyId || budgetPolicyIdFor("trust-partner", null, "first_partner_test"),
    );
    const dealTermsFingerprintHash = hashValue(JSON.stringify({
        budgetPolicyId: budgetRef.id,
        deliverableCount: input.deliverableCount,
        dueDate: input.dueDate || null,
        flatFeeUsd: input.flatFeeUsd,
        nicheTestId: input.nicheTestId || null,
        partnerId: input.partnerId,
        pricingModel: input.pricingModel,
    }));
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const [partnerSnap, nicheTestSnap, budgetSnap, existingDealSnap] = await Promise.all([
            transaction.get(partnerRef),
            nicheTestRef ? transaction.get(nicheTestRef) : Promise.resolve(null),
            transaction.get(budgetRef),
            transaction.get(dealRef),
        ]);
        if (!partnerSnap.exists) throw new Error("Trust partner not found");
        const partner = projectSignalDeskWorkspaceDocument(
            SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES,
            partnerSnap.data(),
            partnerSnap.id,
            currentPeriod,
        ) as SignalDeskTrustPartnerProfileSummary | null;
        if (!partner || partner.status === "rejected") throw new Error("TRUST_PARTNER_NOT_ELIGIBLE");
        if (nicheTestRef) {
            const rawNicheTest = nicheTestSnap?.exists ? nicheTestSnap.data() || {} : {};
            const nicheTest = nicheTestSnap?.exists
                ? projectSignalDeskWorkspaceDocument(
                    SIGNALDESK_COLLECTIONS.TRUST_PARTNER_NICHE_TESTS,
                    nicheTestSnap.data(),
                    nicheTestSnap.id,
                    currentPeriod,
                ) as SignalDeskTrustPartnerNicheTestSummary | null
                : null;
            const nichePartnerIds = Array.isArray(rawNicheTest.partnerIds)
                ? rawNicheTest.partnerIds.map((value: unknown) => normalizeText(value)).filter(Boolean)
                : [];
            if (
                !nicheTest
                || nichePartnerIds.length > 100
                || new Set(nichePartnerIds).size !== nichePartnerIds.length
                || !nichePartnerIds.includes(input.partnerId)
            ) {
                throw new Error("TRUST_PARTNER_NICHE_TEST_MISMATCH");
            }
        }
        const budget = budgetSnap.exists
            ? parseSignalDeskBudgetPolicyDocument(budgetSnap.data(), budgetRef.id, currentPeriod)
            : null;
        if (budget && budget.scope !== "trust-partner") throw new Error("TRUST_PARTNER_BUDGET_SCOPE_INVALID");
        const existingDeal = existingDealSnap.exists
            ? projectSignalDeskWorkspaceDocument(
                SIGNALDESK_COLLECTIONS.TRUST_PARTNER_DEALS,
                existingDealSnap.data(),
                existingDealSnap.id,
                currentPeriod,
            ) as SignalDeskTrustPartnerDealSummary | null
            : null;
        if (existingDealSnap.exists && !existingDeal) throw new Error("TRUST_PARTNER_DEAL_SHAPE_INVALID");
        if (existingDeal) {
            const existingRaw = existingDealSnap.data() || {};
            const legacyTermsMatch = existingDeal.partnerId === input.partnerId
                && (existingDeal.nicheTestId || null) === (input.nicheTestId || null)
                && existingDeal.flatFeeUsd === input.flatFeeUsd
                && existingDeal.pricingModel === input.pricingModel
                && existingDeal.deliverableCount === input.deliverableCount
                && existingDeal.dueDate === (input.dueDate || null)
                && existingDeal.budgetPolicyId === budgetRef.id;
            if (
                (existingRaw.dealTermsFingerprintHash && existingRaw.dealTermsFingerprintHash !== dealTermsFingerprintHash)
                || (!existingRaw.dealTermsFingerprintHash && !legacyTermsMatch)
            ) throw new Error("TRUST_PARTNER_DEAL_TERMS_CONFLICT");
            if (existingDeal.approvalStatus === "approved" && input.approvalStatus !== "approved") {
                throw new Error("TRUST_PARTNER_DEAL_APPROVAL_IMMUTABLE");
            }
            const hasReservationEvidence = existingRaw.budgetReservationState === "reserved"
                || existingRaw.budgetReservationState === "legacy-assumed-reserved";
            if (
                existingDeal.approvalStatus === input.approvalStatus
                && (input.approvalStatus !== "approved" || hasReservationEvidence)
            ) {
                return existingDeal;
            }
        }
        const existingRaw = existingDealSnap.exists ? existingDealSnap.data() || {} : {};
        const legacyApproved = existingDeal?.approvalStatus === "approved"
            && existingRaw.budgetReservationState == null;
        const alreadyReserved = legacyApproved
            || existingRaw.budgetReservationState === "reserved"
            || existingRaw.budgetReservationState === "legacy-assumed-reserved";
        const reserveNow = input.approvalStatus === "approved" && !alreadyReserved;
        if (reserveNow) {
            if (!budget || budget.status !== "active") throw new Error("Trust partner budget is not approved");
            if (input.flatFeeUsd > budget.perRunBudgetUsd) throw new Error("Provider per-run budget exceeded");
            if (budget.spentTodayUsd + input.flatFeeUsd > budget.dailyBudgetUsd) {
                throw new Error("Provider daily budget exceeded");
            }
            if (budget.spentMonthUsd + input.flatFeeUsd > budget.monthlyBudgetUsd) {
                throw new Error("Provider monthly budget exceeded");
            }
        }
        if (reserveNow && budget) {
            transaction.set(budgetRef, sanitizeForFirestore(buildSignalDeskSpendMutation({
                amountUsd: input.flatFeeUsd,
                authority: budget,
                currentPeriod,
                updatedAt: timestamp,
            })), { merge: true });
        }
        const deal = {
            dealId: dealRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            partnerId: input.partnerId,
            partnerName: partner.displayName,
            nicheTestId: input.nicheTestId || null,
            flatFeeUsd: input.flatFeeUsd,
            pricingModel: input.pricingModel,
            deliverableCount: input.deliverableCount,
            dueDate: input.dueDate || null,
            approvalStatus: input.approvalStatus,
            budgetPolicyId: budgetRef.id,
            budgetReservationAccountingDay: reserveNow
                ? currentPeriod.spendDayKey
                : existingRaw.budgetReservationAccountingDay || null,
            budgetReservationAccountingMonth: reserveNow
                ? currentPeriod.spendMonthKey
                : existingRaw.budgetReservationAccountingMonth || null,
            budgetReservationAmountUsd: reserveNow
                ? input.flatFeeUsd
                : existingRaw.budgetReservationAmountUsd ?? (legacyApproved ? input.flatFeeUsd : null),
            budgetReservationAt: reserveNow
                ? timestamp
                : existingRaw.budgetReservationAt || null,
            budgetReservationState: reserveNow
                ? "reserved"
                : legacyApproved ? "legacy-assumed-reserved" : existingRaw.budgetReservationState || null,
            dealTermsFingerprintHash,
            paymentState: input.approvalStatus === "approved" ? "pending" : "held",
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        transaction.set(dealRef, sanitizeForFirestore(deal), { merge: true });
        writeRunTimeline(db, transaction, {
            entityId: dealRef.id,
            entityType: "trust-partner",
            label: "Trust partner deal",
            status: input.approvalStatus === "approved" ? "ready" : input.approvalStatus === "blocked" ? "blocked" : "held",
            steps: [
                { label: "Flat-fee economics checked", status: input.pricingModel === "flat-fee" || input.pricingModel === "barter" ? "completed" : "blocked", at: toIso(timestamp) },
                { label: "Founder budget approval checked", status: input.founderApproved ? "completed" : "held", at: toIso(timestamp) },
            ],
        });
        appendAudit(db, transaction, access, "trust_partner_deal_review", "trustPartnerDeal", dealRef.id, input.approvalStatus);
        updateDailyCost(db, transaction, input.approvalStatus === "approved" ? 5 : 3, 0, 0);
        return toPlain(deal) as SignalDeskTrustPartnerDealSummary;
    });
}

export async function createSignalDeskTrustPartnerBriefServer(
    access: SignalDeskAccessContext,
    input: TrustPartnerBriefInput,
) {
    requireTrustPartnerRail();
    const db = requireDb();
    if (!input.disclosureText.trim()) throw new Error("Trust partner disclosure is required");
    const partnerId = normalizeText(input.partnerId);
    const dealId = normalizeText(input.dealId) || null;
    const ctaId = normalizeText(input.ctaId) || SIGNALDESK_AUTHORITATIVE_PREVIEW_CTA_ID;
    const approvedClaims = canonicalTrustPartnerClaims(input.approvedClaims);
    const bannedClaims = canonicalTrustPartnerClaims(input.bannedClaims);
    if (!approvedClaims || !bannedClaims) throw new Error("TRUST_PARTNER_BRIEF_CLAIMS_REQUIRED");
    const bannedClaimKeys = new Set(bannedClaims.map(normalizeLower));
    if (approvedClaims.some((claim) => bannedClaimKeys.has(normalizeLower(claim)))) {
        throw new Error("TRUST_PARTNER_BRIEF_CLAIM_CONFLICT");
    }
    const briefIdentityHash = hashValue(JSON.stringify({
        approvedClaims,
        bannedClaims,
        ctaId,
        dealId,
        disclosureText: normalizeText(input.disclosureText),
        onePageBrief: normalizeText(input.onePageBrief),
        partnerId,
    })).slice(0, 28);
    const partnerRef = db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES).doc(partnerId);
    const dealRef = dealId ? db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_DEALS).doc(dealId) : null;
    const briefRef = db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_BRIEFS).doc(`trust_brief_${briefIdentityHash}`);
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const [partnerSnap, dealSnap, existingBriefSnap] = await Promise.all([
            transaction.get(partnerRef),
            dealRef ? transaction.get(dealRef) : Promise.resolve(null),
            transaction.get(briefRef),
        ]);
        if (!partnerSnap.exists) throw new Error("Trust partner not found");
        const partner = partnerSnap.data() as AnyRecord;
        if (normalizeText(partner.pId) !== SIGNALDESK_PRODUCT_CODE) throw new Error("TRUST_PARTNER_PRODUCT_MISMATCH");
        if (normalizeText(partner.partnerId) !== partnerRef.id) throw new Error("TRUST_PARTNER_IDENTITY_MISMATCH");
        if (partner.dependentHoldReconciliationPending === true) throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        if (partner.status !== "approved" && partner.status !== "active") throw new Error("TRUST_PARTNER_NOT_APPROVED");
        if (dealRef) {
            if (!dealSnap?.exists) throw new Error("Trust partner deal not found");
            const deal = dealSnap.data() as AnyRecord;
            if (normalizeText(deal.pId) !== SIGNALDESK_PRODUCT_CODE) throw new Error("TRUST_PARTNER_DEAL_PRODUCT_MISMATCH");
            if (normalizeText(deal.dealId) !== dealRef.id || normalizeText(deal.partnerId) !== partnerRef.id) {
                throw new Error("TRUST_PARTNER_DEAL_IDENTITY_MISMATCH");
            }
            if (deal.dependentHoldReconciliationPending === true) throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
            if (deal.approvalStatus !== "approved") throw new Error("TRUST_PARTNER_DEAL_NOT_APPROVED");
        }
        const ctaAuthority = await readSignalDeskCtaAuthority(db, transaction, {
            ctaId,
            requireActive: true,
            useAuthoritativePreview: !input.ctaId,
        });
        if (existingBriefSnap.exists) {
            if (normalizeText(existingBriefSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
                throw new Error("TRUST_PARTNER_BRIEF_PRODUCT_MISMATCH");
            }
            const existing = projectSignalDeskTrustPartnerBrief({
                ...toPlain(existingBriefSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.TRUST_PARTNER_BRIEFS}DocId`]: existingBriefSnap.id,
            });
            if (!existing) throw new Error("TRUST_PARTNER_BRIEF_SHAPE_INVALID");
            if (
                existing.briefId !== briefRef.id
                || existing.partnerId !== partnerId
                || (existing.dealId || null) !== dealId
                || existing.ctaId !== ctaAuthority.cta.ctaId
                || existing.ctaFingerprintHash !== ctaAuthority.ctaFingerprintHash
                || existing.disclosureText !== normalizeText(input.disclosureText)
                || existing.onePageBrief !== normalizeText(input.onePageBrief)
                || JSON.stringify(existing.approvedClaims) !== JSON.stringify(approvedClaims)
                || JSON.stringify(existing.bannedClaims) !== JSON.stringify(bannedClaims)
            ) throw new Error("TRUST_PARTNER_BRIEF_IDENTITY_CONFLICT");
            return existing;
        }
        const timestamp = now();
        const brief = {
            approvedClaims,
            bannedClaims,
            briefId: briefRef.id,
            ctaFingerprintHash: ctaAuthority.ctaFingerprintHash,
            ctaId: ctaAuthority.cta.ctaId,
            dealId,
            disclosureRequired: true,
            disclosureText: normalizeText(input.disclosureText),
            onePageBrief: normalizeText(input.onePageBrief),
            pId: SIGNALDESK_PRODUCT_CODE,
            partnerId,
            status: "ready" as const,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        transaction.create(briefRef, sanitizeForFirestore(brief));
        writeRunTimeline(db, transaction, {
            entityId: briefRef.id,
            entityType: "trust-partner",
            label: "Trust partner brief",
            status: "ready",
            steps: [
                { label: "Approved claims attached", status: "completed", at: toIso(timestamp) },
                { label: "Disclosure instruction attached", status: "completed", at: toIso(timestamp) },
                { label: "Banned claims attached", status: "completed", at: toIso(timestamp) },
                { label: "Current CTA authority attached", status: "completed", at: toIso(timestamp) },
            ],
        });
        appendAudit(db, transaction, access, "trust_partner_brief_create", "trustPartnerBrief", briefRef.id, partnerId);
        updateDailyCost(db, transaction, 5 + (dealRef ? 1 : 0), 0, 0);
        return toPlain(brief) as SignalDeskTrustPartnerBriefSummary;
    });
}

export async function recordSignalDeskTrustPartnerDeliverableServer(
    access: SignalDeskAccessContext,
    input: TrustPartnerDeliverableInput,
) {
    requireTrustPartnerRail();
    const db = requireDb();
    const partnerSnap = await db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES).doc(input.partnerId).get();
    if (!partnerSnap.exists) throw new Error("Trust partner not found");
    if (input.dealId) {
        const dealSnap = await db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_DEALS).doc(input.dealId).get();
        if (!dealSnap.exists) throw new Error("Trust partner deal not found");
    }
    const batch = db.batch();
    const timestamp = now();
    const deliverableRef = db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_DELIVERABLES).doc();
    const risk = input.status === "live" && !input.disclosurePresent;
    const deliverable = {
        deliverableId: deliverableRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        partnerId: input.partnerId,
        dealId: input.dealId || null,
        dueDate: input.dueDate || null,
        postUrl: input.postUrl || null,
        status: input.status,
        reviewState: risk ? "risk" : input.reviewState,
        disclosurePresent: input.disclosurePresent,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };
    batch.set(deliverableRef, sanitizeForFirestore(deliverable));
    writeRunTimeline(db, batch, {
        entityId: deliverableRef.id,
        entityType: "trust-partner",
        label: "Trust partner deliverable",
        status: risk ? "blocked" : input.status === "live" ? "completed" : "held",
        steps: [
            { label: "Deliverable captured", status: "completed", at: toIso(timestamp) },
            { label: "Disclosure checked", status: input.disclosurePresent ? "completed" : "blocked", at: toIso(timestamp) },
        ],
    });
    appendAudit(db, batch, access, "trust_partner_deliverable_record", "trustPartnerDeliverable", deliverableRef.id, input.status);
    updateDailyCost(db, batch, 3, 0, 0);
    await batch.commit();
    return toPlain(deliverable) as SignalDeskTrustPartnerDeliverableSummary;
}

export async function recordSignalDeskTrustPartnerMetricsServer(
    access: SignalDeskAccessContext,
    input: TrustPartnerMetricsInput,
) {
    requireTrustPartnerRail();
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("TRUST_PARTNER_METRICS_IDEMPOTENCY_KEY_REQUIRED");
    const requestFingerprintHash = hashValue(JSON.stringify({ activations: input.activations, commentQuality: input.commentQuality, comments: input.comments, currentListSubmissions: input.currentListSubmissions, deliverableId: input.deliverableId || null, ownerLeads: input.ownerLeads, partnerId: input.partnerId, views: input.views }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const metricRef = db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_METRICS).doc(`partner_metric_${operationHash.slice(0, 32)}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`trust_partner_metrics_${operationHash}`);
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const partnerRef = db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES).doc(input.partnerId);
        const deliverableRef = input.deliverableId ? db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_DELIVERABLES).doc(input.deliverableId) : null;
        const [claimSnap, partnerSnap, deliverableSnap, metricSnap] = await Promise.all([
            transaction.get(claimRef), transaction.get(partnerRef),
            deliverableRef ? transaction.get(deliverableRef) : Promise.resolve(null), transaction.get(metricRef),
        ]);
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) throw new Error("TRUST_PARTNER_METRICS_IDEMPOTENCY_CONFLICT");
            if (!metricSnap.exists) throw new Error("TRUST_PARTNER_METRICS_REPLAY_MISSING");
            return toPlain(metricSnap.data()) as SignalDeskTrustPartnerMetricSummary;
        }
        if (!partnerSnap.exists) throw new Error("Trust partner not found");
        if (deliverableRef && !deliverableSnap?.exists) throw new Error("Trust partner deliverable not found");
        if (deliverableSnap?.exists && normalizeText(deliverableSnap.data()?.partnerId) !== input.partnerId) throw new Error("TRUST_PARTNER_DELIVERABLE_MISMATCH");
        const timestamp = now();
        const metric = {
        metricsId: metricRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        partnerId: input.partnerId,
        deliverableId: input.deliverableId || null,
        views: input.views,
        comments: input.comments,
        commentQuality: input.commentQuality,
        ownerLeads: input.ownerLeads,
        currentListSubmissions: input.currentListSubmissions,
        activations: input.activations,
        capturedAt: timestamp,
        updatedBy: access.userId,
        };
        transaction.create(metricRef, sanitizeForFirestore(metric));
        const ownerSignals = input.ownerLeads + input.currentListSubmissions + input.activations;
        if (ownerSignals) {
            transaction.set(db.collection(SIGNALDESK_COLLECTIONS.DEMAND_SIGNAL_SUMMARIES).doc(`trust_partner_${input.partnerId}_${todayKey()}`), sanitizeForFirestore({
            demandSignalId: `trust_partner_${input.partnerId}_${todayKey()}`,
            pId: SIGNALDESK_PRODUCT_CODE,
            signalType: "referral",
            sourceSurface: "manual",
            targetId: null,
            targetName: partnerSnap.data()?.displayName || input.partnerId,
            count: increment(ownerSignals),
            day: todayKey(),
            updatedAt: timestamp,
            }), { merge: true });
        }
        transaction.create(claimRef, sanitizeForFirestore({ actorId: access.userId, entityId: metricRef.id, operation: "trust_partner_metrics_record", pId: SIGNALDESK_PRODUCT_CODE, requestFingerprintHash, updatedAt: timestamp }));
        writeRunTimeline(db, transaction, {
        entityId: metricRef.id,
        entityType: "trust-partner",
        label: "Trust partner metrics",
        status: input.activations || input.currentListSubmissions || input.ownerLeads ? "completed" : "held",
        steps: [
            { label: `${input.views} views captured`, status: "completed", at: toIso(timestamp) },
            { label: `${input.ownerLeads + input.currentListSubmissions + input.activations} owner outcomes`, status: input.ownerLeads + input.currentListSubmissions + input.activations ? "completed" : "held", at: toIso(timestamp) },
        ],
        });
        appendAudit(db, transaction, access, "trust_partner_metrics_record", "trustPartnerMetric", metricRef.id, input.partnerId);
        updateControlSummary(db, transaction, { demandSignalCount: increment(ownerSignals) });
        updateDailyCost(db, transaction, 4, 0, 0);
        return toPlain(metric) as SignalDeskTrustPartnerMetricSummary;
    });
}

export async function reviewSignalDeskTrustPartnerRenewalServer(
    access: SignalDeskAccessContext,
    input: TrustPartnerRenewalInput,
) {
    requireTrustPartnerRail();
    const db = requireDb();
    const partnerSnap = await db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES).doc(input.partnerId).get();
    if (!partnerSnap.exists) throw new Error("Trust partner not found");
    const metricsSnap = await db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_METRICS)
        .where("partnerId", "==", input.partnerId)
        .orderBy("capturedAt", "desc")
        .limit(10)
        .get();
    const metrics = metricsSnap.docs.map((doc: any) => toPlain(doc.data()) as SignalDeskTrustPartnerMetricSummary);
    const outcomeBackedRecommendation = recommendationFromTrustOutcomes(metrics);
    if (input.recommendation === "renew" && outcomeBackedRecommendation !== "renew") {
        throw new Error("Trust partner renewal requires outcome evidence");
    }
    const batch = db.batch();
    const timestamp = now();
    const decisionRef = db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_RENEWAL_DECISIONS).doc();
    const decision = {
        decisionId: decisionRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        partnerId: input.partnerId,
        nicheTestId: input.nicheTestId || null,
        recommendation: input.recommendation,
        ownerDecision: input.ownerDecision || "pending",
        evidenceSummary: input.evidenceSummary,
        createdAt: timestamp,
        updatedAt: timestamp,
        updatedBy: access.userId,
    };
    batch.set(decisionRef, sanitizeForFirestore(decision));
    batch.set(db.collection(SIGNALDESK_COLLECTIONS.TRUST_PARTNER_PROFILES).doc(input.partnerId), sanitizeForFirestore({
        status: input.recommendation === "renew" ? "active" : input.recommendation === "cut" ? "rejected" : "hold",
        updatedAt: timestamp,
    }), { merge: true });
    writeRunTimeline(db, batch, {
        entityId: decisionRef.id,
        entityType: "trust-partner",
        label: "Trust partner renewal",
        status: input.recommendation === "renew" ? "ready" : input.recommendation === "cut" ? "blocked" : "held",
        steps: [
            { label: `${metrics.length} metric records checked`, status: metrics.length ? "completed" : "held", at: toIso(timestamp) },
            { label: `${input.recommendation} recommendation`, status: input.recommendation === "renew" ? "completed" : "held", at: toIso(timestamp) },
        ],
    });
    appendAudit(db, batch, access, "trust_partner_renewal_review", "trustPartnerRenewalDecision", decisionRef.id, input.recommendation);
    updateDailyCost(db, batch, 3, 0, 0);
    await batch.commit();
    return toPlain(decision) as SignalDeskTrustPartnerRenewalDecisionSummary;
}

export async function upsertSignalDeskContentSourceServer(
    access: SignalDeskAccessContext,
    input: ContentSourceInput,
) {
    requireContentDistributionRail();
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("CONTENT_SOURCE_IDEMPOTENCY_KEY_REQUIRED");
    const title = normalizeText(input.title);
    const explicitContentSourceId = normalizeText(input.contentSourceId) || null;
    const canonicalSourceUrl = canonicalizeContentUrl(input.sourceUrl);
    const requestedMarketPodId = input.defaultMarketPodId === undefined ? undefined : normalizeText(input.defaultMarketPodId) || null;
    const canonicalContentSourceId = contentSourceIdFor(title, input.sourceType, canonicalSourceUrl);
    const legacyContentSourceId = legacyContentSourceIdFor(title, input.sourceType, input.sourceUrl);
    const requestFingerprintHash = hashValue(JSON.stringify({
        contentSourceId: explicitContentSourceId,
        defaultAudience: input.defaultAudience,
        defaultMarketPodId: requestedMarketPodId === undefined ? "preserve" : requestedMarketPodId,
        sourceType: input.sourceType,
        sourceUrl: canonicalSourceUrl,
        status: input.status,
        title,
    }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`content_source_${operationHash}`);
    const canonicalRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_SOURCES).doc(explicitContentSourceId || canonicalContentSourceId);
    const legacyRef = !explicitContentSourceId && legacyContentSourceId !== canonicalContentSourceId
        ? db.collection(SIGNALDESK_COLLECTIONS.CONTENT_SOURCES).doc(legacyContentSourceId)
        : null;
    const resumeSourceReconciliation = async (authorityRef: FirebaseFirestore.DocumentReference) => (
        resumePendingContentAuthorityReconciliation(db, access, {
            action: "content_source_dependency_reconcile_recovery",
            assetField: "sourceId",
            assetValue: authorityRef.id,
            authorityRef,
            entityType: "contentSource",
            reason: "Content source authority is no longer active. Review before distribution.",
            shouldHoldAsset: () => true,
        })
    );
    await resumeSourceReconciliation(canonicalRef);
    if (legacyRef) await resumeSourceReconciliation(legacyRef);
    const transactionResult = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const pauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_content-distribution");
        const [claimSnap, pauseSnap] = await Promise.all([transaction.get(claimRef), transaction.get(pauseRef)]);
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) throw new Error("CONTENT_SOURCE_IDEMPOTENCY_CONFLICT");
            const replaySourceId = normalizeText(claimSnap.data()?.entityId);
            if (!replaySourceId) throw new Error("CONTENT_SOURCE_REPLAY_MISSING");
            const replayRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_SOURCES).doc(replaySourceId);
            const replaySnap = await transaction.get(replayRef);
            if (!replaySnap.exists) throw new Error("CONTENT_SOURCE_REPLAY_MISSING");
            const replay = projectSignalDeskContentSource({
                ...toPlain(replaySnap.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_SOURCES}DocId`]: replayRef.id,
            });
            if (!replay) throw new Error("CONTENT_SOURCE_REPLAY_MISSING");
            const storedReplay = claimSnap.data()?.resultSnapshot
                ? projectSignalDeskContentSource({
                    ...toPlain(claimSnap.data()?.resultSnapshot),
                    pId: SIGNALDESK_PRODUCT_CODE,
                    [`${SIGNALDESK_COLLECTIONS.CONTENT_SOURCES}DocId`]: replayRef.id,
                })
                : replay;
            if (!storedReplay) throw new Error("CONTENT_SOURCE_REPLAY_MISSING");
            const replayReconciliationToken = normalizeText(replaySnap.data()?.dependentHoldReconciliationToken);
            return {
                reconciliationRequired: replaySnap.data()?.dependentHoldReconciliationPending === true
                    && replayReconciliationToken === claimRef.id,
                reconciliationToken: replayReconciliationToken,
                source: storedReplay,
                sourceRef: replayRef,
            };
        }
        if (pauseSnap.data()?.status === "active" && input.status === "active") throw new Error("Content distribution is paused");

        const [canonicalSnap, legacySnap] = await Promise.all([
            transaction.get(canonicalRef), legacyRef ? transaction.get(legacyRef) : Promise.resolve(null),
        ]);
        if (explicitContentSourceId && !canonicalSnap.exists) throw new Error("Content source not found");
        if (!explicitContentSourceId && canonicalSnap.exists && legacySnap?.exists) throw new Error("CONTENT_SOURCE_IDENTITY_AMBIGUOUS");
        let sourceRef = canonicalRef;
        let sourceSnap = canonicalSnap;
        if (!canonicalSnap.exists && legacySnap?.exists) {
            const legacyData = legacySnap.data() as AnyRecord;
            let legacyCanonicalUrl: string | null = null;
            try {
                legacyCanonicalUrl = canonicalizeContentUrl(typeof legacyData.sourceUrl === "string" ? legacyData.sourceUrl : null);
            } catch {
                legacyCanonicalUrl = null;
            }
            if (normalizeText(legacyData.sourceType) === input.sourceType && legacyCanonicalUrl === canonicalSourceUrl) {
                sourceRef = legacyRef!;
                sourceSnap = legacySnap;
            }
        }
        const existingData = sourceSnap.exists ? sourceSnap.data() as AnyRecord : null;
        if (existingData && normalizeText(existingData.pId) && normalizeText(existingData.pId) !== SIGNALDESK_PRODUCT_CODE) throw new Error("CONTENT_SOURCE_PRODUCT_MISMATCH");
        const existingSource = existingData ? projectSignalDeskContentSource({
            ...toPlain(existingData),
            [`${SIGNALDESK_COLLECTIONS.CONTENT_SOURCES}DocId`]: sourceRef.id,
        }) : null;
        if (existingData && !existingSource) throw new Error("CONTENT_SOURCE_SHAPE_INVALID");
        if (existingData?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        let effectiveSourceUrl = canonicalSourceUrl;
        if (existingData) {
            const existingSourceType = normalizeText(existingData.sourceType);
            let existingSourceUrl: string | null;
            try {
                existingSourceUrl = canonicalizeContentUrl(typeof existingData.sourceUrl === "string" ? existingData.sourceUrl : null);
            } catch {
                throw new Error("CONTENT_SOURCE_PROVENANCE_INVALID");
            }
            if (existingSourceType !== input.sourceType || (input.sourceUrl !== undefined && existingSourceUrl !== canonicalSourceUrl)) {
                throw new Error("CONTENT_SOURCE_PROVENANCE_IMMUTABLE");
            }
            effectiveSourceUrl = existingSourceUrl;
        }
        const effectiveMarketPodId = requestedMarketPodId === undefined
            ? normalizeText(existingData?.defaultMarketPodId) || null
            : requestedMarketPodId;
        const marketPodRef = effectiveMarketPodId ? db.collection(SIGNALDESK_COLLECTIONS.MARKET_PODS).doc(effectiveMarketPodId) : null;
        const marketPodSnap = marketPodRef ? await transaction.get(marketPodRef) : null;
        const marketPodReferenceChanged = Boolean(existingSource
            && (existingSource.defaultMarketPodId || null) !== effectiveMarketPodId);
        const marketPodMustExist = Boolean(marketPodRef
            && (!existingSource || input.status === "active" || marketPodReferenceChanged));
        if (marketPodMustExist && !marketPodSnap?.exists) throw new Error("Market pod not found");
        if (marketPodMustExist && normalizeText(marketPodSnap?.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
            throw new Error("MARKET_POD_PRODUCT_MISMATCH");
        }
        if (input.status === "active" && marketPodSnap?.exists && (
            marketPodSnap.data()?.status !== "active"
            || marketPodSnap.data()?.reviewDecision !== "approved"
            || !normalizeText(marketPodSnap.data()?.approvedBy)
        )) throw new Error("Market pod is not founder-approved");
        const authorityIdentityChanged = Boolean(existingSource && (
            existingSource.defaultAudience !== input.defaultAudience
            || (existingSource.defaultMarketPodId || null) !== effectiveMarketPodId
        ));
        if (authorityIdentityChanged) {
            const dependentAssetsSnap = await transaction.get(
                db.collection(SIGNALDESK_COLLECTIONS.CONTENT_ASSETS).where("sourceId", "==", sourceRef.id).limit(1),
            );
            if (!dependentAssetsSnap.empty) throw new Error("CONTENT_SOURCE_REFERENCED_IMMUTABLE");
        }
        const timestamp = now();
        const contentSourceId = sourceRef.id;
        const reconciliationRequired = Boolean(existingSource
            && existingSource.status !== input.status
            && input.status !== "active");
        const reconciliationToken = reconciliationRequired ? claimRef.id : "";
        const source = {
            contentSourceId,
            pId: SIGNALDESK_PRODUCT_CODE,
            title,
            sourceType: input.sourceType,
            sourceUrl: effectiveSourceUrl,
            status: input.status,
            defaultAudience: input.defaultAudience,
            defaultMarketPodId: effectiveMarketPodId,
            lastAssetAt: existingData?.lastAssetAt ?? null,
            lastCheckedAt: timestamp,
            createdAt: existingData?.createdAt || timestamp,
            dependentHoldReconciliationKind: reconciliationRequired
                ? CONTENT_AUTHORITY_RECONCILIATION_KIND
                : null,
            dependentHoldReconciliationPending: reconciliationRequired,
            dependentHoldReconciliationProgress: reconciliationRequired
                ? emptyContentAuthorityReconciliationResult()
                : null,
            dependentHoldReconciliationToken: reconciliationToken || null,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        const projectedSource = projectSignalDeskContentSource({
            ...toPlain(source),
            [`${SIGNALDESK_COLLECTIONS.CONTENT_SOURCES}DocId`]: sourceRef.id,
        });
        if (!projectedSource) throw new Error("CONTENT_SOURCE_SHAPE_INVALID");
        transaction.set(sourceRef, sanitizeForFirestore(source), { merge: true });
        transaction.create(claimRef, sanitizeForFirestore({ actorId: access.userId, entityId: contentSourceId, operation: "content_source_upsert", pId: SIGNALDESK_PRODUCT_CODE, requestFingerprintHash, resultSnapshot: { ...toPlain(projectedSource), pId: SIGNALDESK_PRODUCT_CODE }, updatedAt: timestamp }));
        writeRunTimeline(db, transaction, {
            entityId: contentSourceId,
            entityType: "content",
            label: "Content source",
            status: input.status === "active" ? "ready" : input.status === "blocked" ? "blocked" : "held",
            steps: [
                { label: "Source registered", status: "completed", at: toIso(timestamp) },
                { label: `Default audience ${input.defaultAudience}`, status: "completed", at: toIso(timestamp) },
            ],
        });
        appendAudit(db, transaction, access, "content_source_upsert", "contentSource", contentSourceId, `${title}:reconcile=${reconciliationRequired}`);
        updateDailyCost(db, transaction, 3, 0, 0);
        return { reconciliationRequired, reconciliationToken, source: projectedSource, sourceRef };
    });
    if (transactionResult.reconciliationRequired) {
        if (!transactionResult.reconciliationToken) throw new Error("CONTENT_AUTHORITY_RECONCILIATION_TOKEN_MISSING");
        const reconciliationResult = await reconcileContentAuthorityHolds(db, {
            actorId: access.userId,
            assetField: "sourceId",
            assetValue: transactionResult.source.contentSourceId,
            authorityRef: transactionResult.sourceRef,
            reason: "Content source authority is no longer active. Review before distribution.",
            reconciliationToken: transactionResult.reconciliationToken,
            shouldHoldAsset: () => true,
        });
        await completeContentAuthorityReconciliation(db, access, {
            action: "content_source_dependency_reconcile",
            authorityRef: transactionResult.sourceRef,
            entityType: "contentSource",
            reconciliationToken: transactionResult.reconciliationToken,
        }, reconciliationResult);
    }
    return transactionResult.source;
}

export async function upsertSignalDeskProofPermissionServer(
    access: SignalDeskAccessContext,
    input: ProofPermissionInput,
) {
    requireContentDistributionRail();
    if (access.role !== "founder-admin") throw new Error("Founder approval is required for proof permissions");
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("PROOF_PERMISSION_IDEMPOTENCY_KEY_REQUIRED");
    const proofPermissionId = input.proofPermissionId || proofPermissionIdFor(input.targetId);
    const permissionRef = db.collection(SIGNALDESK_COLLECTIONS.PROOF_PERMISSIONS).doc(proofPermissionId);
    const normalizedScopes = Array.from(new Set(input.scopes)).sort();
    const requestedGrantedAt = input.grantedAt ? new Date(input.grantedAt) : null;
    if (requestedGrantedAt && Number.isNaN(requestedGrantedAt.getTime())) throw new Error("PROOF_PERMISSION_GRANTED_AT_INVALID");
    const requestedExpiresAt = input.expiresAt ? new Date(input.expiresAt) : null;
    if (requestedExpiresAt && Number.isNaN(requestedExpiresAt.getTime())) throw new Error("PROOF_PERMISSION_EXPIRES_AT_INVALID");
    const canonicalGrantedAt = requestedGrantedAt?.toISOString() || null;
    const canonicalExpiresAt = requestedExpiresAt?.toISOString() || null;
    const requestFingerprintHash = hashValue(JSON.stringify({ evidenceRef: normalizeText(input.evidenceRef), expiresAt: input.expiresAt === undefined ? "preserve" : canonicalExpiresAt, grantedAt: canonicalGrantedAt, notes: normalizeText(input.notes) || null, proofPermissionId, scopes: normalizedScopes, status: input.status, targetId: input.targetId }));
    const legacyRequestFingerprintHash = hashValue(JSON.stringify({ evidenceRef: input.evidenceRef, expiresAt: input.expiresAt || null, notes: input.notes || null, proofPermissionId, scopes: normalizedScopes, status: input.status, targetId: input.targetId }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`proof_permission_${operationHash}`);
    await resumePendingContentAuthorityReconciliation(db, access, {
        action: "proof_permission_dependency_reconcile_recovery",
        assetField: "proofPermissionId",
        assetValue: proofPermissionId,
        authorityRef: permissionRef,
        entityType: "proofPermission",
        reason: "Proof permission authority changed. Review before distribution.",
        shouldHoldAsset: () => true,
    });
    const transactionResult = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(input.targetId);
        const pauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_content-distribution");
        const [claimSnap, targetSnap, existingSnap, pauseSnap] = await Promise.all([
            transaction.get(claimRef), transaction.get(targetRef), transaction.get(permissionRef), transaction.get(pauseRef),
        ]);
        if (claimSnap.exists) {
            const storedFingerprint = normalizeText(claimSnap.data()?.requestFingerprintHash);
            const storedFingerprintVersion = claimSnap.data()?.requestFingerprintVersion;
            if (
                (storedFingerprintVersion === 2 && storedFingerprint !== requestFingerprintHash)
                || (storedFingerprintVersion !== 2 && storedFingerprint !== legacyRequestFingerprintHash)
            ) throw new Error("PROOF_PERMISSION_IDEMPOTENCY_CONFLICT");
            if (!existingSnap.exists) throw new Error("PROOF_PERMISSION_REPLAY_MISSING");
            const replay = projectSignalDeskProofPermission({
                ...toPlain(existingSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.PROOF_PERMISSIONS}DocId`]: permissionRef.id,
            });
            if (!replay) throw new Error("PROOF_PERMISSION_REPLAY_MISSING");
            const storedReplay = claimSnap.data()?.resultSnapshot
                ? projectSignalDeskProofPermission({
                    ...toPlain(claimSnap.data()?.resultSnapshot),
                    pId: SIGNALDESK_PRODUCT_CODE,
                    [`${SIGNALDESK_COLLECTIONS.PROOF_PERMISSIONS}DocId`]: permissionRef.id,
                })
                : replay;
            if (!storedReplay) throw new Error("PROOF_PERMISSION_REPLAY_MISSING");
            const replayReconciliationToken = normalizeText(existingSnap.data()?.dependentHoldReconciliationToken);
            return {
                permission: storedReplay,
                reconciliationRequired: existingSnap.data()?.dependentHoldReconciliationPending === true
                    && replayReconciliationToken === claimRef.id,
                reconciliationToken: replayReconciliationToken,
            };
        }
        if (pauseSnap.data()?.status === "active" && input.status === "active") {
            throw new Error("Content distribution is paused");
        }
        if (!targetSnap.exists || normalizeText(targetSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) throw new Error("Target not found");
        const target = toPlain(targetSnap.data()) as SignalDeskTargetSummary;
        const existingRawData = existingSnap.exists ? existingSnap.data() as AnyRecord : null;
        const existingData = existingRawData ? toPlain(existingRawData) as AnyRecord : null;
        if (existingData && normalizeText(existingData.pId) !== SIGNALDESK_PRODUCT_CODE) throw new Error("PROOF_PERMISSION_PRODUCT_MISMATCH");
        const existing = existingData ? projectSignalDeskProofPermission({
            ...existingData,
            [`${SIGNALDESK_COLLECTIONS.PROOF_PERMISSIONS}DocId`]: permissionRef.id,
        }) : null;
        if (existingData && !existing) throw new Error("PROOF_PERMISSION_SHAPE_INVALID");
        if (existing && existing.targetId !== input.targetId) throw new Error("PROOF_PERMISSION_TARGET_IMMUTABLE");
        if (existingRawData?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        const timestamp = now();
        let expiresAt: FirebaseFirestore.Timestamp | null = input.expiresAt === undefined && existing?.expiresAt
            ? admin.firestore.Timestamp.fromDate(new Date(existing.expiresAt))
            : null;
        if (input.expiresAt !== undefined && requestedExpiresAt) {
            expiresAt = admin.firestore.Timestamp.fromDate(requestedExpiresAt);
        }
        if (input.status === "active" && expiresAt && toTimestampMillis(expiresAt) <= Date.now()) throw new Error("Proof permission expiry must be in the future");
        let grantedAt: FirebaseFirestore.Timestamp | null = existing?.grantedAt
            ? admin.firestore.Timestamp.fromDate(new Date(existing.grantedAt))
            : null;
        if (input.status === "active") {
            const isReactivation = Boolean(
                existing
                && (
                    !isProofPermissionActive(existing)
                    || ["revoked", "expired"].includes(existing.status)
                    || Boolean(existing.revokedAt)
                )
            );
            if (isReactivation && !requestedGrantedAt) {
                throw new Error("PROOF_PERMISSION_REACTIVATION_GRANT_REQUIRED");
            }
            const grantedDate = requestedGrantedAt
                ? requestedGrantedAt
                : existing?.grantedAt
                    ? new Date(existing.grantedAt)
                    : new Date();
            if (Number.isNaN(grantedDate.getTime()) || grantedDate.getTime() > Date.now() + CONTENT_PUBLICATION_FUTURE_SKEW_MS) {
                throw new Error("PROOF_PERMISSION_GRANTED_AT_INVALID");
            }
            const priorGrantMillis = existing?.grantedAt ? new Date(existing.grantedAt).getTime() : null;
            const priorExpiryMillis = existing?.expiresAt ? new Date(existing.expiresAt).getTime() : null;
            const priorRevokedMillis = existing?.revokedAt ? new Date(existing.revokedAt).getTime() : null;
            if (priorGrantMillis != null && grantedDate.getTime() < priorGrantMillis) {
                throw new Error("PROOF_PERMISSION_REACTIVATION_GRANT_INVALID");
            }
            const isRevokedGrant = existing?.status === "revoked" || priorRevokedMillis != null;
            const isExpiredGrant = existing?.status === "expired" || Boolean(
                !isRevokedGrant
                && priorExpiryMillis != null
                && priorExpiryMillis <= Date.now()
            );
            const reactivationBoundaryMillis = Math.max(
                isReactivation && priorGrantMillis != null ? priorGrantMillis : Number.NEGATIVE_INFINITY,
                isReactivation && isExpiredGrant && priorExpiryMillis != null ? priorExpiryMillis : Number.NEGATIVE_INFINITY,
                isReactivation && isRevokedGrant && priorRevokedMillis != null ? priorRevokedMillis : Number.NEGATIVE_INFINITY,
            );
            if (isReactivation && grantedDate.getTime() <= reactivationBoundaryMillis) {
                throw new Error("PROOF_PERMISSION_REACTIVATION_GRANT_INVALID");
            }
            grantedAt = admin.firestore.Timestamp.fromDate(grantedDate);
        }
        if (expiresAt && grantedAt && toTimestampMillis(expiresAt)! <= toTimestampMillis(grantedAt)!) {
            throw new Error("PROOF_PERMISSION_EXPIRY_ORDER_INVALID");
        }
        const permission = {
            proofPermissionId, pId: SIGNALDESK_PRODUCT_CODE, targetId: input.targetId, targetName: target.displayName,
            status: input.status, scopes: normalizedScopes, evidenceRef: input.evidenceRef,
            grantedAt,
            expiresAt,
            revokedAt: input.status === "revoked"
                ? timestamp
                : input.status === "active"
                    ? null
                    : existing?.revokedAt
                        ? admin.firestore.Timestamp.fromDate(new Date(existing.revokedAt))
                        : null,
            notes: input.notes || null,
            createdAt: existingData?.createdAt || timestamp, updatedAt: timestamp, updatedBy: access.userId,
        };
        const plainPermission = projectSignalDeskProofPermission({
            ...toPlain(permission),
            [`${SIGNALDESK_COLLECTIONS.PROOF_PERMISSIONS}DocId`]: permissionRef.id,
        });
        if (!plainPermission) throw new Error("PROOF_PERMISSION_SHAPE_INVALID");
        const reconciliationRequired = Boolean(existing && (
            existing.evidenceRef !== plainPermission.evidenceRef
            || existing.status !== plainPermission.status
            || existing.grantedAt !== plainPermission.grantedAt
            || existing.expiresAt !== plainPermission.expiresAt
            || JSON.stringify([...existing.scopes].sort()) !== JSON.stringify([...plainPermission.scopes].sort())
        ));
        const reconciliationToken = reconciliationRequired ? claimRef.id : "";
        transaction.set(permissionRef, sanitizeForFirestore({
            ...permission,
            dependentHoldReconciliationKind: reconciliationRequired
                ? CONTENT_AUTHORITY_RECONCILIATION_KIND
                : null,
            dependentHoldReconciliationPending: reconciliationRequired,
            dependentHoldReconciliationProgress: reconciliationRequired
                ? emptyContentAuthorityReconciliationResult()
                : null,
            dependentHoldReconciliationToken: reconciliationToken || null,
        }), { merge: true });
        transaction.create(claimRef, sanitizeForFirestore({ actorId: access.userId, entityId: proofPermissionId, operation: "proof_permission_upsert", pId: SIGNALDESK_PRODUCT_CODE, requestFingerprintHash, requestFingerprintVersion: 2, resultSnapshot: { ...toPlain(plainPermission), pId: SIGNALDESK_PRODUCT_CODE }, updatedAt: timestamp }));
        appendAudit(db, transaction, access, "proof_permission_upsert", "proofPermission", proofPermissionId, `${input.status}:${normalizedScopes.join(",")}:reconcile=${reconciliationRequired}`);
        updateDailyCost(db, transaction, 4, 0, 0);
        return { permission: plainPermission, reconciliationRequired, reconciliationToken };
    });
    if (transactionResult.reconciliationRequired) {
        if (!transactionResult.reconciliationToken) throw new Error("CONTENT_AUTHORITY_RECONCILIATION_TOKEN_MISSING");
        const reconciliationResult = await reconcileContentAuthorityHolds(db, {
            actorId: access.userId,
            assetField: "proofPermissionId",
            assetValue: proofPermissionId,
            authorityRef: permissionRef,
            reason: "Proof permission authority changed. Review before distribution.",
            reconciliationToken: transactionResult.reconciliationToken,
            shouldHoldAsset: () => true,
        });
        await completeContentAuthorityReconciliation(db, access, {
            action: "proof_permission_dependency_reconcile",
            authorityRef: permissionRef,
            entityType: "proofPermission",
            reconciliationToken: transactionResult.reconciliationToken,
        }, reconciliationResult);
    }
    return transactionResult.permission;
}

export async function createSignalDeskContentAssetServer(
    access: SignalDeskAccessContext,
    input: ContentAssetInput,
) {
    requireContentDistributionRail();
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("CONTENT_ASSET_IDEMPOTENCY_KEY_REQUIRED");
    const proofScopes = Array.from(new Set(input.proofScopes)).sort();
    const requestFingerprintHash = hashValue(JSON.stringify({ ...input, idempotencyKey: undefined, proofScopes }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`content_asset_${operationHash}`);
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const pauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_content-distribution");
        const sourceRef = input.sourceId ? db.collection(SIGNALDESK_COLLECTIONS.CONTENT_SOURCES).doc(input.sourceId) : null;
        const [claimSnap, pauseSnap, sourceSnap] = await Promise.all([
            transaction.get(claimRef), transaction.get(pauseRef), sourceRef ? transaction.get(sourceRef) : Promise.resolve(null),
        ]);
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) throw new Error("CONTENT_ASSET_IDEMPOTENCY_CONFLICT");
            const replayAssetId = normalizeText(claimSnap.data()?.entityId);
            if (!replayAssetId) throw new Error("CONTENT_ASSET_REPLAY_MISSING");
            const replayRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_ASSETS).doc(replayAssetId);
            const replaySnap = await transaction.get(replayRef);
            if (!replaySnap.exists) throw new Error("CONTENT_ASSET_REPLAY_MISSING");
            const replay = projectSignalDeskContentAsset({
                ...toPlain(replaySnap.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_ASSETS}DocId`]: replayRef.id,
            });
            if (!replay) throw new Error("CONTENT_ASSET_REPLAY_MISSING");
            return replay;
        }
        if (pauseSnap.data()?.status === "active") throw new Error("Content distribution is paused");
        if (input.status !== undefined) throw new Error("CONTENT_ASSET_STATUS_NOT_ALLOWED");
        if (input.sourceId && !sourceSnap?.exists) throw new Error("Content source not found");
        const source = sourceSnap?.exists && sourceRef
            ? projectSignalDeskContentSource({ ...toPlain(sourceSnap.data()), [`${SIGNALDESK_COLLECTIONS.CONTENT_SOURCES}DocId`]: sourceRef.id })
            : null;
        if (sourceSnap?.exists && !source) throw new Error("CONTENT_SOURCE_SHAPE_INVALID");
        if (sourceSnap?.data()?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        if (source && source.status !== "active") throw new Error("Content source is not active");
        if (source && source.sourceType !== input.sourceType) throw new Error("CONTENT_SOURCE_TYPE_MISMATCH");
        const canonicalInputSourceUrl = canonicalizeContentUrl(input.sourceUrl);
        if (source && input.sourceUrl !== undefined && source.sourceUrl !== canonicalInputSourceUrl) throw new Error("CONTENT_SOURCE_URL_MISMATCH");
        if (source && source.defaultAudience !== input.primaryAudience) throw new Error("CONTENT_SOURCE_AUDIENCE_MISMATCH");
        if (source && normalizeText(input.marketPodId) && normalizeText(input.marketPodId) !== normalizeText(source.defaultMarketPodId)) throw new Error("CONTENT_SOURCE_MARKET_POD_MISMATCH");
        const title = normalizeText(input.title);
        const canonicalMessage = normalizeText(input.canonicalMessage);
        const effectiveSourceId = source?.contentSourceId || null;
        const effectiveSourceType = source?.sourceType || input.sourceType;
        const effectiveSourceUrl = source?.sourceUrl || canonicalInputSourceUrl;
        const explicitContentAssetId = normalizeText(input.contentAssetId) || null;
        const canonicalContentAssetId = contentAssetIdFor(title, effectiveSourceId, effectiveSourceType, effectiveSourceUrl);
        const legacyContentAssetId = legacyContentAssetIdFor(title, effectiveSourceUrl);
        const canonicalRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_ASSETS).doc(explicitContentAssetId || canonicalContentAssetId);
        const legacyRef = !explicitContentAssetId && legacyContentAssetId !== canonicalContentAssetId
            ? db.collection(SIGNALDESK_COLLECTIONS.CONTENT_ASSETS).doc(legacyContentAssetId)
            : null;
        const [canonicalSnap, legacySnap] = await Promise.all([
            transaction.get(canonicalRef), legacyRef ? transaction.get(legacyRef) : Promise.resolve(null),
        ]);
        if (explicitContentAssetId && !canonicalSnap.exists) throw new Error("Content asset not found");
        if (!explicitContentAssetId && canonicalSnap.exists && legacySnap?.exists) throw new Error("CONTENT_ASSET_IDENTITY_AMBIGUOUS");
        let assetRef = canonicalRef;
        let assetSnap = canonicalSnap;
        if (!canonicalSnap.exists && legacySnap?.exists) {
            const legacy = projectSignalDeskContentAsset({
                ...toPlain(legacySnap.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_ASSETS}DocId`]: legacyRef!.id,
            });
            if (
                legacy
                && legacy.sourceId === effectiveSourceId
                && legacy.sourceType === effectiveSourceType
                && legacy.sourceUrl === effectiveSourceUrl
            ) {
                assetRef = legacyRef!;
                assetSnap = legacySnap;
            }
        }
        const existingData = assetSnap.exists ? assetSnap.data() as AnyRecord : null;
        if (existingData && normalizeText(existingData.pId) !== SIGNALDESK_PRODUCT_CODE) throw new Error("CONTENT_ASSET_PRODUCT_MISMATCH");
        if (existingData?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        const existingAsset = existingData ? projectSignalDeskContentAsset({
            ...toPlain(existingData),
            [`${SIGNALDESK_COLLECTIONS.CONTENT_ASSETS}DocId`]: assetRef.id,
        }) : null;
        if (existingData && !existingAsset) throw new Error("CONTENT_ASSET_PROVENANCE_INVALID");
        const effectiveProofPermissionId = input.proofLevel === "customer-proof"
            ? normalizeText(input.proofPermissionId) || null
            : null;
        if (input.proofLevel !== "customer-proof" && (normalizeText(input.proofPermissionId) || proofScopes.length)) {
            throw new Error("PROOF_PERMISSION_NOT_ALLOWED");
        }
        const effectiveProofScopes = input.proofLevel === "customer-proof" ? proofScopes : [];
        if (existingAsset && (
            existingAsset.sourceId !== effectiveSourceId
            || existingAsset.sourceType !== effectiveSourceType
            || existingAsset.sourceUrl !== effectiveSourceUrl
            || existingAsset.primaryAudience !== input.primaryAudience
            || existingAsset.proofLevel !== input.proofLevel
            || existingAsset.proofPermissionId !== effectiveProofPermissionId
            || JSON.stringify([...(existingAsset.proofScopes || [])].sort()) !== JSON.stringify(effectiveProofScopes)
            || existingAsset.marketPodId !== (source ? source.defaultMarketPodId || null : normalizeText(input.marketPodId) || null)
        )) throw new Error("CONTENT_ASSET_PROVENANCE_IMMUTABLE");
        const proofPermissionRef = effectiveProofPermissionId ? db.collection(SIGNALDESK_COLLECTIONS.PROOF_PERMISSIONS).doc(effectiveProofPermissionId) : null;
        const ctaRef = input.ctaId ? db.collection(SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS).doc(input.ctaId) : null;
        const effectiveMarketPodId = source ? source.defaultMarketPodId || null : normalizeText(input.marketPodId) || null;
        const marketPodRef = effectiveMarketPodId ? db.collection(SIGNALDESK_COLLECTIONS.MARKET_PODS).doc(effectiveMarketPodId) : null;
        const draftQuery = existingAsset ? db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS).where("contentAssetId", "==", assetRef.id).limit(1) : null;
        const performanceQuery = existingAsset ? db.collection(SIGNALDESK_COLLECTIONS.CONTENT_PERFORMANCE_SUMMARIES).where("contentAssetId", "==", assetRef.id).limit(1) : null;
        const experimentQuery = existingAsset ? db.collection(SIGNALDESK_COLLECTIONS.EXPERIMENT_CARDS).where("contentAssetId", "==", assetRef.id).limit(1) : null;
        const [proofPermissionSnap, marketPodSnap, draftDependencySnap, performanceDependencySnap, experimentDependencySnap] = await Promise.all([
            proofPermissionRef ? transaction.get(proofPermissionRef) : Promise.resolve(null),
            marketPodRef ? transaction.get(marketPodRef) : Promise.resolve(null),
            draftQuery ? transaction.get(draftQuery) : Promise.resolve(null),
            performanceQuery ? transaction.get(performanceQuery) : Promise.resolve(null),
            experimentQuery ? transaction.get(experimentQuery) : Promise.resolve(null),
        ]);
        if (marketPodRef && !marketPodSnap?.exists) throw new Error("Market pod not found");
        if (marketPodSnap?.exists && normalizeText(marketPodSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
            throw new Error("MARKET_POD_PRODUCT_MISMATCH");
        }
        if (marketPodSnap?.data()?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        if (marketPodSnap?.exists && (
            marketPodSnap.data()?.status !== "active"
            || marketPodSnap.data()?.reviewDecision !== "approved"
            || !normalizeText(marketPodSnap.data()?.approvedBy)
        )) throw new Error("Market pod is not founder-approved");
        const proofPermission = proofPermissionSnap?.exists && proofPermissionRef
            ? projectSignalDeskProofPermission({
                ...toPlain(proofPermissionSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.PROOF_PERMISSIONS}DocId`]: proofPermissionRef.id,
            })
            : null;
        if (proofPermissionSnap?.data()?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        if (input.proofLevel === "customer-proof" && !isProofPermissionActive(proofPermission)) throw new Error("PROOF_PERMISSION_REQUIRED");
        if (input.proofLevel === "customer-proof" && !isProofPermissionUsable(proofPermission, proofScopes)) throw new Error("PROOF_PERMISSION_SCOPE_NOT_ALLOWED");
        if (input.proofLevel === "customer-proof") {
            if (!proofPermission?.targetId) throw new Error("PROOF_PERMISSION_REQUIRED");
            const proofTargetSnap = await transaction.get(db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(proofPermission.targetId));
            if (!proofTargetSnap.exists || normalizeText(proofTargetSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
                throw new Error("Proof permission target not found");
            }
        }
        const { cta } = await readSignalDeskCtaAuthority(db, transaction, {
            ctaId: ctaRef?.id,
            requireActive: true,
            useAuthoritativePreview: !ctaRef,
        });
        const timestamp = now();
        const readinessStatus: SignalDeskContentAssetSummary["status"] = input.proofLevel === "internal-note" || input.riskNotes.length ? "hold" : "ready";
        if (readinessStatus === "ready" && !cta) throw new Error("CONTENT_ASSET_ACTIVE_CTA_REQUIRED");
        const status = readinessStatus === "hold" ? "hold" : existingAsset?.status || readinessStatus;
        const resolvedCtaId = input.ctaId || cta?.ctaId || null;
        const riskNotes = input.riskNotes.map((note) => normalizeText(note));
        const sourceNotes = normalizeText(input.sourceNotes) || null;
        const asset = {
            contentAssetId: assetRef.id, pId: SIGNALDESK_PRODUCT_CODE, title, canonicalMessage,
            sourceId: effectiveSourceId, sourceType: effectiveSourceType, sourceUrl: effectiveSourceUrl,
            sourceNotes, primaryAudience: input.primaryAudience, proofLevel: input.proofLevel,
            proofPermissionId: effectiveProofPermissionId, proofScopes: effectiveProofScopes,
            riskNotes, ctaId: resolvedCtaId,
            marketPodId: effectiveMarketPodId, status,
            ...(existingData ? {} : { hasPublishedContent: false, publicationStateVersion: 1 }),
            createdAt: existingData?.createdAt || timestamp, updatedAt: timestamp, updatedBy: access.userId,
        };
        if (existingAsset) {
            const currentComparable = {
                canonicalMessage: existingAsset.canonicalMessage,
                ctaId: existingAsset.ctaId || null,
                riskNotes: existingAsset.riskNotes,
                sourceNotes: existingAsset.sourceNotes || null,
                status: existingAsset.status,
                title: existingAsset.title,
            };
            const nextComparable = {
                canonicalMessage: asset.canonicalMessage,
                ctaId: asset.ctaId,
                riskNotes: asset.riskNotes,
                sourceNotes: asset.sourceNotes,
                status: asset.status,
                title: asset.title,
            };
            const hasMutableChange = JSON.stringify(currentComparable) !== JSON.stringify(nextComparable);
            const hasDependencies = Boolean(
                draftDependencySnap?.docs?.length
                || performanceDependencySnap?.docs?.length
                || experimentDependencySnap?.docs?.length
            );
            if (hasMutableChange && hasDependencies) throw new Error("CONTENT_ASSET_REFERENCED_IMMUTABLE");
            if (hasMutableChange && (existingAsset.status === "distributed" || existingAsset.status === "archived")) {
                throw new Error("CONTENT_ASSET_TERMINAL_IMMUTABLE");
            }
            transaction.set(assetRef, sanitizeForFirestore(asset), { merge: true });
        } else {
            transaction.create(assetRef, sanitizeForFirestore(asset));
            if (sourceRef) transaction.set(sourceRef, sanitizeForFirestore({ lastAssetAt: timestamp, updatedAt: timestamp }), { merge: true });
        }
        transaction.create(claimRef, sanitizeForFirestore({ actorId: access.userId, entityId: assetRef.id, operation: "content_asset_create", pId: SIGNALDESK_PRODUCT_CODE, requestFingerprintHash, updatedAt: timestamp }));
        writeRunTimeline(db, transaction, {
            entityId: assetRef.id, entityType: "content", label: "Content asset",
            status: status === "ready" ? "ready" : status === "archived" ? "blocked" : "held",
            steps: [
                { label: "Canonical message captured", status: "completed", at: toIso(timestamp) },
                { label: `${input.proofLevel} proof level`, status: input.proofLevel === "internal-note" ? "held" : "completed", at: toIso(timestamp) },
                { label: "Proof permission checked", status: input.proofLevel === "customer-proof" ? "completed" : "ready", at: toIso(timestamp) },
                { label: "CTA attached", status: cta ? "completed" : "held", at: toIso(timestamp) },
            ],
        });
        appendAudit(db, transaction, access, "content_asset_create", "contentAsset", assetRef.id, title);
        updateDailyCost(db, transaction, input.sourceId ? 4 : 3, 0, 0);
        return toPlain(asset) as SignalDeskContentAssetSummary;
    });
}

export async function reviewSignalDeskContentAssetServer(
    access: SignalDeskAccessContext,
    input: ContentAssetReviewInput,
) {
    requireContentDistributionRail();
    if (input.status === "archived" && access.role !== "founder-admin") {
        throw new Error("Founder approval is required to archive content assets");
    }
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("CONTENT_ASSET_REVIEW_IDEMPOTENCY_KEY_REQUIRED");
    const requestFingerprintHash = hashValue(JSON.stringify({
        contentAssetId: input.contentAssetId,
        reason: normalizeText(input.reason),
        status: input.status,
    }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`content_asset_review_${operationHash}`);
    const assetRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_ASSETS).doc(input.contentAssetId);
    await resumePendingContentAuthorityReconciliation(db, access, {
        action: "content_asset_dependency_reconcile_recovery",
        assetField: "contentAssetId",
        assetValue: input.contentAssetId,
        authorityRef: assetRef,
        entityType: "contentAsset",
        reason: "Content asset authority changed. Review before distribution.",
        shouldHoldAsset: () => true,
    });
    const transactionResult = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const pauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_content-distribution");
        const [claimSnap, pauseSnap, assetSnap] = await Promise.all([
            transaction.get(claimRef), transaction.get(pauseRef), transaction.get(assetRef),
        ]);
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) throw new Error("CONTENT_ASSET_REVIEW_IDEMPOTENCY_CONFLICT");
            if (!assetSnap.exists) throw new Error("CONTENT_ASSET_REVIEW_REPLAY_MISSING");
            const replay = projectSignalDeskContentAsset({
                ...toPlain(assetSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_ASSETS}DocId`]: assetRef.id,
            });
            if (!replay) throw new Error("CONTENT_ASSET_REVIEW_REPLAY_MISSING");
            const storedReplay = claimSnap.data()?.resultSnapshot
                ? projectSignalDeskContentAsset({
                    ...toPlain(claimSnap.data()?.resultSnapshot),
                    pId: SIGNALDESK_PRODUCT_CODE,
                    [`${SIGNALDESK_COLLECTIONS.CONTENT_ASSETS}DocId`]: assetRef.id,
                })
                : replay;
            if (!storedReplay) throw new Error("CONTENT_ASSET_REVIEW_REPLAY_MISSING");
            const reconciliationToken = normalizeText(assetSnap.data()?.dependentHoldReconciliationToken);
            return {
                asset: storedReplay,
                reconciliationRequired: assetSnap.data()?.dependentHoldReconciliationPending === true
                    && reconciliationToken === claimRef.id,
                reconciliationToken,
            };
        }
        if (!assetSnap.exists) throw new Error("Content asset not found");
        if (assetSnap.data()?.dependentHoldReconciliationPending === true) {
            throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
        }
        const current = projectSignalDeskContentAsset({
            ...toPlain(assetSnap.data()),
            [`${SIGNALDESK_COLLECTIONS.CONTENT_ASSETS}DocId`]: assetRef.id,
        });
        if (!current) throw new Error("CONTENT_ASSET_SHAPE_INVALID");
        if (current.status === "archived" && input.status !== "archived") throw new Error("CONTENT_ASSET_STATUS_TRANSITION_INVALID");
        let effectiveStatus: ContentAssetReviewInput["status"] | "distributed" = input.status;
        let publicationStatePatch: AnyRecord = {};
        if (input.status === "ready") {
            if (pauseSnap.data()?.status === "active") throw new Error("Content distribution is paused");
            if (current.status === "distributed" || current.status === "archived") throw new Error("CONTENT_ASSET_STATUS_TRANSITION_INVALID");
            if (current.proofLevel === "internal-note" || current.riskNotes.length) throw new Error("CONTENT_ASSET_READINESS_BLOCKED");
            const authority = await readSignalDeskContentAssetAuthority(db, transaction, assetRef, assetSnap, false);
            if (!authority.cta) throw new Error("CONTENT_ASSET_ACTIVE_CTA_REQUIRED");
            const lastPublishedContentDraftId = normalizeText(assetSnap.data()?.lastPublishedContentDraftId);
            const storedHasPublishedContent = assetSnap.data()?.hasPublishedContent;
            const storedPublicationStateVersion = assetSnap.data()?.publicationStateVersion;
            let hasPublishedTruth = false;
            if (storedPublicationStateVersion === 1 && storedHasPublishedContent === true) {
                if (!lastPublishedContentDraftId) throw new Error("CONTENT_ASSET_PUBLICATION_MARKER_INVALID");
                const publishedDraftRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS)
                    .doc(lastPublishedContentDraftId);
                const publishedCalendarRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_CALENDAR_ITEMS)
                    .doc(contentCalendarItemIdFor(lastPublishedContentDraftId));
                const [publishedDraftSnap, publishedCalendarSnap] = await Promise.all([
                    transaction.get(publishedDraftRef),
                    transaction.get(publishedCalendarRef),
                ]);
                const publishedDraft = publishedDraftSnap.exists ? projectSignalDeskContentDraft({
                    ...toPlain(publishedDraftSnap.data()),
                    [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: publishedDraftRef.id,
                }) : null;
                const publishedCalendar = publishedCalendarSnap.exists ? projectSignalDeskContentCalendarItem({
                    ...toPlain(publishedCalendarSnap.data()),
                    [`${SIGNALDESK_COLLECTIONS.CONTENT_CALENDAR_ITEMS}DocId`]: publishedCalendarRef.id,
                }) : null;
                hasPublishedTruth = Boolean(
                    publishedDraft
                    && publishedCalendar
                    && publishedDraft.contentAssetId === input.contentAssetId
                    && publishedDraft.status === "published"
                    && publishedCalendar.contentAssetId === input.contentAssetId
                    && publishedCalendar.contentDraftId === publishedDraft.contentDraftId
                    && publishedCalendar.channel === publishedDraft.channel
                    && publishedCalendar.status === "published"
                    && publishedCalendar.publicationUrl === normalizeText(assetSnap.data()?.lastPublicationUrl)
                    && publishedCalendar.publishedAt === toIso(assetSnap.data()?.lastPublishedAt)
                );
                if (!hasPublishedTruth) throw new Error("CONTENT_ASSET_PUBLICATION_MARKER_INVALID");
            } else if (storedPublicationStateVersion === 1 && storedHasPublishedContent === false) {
                if (
                    lastPublishedContentDraftId
                    || assetSnap.data()?.lastPublicationUrl != null
                    || assetSnap.data()?.lastPublishedAt != null
                ) throw new Error("CONTENT_ASSET_PUBLICATION_MARKER_INVALID");
            } else {
                const [dependentDraftsSnap, dependentCalendarSnap] = await Promise.all([
                    transaction.get(db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS)
                        .where("contentAssetId", "==", input.contentAssetId).limit(21)),
                    transaction.get(db.collection(SIGNALDESK_COLLECTIONS.CONTENT_CALENDAR_ITEMS)
                        .where("contentAssetId", "==", input.contentAssetId).limit(21)),
                ]);
                if (dependentDraftsSnap.size > 20 || dependentCalendarSnap.size > 20) {
                    throw new Error("CONTENT_ASSET_PUBLICATION_HISTORY_UNBOUNDED");
                }
                const dependentDrafts = dependentDraftsSnap.docs.map((draftDoc) => projectSignalDeskContentDraft({
                    ...toPlain(draftDoc.data()),
                    [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: draftDoc.id,
                }));
                const dependentCalendarItems = dependentCalendarSnap.docs.map((calendarDoc) => projectSignalDeskContentCalendarItem({
                    ...toPlain(calendarDoc.data()),
                    [`${SIGNALDESK_COLLECTIONS.CONTENT_CALENDAR_ITEMS}DocId`]: calendarDoc.id,
                }));
                if (dependentDrafts.some((draft) => !draft)) throw new Error("CONTENT_DRAFT_SHAPE_INVALID");
                if (dependentCalendarItems.some((calendarItem) => !calendarItem)) throw new Error("CONTENT_CALENDAR_SHAPE_INVALID");
                const publishedDraftsById = new Map(dependentDrafts
                    .filter((draft): draft is SignalDeskContentDistributionDraftSummary => Boolean(draft && draft.status === "published"))
                    .map((draft) => [draft.contentDraftId, draft]));
                const legacyPublishedCalendar = dependentCalendarItems
                    .filter((calendarItem): calendarItem is SignalDeskContentCalendarItemSummary => {
                        if (!calendarItem || calendarItem.status !== "published") return false;
                        const publishedDraft = publishedDraftsById.get(calendarItem.contentDraftId);
                        return Boolean(
                            publishedDraft
                            && calendarItem.channel === publishedDraft.channel
                            && calendarItem.contentAssetId === publishedDraft.contentAssetId
                            && calendarItem.publicationUrl
                            && calendarItem.publishedAt
                        );
                    })
                    .sort((left, right) => (
                        new Date(right.publishedAt!).getTime() - new Date(left.publishedAt!).getTime()
                        || right.contentDraftId.localeCompare(left.contentDraftId)
                    ))[0];
                hasPublishedTruth = Boolean(legacyPublishedCalendar);
                const legacyPublishedAt = legacyPublishedCalendar?.publishedAt;
                publicationStatePatch = legacyPublishedCalendar && legacyPublishedAt
                    ? {
                        hasPublishedContent: true,
                        lastPublicationUrl: legacyPublishedCalendar.publicationUrl,
                        lastPublishedAt: admin.firestore.Timestamp.fromDate(new Date(legacyPublishedAt)),
                        lastPublishedContentDraftId: legacyPublishedCalendar.contentDraftId,
                        publicationStateVersion: 1,
                    }
                    : { hasPublishedContent: false, publicationStateVersion: 1 };
            }
            if (hasPublishedTruth) effectiveStatus = "distributed";
        }
        const timestamp = now();
        const publicationReviewPatch = input.status === "ready"
            ? await resolveContentAuthorityPublicationReview({
                actorId: access.userId,
                asset: assetSnap.data() as AnyRecord,
                assetRef,
                db,
                reason: normalizeText(input.reason),
                timestamp,
                transaction,
            })
            : {};
        const reconciliationRequired = input.status !== "ready" && current.status !== input.status;
        const reconciliationToken = reconciliationRequired ? claimRef.id : "";
        const assetUpdate = {
            ...publicationStatePatch,
            ...publicationReviewPatch,
            dependentHoldReconciliationKind: reconciliationRequired
                ? CONTENT_AUTHORITY_RECONCILIATION_KIND
                : null,
            dependentHoldReconciliationPending: reconciliationRequired,
            dependentHoldReconciliationProgress: reconciliationRequired
                ? emptyContentAuthorityReconciliationResult()
                : null,
            dependentHoldReconciliationToken: reconciliationToken || null,
            status: effectiveStatus,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        transaction.set(assetRef, sanitizeForFirestore(assetUpdate), { merge: true });
        const projectedAsset = projectSignalDeskContentAsset({
            ...toPlain({ ...current, ...assetUpdate, pId: SIGNALDESK_PRODUCT_CODE }),
            [`${SIGNALDESK_COLLECTIONS.CONTENT_ASSETS}DocId`]: assetRef.id,
        });
        if (!projectedAsset) throw new Error("CONTENT_ASSET_SHAPE_INVALID");
        transaction.create(claimRef, sanitizeForFirestore({
            actorId: access.userId,
            entityId: input.contentAssetId,
            operation: "content_asset_review",
            pId: SIGNALDESK_PRODUCT_CODE,
            requestFingerprintHash,
            resultSnapshot: { ...toPlain(projectedAsset), pId: SIGNALDESK_PRODUCT_CODE },
            updatedAt: timestamp,
        }));
        writeRunTimeline(db, transaction, {
            entityId: input.contentAssetId,
            entityType: "content",
            label: "Content asset review",
            status: effectiveStatus === "ready" || effectiveStatus === "distributed" ? "ready" : effectiveStatus === "archived" ? "blocked" : "held",
            steps: [{
                at: toIso(timestamp),
                label: `${current.status} to ${effectiveStatus}: ${normalizeText(input.reason)}`,
                status: effectiveStatus === "ready" || effectiveStatus === "distributed" ? "completed" : effectiveStatus === "archived" ? "blocked" : "held",
            }],
        });
        appendAudit(db, transaction, access, "content_asset_review", "contentAsset", input.contentAssetId, `${current.status}->${effectiveStatus}:${normalizeText(input.reason)}`);
        updateDailyCost(db, transaction, input.status === "ready" ? 6 : 3, 0, 0);
        return { asset: projectedAsset, reconciliationRequired, reconciliationToken };
    });
    if (transactionResult.reconciliationRequired) {
        if (!transactionResult.reconciliationToken) throw new Error("CONTENT_AUTHORITY_RECONCILIATION_TOKEN_MISSING");
        const reconciliationResult = await reconcileContentAuthorityHolds(db, {
            actorId: access.userId,
            assetField: "contentAssetId",
            assetValue: input.contentAssetId,
            authorityRef: assetRef,
            reason: "Content asset authority changed. Review before distribution.",
            reconciliationToken: transactionResult.reconciliationToken,
            shouldHoldAsset: () => true,
        });
        await completeContentAuthorityReconciliation(db, access, {
            action: "content_asset_dependency_reconcile",
            authorityRef: assetRef,
            entityType: "contentAsset",
            reconciliationToken: transactionResult.reconciliationToken,
        }, reconciliationResult);
    }
    return transactionResult.asset;
}

export async function generateSignalDeskContentDistributionDraftsServer(
    access: SignalDeskAccessContext,
    input: ContentDistributionDraftInput,
) {
    requireContentDistributionRail();
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("CONTENT_DRAFT_GENERATION_IDEMPOTENCY_KEY_REQUIRED");
    if (!Array.isArray(input.channels)) throw new Error("CONTENT_DRAFT_CHANNELS_INVALID");
    const uniqueChannels = Array.from(new Set(input.channels)).sort();
    if (uniqueChannels.length < 1 || uniqueChannels.length > 8 || uniqueChannels.some((channel) => !CONTENT_CHANNELS.has(channel))) {
        throw new Error("CONTENT_DRAFT_CHANNELS_INVALID");
    }
    const requestFingerprintHash = hashValue(JSON.stringify({ channels: uniqueChannels, contentAssetId: input.contentAssetId }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`content_draft_generation_${operationHash}`);
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const assetRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_ASSETS).doc(input.contentAssetId);
        const pauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_content-distribution");
        const baseDraftRefs = uniqueChannels.map((channel) => (
            db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS)
                .doc(contentDraftIdFor(input.contentAssetId, channel))
        ));
        const [claimSnap, pauseSnap, assetSnap, ...baseDraftSnaps] = await Promise.all([
            transaction.get(claimRef),
            transaction.get(pauseRef),
            transaction.get(assetRef),
            ...baseDraftRefs.map((ref) => transaction.get(ref)),
        ]);
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) throw new Error("CONTENT_DRAFT_GENERATION_IDEMPOTENCY_CONFLICT");
            const storedEntityIds = Array.isArray(claimSnap.data()?.entityIds)
                ? claimSnap.data()!.entityIds.map((value: unknown) => normalizeText(value))
                : baseDraftRefs.map((ref) => ref.id);
            if (
                storedEntityIds.length !== uniqueChannels.length
                || new Set(storedEntityIds).size !== storedEntityIds.length
                || storedEntityIds.some((value: string) => !value || value.length > 180)
            ) throw new Error("CONTENT_DRAFT_GENERATION_REPLAY_MISSING");
            const replayRefs = storedEntityIds.map((entityId: string) => (
                db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS).doc(entityId)
            ));
            const replaySnaps = await Promise.all(replayRefs.map((ref, index) => (
                ref.id === baseDraftRefs[index].id
                    ? Promise.resolve(baseDraftSnaps[index])
                    : transaction.get(ref)
            )));
            if (replaySnaps.some((snap) => !snap.exists)) throw new Error("CONTENT_DRAFT_GENERATION_REPLAY_MISSING");
            const replayDrafts = replaySnaps.map((snap, index) => projectSignalDeskContentDraft({
                ...toPlain(snap.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: replayRefs[index].id,
            }));
            if (replayDrafts.some((draft, index) => (
                !draft
                || draft.contentAssetId !== input.contentAssetId
                || draft.channel !== uniqueChannels[index]
                || draft.contentDraftId !== contentDraftIdFor(input.contentAssetId, uniqueChannels[index], draft.revision)
                || draft.supersedesContentDraftId !== (draft.revision > 1
                    ? contentDraftIdFor(input.contentAssetId, uniqueChannels[index], draft.revision - 1)
                    : null)
            ))) throw new Error("CONTENT_DRAFT_GENERATION_REPLAY_MISSING");
            const replayPredecessorRefs = replayDrafts.map((draft, index) => (
                draft && draft.revision > 1
                    ? db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS)
                        .doc(contentDraftIdFor(input.contentAssetId, uniqueChannels[index], draft.revision - 1))
                    : null
            ));
            const replayPredecessorSnaps = await Promise.all(replayPredecessorRefs.map((ref) => (
                ref ? transaction.get(ref) : Promise.resolve(null)
            )));
            replayDrafts.forEach((draft, index) => {
                if (!draft) throw new Error("CONTENT_DRAFT_GENERATION_REPLAY_MISSING");
                const baseDraft = projectSignalDeskContentDraft({
                    ...toPlain(baseDraftSnaps[index].data()),
                    [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: baseDraftRefs[index].id,
                });
                const storedLatestRevision = baseDraftSnaps[index].data()?.latestRevision ?? baseDraft?.revision;
                const storedLatestContentDraftId = normalizeText(baseDraftSnaps[index].data()?.latestContentDraftId) || baseDraftRefs[index].id;
                if (
                    !baseDraftSnaps[index].exists
                    || !baseDraft
                    || baseDraft.revision !== 1
                    || !Number.isInteger(storedLatestRevision)
                    || storedLatestRevision < draft.revision
                    || storedLatestContentDraftId !== contentDraftIdFor(input.contentAssetId, uniqueChannels[index], storedLatestRevision)
                ) throw new Error("CONTENT_DRAFT_GENERATION_REPLAY_MISSING");
                const predecessorRef = replayPredecessorRefs[index];
                const predecessorSnap = replayPredecessorSnaps[index];
                if (!predecessorRef) return;
                if (!predecessorSnap?.exists) throw new Error("CONTENT_DRAFT_GENERATION_REPLAY_MISSING");
                const predecessor = projectSignalDeskContentDraft({
                    ...toPlain(predecessorSnap.data()),
                    [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: predecessorRef.id,
                });
                if (
                    !predecessor
                    || predecessor.contentAssetId !== input.contentAssetId
                    || predecessor.channel !== uniqueChannels[index]
                    || predecessor.revision !== draft.revision - 1
                ) throw new Error("CONTENT_DRAFT_GENERATION_REPLAY_MISSING");
            });
            return replayDrafts as SignalDeskContentDistributionDraftSummary[];
        }
        if (pauseSnap.data()?.status === "active") throw new Error("Content distribution is paused");
        const { asset, cta: assetCta } = await readSignalDeskContentAssetAuthority(db, transaction, assetRef, assetSnap);
        let cta = assetCta;
        if (!asset.ctaId) {
            cta = (await readSignalDeskCtaAuthority(db, transaction, {
                requireActive: true,
                useAuthoritativePreview: true,
            })).cta;
        }
        if (!cta) throw new Error("CONTENT_DRAFT_ACTIVE_CTA_REQUIRED");
        let backfillAssetCtaId: string | null = null;
        if (!asset.ctaId && cta) {
            const existingAssetDraftsSnap = await transaction.get(
                db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS)
                    .where("contentAssetId", "==", input.contentAssetId)
                    .limit(21),
            );
            if (existingAssetDraftsSnap.size > 20) throw new Error("CONTENT_ASSET_CTA_BACKFILL_UNBOUNDED");
            const existingAssetDrafts = existingAssetDraftsSnap.docs.map((draftDoc) => projectSignalDeskContentDraft({
                ...toPlain(draftDoc.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: draftDoc.id,
            }));
            if (existingAssetDrafts.some((draft) => !draft)) throw new Error("CONTENT_DRAFT_SHAPE_INVALID");
            if (existingAssetDrafts.some((draft) => (
                draft
                && draft.ctaId !== cta.ctaId
                && !["hold", "rejected"].includes(draft.status)
            ))) throw new Error("CONTENT_ASSET_CTA_BACKFILL_CONFLICT");
            backfillAssetCtaId = cta.ctaId;
        }
        const latestDraftRefs = baseDraftSnaps.map((baseSnap, index) => {
            if (!baseSnap.exists) return baseDraftRefs[index];
            const latestContentDraftId = normalizeText(baseSnap.data()?.latestContentDraftId) || baseDraftRefs[index].id;
            if (latestContentDraftId.length > 180) throw new Error("CONTENT_DRAFT_HEAD_INVALID");
            return db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS).doc(latestContentDraftId);
        });
        const latestDraftSnaps = await Promise.all(latestDraftRefs.map((latestRef, index) => (
            latestRef.id === baseDraftRefs[index].id
                ? Promise.resolve(baseDraftSnaps[index])
                : transaction.get(latestRef)
        )));
        const revisions = latestDraftSnaps.map((latestSnap, index) => {
            if (!baseDraftSnaps[index].exists) return 1;
            if (!latestSnap.exists) throw new Error("CONTENT_DRAFT_HEAD_INVALID");
            const baseDraft = projectSignalDeskContentDraft({
                ...toPlain(baseDraftSnaps[index].data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: baseDraftRefs[index].id,
            });
            const latestDraft = projectSignalDeskContentDraft({
                ...toPlain(latestSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: latestDraftRefs[index].id,
            });
            if (
                !baseDraft
                || !latestDraft
                || baseDraft.revision !== 1
                || baseDraft.contentAssetId !== input.contentAssetId
                || latestDraft.contentAssetId !== input.contentAssetId
                || baseDraft.channel !== uniqueChannels[index]
                || latestDraft.channel !== uniqueChannels[index]
                || latestDraft.contentDraftId !== contentDraftIdFor(input.contentAssetId, uniqueChannels[index], latestDraft.revision)
                || (latestDraft.revision > 1
                    && latestDraft.supersedesContentDraftId !== contentDraftIdFor(input.contentAssetId, uniqueChannels[index], latestDraft.revision - 1))
            ) throw new Error("CONTENT_DRAFT_HEAD_INVALID");
            const storedLatestRevision = baseDraftSnaps[index].data()?.latestRevision;
            if (storedLatestRevision != null && storedLatestRevision !== latestDraft.revision) {
                throw new Error("CONTENT_DRAFT_HEAD_INVALID");
            }
            if (![
                "rejected",
                "hold",
            ].includes(latestDraft.status) || !["rejected", "hold"].includes(latestDraft.approvalStatus)) {
                throw new Error("CONTENT_DRAFT_ALREADY_EXISTS");
            }
            if (latestDraft.revision >= 1000) throw new Error("CONTENT_DRAFT_REVISION_LIMIT");
            return latestDraft.revision + 1;
        });
        const draftRefs = uniqueChannels.map((channel, index) => (
            db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS)
                .doc(contentDraftIdFor(input.contentAssetId, channel, revisions[index]))
        ));
        const revisionDependencyIndexes = revisions
            .map((revision, index) => revision > 1 ? index : -1)
            .filter((index) => index >= 0);
        const revisionDependencyResults = await Promise.all(revisionDependencyIndexes.map(async (index) => {
            const previousDraftRef = latestDraftRefs[index];
            const previousRevision = revisions[index] - 1;
            const predecessorRef = previousRevision > 1
                ? db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS)
                    .doc(contentDraftIdFor(input.contentAssetId, uniqueChannels[index], previousRevision - 1))
                : null;
            const calendarRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_CALENDAR_ITEMS)
                .doc(contentCalendarItemIdFor(previousDraftRef.id));
            const performanceQuery = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_PERFORMANCE_SUMMARIES)
                .where("contentDraftId", "==", previousDraftRef.id)
                .limit(21);
            const [calendarSnap, performanceSnap, collisionSnap, predecessorSnap] = await Promise.all([
                transaction.get(calendarRef),
                transaction.get(performanceQuery),
                transaction.get(draftRefs[index]),
                predecessorRef ? transaction.get(predecessorRef) : Promise.resolve(null),
            ]);
            return { calendarSnap, collisionSnap, index, performanceSnap, predecessorRef, predecessorSnap, previousRevision };
        }));
        revisionDependencyResults.forEach(({
            calendarSnap, collisionSnap, index, performanceSnap, predecessorRef, predecessorSnap, previousRevision,
        }) => {
            if (performanceSnap.size > 20) throw new Error("CONTENT_DRAFT_REVISION_REFERENCED");
            const performanceRows = performanceSnap.docs.map((performanceDoc) => projectSignalDeskContentPerformance({
                ...toPlain(performanceDoc.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_PERFORMANCE_SUMMARIES}DocId`]: performanceDoc.id,
            }));
            if (performanceRows.some((performance) => (
                !performance
                || performance.contentDraftId !== latestDraftRefs[index].id
                || Boolean(performance.publicationUrl)
                || Boolean(performance.publishedAt)
                || performance.views > 0
                || performance.clicks > 0
                || performance.ownerLeads > 0
                || performance.currentListSubmissions > 0
                || performance.activations > 0
            ))) throw new Error("CONTENT_DRAFT_REVISION_REFERENCED");
            if (calendarSnap.exists) {
                const previousDraft = projectSignalDeskContentDraft({
                    ...toPlain(latestDraftSnaps[index].data()),
                    [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: latestDraftRefs[index].id,
                });
                const heldCalendar = projectSignalDeskContentCalendarItem({
                    ...toPlain(calendarSnap.data()),
                    [`${SIGNALDESK_COLLECTIONS.CONTENT_CALENDAR_ITEMS}DocId`]: calendarSnap.id,
                });
                if (
                    !previousDraft
                    || previousDraft.status !== "hold"
                    || previousDraft.approvalStatus !== "hold"
                    || !heldCalendar
                    || heldCalendar.status !== "held"
                    || heldCalendar.contentAssetId !== input.contentAssetId
                    || heldCalendar.contentDraftId !== previousDraft.contentDraftId
                    || heldCalendar.channel !== uniqueChannels[index]
                    || heldCalendar.publicationUrl !== null
                    || heldCalendar.publishedAt !== null
                ) throw new Error("CONTENT_DRAFT_REVISION_REFERENCED");
            }
            if (collisionSnap.exists) throw new Error("CONTENT_DRAFT_IDENTITY_COLLISION");
            if (!predecessorRef) return;
            if (!predecessorSnap?.exists) throw new Error("CONTENT_DRAFT_HEAD_INVALID");
            const predecessor = projectSignalDeskContentDraft({
                ...toPlain(predecessorSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: predecessorRef.id,
            });
            if (
                !predecessor
                || predecessor.contentAssetId !== input.contentAssetId
                || predecessor.channel !== uniqueChannels[index]
                || predecessor.revision !== previousRevision - 1
            ) throw new Error("CONTENT_DRAFT_HEAD_INVALID");
        });
        const timestamp = now();
        if (backfillAssetCtaId) {
            transaction.set(assetRef, sanitizeForFirestore({
                ctaId: backfillAssetCtaId,
                updatedAt: timestamp,
                updatedBy: access.userId,
            }), { merge: true });
        }
        const drafts: SignalDeskContentDistributionDraftSummary[] = uniqueChannels.map((channel, index) => {
            const contentDraftId = draftRefs[index].id;
            const copy = buildContentDraftCopy(asset, channel, cta);
            const ctaFingerprintHash = cta
                ? signalDeskCtaFingerprintHash(cta)
                : null;
            const draft = {
                contentDraftId, pId: SIGNALDESK_PRODUCT_CODE, contentAssetId: input.contentAssetId, channel,
                title: copy.title, hook: copy.hook, body: copy.body, ctaId: asset.ctaId || cta?.ctaId || null, ctaFingerprintHash,
                status: "draft" as const, approvalStatus: "pending" as const,
                reviewReason: "Generated from approved content asset. Human review required before scheduling.",
                revision: revisions[index],
                scheduledFor: null, createdAt: timestamp, updatedAt: timestamp, updatedBy: access.userId,
                supersedesContentDraftId: revisions[index] > 1 ? latestDraftRefs[index].id : null,
                latestContentDraftId: contentDraftId,
                latestRevision: revisions[index],
            };
            transaction.create(draftRefs[index], sanitizeForFirestore(draft));
            if (revisions[index] > 1) {
                transaction.set(baseDraftRefs[index], sanitizeForFirestore({
                    headUpdatedAt: timestamp,
                    latestContentDraftId: contentDraftId,
                    latestRevision: revisions[index],
                }), { merge: true });
            }
            const projectedDraft = projectSignalDeskContentDraft({
                ...toPlain(draft),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: contentDraftId,
            });
            if (!projectedDraft) throw new Error("CONTENT_DRAFT_SHAPE_INVALID");
            return projectedDraft;
        });
        transaction.create(claimRef, sanitizeForFirestore({
            actorId: access.userId,
            entityId: input.contentAssetId,
            entityIds: draftRefs.map((ref) => ref.id),
            operation: "content_distribution_drafts_generate",
            pId: SIGNALDESK_PRODUCT_CODE,
            requestFingerprintHash,
            updatedAt: timestamp,
        }));
        writeRunTimeline(db, transaction, {
            entityId: input.contentAssetId, entityType: "content", label: "Content distribution drafts", status: "held",
            steps: [
                { label: `${uniqueChannels.length} channel drafts generated`, status: "completed", at: toIso(timestamp) },
                { label: "Approval required before schedule", status: "held", at: toIso(timestamp) },
            ],
        });
        appendAudit(db, transaction, access, "content_distribution_drafts_generate", "contentAsset", input.contentAssetId, uniqueChannels.join(", "));
        updateQueueSummary(db, transaction, { humanReview: increment(uniqueChannels.length) });
        updateDailyCost(db, transaction, 3 + uniqueChannels.length + (backfillAssetCtaId ? 1 : 0), 0, 0);
        return drafts;
    });
}

export async function reviewSignalDeskContentDistributionDraftServer(
    access: SignalDeskAccessContext,
    input: ContentDraftReviewInput,
) {
    requireContentDistributionRail();
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("CONTENT_REVIEW_IDEMPOTENCY_KEY_REQUIRED");
    const requestFingerprintHash = hashValue(JSON.stringify({ approvalStatus: input.approvalStatus, contentDraftId: input.contentDraftId, reviewReason: input.reviewReason || null }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`content_review_${operationHash}`);
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const draftRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS).doc(input.contentDraftId);
        const pauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_content-distribution");
        const queueRef = db.collection(SIGNALDESK_COLLECTIONS.QUEUE_SUMMARIES).doc(SIGNALDESK_SUMMARY_DOCS.QUEUES);
        const [claimSnap, pauseSnap, draftSnap, queueSnap] = await Promise.all([
            transaction.get(claimRef), transaction.get(pauseRef), transaction.get(draftRef), transaction.get(queueRef),
        ]);
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) throw new Error("CONTENT_REVIEW_IDEMPOTENCY_CONFLICT");
            if (!draftSnap.exists) throw new Error("CONTENT_REVIEW_REPLAY_MISSING");
            const replay = projectSignalDeskContentDraft({
                ...toPlain(draftSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: draftRef.id,
            });
            if (!replay) throw new Error("CONTENT_REVIEW_REPLAY_MISSING");
            return replay;
        }
        if (pauseSnap.data()?.status === "active" && input.approvalStatus === "approved") {
            throw new Error("Content distribution is paused");
        }
        if (!draftSnap.exists) throw new Error("Content draft not found");
        const currentDraft = projectSignalDeskContentDraft({
            ...toPlain(draftSnap.data()),
            [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: draftRef.id,
        });
        if (!currentDraft) throw new Error("CONTENT_DRAFT_SHAPE_INVALID");
        if (currentDraft.status === "queued" || currentDraft.status === "published") throw new Error("CONTENT_DRAFT_ALREADY_ADVANCED");
        if (currentDraft.approvalStatus !== "pending") throw new Error("CONTENT_DRAFT_ALREADY_REVIEWED");
        if (input.approvalStatus === "approved") {
            await readSignalDeskContentDraftAuthority(db, transaction, draftRef, draftSnap);
        }
        const timestamp = now();
        const status: SignalDeskContentDistributionDraftSummary["status"] = input.approvalStatus === "approved"
            ? "approved"
            : input.approvalStatus === "rejected"
                ? "rejected"
                : "hold";
        const draft = {
            ...currentDraft,
            approvalStatus: input.approvalStatus,
            pId: SIGNALDESK_PRODUCT_CODE,
            status,
            reviewReason: input.reviewReason || (input.approvalStatus === "approved" ? "Approved for scheduling." : "Held for revision."),
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        transaction.set(draftRef, sanitizeForFirestore(draft), { merge: true });
        if (currentDraft.approvalStatus === "pending") {
            transaction.set(queueRef, sanitizeForFirestore({
                humanReview: Math.max(0, Math.floor(numberOrZero(queueSnap.data()?.humanReview)) - 1),
                updatedAt: timestamp,
            }), { merge: true });
        }
        transaction.create(claimRef, sanitizeForFirestore({ actorId: access.userId, entityId: input.contentDraftId, operation: "content_distribution_draft_review", pId: SIGNALDESK_PRODUCT_CODE, requestFingerprintHash, updatedAt: timestamp }));
        writeRunTimeline(db, transaction, {
            entityId: input.contentDraftId,
            entityType: "content",
            label: "Content draft review",
            status: input.approvalStatus === "approved" ? "ready" : input.approvalStatus === "rejected" ? "blocked" : "held",
            steps: [{ label: `Review ${input.approvalStatus}`, status: input.approvalStatus === "approved" ? "completed" : "held", at: toIso(timestamp) }],
        });
        appendAudit(db, transaction, access, "content_distribution_draft_review", "contentDistributionDraft", input.contentDraftId, input.approvalStatus);
        updateDailyCost(db, transaction, currentDraft.approvalStatus === "pending" ? 4 : 3, 0, 0);
        const projectedDraft = projectSignalDeskContentDraft({
            ...toPlain(draft),
            [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: draftRef.id,
        });
        if (!projectedDraft) throw new Error("CONTENT_DRAFT_SHAPE_INVALID");
        return projectedDraft;
    });
}

export async function scheduleSignalDeskContentDistributionDraftServer(
    access: SignalDeskAccessContext,
    input: ContentDraftScheduleInput,
) {
    requireContentDistributionRail();
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("CONTENT_SCHEDULE_IDEMPOTENCY_KEY_REQUIRED");
    const requestFingerprintHash = hashValue(JSON.stringify({ contentDraftId: input.contentDraftId, scheduledFor: input.scheduledFor || null, status: input.status || "queued" }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const calendarItemId = contentCalendarItemIdFor(input.contentDraftId);
    const calendarRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_CALENDAR_ITEMS).doc(calendarItemId);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`content_schedule_${operationHash}`);
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const draftRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS).doc(input.contentDraftId);
        const pauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_content-distribution");
        const [claimSnap, calendarSnap, pauseSnap, draftSnap] = await Promise.all([
            transaction.get(claimRef), transaction.get(calendarRef), transaction.get(pauseRef), transaction.get(draftRef),
        ]);
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) throw new Error("CONTENT_SCHEDULE_IDEMPOTENCY_CONFLICT");
            if (!calendarSnap.exists) throw new Error("CONTENT_SCHEDULE_REPLAY_MISSING");
            const replay = projectSignalDeskContentCalendarItem({
                ...toPlain(calendarSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_CALENDAR_ITEMS}DocId`]: calendarRef.id,
            });
            if (!replay) throw new Error("CONTENT_CALENDAR_SHAPE_INVALID");
            return replay;
        }
        if (input.status === "approved") throw new Error("CONTENT_SCHEDULE_STATUS_INVALID");
        if (pauseSnap.data()?.status === "active" && input.status !== "hold") {
            throw new Error("Content distribution is paused");
        }
        if (!draftSnap.exists) throw new Error("Content draft not found");
        const draft = projectSignalDeskContentDraft({
            ...toPlain(draftSnap.data()),
            [`${SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS}DocId`]: draftRef.id,
        });
        if (!draft) throw new Error("CONTENT_DRAFT_SHAPE_INVALID");
        if (draft.approvalStatus !== "approved") throw new Error("Content draft must be approved before scheduling");
        if (draft.status === "published") throw new Error("CONTENT_DRAFT_ALREADY_ADVANCED");
        if (calendarSnap.exists) {
            const existingCalendar = projectSignalDeskContentCalendarItem({
                ...toPlain(calendarSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_CALENDAR_ITEMS}DocId`]: calendarRef.id,
            });
            if (!existingCalendar) throw new Error("CONTENT_CALENDAR_SHAPE_INVALID");
            if (
                existingCalendar.contentDraftId !== draft.contentDraftId
                || existingCalendar.contentAssetId !== draft.contentAssetId
                || existingCalendar.channel !== draft.channel
            ) throw new Error("CONTENT_CALENDAR_IDENTITY_MISMATCH");
            if (existingCalendar.status === "published") throw new Error("CONTENT_DRAFT_ALREADY_ADVANCED");
        }
        const schedulingAuthority = input.status !== "hold"
            ? await readSignalDeskContentDraftAuthority(db, transaction, draftRef, draftSnap)
            : null;
        const timestamp = now();
        let scheduledFor: FirebaseFirestore.Timestamp;
        if (input.scheduledFor) {
            const scheduledDate = new Date(input.scheduledFor);
            if (Number.isNaN(scheduledDate.getTime()) || scheduledDate.getTime() < Date.now() - CONTENT_PUBLICATION_FUTURE_SKEW_MS) {
                throw new Error("CONTENT_SCHEDULED_AT_INVALID");
            }
            scheduledFor = admin.firestore.Timestamp.fromDate(scheduledDate);
        } else {
            scheduledFor = timestampAfterDays(1);
        }
        if (schedulingAuthority?.asset.proofLevel === "customer-proof" && schedulingAuthority.permission?.expiresAt) {
            const scheduledForMillis = toTimestampMillis(scheduledFor);
            const permissionExpiryMillis = toTimestampMillis(schedulingAuthority.permission.expiresAt);
            if (!scheduledForMillis || !permissionExpiryMillis) throw new Error("CONTENT_SCHEDULE_PROOF_TIME_INVALID");
            if (scheduledForMillis >= permissionExpiryMillis) throw new Error("CONTENT_SCHEDULE_AFTER_PROOF_EXPIRY");
        }
        const draftStatus: SignalDeskContentDistributionDraftSummary["status"] = input.status === "hold" ? "hold" : "queued";
        const calendarStatus: SignalDeskContentCalendarItemSummary["status"] = input.status === "hold" ? "held" : "queued";
        const calendarItem = {
            contentCalendarItemId: calendarItemId,
            pId: SIGNALDESK_PRODUCT_CODE,
            contentDraftId: input.contentDraftId,
            contentAssetId: draft.contentAssetId,
            channel: draft.channel,
            scheduledFor,
            publicationUrl: null,
            publishedAt: null,
            status: calendarStatus,
            createdAt: calendarSnap.data()?.createdAt || timestamp,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        transaction.set(draftRef, sanitizeForFirestore({ scheduledFor, status: draftStatus, updatedAt: timestamp, updatedBy: access.userId }), { merge: true });
        transaction.set(calendarRef, sanitizeForFirestore(calendarItem), { merge: true });
        transaction.create(claimRef, sanitizeForFirestore({ actorId: access.userId, entityId: calendarItemId, operation: "content_distribution_draft_schedule", pId: SIGNALDESK_PRODUCT_CODE, requestFingerprintHash, updatedAt: timestamp }));
        writeRunTimeline(db, transaction, {
            entityId: input.contentDraftId,
            entityType: "content",
            label: "Content schedule",
            status: draftStatus === "queued" ? "ready" : "held",
            steps: [
                { label: "Draft approval checked", status: "completed", at: toIso(timestamp) },
                { label: "Calendar item queued without auto-publish", status: draftStatus === "queued" ? "completed" : "held", at: toIso(timestamp) },
            ],
        });
        appendAudit(db, transaction, access, "content_distribution_draft_schedule", "contentDistributionDraft", input.contentDraftId, toIso(scheduledFor) || "");
        updateDailyCost(db, transaction, 4, 0, 0);
        const projectedCalendarItem = projectSignalDeskContentCalendarItem({
            ...toPlain(calendarItem),
            [`${SIGNALDESK_COLLECTIONS.CONTENT_CALENDAR_ITEMS}DocId`]: calendarItemId,
        });
        if (!projectedCalendarItem) throw new Error("CONTENT_CALENDAR_SHAPE_INVALID");
        return projectedCalendarItem;
    });
}

export async function recordSignalDeskContentPerformanceServer(
    access: SignalDeskAccessContext,
    input: ContentPerformanceInput,
) {
    requireContentDistributionRail();
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("CONTENT_PERFORMANCE_IDEMPOTENCY_KEY_REQUIRED");
    const requestFingerprint: AnyRecord = {
        activations: input.activations,
        channel: input.channel,
        clicks: input.clicks,
        contentAssetId: input.contentAssetId,
        contentDraftId: input.contentDraftId || null,
        currentListSubmissions: input.currentListSubmissions,
        engagementQuality: input.engagementQuality,
        ownerLeads: input.ownerLeads,
        views: input.views,
    };
    // Keep the historical fingerprint byte-for-byte compatible when publication
    // evidence is omitted so durable pre-repair claims remain replayable.
    if (input.publicationUrl !== undefined) requestFingerprint.publicationUrl = normalizeText(input.publicationUrl);
    if (input.publishedAt !== undefined) requestFingerprint.publishedAt = normalizeText(input.publishedAt);
    const requestFingerprintHash = hashValue(JSON.stringify(requestFingerprint));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const performanceRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_PERFORMANCE_SUMMARIES).doc(`content_performance_${operationHash.slice(0, 32)}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`content_performance_${operationHash}`);
    const ownerSignals = input.ownerLeads + input.currentListSubmissions + input.activations;
    const observedMetricCount = input.views + input.clicks + ownerSignals;
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const assetRef = db.collection(SIGNALDESK_COLLECTIONS.CONTENT_ASSETS).doc(input.contentAssetId);
        const draftRef = input.contentDraftId ? db.collection(SIGNALDESK_COLLECTIONS.CONTENT_DISTRIBUTION_DRAFTS).doc(input.contentDraftId) : null;
        const calendarRef = input.contentDraftId
            ? db.collection(SIGNALDESK_COLLECTIONS.CONTENT_CALENDAR_ITEMS).doc(contentCalendarItemIdFor(input.contentDraftId))
            : null;
        const pauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_content-distribution");
        const [claimSnap, pauseSnap, assetSnap, draftSnap, calendarSnap, performanceSnap] = await Promise.all([
            transaction.get(claimRef), transaction.get(pauseRef), transaction.get(assetRef),
            draftRef ? transaction.get(draftRef) : Promise.resolve(null),
            calendarRef ? transaction.get(calendarRef) : Promise.resolve(null),
            transaction.get(performanceRef),
        ]);
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) throw new Error("CONTENT_PERFORMANCE_IDEMPOTENCY_CONFLICT");
            if (!performanceSnap.exists) throw new Error("CONTENT_PERFORMANCE_REPLAY_MISSING");
            const replay = projectSignalDeskContentPerformance({
                ...toPlain(performanceSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_PERFORMANCE_SUMMARIES}DocId`]: performanceRef.id,
            });
            if (!replay) throw new Error("CONTENT_PERFORMANCE_SHAPE_INVALID");
            return replay;
        }
        if (pauseSnap.data()?.status === "active") throw new Error("Content distribution is paused");
        const rawPublicationUrl = normalizeText(input.publicationUrl);
        const rawPublishedAt = normalizeText(input.publishedAt);
        const hasPublicationUrl = Boolean(rawPublicationUrl);
        const hasPublishedAt = Boolean(rawPublishedAt);
        if (hasPublicationUrl !== hasPublishedAt || (observedMetricCount > 0 && (!hasPublicationUrl || !hasPublishedAt))) {
            throw new Error("CONTENT_PERFORMANCE_PUBLICATION_EVIDENCE_REQUIRED");
        }
        let publicationUrl: string | null = null;
        let publishedAt: FirebaseFirestore.Timestamp | null = null;
        if (hasPublicationUrl && hasPublishedAt) {
            publicationUrl = canonicalizeContentUrl(rawPublicationUrl);
            const publicationDate = new Date(rawPublishedAt);
            if (Number.isNaN(publicationDate.getTime()) || publicationDate.getTime() > Date.now() + CONTENT_PUBLICATION_FUTURE_SKEW_MS) {
                throw new Error("CONTENT_PERFORMANCE_PUBLISHED_AT_INVALID");
            }
            publishedAt = admin.firestore.Timestamp.fromDate(publicationDate);
        }
        const hasPublicationEvidence = Boolean(publicationUrl && publishedAt);
        if (hasPublicationEvidence && (!draftRef || !calendarRef)) throw new Error("CONTENT_PERFORMANCE_PUBLICATION_DRAFT_REQUIRED");
        let asset: SignalDeskContentAssetSummary;
        let draft: SignalDeskContentDistributionDraftSummary | null = null;
        let calendarItem: SignalDeskContentCalendarItemSummary | null = null;
        if (draftRef) {
            if (!draftSnap?.exists) throw new Error("Content draft not found");
            const authority = await readSignalDeskContentDraftAuthority(db, transaction, draftRef, draftSnap);
            asset = authority.asset;
            draft = authority.draft;
            if (draft.contentAssetId !== input.contentAssetId || draft.channel !== input.channel) throw new Error("CONTENT_PERFORMANCE_DRAFT_MISMATCH");
            if (draft.approvalStatus !== "approved" || !["approved", "queued", "published"].includes(draft.status)) {
                throw new Error("CONTENT_PERFORMANCE_DRAFT_NOT_APPROVED");
            }
        } else {
            ({ asset } = await readSignalDeskContentAssetAuthority(db, transaction, assetRef, assetSnap));
        }
        if (observedMetricCount > 0 && !draft) throw new Error("CONTENT_PERFORMANCE_APPROVED_DRAFT_REQUIRED");
        if (hasPublicationEvidence) {
            if (!calendarSnap?.exists || !calendarRef || !draft) throw new Error("CONTENT_PERFORMANCE_CALENDAR_REQUIRED");
            calendarItem = projectSignalDeskContentCalendarItem({
                ...toPlain(calendarSnap.data()),
                [`${SIGNALDESK_COLLECTIONS.CONTENT_CALENDAR_ITEMS}DocId`]: calendarRef.id,
            });
            if (!calendarItem) throw new Error("CONTENT_CALENDAR_SHAPE_INVALID");
            if (
                calendarItem.contentAssetId !== input.contentAssetId
                || calendarItem.contentDraftId !== draft.contentDraftId
                || calendarItem.channel !== input.channel
            ) throw new Error("CONTENT_PERFORMANCE_CALENDAR_MISMATCH");
            if (!["queued", "approved", "published"].includes(calendarItem.status)) {
                throw new Error("CONTENT_PERFORMANCE_CALENDAR_NOT_READY");
            }
            const authorityCreatedAtValues = [asset.createdAt, draft.createdAt, calendarItem.createdAt];
            if (authorityCreatedAtValues.some((value) => !value)) {
                throw new Error("CONTENT_PERFORMANCE_AUTHORITY_TIME_MISSING");
            }
            const authorityCreatedAtMillis = authorityCreatedAtValues.map((value) => new Date(value!).getTime());
            if (authorityCreatedAtMillis.some((value) => Number.isNaN(value))) {
                throw new Error("CONTENT_PERFORMANCE_AUTHORITY_TIME_INVALID");
            }
            const publicationMillis = toTimestampMillis(publishedAt);
            const latestAuthorityCreationMillis = Math.max(...authorityCreatedAtMillis);
            if (!publicationMillis || publicationMillis < latestAuthorityCreationMillis) {
                throw new Error("CONTENT_PERFORMANCE_PREDATES_AUTHORITY");
            }
            const draftPublished = draft.status === "published";
            const calendarPublished = calendarItem.status === "published";
            if (draftPublished !== calendarPublished) throw new Error("CONTENT_PERFORMANCE_PUBLICATION_STATE_INVALID");
            if (calendarPublished) {
                if (
                    asset.status !== "distributed"
                    || calendarItem.publicationUrl !== publicationUrl
                    || calendarItem.publishedAt !== toIso(publishedAt)
                ) throw new Error("CONTENT_PERFORMANCE_PUBLICATION_MISMATCH");
            }
        }
        const timestamp = now();
        const performance = {
            contractVersion: 2,
            contentPerformanceId: performanceRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            contentAssetId: input.contentAssetId,
            contentDraftId: input.contentDraftId || null,
            channel: input.channel,
            views: input.views,
            clicks: input.clicks,
            ownerLeads: input.ownerLeads,
            currentListSubmissions: input.currentListSubmissions,
            activations: input.activations,
            engagementQuality: input.engagementQuality,
            publicationUrl,
            publishedAt,
            capturedAt: timestamp,
            updatedBy: access.userId,
        };
        transaction.create(performanceRef, sanitizeForFirestore(performance));
        const publicationStateTransition = Boolean(
            hasPublicationEvidence
            && draftRef
            && calendarRef
            && draft
            && calendarItem
            && draft.status !== "published",
        );
        const rawLastPublishedAt = assetSnap.data()?.lastPublishedAt;
        const existingLastPublishedAt = toIso(rawLastPublishedAt);
        const existingLastPublicationUrl = normalizeText(assetSnap.data()?.lastPublicationUrl);
        const existingLastPublishedContentDraftId = normalizeText(assetSnap.data()?.lastPublishedContentDraftId);
        const hasCompletePublicationMarker = Boolean(
            assetSnap.data()?.hasPublishedContent === true
            && assetSnap.data()?.publicationStateVersion === 1
            && existingLastPublishedAt
            && existingLastPublicationUrl
            && existingLastPublishedContentDraftId
        );
        const incomingPublishedAtMillis = toTimestampMillis(publishedAt);
        const existingLastPublishedAtMillis = existingLastPublishedAt
            ? new Date(existingLastPublishedAt).getTime()
            : null;
        const shouldAdvancePublicationMarker = Boolean(
            hasPublicationEvidence
            && incomingPublishedAtMillis != null
            && (
                !hasCompletePublicationMarker
                || existingLastPublishedAtMillis == null
                || incomingPublishedAtMillis >= existingLastPublishedAtMillis
            )
        );
        const publicationMarkerBackfill = Boolean(
            hasPublicationEvidence
            && draft
            && calendarItem
            && draft.status === "published"
            && calendarItem.status === "published"
            && !hasCompletePublicationMarker,
        );
        if (publicationStateTransition && draftRef && calendarRef) {
            transaction.set(draftRef, sanitizeForFirestore({
                status: "published",
                updatedAt: timestamp,
                updatedBy: access.userId,
            }), { merge: true });
            transaction.set(calendarRef, sanitizeForFirestore({
                publicationUrl,
                publishedAt,
                status: "published",
                updatedAt: timestamp,
                updatedBy: access.userId,
            }), { merge: true });
            transaction.set(assetRef, sanitizeForFirestore({
                hasPublishedContent: true,
                publicationStateVersion: 1,
                status: "distributed",
                updatedAt: timestamp,
                updatedBy: access.userId,
                ...(shouldAdvancePublicationMarker ? {
                    lastPublicationUrl: publicationUrl,
                    lastPublishedAt: publishedAt,
                    lastPublishedContentDraftId: draft.contentDraftId,
                } : {}),
            }), { merge: true });
        } else if (publicationMarkerBackfill && draft) {
            transaction.set(assetRef, sanitizeForFirestore({
                hasPublishedContent: true,
                publicationStateVersion: 1,
                updatedAt: timestamp,
                updatedBy: access.userId,
                ...(shouldAdvancePublicationMarker ? {
                    lastPublicationUrl: publicationUrl,
                    lastPublishedAt: publishedAt,
                    lastPublishedContentDraftId: draft.contentDraftId,
                } : {}),
            }), { merge: true });
        }
        if (ownerSignals) {
            const demandId = `content_${input.contentAssetId}_${todayKey()}`;
            transaction.set(db.collection(SIGNALDESK_COLLECTIONS.DEMAND_SIGNAL_SUMMARIES).doc(demandId), sanitizeForFirestore({
                demandSignalId: demandId,
                pId: SIGNALDESK_PRODUCT_CODE,
                signalType: "referral",
                sourceSurface: "manual",
                targetId: null,
                targetName: asset.title,
                count: increment(ownerSignals),
                day: todayKey(),
                updatedAt: timestamp,
            }), { merge: true });
            updateControlSummary(db, transaction, { demandSignalCount: increment(ownerSignals) });
        }
        transaction.create(claimRef, sanitizeForFirestore({ actorId: access.userId, entityId: performanceRef.id, operation: "content_performance_record", pId: SIGNALDESK_PRODUCT_CODE, requestFingerprintHash, updatedAt: timestamp }));
        writeRunTimeline(db, transaction, {
            entityId: performanceRef.id,
            entityType: "content",
            label: "Content performance",
            status: hasPublicationEvidence || observedMetricCount ? "completed" : "held",
            steps: [
                { label: hasPublicationEvidence ? "Publication evidence verified" : "Publication evidence not supplied", status: hasPublicationEvidence ? "completed" : "held", at: toIso(timestamp) },
                { label: `${input.views} views`, status: input.views ? "completed" : "held", at: toIso(timestamp) },
                { label: `${input.clicks} clicks`, status: input.clicks ? "completed" : "held", at: toIso(timestamp) },
                { label: `${ownerSignals} owner outcomes`, status: ownerSignals ? "completed" : "held", at: toIso(timestamp) },
            ],
        });
        appendAudit(db, transaction, access, "content_performance_record", "contentPerformance", performanceRef.id, input.contentAssetId);
        updateDailyCost(db, transaction, 4 + (ownerSignals ? 1 : 0) + (publicationStateTransition ? 3 : publicationMarkerBackfill ? 1 : 0), 0, 0);
        const projectedPerformance = projectSignalDeskContentPerformance({
            ...toPlain(performance),
            [`${SIGNALDESK_COLLECTIONS.CONTENT_PERFORMANCE_SUMMARIES}DocId`]: performanceRef.id,
        });
        if (!projectedPerformance) throw new Error("CONTENT_PERFORMANCE_SHAPE_INVALID");
        return projectedPerformance;
    });
}

export async function runSignalDeskEnrichmentWaterfallServer(access: SignalDeskAccessContext, input: EnrichmentWaterfallRunInput) {
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("ENRICHMENT_WATERFALL_IDEMPOTENCY_KEY_REQUIRED");
    const requestFingerprintHash = hashValue(JSON.stringify({ targetId: input.targetId, waterfallId: input.waterfallId }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const resultRef = db.collection(SIGNALDESK_COLLECTIONS.ENRICHMENT_RESULTS).doc(`enrichment_${operationHash.slice(0, 32)}`);
    const vendorRunRef = db.collection(SIGNALDESK_COLLECTIONS.VENDOR_RUNS).doc(`enrichment_vendor_${operationHash.slice(0, 32)}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`enrichment_waterfall_${operationHash}`);

    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(input.targetId);
        const targetDetailRef = db.collection(SIGNALDESK_COLLECTIONS.TARGETS).doc(input.targetId);
        const waterfallRef = db.collection(SIGNALDESK_COLLECTIONS.ENRICHMENT_WATERFALLS).doc(input.waterfallId);
        const pauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_source-provider");
        const [claimSnap, resultSnap, pauseSnap, targetSnap, targetDetailSnap, waterfallSnap] = await Promise.all([
            transaction.get(claimRef), transaction.get(resultRef), transaction.get(pauseRef),
            transaction.get(targetRef), transaction.get(targetDetailRef), transaction.get(waterfallRef),
        ]);
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) throw new Error("ENRICHMENT_WATERFALL_IDEMPOTENCY_CONFLICT");
            if (!resultSnap.exists) throw new Error("ENRICHMENT_WATERFALL_REPLAY_MISSING");
            return toPlain(resultSnap.data()) as SignalDeskEnrichmentResultSummary;
        }
        if (pauseSnap.data()?.status === "active") throw new Error("SignalDesk source providers are paused");
        if (!targetSnap.exists) throw new Error("Target not found");
        if (!waterfallSnap.exists) throw new Error("Enrichment waterfall not found");
        const target = toPlain(targetSnap.data()) as SignalDeskTargetSummary;
        const targetDetail = toPlain(targetDetailSnap.data() || {}) as AnyRecord;
        const waterfall = toPlain(waterfallSnap.data()) as SignalDeskEnrichmentWaterfallSummary;
        if (waterfall.status !== "active") throw new Error("Enrichment waterfall is not active");

        const conversationRef = target.latestConversationId
            ? db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES).doc(target.latestConversationId)
            : null;
        const policyId = waterfall.sourcePolicyId || target.sourcePolicyId;
        const policyRef = policyId ? db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(policyId) : null;
        const [conversationSnap, policySnap] = await Promise.all([
            conversationRef ? transaction.get(conversationRef) : Promise.resolve(null),
            policyRef ? transaction.get(policyRef) : Promise.resolve(null),
        ]);
        if (!targetPriorGuard(target, conversationSnap?.exists ? conversationSnap.data() as AnyRecord : null).clear) {
            throw new Error("Target has prior contact or outcome");
        }
        const policy = policySnap ? readSourcePolicySnapshot(policySnap) : null;
        const contactField = waterfall.requestedField === "email" || waterfall.requestedField === "phone";
        const policyError = sourcePolicyUsabilityError(policy, { entityId: target.targetId, use: contactField ? "contact" : "evidence" });
        if (policyError) throw new Error(policyError);
        const allowedUse = resolveAllowedUse(policy);
        if (contactField && !allowedUse.contact) throw new Error("Contact use is not approved for this target");
        if (!contactField && !allowedUse.evidence) throw new Error("Evidence use is not approved for this target");

        const timestamp = now();
        const existingValue = getExistingEnrichmentValue(target, targetDetail, waterfall.requestedField);
        let readyProvider: SignalDeskProviderId | null = null;
        let readyUse: SignalDeskProviderUse | null = null;
        let providerCost = 0;
        const blockedReasons: string[] = [];
        const providers = waterfall.providerOrder.slice(0, Math.max(1, Math.min(waterfall.maxCredits, waterfall.providerOrder.length)));
        if (!existingValue) {
            providerCost = providers.length ? Math.min(numberOrZero(waterfall.maxCostUsd) / providers.length, 0.25) : 0;
            for (const provider of providers) {
                const use = providerUseForWaterfall(provider, waterfall.requestedField);
                const accountRef = db.collection(SIGNALDESK_COLLECTIONS.PROVIDER_ACCOUNTS).doc(providerAccountIdFor(provider, use));
                const budgetRef = db.collection(SIGNALDESK_COLLECTIONS.BUDGET_POLICIES).doc(budgetPolicyIdFor("provider", provider));
                const [accountSnap, budgetSnap] = await Promise.all([transaction.get(accountRef), transaction.get(budgetRef)]);
                try {
                    const spendPeriod = getSignalDeskSpendPeriod(timestamp.toMillis());
                    assertProviderBudgetState(
                        accountSnap.exists
                            ? parseSignalDeskProviderAccountDocument(accountSnap.data(), accountRef.id, spendPeriod)
                            : null,
                        budgetSnap.exists
                            ? parseSignalDeskBudgetPolicyDocument(budgetSnap.data(), budgetRef.id, spendPeriod)
                            : null,
                        { estimatedCostUsd: providerCost },
                    );
                    readyProvider = provider;
                    readyUse = use;
                    break;
                } catch {
                    blockedReasons.push(`${provider}: ${SIGNALDESK_PROVIDER_BUDGET_BLOCKED_REASON}`);
                }
            }
        }

        const selectedProvider = existingValue ? "manual" : readyProvider || providers[0] || "manual";
        const accountingPeriod = getSignalDeskSpendPeriod(timestamp.toMillis());
        const result = {
            accountingDay: readyProvider ? accountingPeriod.spendDayKey : null,
            accountingMonth: readyProvider ? accountingPeriod.spendMonthKey : null,
            enrichmentResultId: resultRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            targetId: target.targetId,
            targetName: target.displayName,
            provider: selectedProvider,
            providerUse: readyProvider ? readyUse : null,
            field: waterfall.requestedField,
            status: existingValue ? "verified" : readyProvider ? "missing" : "blocked",
            confidence: existingValue ? "high" : "low",
            valuePreview: existingValue ? previewSensitiveValue(existingValue) : null,
            sourcePolicyId: policyId || null,
            expiresAt: expiresAtForRetention(waterfall.retentionDays),
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        transaction.create(resultRef, sanitizeForFirestore(result));
        transaction.create(vendorRunRef, sanitizeForFirestore({
            accountingDay: readyProvider ? accountingPeriod.spendDayKey : null,
            accountingMonth: readyProvider ? accountingPeriod.spendMonthKey : null,
            vendorRunId: vendorRunRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            provider: selectedProvider,
            providerUse: readyProvider ? readyUse : null,
            status: existingValue ? "skipped" : readyProvider ? "ready" : "blocked",
            targetId: target.targetId,
            targetName: target.displayName,
            waterfallId: waterfall.waterfallId,
            requestedField: waterfall.requestedField,
            costEstimateUsd: readyProvider ? providerCost : 0,
            resultCount: existingValue ? 1 : 0,
            blockedReason: existingValue
                ? "Approved source data already contains this field."
                : readyProvider
                    ? `Provider budget is ready for ${readyProvider}/${readyUse}; external connector is held for owner approval.`
                    : blockedReasons.join(" | "),
            updatedAt: timestamp,
            updatedBy: access.userId,
        }));
        transaction.create(claimRef, sanitizeForFirestore({ actorId: access.userId, entityId: resultRef.id, operation: "enrichment_waterfall_run", pId: SIGNALDESK_PRODUCT_CODE, requestFingerprintHash, updatedAt: timestamp }));
        writeRunTimeline(db, transaction, {
            entityId: resultRef.id,
            entityType: "target",
            label: `${waterfall.name} enrichment`,
            status: existingValue ? "completed" : readyProvider ? "held" : "blocked",
            steps: existingValue ? [
                { label: "Prior-contact guard", status: "completed", at: toIso(timestamp) },
                { label: "Approved source data reused", status: "completed", at: toIso(timestamp) },
                { label: "No provider spend", status: "completed", at: toIso(timestamp) },
            ] : [
                { label: "Prior-contact guard", status: "completed", at: toIso(timestamp) },
                { label: "Source policy checked", status: "completed", at: toIso(timestamp) },
                { label: readyProvider ? `${readyProvider} budget ready` : "No provider budget ready", status: readyProvider ? "held" : "blocked", at: toIso(timestamp) },
            ],
        });
        appendAudit(db, transaction, access, "enrichment_waterfall_run", "enrichmentResult", resultRef.id, existingValue ? "Existing approved source data reused." : readyProvider || blockedReasons.join(" | "));
        updateDailyCost(db, transaction, existingValue ? 4 : 5, 0, 0);
        return toPlain(result) as SignalDeskEnrichmentResultSummary;
    });
}

export async function createSignalDeskApprovalPacketServer(access: SignalDeskAccessContext, input: {
    approvalId?: string;
    targetId?: string;
}) {
    if (Boolean(input.approvalId) === Boolean(input.targetId)) {
        throw new Error("Exactly one approval or target is required");
    }
    const db = requireDb();
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        let approval: SignalDeskApprovalItem | null = null;
        if (input.approvalId) {
            const approvalSnap = await transaction.get(db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE).doc(input.approvalId));
            if (!approvalSnap.exists) throw new Error("Approval not found");
            approval = toPlain(approvalSnap.data()) as SignalDeskApprovalItem;
        }
        const targetId = approval?.targetId || input.targetId;
        if (!targetId) throw new Error("Target not found");
        const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(targetId);
        const targetSnap = await transaction.get(targetRef);
        if (!targetSnap.exists) throw new Error("Target not found");
        const target = toPlain(targetSnap.data()) as SignalDeskTargetSummary;
        if (!approval && target.latestApprovalId) {
            const approvalSnap = await transaction.get(db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE).doc(target.latestApprovalId));
            approval = approvalSnap.exists ? toPlain(approvalSnap.data()) as SignalDeskApprovalItem : null;
        }
        if (approval && approval.targetId !== target.targetId) throw new Error("Approval does not belong to target");
        const draftId = approval?.draftId || target.latestDraftId || null;
        const draftRef = draftId ? db.collection(SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES).doc(draftId) : null;
        const evidenceQuery = db.collection(SIGNALDESK_COLLECTIONS.EVIDENCE_PACKET_SUMMARIES)
            .where("targetId", "==", targetId)
            .orderBy("updatedAt", "desc")
            .limit(1);
        const policyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(target.sourcePolicyId);
        const conversationRef = target.latestConversationId
            ? db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES).doc(target.latestConversationId)
            : null;
        const [draftSnap, evidenceSnap, policySnap, conversationSnap] = await Promise.all([
            draftRef ? transaction.get(draftRef) : Promise.resolve(null),
            transaction.get(evidenceQuery),
            transaction.get(policyRef),
            conversationRef ? transaction.get(conversationRef) : Promise.resolve(null),
        ]);
        const draft = draftSnap?.exists ? toPlain(draftSnap.data()) as SignalDeskDraftSummary : null;
        if (draft && (draft.targetId !== targetId || (approval && draft.approvalId !== approval.approvalId))) {
            throw new Error("Draft does not match approval target");
        }
        const evidence = evidenceSnap.docs[0]
            ? toPlain(evidenceSnap.docs[0].data()) as SignalDeskEvidencePacketSummary
            : null;
        let packetEvidence = evidence;
        if (draft?.evidencePacketId && evidence?.evidencePacketId !== draft.evidencePacketId) {
            const exactEvidenceSnap = await transaction.get(
                db.collection(SIGNALDESK_COLLECTIONS.EVIDENCE_PACKET_SUMMARIES).doc(draft.evidencePacketId),
            );
            if (!exactEvidenceSnap.exists) throw new Error("Draft evidence packet is missing");
            if (exactEvidenceSnap.data()?.targetId !== targetId) throw new Error("Draft evidence does not belong to target");
            packetEvidence = toPlain(exactEvidenceSnap.data()) as SignalDeskEvidencePacketSummary;
        }
        const ctaSnap = draft?.ctaId
            ? await transaction.get(db.collection(SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS).doc(draft.ctaId))
            : null;
        if (draft && (!normalizeText(draft.ctaId) || !normalizeText(draft.ctaFingerprintHash))) {
            throw new Error("CONTENT_CTA_LINEAGE_REQUIRED");
        }
        const ctaAuthority = ctaSnap?.exists
            ? await readSignalDeskCtaAuthority(db, transaction, {
                ctaId: draft?.ctaId,
                existingSnap: ctaSnap,
                requireActive: true,
            })
            : null;
        if (draft && (
            !ctaAuthority
            || draft.ctaId !== ctaAuthority.cta.ctaId
            || draft.ctaFingerprintHash !== ctaAuthority.ctaFingerprintHash
        )) throw new Error("CONTENT_CTA_STALE");
        const cta = ctaAuthority?.cta || null;
        const senderSnap = draft?.senderDomainId
            ? await transaction.get(db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(draft.senderDomainId))
            : null;
        const sender = projectSenderDomainDocument(senderSnap);
        if (draft) assertDraftSenderAuthority(draft, sender);
        const sourcePolicy = readSourcePolicySnapshot(policySnap);
        const priorGuard = targetPriorGuard(target, conversationSnap?.exists ? conversationSnap.data() as AnyRecord : null);
        const packetCore = await buildApprovalPacketSummary(db, {
            approval,
            cta,
            draft,
            evidence: packetEvidence,
            priorGuard,
            sender,
            sourcePolicy,
            target,
        });
        const packetRef = db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_PACKETS).doc(
            approval?.approvalPacketId || `packet_${approval?.approvalId || target.targetId}`,
        );
        const existingPacketSnap = await transaction.get(packetRef);
        const existingPacket = existingPacketSnap.exists
            ? toPlain(existingPacketSnap.data()) as SignalDeskApprovalPacketSummary
            : null;
        if (
            existingPacket
            && approvalPacketContentMatches(existingPacket, packetCore)
            && (!approval || approval.approvalPacketId === packetRef.id)
        ) {
            return existingPacket;
        }
        const timestamp = now();
        const packet = {
            approvalPacketId: packetRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            ...packetCore,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        transaction.set(packetRef, sanitizeForFirestore(packet), { merge: true });
        if (approval && approval.approvalPacketId !== packetRef.id) {
            transaction.set(db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE).doc(approval.approvalId), sanitizeForFirestore({
                approvalPacketId: packetRef.id,
                updatedAt: timestamp,
            }), { merge: true });
        }
        writeRunTimeline(db, transaction, {
            entityId: packetRef.id,
            entityType: "approval",
            label: "Approval packet",
            status: packetCore.recommendedAction === "approve" ? "ready" : "held",
            steps: [
                { label: "Target guard checked", status: packetCore.recommendedAction === "approve" ? "completed" : "held", at: toIso(timestamp) },
                { label: "Evidence and draft checked", status: packetCore.evidencePacketId && draft ? "completed" : "held", at: toIso(timestamp) },
                { label: "Sender domain checked", status: packetCore.channelReadiness === "ready" ? "completed" : "held", at: toIso(timestamp) },
            ],
        });
        appendAudit(db, transaction, access, "approval_packet_create", "approvalPacket", packetRef.id, packetCore.recommendedAction);
        updateDailyCost(db, transaction, 4, 0, 0);
        return toPlain(packet) as SignalDeskApprovalPacketSummary;
    });
}

export async function createSignalDeskSequencerHandoffServer(access: SignalDeskAccessContext, input: SequencerHandoffInput) {
    if (input.provider === "owned-email" && !FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_OWNED_EMAIL_SEQUENCER) {
        throw new Error("Owned email sequencer is disabled");
    }
    const db = requireDb();
    const handoffRef = db.collection(SIGNALDESK_COLLECTIONS.SEQUENCER_HANDOFFS)
        .doc(`sequencer_${input.provider}_${input.approvalId}`);
    try {
        return await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const [existingHandoffSnap, approvalSnap] = await Promise.all([
                transaction.get(handoffRef),
                transaction.get(db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE).doc(input.approvalId)),
            ]);
            const existingHandoff = existingHandoffSnap.exists
                ? toPlain(existingHandoffSnap.data()) as SignalDeskSequencerHandoffSummary & { requestFingerprintHash?: string }
                : null;
            if (!approvalSnap.exists) throw new Error("Approval not found");
            const approval = toPlain(approvalSnap.data()) as SignalDeskApprovalItem;
            if (existingHandoff) {
                if (
                    normalizeText(existingHandoffSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE
                    || existingHandoff.approvalId !== input.approvalId
                    || existingHandoff.provider !== input.provider
                    || (input.senderDomainId && existingHandoff.senderDomainId !== input.senderDomainId)
                    || !normalizeText(existingHandoff.requestFingerprintHash)
                ) {
                    throw new Error("Sequencer handoff request conflicts with existing truth");
                }
                if (!approval.draftId) throw new Error("Draft is required before sequencer handoff");
                const replayDraftSnap = await transaction.get(
                    db.collection(SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES).doc(approval.draftId),
                );
                if (!replayDraftSnap.exists) throw new Error("Draft is required before sequencer handoff");
                const replayDraft = toPlain(replayDraftSnap.data()) as SignalDeskDraftSummary;
                if (
                    replayDraft.approvalId !== approval.approvalId
                    || replayDraft.targetId !== approval.targetId
                    || existingHandoff.targetId !== approval.targetId
                    || existingHandoff.ctaId !== replayDraft.ctaId
                    || existingHandoff.ctaFingerprintHash !== replayDraft.ctaFingerprintHash
                    || existingHandoff.senderDomainId !== replayDraft.senderDomainId
                    || existingHandoff.senderDomainFingerprintHash !== replayDraft.senderDomainFingerprintHash
                ) throw new Error("Sequencer handoff truth is stale");
                await assertSignalDeskCtaLineage(db, transaction, replayDraft);
                const replaySenderSnap = replayDraft.senderDomainId
                    ? await transaction.get(db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(replayDraft.senderDomainId))
                    : null;
                const replaySender = projectSenderDomainDocument(replaySenderSnap);
                assertDraftSenderAuthority(replayDraft, replaySender);
                assertSenderDomainAuthorityBinding(existingHandoff, replaySender);
                return existingHandoff;
            }
            if (approval.status !== "approved" || !approval.draftId) {
                throw new Error("Approval must be approved before sequencer handoff");
            }
            const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(approval.targetId);
            const targetDetailRef = db.collection(SIGNALDESK_COLLECTIONS.TARGETS).doc(approval.targetId);
            const draftRef = db.collection(SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES).doc(approval.draftId);
            const globalPauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_global-outbound");
            const emailPauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_email");
            const campaignPauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_campaign");
            const accountRef = db.collection(SIGNALDESK_COLLECTIONS.PROVIDER_ACCOUNTS)
                .doc(providerAccountIdFor(input.provider, "sequencer"));
            const [targetSnap, targetDetailSnap, draftSnap, globalPauseSnap, emailPauseSnap, campaignPauseSnap, accountSnap] = await Promise.all([
                transaction.get(targetRef),
                transaction.get(targetDetailRef),
                transaction.get(draftRef),
                transaction.get(globalPauseRef),
                transaction.get(emailPauseRef),
                transaction.get(campaignPauseRef),
                transaction.get(accountRef),
            ]);
            if (!targetSnap.exists) throw new Error("Target not found");
            if (!draftSnap.exists) throw new Error("Draft is required before sequencer handoff");
            const target = parseSignalDeskTargetSummaryDocument(targetSnap.data(), targetSnap.id);
            if (!target.sourcePolicyId) throw new Error(SOURCE_POLICY_REVIEW_REQUIRED);
            const targetDetail = toPlain(targetDetailSnap.data() || {}) as AnyRecord;
            const draft = toPlain(draftSnap.data()) as SignalDeskDraftSummary;
            if (approval.targetId !== target.targetId
                || draft.targetId !== target.targetId
                || draft.approvalId !== approval.approvalId
                || target.latestApprovalId !== approval.approvalId
                || target.latestDraftId !== draft.draftId) {
                throw new Error("Sequencer handoff truth is stale");
            }
            if (draft.status !== "approved" || !draft.evidencePacketId) {
                throw new Error("Draft must be approved before sequencer handoff");
            }
            if (!draft.senderDomainId || (input.senderDomainId && input.senderDomainId !== draft.senderDomainId)) {
                throw new Error("SEQUENCER_SENDER_AUTHORITY_MISMATCH");
            }
            const senderSnap = await transaction.get(
                db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(draft.senderDomainId),
            );
            const sender = projectSenderDomainDocument(senderSnap);
            assertDraftSenderAuthority(draft, sender);
            const ctaAuthority = await assertSignalDeskCtaLineage(db, transaction, draft);
            const policyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(target.sourcePolicyId);
            const conversationRef = db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES)
                .doc(target.latestConversationId || `conv_${target.targetId}`);
            const [policySnap, conversationSnap] = await Promise.all([
                transaction.get(policyRef),
                transaction.get(conversationRef),
            ]);
            const policy = readSourcePolicySnapshot(policySnap);
            const policyError = sourcePolicyUsabilityError(policy, { entityId: input.approvalId, use: "sequence" });
            if (policyError) throw new Error(policyError);
            if (globalPauseSnap.data()?.status === "active" || emailPauseSnap.data()?.status === "active") {
                throw new Error("Outbound export is paused");
            }
            if (campaignPauseSnap.data()?.status === "active") throw new Error("SignalDesk campaign rail is paused");
            const priorGuard = targetPriorGuard(target, conversationSnap.exists ? conversationSnap.data() as AnyRecord : null);
            if (!priorGuard.clear) throw new Error("Target has prior contact or outcome");
            const recipient = getProviderRecipientForChannel(targetDetail, "email");
            if (!recipient) throw new Error("Channel recipient is not configured");
            if (target.contactability !== "ready") throw new Error("Target contact is not export-ready");
            const account = accountSnap.exists ? toPlain(accountSnap.data()) as SignalDeskProviderAccountSummary : null;
            const blockedReasons = [
                !account ? "Sequencer provider account is not registered." : "",
                account && (!account.ownerApproved || account.status !== "approved") ? "Sequencer provider account is not approved." : "",
                account && account.credentialState === "missing" ? "Provider account credentials are not configured." : "",
                input.provider === "owned-email" && !isEmailChannelReady() ? "Email provider is not configured." : "",
            ].filter(Boolean);
            const ready = blockedReasons.length === 0;
            const owned = input.provider === "owned-email";
            const requestFingerprintHash = hashValue(JSON.stringify({
                accountCredentialState: account?.credentialState || null,
                accountOwnerApproved: account?.ownerApproved || false,
                accountStatus: account?.status || null,
                approvalId: approval.approvalId,
                ctaFingerprintHash: ctaAuthority.ctaFingerprintHash,
                ctaId: ctaAuthority.cta.ctaId,
                draftId: draft.draftId,
                emailReady: owned ? isEmailChannelReady() : true,
                provider: input.provider,
                recipientHash: hashValue(recipient),
                senderDomainFingerprintHash: senderDomainFingerprintHashFor(sender),
                senderDomainId: sender.senderDomainId,
                targetId: target.targetId,
            }));
            const timestamp = now();
            const handoff = {
                sequencerHandoffId: handoffRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                provider: input.provider,
                status: blockedReasons.length ? "blocked" : owned ? "queued" : "ready",
                approvalId: approval.approvalId,
                ctaFingerprintHash: ctaAuthority.ctaFingerprintHash,
                ctaId: ctaAuthority.cta.ctaId,
                targetId: target.targetId,
                targetName: target.displayName,
                senderDomainFingerprintHash: senderDomainFingerprintHashFor(sender),
                senderDomainId: sender.senderDomainId,
                blockedReason: blockedReasons.join(" "),
                currentStep: owned && ready ? 1 : null,
                nextSendAt: owned && ready ? timestamp : null,
                providerCampaignId: null,
                providerLeadId: null,
                recipientPreview: previewSensitiveValue(recipient),
                requestFingerprintHash,
                stepCount: owned && ready ? 1 : null,
                updatedAt: timestamp,
                updatedBy: access.userId,
            };
            transaction.set(handoffRef, sanitizeForFirestore(handoff), { merge: true });
            if (owned && ready) {
                const stepRef = db.collection(SIGNALDESK_COLLECTIONS.SEQUENCER_STEPS).doc(sequenceStepIdFor(handoffRef.id, 1));
                transaction.set(stepRef, sanitizeForFirestore({
                    sequenceStepId: stepRef.id,
                    pId: SIGNALDESK_PRODUCT_CODE,
                    sequencerHandoffId: handoffRef.id,
                    approvalId: approval.approvalId,
                    ctaFingerprintHash: ctaAuthority.ctaFingerprintHash,
                    ctaId: ctaAuthority.cta.ctaId,
                    draftId: draft.draftId,
                    senderDomainId: sender.senderDomainId,
                    targetId: target.targetId,
                    targetName: target.displayName,
                    channel: "email",
                    stepNumber: 1,
                    status: "ready",
                    subject: draft.subject,
                    body: draft.body,
                    bodyPreview: draft.body.slice(0, 180),
                    scheduledAt: timestamp,
                    sentAt: null,
                    updatedAt: timestamp,
                    updatedBy: access.userId,
                }), { merge: true });
                transaction.set(db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE).doc(approval.approvalId), sanitizeForFirestore({
                    status: "queued",
                    updatedAt: timestamp,
                }), { merge: true });
                transaction.set(draftRef, sanitizeForFirestore({
                    status: "queued",
                    updatedAt: timestamp,
                }), { merge: true });
            }
            writeRunTimeline(db, transaction, {
                entityId: handoffRef.id,
                entityType: "approval",
                label: `${input.provider} sequencer handoff`,
                status: blockedReasons.length ? "blocked" : "ready",
                steps: [
                    { label: "Approved message loaded", status: "completed", at: toIso(timestamp) },
                    { label: "Provider account checked", status: account && account.ownerApproved && account.status === "approved" ? "completed" : "blocked", at: toIso(timestamp) },
                    { label: "Sender domain checked", status: isSenderDomainReady(sender) ? "completed" : "blocked", at: toIso(timestamp) },
                    { label: owned ? "Owned email step queued" : "External sequencer connector held", status: ready ? "completed" : "blocked", at: toIso(timestamp) },
                ],
            });
            appendAudit(db, transaction, access, "sequencer_handoff_create", "sequencerHandoff", handoffRef.id, handoff.status);
            updateDailyCost(db, transaction, owned && ready ? 7 : 3, 0, 0);
            return toPlain(handoff) as SignalDeskSequencerHandoffSummary;
        });
    } catch (error) {
        const code = error instanceof Error ? error.message : "";
        if ([SOURCE_POLICY_EXPIRED, SOURCE_POLICY_REVIEW_REQUIRED, SOURCE_POLICY_RETENTION_MISSING, SOURCE_POLICY_USE_NOT_ALLOWED].includes(code)) {
            await appendSourcePolicyBlockedAudit(db, access, null, { entityId: input.approvalId, use: "sequence" }, code);
        }
        throw error;
    }
}

export async function sendSignalDeskOwnedSequenceStepServer(access: SignalDeskAccessContext, input: OwnedSequenceStepInput) {
    if (!FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_OWNED_EMAIL_SEQUENCER) {
        throw new Error("Owned email sequencer is disabled");
    }
    if (!FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_PROVIDER_SEND) {
        throw new Error("SignalDesk provider send is disabled");
    }
    const db = requireDb();
    const handoffRef = db.collection(SIGNALDESK_COLLECTIONS.SEQUENCER_HANDOFFS).doc(input.sequencerHandoffId);
    const operationHash = hashValue(`${input.sequencerHandoffId}|owned-sequence-send-v1`).slice(0, 32);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`owned_sequence_send_${operationHash}`);
    const exportRef = db.collection(SIGNALDESK_COLLECTIONS.MESSAGE_EXPORTS).doc(`sequence_send_${operationHash}`);
    const start = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const [claimSnap, exportSnap, handoffSnap] = await Promise.all([
            transaction.get(claimRef),
            transaction.get(exportRef),
            transaction.get(handoffRef),
        ]);
        if (claimSnap.exists) {
            const claim = toPlain(claimSnap.data()) as AnyRecord;
            if (claim.status === "completed" && exportSnap.exists) {
                const historicalExport = toPlain(exportSnap.data()) as AnyRecord;
                let currentCtaAuthority = true;
                try {
                    await assertSignalDeskCtaLineage(db, transaction, historicalExport);
                } catch {
                    currentCtaAuthority = false;
                }
                const historicalSenderDomainId = normalizeText(historicalExport.senderDomainId);
                const historicalSenderSnap = historicalSenderDomainId
                    ? await transaction.get(db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(historicalSenderDomainId))
                    : null;
                const currentSenderAuthority = isSenderDomainAuthorityBindingCurrent(
                    historicalExport,
                    projectSenderDomainDocument(historicalSenderSnap),
                );
                return {
                    context: null,
                    currentCtaAuthority,
                    currentSenderAuthority,
                    replay: {
                        exportId: historicalExport.exportId,
                        providerMessageId: historicalExport.providerMessageId || null,
                    },
                };
            }
            throw new Error("OWNED_SEQUENCE_SEND_REVIEW_REQUIRED");
        }
        if (!handoffSnap.exists) throw new Error("Owned sequence not found");
        const handoff = toPlain(handoffSnap.data()) as SignalDeskSequencerHandoffSummary;
        if (handoff.provider !== "owned-email" || (handoff.status !== "queued" && handoff.status !== "ready")) {
            throw new Error("Owned sequence is not ready");
        }
        if (!handoff.approvalId || !handoff.targetId) throw new Error("Owned sequence truth is incomplete");
        const stepNumber = Math.max(1, Number(handoff.currentStep || 1));
        const stepRef = db.collection(SIGNALDESK_COLLECTIONS.SEQUENCER_STEPS)
            .doc(sequenceStepIdFor(handoff.sequencerHandoffId, stepNumber));
        const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(handoff.targetId);
        const targetDetailRef = db.collection(SIGNALDESK_COLLECTIONS.TARGETS).doc(handoff.targetId);
        const approvalRef = db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE).doc(handoff.approvalId);
        const globalPauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_global-outbound");
        const emailPauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_email");
        const campaignPauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_campaign");
        const accountRef = db.collection(SIGNALDESK_COLLECTIONS.PROVIDER_ACCOUNTS).doc(providerAccountIdFor("owned-email", "sequencer"));
        const senderRef = handoff.senderDomainId
            ? db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(handoff.senderDomainId)
            : null;
        const [stepSnap, targetSnap, targetDetailSnap, approvalSnap, globalPauseSnap, emailPauseSnap, campaignPauseSnap, accountSnap, senderSnap] = await Promise.all([
            transaction.get(stepRef),
            transaction.get(targetRef),
            transaction.get(targetDetailRef),
            transaction.get(approvalRef),
            transaction.get(globalPauseRef),
            transaction.get(emailPauseRef),
            transaction.get(campaignPauseRef),
            transaction.get(accountRef),
            senderRef ? transaction.get(senderRef) : Promise.resolve(null),
        ]);
        if (!stepSnap.exists) throw new Error("Owned sequence step not found");
        if (!targetSnap.exists) throw new Error("Target not found");
        if (!approvalSnap.exists) throw new Error("Approval not found");
        const step = toPlain(stepSnap.data()) as SignalDeskSequencerStepSummary & { body?: string | null };
        const target = toPlain(targetSnap.data()) as SignalDeskTargetSummary;
        const targetDetail = toPlain(targetDetailSnap.data() || {}) as AnyRecord;
        const approval = toPlain(approvalSnap.data()) as SignalDeskApprovalItem;
        if (!approval.draftId) throw new Error("Draft is required before send");
        const draftRef = db.collection(SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES).doc(approval.draftId);
        const policyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(target.sourcePolicyId);
        const conversationRef = db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES)
            .doc(target.latestConversationId || `conv_${target.targetId}`);
        const [draftSnap, policySnap, conversationSnap] = await Promise.all([
            transaction.get(draftRef),
            transaction.get(policyRef),
            transaction.get(conversationRef),
        ]);
        if (!draftSnap.exists) throw new Error("Draft is required before send");
        const draft = toPlain(draftSnap.data()) as SignalDeskDraftSummary;
        if (handoff.approvalId !== approval.approvalId
            || handoff.targetId !== target.targetId
            || step.sequencerHandoffId !== handoff.sequencerHandoffId
            || step.approvalId !== approval.approvalId
            || step.draftId !== draft.draftId
            || step.ctaId !== draft.ctaId
            || step.ctaFingerprintHash !== draft.ctaFingerprintHash
            || step.senderDomainId !== draft.senderDomainId
            || step.targetId !== target.targetId
            || approval.targetId !== target.targetId
            || draft.targetId !== target.targetId
            || draft.approvalId !== approval.approvalId
            || handoff.senderDomainId !== draft.senderDomainId
            || handoff.senderDomainFingerprintHash !== draft.senderDomainFingerprintHash
            || handoff.ctaId !== draft.ctaId
            || handoff.ctaFingerprintHash !== draft.ctaFingerprintHash
            || target.latestApprovalId !== approval.approvalId
            || target.latestDraftId !== draft.draftId) {
            throw new Error("Owned sequence truth is stale");
        }
        if (approval.status !== "queued" || draft.status !== "queued" || !draft.evidencePacketId) {
            throw new Error("Owned sequence approval is not queued");
        }
        if (step.status !== "ready") throw new Error("Owned sequence is not ready");
        if (!isTimestampDue((step as AnyRecord).scheduledAt)) throw new Error("Owned sequence step is not due");
        if (globalPauseSnap.data()?.status === "active" || emailPauseSnap.data()?.status === "active") {
            throw new Error("Outbound export is paused");
        }
        if (campaignPauseSnap.data()?.status === "active") throw new Error("SignalDesk campaign rail is paused");
            const policy = readSourcePolicySnapshot(policySnap);
        const policyError = sourcePolicyUsabilityError(policy, { entityId: input.sequencerHandoffId, use: "send" });
        if (policyError) throw new Error(policyError);
        const priorGuard = targetPriorGuard(target, conversationSnap.exists ? conversationSnap.data() as AnyRecord : null);
        if (!priorGuard.clear) throw new Error("Target has prior contact or outcome");
        const recipient = getProviderRecipientForChannel(targetDetail, "email");
        if (!recipient) throw new Error("Channel recipient is not configured");
        if (target.contactability !== "ready") throw new Error("Target contact is not export-ready");
        const account = accountSnap.exists ? toPlain(accountSnap.data()) as SignalDeskProviderAccountSummary : null;
        if (!account || !account.ownerApproved || account.status !== "approved" || account.credentialState === "missing") {
            throw new Error("Sequencer provider account is not approved");
        }
        const sender = projectSenderDomainDocument(senderSnap);
        assertDraftSenderAuthority(draft, sender);
        const ctaAuthority = await assertSignalDeskCtaLineage(db, transaction, draft);
        assertSignalDeskEmailSenderDomainAuthority(sender.domain);
        const body = normalizeText((step as AnyRecord).body);
        const subject = normalizeText(step.subject);
        if (!body || body !== draft.body || !subject || subject !== draft.subject) {
            throw new Error("Owned sequence truth is stale");
        }
        const requestFingerprintHash = hashValue(JSON.stringify({
            approvalId: approval.approvalId,
            body,
            ctaFingerprintHash: ctaAuthority.ctaFingerprintHash,
            ctaId: ctaAuthority.cta.ctaId,
            draftId: draft.draftId,
            recipientHash: hashValue(recipient),
            senderDomainFingerprintHash: senderDomainFingerprintHashFor(sender),
            senderDomainId: sender.senderDomainId,
            sequenceStepId: step.sequenceStepId,
            subject,
            targetId: target.targetId,
        }));
        const timestamp = now();
        const senderReservation = await reserveSignalDeskOwnedEmailSenderCapacity(db, transaction, timestamp);
        transaction.create(claimRef, sanitizeForFirestore({
            ...senderReservation,
            actorId: access.userId,
            claimId: claimRef.id,
            entityId: exportRef.id,
            operation: "owned_sequence_send",
            pId: SIGNALDESK_PRODUCT_CODE,
            ctaFingerprintHash: ctaAuthority.ctaFingerprintHash,
            ctaId: ctaAuthority.cta.ctaId,
            requestFingerprintHash,
            sequenceStepId: step.sequenceStepId,
            status: "running",
            updatedAt: timestamp,
        }));
        appendAudit(db, transaction, access, "owned_sequence_send_started", "sequencerHandoff", handoff.sequencerHandoffId, step.sequenceStepId);
        updateDailyCost(db, transaction, 4, 0);
        return {
            currentCtaAuthority: true,
            currentSenderAuthority: true,
            replay: null,
            context: { approval, body, draft, handoff, recipient, requestFingerprintHash, sender, stepRef, subject, target },
        };
    });
    if (start.replay) {
        return {
            currentAuthority: start.currentCtaAuthority && start.currentSenderAuthority,
            historicalReplay: true,
            providerMessageId: start.replay.providerMessageId || null,
            sequencerHandoffId: input.sequencerHandoffId,
            status: "sent",
        };
    }
    if (!start.context) throw new Error("OWNED_SEQUENCE_SEND_REVIEW_REQUIRED");
    const { approval, body, draft, handoff, recipient, requestFingerprintHash, sender, stepRef, subject, target } = start.context;
    let providerResult: Awaited<ReturnType<typeof sendSignalDeskProviderMessage>>;
    try {
        providerResult = await sendSignalDeskProviderMessage({
            body,
            channel: "email",
            recipient,
            senderDomain: sender.domain,
            subject,
        });
    } catch (error) {
        await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const claimSnap = await transaction.get(claimRef);
            if (claimSnap.exists && claimSnap.data()?.status === "running") {
                transaction.set(claimRef, sanitizeForFirestore({
                    failureCode: "owned_sequence_send_outcome_unresolved",
                    status: "unresolved",
                    updatedAt: now(),
                }), { merge: true });
                appendAudit(db, transaction, access, "owned_sequence_send_unresolved", "sequencerHandoff", handoff.sequencerHandoffId, "provider");
                updateDailyCost(db, transaction, 3, 0);
            }
        });
        throw new Error("OWNED_SEQUENCE_SEND_OUTCOME_UNRESOLVED", { cause: error });
    }

    try {
        await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const claimSnap = await transaction.get(claimRef);
            if (!claimSnap.exists
                || claimSnap.data()?.status !== "running"
                || claimSnap.data()?.requestFingerprintHash !== requestFingerprintHash) {
                throw new Error("OWNED_SEQUENCE_SEND_REVIEW_REQUIRED");
            }
            await assertSignalDeskCtaLineage(db, transaction, draft);
            const timestamp = now();
            writeChannelDeliveryState({
                access,
                approval,
                batch: transaction,
                channel: "email",
                db,
                draft,
                exportRef,
                providerMessageId: providerResult.providerMessageId || null,
                providerName: providerResult.provider,
                recipientPreview: maskedRecipientPreview(recipient, "email"),
                sender,
                status: "sent",
                target,
            });
            transaction.set(stepRef, sanitizeForFirestore({
                status: "sent",
                providerMessageId: providerResult.providerMessageId || null,
                sentAt: timestamp,
                updatedAt: timestamp,
                updatedBy: access.userId,
            }), { merge: true });
            transaction.set(handoffRef, sanitizeForFirestore({
                status: "sent",
                blockedReason: null,
                lastSendAt: timestamp,
                nextSendAt: null,
                updatedAt: timestamp,
                updatedBy: access.userId,
            }), { merge: true });
            writeRunTimeline(db, transaction, {
                entityId: handoff.sequencerHandoffId,
                entityType: "approval",
                label: "Owned email sequence",
                status: "completed",
                steps: [
                    { label: "Pause checks clear", status: "completed", at: toIso(timestamp) },
                    { label: "Suppression clear", status: "completed", at: toIso(timestamp) },
                    { label: "Email sent", status: "completed", at: toIso(timestamp) },
                ],
            });
            appendAudit(db, transaction, access, "owned_sequence_step_send", "sequencerHandoff", handoff.sequencerHandoffId, providerResult.providerMessageId || "sent");
            transaction.set(claimRef, sanitizeForFirestore({
                completedAt: timestamp,
                providerMessageId: providerResult.providerMessageId || null,
                providerName: providerResult.provider,
                status: "completed",
                updatedAt: timestamp,
            }), { merge: true });
            updateDailyCost(db, transaction, 9, 0, 0.01);
        });
    } catch (error) {
        const [claimSnap, exportSnap] = await Promise.all([claimRef.get(), exportRef.get()]);
        if (claimSnap.data()?.status !== "completed" || !exportSnap.exists) {
            await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
                const currentClaimSnap = await transaction.get(claimRef);
                if (currentClaimSnap.exists && currentClaimSnap.data()?.status === "running") {
                    transaction.set(claimRef, sanitizeForFirestore({
                        failureCode: "owned_sequence_send_persistence_unresolved",
                        providerMessageId: providerResult.providerMessageId || null,
                        providerName: providerResult.provider,
                        status: "unresolved",
                        updatedAt: now(),
                    }), { merge: true });
                    appendAudit(db, transaction, access, "owned_sequence_send_unresolved", "sequencerHandoff", handoff.sequencerHandoffId, "persistence");
                    updateDailyCost(db, transaction, 3, 0);
                }
            });
            throw new Error("OWNED_SEQUENCE_SEND_OUTCOME_UNRESOLVED", { cause: error });
        }
    }

    return {
        providerMessageId: providerResult.providerMessageId || null,
        sequencerHandoffId: handoff.sequencerHandoffId,
        status: "sent",
    };
}

export async function importSignalDeskTargetsServer(
    access: SignalDeskAccessContext,
    input: SignalDeskTargetImportInput,
    providerCompletion?: SourceProviderImportCompletion,
) {
    const parsedInput = SignalDeskTargetImportSchema.safeParse(input);
    if (!parsedInput.success) throw new Error("TARGET_IMPORT_INPUT_INVALID");
    const normalizedInput = parsedInput.data;
    if (!providerCompletion && normalizedInput.rows.some((row) => row.providerRecordId || row.providerRecordUrl)) {
        throw new Error("TARGET_IMPORT_PROVIDER_LINEAGE_REQUIRED");
    }
    const db = requireDb();
    const importIdempotencyHash = hashValue(`${access.userId}|${normalizedInput.idempotencyKey}`);
    const importRequestFingerprintHash = hashValue(JSON.stringify({
        rows: normalizedInput.rows,
        sourceName: normalizedInput.sourceName,
        sourcePolicyId: normalizedInput.sourcePolicyId,
    }));
    const sourceRunRef = providerCompletion
        ? db.collection(SIGNALDESK_COLLECTIONS.SOURCE_RUN_SUMMARIES).doc(providerCompletion.sourceRunId)
        : db.collection(SIGNALDESK_COLLECTIONS.SOURCE_RUN_SUMMARIES)
            .doc(`source_run_${importIdempotencyHash.slice(0, 32)}`);
    const manualImportClaimRef = providerCompletion
        ? null
        : db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS)
            .doc(`target_import_${importIdempotencyHash.slice(0, 40)}`);
    const policyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(normalizedInput.sourcePolicyId);

    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        // Phase 1: authority is read transaction-current. No write may occur until
        // every identity, target, suppression and provenance record is read.
        if (manualImportClaimRef) {
            const priorClaimSnap = await transaction.get(manualImportClaimRef);
            if (priorClaimSnap.exists) {
                const priorClaim = priorClaimSnap.data() || {};
                if (
                    priorClaim.pId !== SIGNALDESK_PRODUCT_CODE
                    || priorClaim.actorId !== access.userId
                    || priorClaim.operation !== "target_import"
                    || priorClaim.idempotencyKeyHash !== importIdempotencyHash
                    || priorClaim.requestFingerprintHash !== importRequestFingerprintHash
                    || priorClaim.sourceRunId !== sourceRunRef.id
                    || priorClaim.status !== "completed"
                ) throw new Error("TARGET_IMPORT_IDEMPOTENCY_CONFLICT");
                const targetIds = Array.isArray(priorClaim.targetIds)
                    ? priorClaim.targetIds.map((value: unknown) => normalizeText(value)).filter(Boolean)
                    : [];
                if (!targetIds.length || targetIds.length > 50 || new Set(targetIds).size !== targetIds.length) {
                    throw new Error("TARGET_IMPORT_IDEMPOTENCY_CONFLICT");
                }
                const [priorRunSnap, ...priorTargetSnaps] = await Promise.all([
                    transaction.get(sourceRunRef),
                    ...targetIds.map((targetId: string) => transaction.get(
                        db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(targetId),
                    )),
                ]);
                if (!priorRunSnap.exists || priorTargetSnaps.some((snapshot) => !snapshot.exists)) {
                    throw new Error("TARGET_IMPORT_IDEMPOTENCY_CONFLICT");
                }
                return {
                    run: parseSignalDeskSourceRunDocument(priorRunSnap.data(), priorRunSnap.id),
                    targets: priorTargetSnaps.map((snapshot) => parseSignalDeskTargetSummaryDocument(snapshot.data(), snapshot.id)),
                };
            }
        }
        const policySnap = await transaction.get(policyRef);
        const policy = readSourcePolicySnapshot(policySnap);
        const policyError = sourcePolicyUsabilityError(policy, {
            entityId: normalizedInput.sourcePolicyId,
            requiredProvider: providerCompletion?.provider,
            requiredSourceType: providerCompletion ? "provider" : undefined,
            use: "import",
        });
        if (policyError) throw new Error(policyError);
        if (!providerCompletion && (!policy || !SIGNALDESK_MANUAL_IMPORT_SOURCE_TYPES.has(policy.sourceType))) {
            throw new Error(SOURCE_POLICY_USE_NOT_ALLOWED);
        }
        if (!policy || !sourcePolicyAllowsField(policy, "displayName")) throw new Error(SOURCE_POLICY_USE_NOT_ALLOWED);
        const allowedUse = resolveAllowedUse(policy);
        const allowEmail = allowedUse.contact
            && sourcePolicyAllowsContactChannel(policy, "email")
            && sourcePolicyAllowsField(policy, "email");
        const allowPhone = allowedUse.contact
            && (sourcePolicyAllowsContactChannel(policy, "manual") || sourcePolicyAllowsContactChannel(policy, "whatsapp"))
            && sourcePolicyAllowsField(policy, "phone");
        const allowInstagram = allowedUse.contact
            && sourcePolicyAllowsContactChannel(policy, "instagram")
            && sourcePolicyAllowsField(policy, "instagram");

        type PreparedRow = {
            allowedRow: SignalDeskTargetImportRow;
            canonicalPhone: string;
            email: string;
            fingerprint: string;
            identityHash: string;
            identityVersion: "legacy-business-v1" | "provider-record-v1" | "provider-url-v1" | "provider-business-v1";
            instagram: string;
            legacyIdentityHash: string;
            occurrences: number;
            permissionEvidenceRef: string;
            phone: string;
            providerIdentityKey: string;
        };
        const preparedByIdentity = new Map<string, PreparedRow>();
        let duplicateCount = 0;
        for (const row of normalizedInput.rows) {
            const email = allowEmail ? normalizeLower(row.email) : "";
            const phone = allowPhone ? normalizeText(row.phone).replace(/[^\d+]/g, "") : "";
            const canonicalPhone = phone.replace(/\D/g, "");
            const instagram = allowInstagram ? normalizeLower(row.instagram).replace(/^@/, "") : "";
            const permissionEvidenceRef = normalizeText(row.permissionEvidenceRef);
            if ((email || phone || instagram) && !permissionEvidenceRef) {
                throw new Error("TARGET_IMPORT_PERMISSION_EVIDENCE_REQUIRED");
            }
            const allowedRow: SignalDeskTargetImportRow = {
                displayName: normalizeText(row.displayName),
                category: sourcePolicyAllowsField(policy, "category") ? row.category : undefined,
                city: sourcePolicyAllowsField(policy, "city") ? row.city : undefined,
                country: sourcePolicyAllowsField(policy, "country") ? row.country : undefined,
                currentListUrl: sourcePolicyAllowsField(policy, "currentListUrl") ? row.currentListUrl : undefined,
                website: sourcePolicyAllowsField(policy, "website") ? row.website : undefined,
                email: email || undefined,
                phone: phone || undefined,
                instagram: instagram || undefined,
                notes: sourcePolicyAllowsField(policy, "notes") ? row.notes : undefined,
                permissionEvidenceRef: permissionEvidenceRef || undefined,
                providerRecordId: sourcePolicyAllowsField(policy, "providerRecordId") ? row.providerRecordId : undefined,
                providerRecordUrl: sourcePolicyAllowsField(policy, "providerRecordUrl") ? row.providerRecordUrl : undefined,
            };
            const identity = computeTargetIdentity(allowedRow, {
                includeContact: allowedUse.contact,
                provider: policy.sourceType === "provider" ? policy.provider : null,
            });
            const identityHash = identity.identityHash;
            const fingerprint = hashValue(JSON.stringify({ allowedRow, provider: policy.provider || null }));
            const existing = preparedByIdentity.get(identityHash);
            if (existing) {
                if (existing.fingerprint !== fingerprint) throw new Error("TARGET_IMPORT_DIVERGENT_DUPLICATE");
                existing.occurrences += 1;
                duplicateCount += 1;
                continue;
            }
            preparedByIdentity.set(identityHash, {
                allowedRow,
                canonicalPhone,
                email,
                fingerprint,
                identityHash,
                identityVersion: identity.identityVersion,
                instagram,
                legacyIdentityHash: identity.legacyIdentityHash,
                occurrences: 1,
                permissionEvidenceRef,
                phone,
                providerIdentityKey: identity.providerIdentityKey,
            });
        }
        const preparedRows = Array.from(preparedByIdentity.values());
        const identityLookups = preparedRows.map((row) => {
            const primaryRef = db.collection(SIGNALDESK_COLLECTIONS.IDENTITY_INDEX).doc(row.identityHash);
            const legacyRef = row.legacyIdentityHash !== row.identityHash
                ? db.collection(SIGNALDESK_COLLECTIONS.IDENTITY_INDEX).doc(row.legacyIdentityHash)
                : null;
            return { legacyRef, primaryRef };
        });
        const identityReadRefs = Array.from(new Map(
            identityLookups.flatMap((lookup) => [lookup.primaryRef, ...(lookup.legacyRef ? [lookup.legacyRef] : [])])
                .map((ref) => [ref.path, ref]),
        ).values());
        const identityReadSnaps = await Promise.all(identityReadRefs.map((ref) => transaction.get(ref)));
        const identitySnapByPath = new Map(identityReadSnaps.map((snapshot) => [snapshot.ref.path, snapshot]));
        const parsedIdentity = (snapshot: FirebaseFirestore.DocumentSnapshot) => {
            if (!snapshot.exists) return { legacyProductMissing: false, targetId: "" };
            const rawIdentity = snapshot.data() || {};
            const identity = parseSignalDeskIdentityIndexDocument(rawIdentity, snapshot.id, { allowExactLegacyProductMissing: true });
            if (identity.legacyProductMissing) {
                const exactKeys = ["identityHash", "targetId", "updatedAt"].sort();
                if (JSON.stringify(Object.keys(rawIdentity).sort()) !== JSON.stringify(exactKeys)) {
                    throw new Error("TARGET_IDENTITY_INDEX_SHAPE_INVALID");
                }
            }
            return { legacyProductMissing: identity.legacyProductMissing, targetId: identity.targetId };
        };

        type ResolvedRow = PreparedRow & {
            candidateRef: FirebaseFirestore.DocumentReference;
            contactRefs: Array<{
                channel: "email" | "phone" | "whatsapp" | "instagram";
                permissioned: boolean;
                ref: FirebaseFirestore.DocumentReference;
                value: string;
            }>;
            detailRef: FirebaseFirestore.DocumentReference;
            fallbackCandidateRef: FirebaseFirestore.DocumentReference | null;
            fallbackDetailRef: FirebaseFirestore.DocumentReference | null;
            fallbackRetentionRef: FirebaseFirestore.DocumentReference | null;
            fallbackSummaryRef: FirebaseFirestore.DocumentReference | null;
            fallbackTargetId: string | null;
            identityRef: FirebaseFirestore.DocumentReference;
            identitySnap: FirebaseFirestore.DocumentSnapshot;
            identityProductMissing: boolean;
            legacyIdentityProductMissing: boolean;
            legacyIdentityRef: FirebaseFirestore.DocumentReference | null;
            legacyIdentitySnap: FirebaseFirestore.DocumentSnapshot | null;
            providerRecordId: string;
            providerRecordUrl: string;
            retentionRef: FirebaseFirestore.DocumentReference | null;
            suppressionRefs: FirebaseFirestore.DocumentReference[];
            summaryRef: FirebaseFirestore.DocumentReference;
            targetId: string;
            usesLegacyIdentity: boolean;
        };
        const retentionRefFor = (row: PreparedRow, targetId: string) => {
            const providerRecordId = normalizeText(row.allowedRow.providerRecordId);
            const providerRecordUrl = normalizeText(row.allowedRow.providerRecordUrl);
            return providerCompletion && (providerRecordId || providerRecordUrl)
                ? db.collection(SIGNALDESK_COLLECTIONS.PROVIDER_SOURCE_RETENTION).doc(
                    `retention_${providerCompletion.provider}_${hashValue(`${providerRecordId || providerRecordUrl}|${targetId}`).slice(0, 18)}`,
                )
                : null;
        };
        const candidateRefFor = (targetId: string) => db.collection(SIGNALDESK_COLLECTIONS.SOURCE_CANDIDATES)
            .doc(`candidate_${hashValue(`${sourceRunRef.id}|${targetId}`).slice(0, 32)}`);
        const summaryRefFor = (targetId: string) => db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(targetId);
        const detailRefFor = (targetId: string) => db.collection(SIGNALDESK_COLLECTIONS.TARGETS).doc(targetId);
        const resolvedRows: ResolvedRow[] = preparedRows.map((row, index) => {
            const lookup = identityLookups[index];
            const identitySnap = identitySnapByPath.get(lookup.primaryRef.path);
            if (!identitySnap) throw new Error("TARGET_IMPORT_TRANSACTION_READ_MISSING");
            const primaryIdentity = parsedIdentity(identitySnap);
            const legacyIdentitySnap = lookup.legacyRef
                ? identitySnapByPath.get(lookup.legacyRef.path) || null
                : null;
            if (lookup.legacyRef && !legacyIdentitySnap) throw new Error("TARGET_IMPORT_TRANSACTION_READ_MISSING");
            const legacyIdentity = legacyIdentitySnap
                ? parsedIdentity(legacyIdentitySnap)
                : { legacyProductMissing: false, targetId: "" };
            const fallbackTargetId = `tgt_${row.identityHash.slice(0, 20)}`;
            const usesLegacyIdentity = !primaryIdentity.targetId && Boolean(legacyIdentity.targetId);
            const targetId = primaryIdentity.targetId || legacyIdentity.targetId || fallbackTargetId;
            const contactRefs: ResolvedRow["contactRefs"] = [];
            if (row.email) contactRefs.push({
                channel: "email",
                permissioned: sourcePolicyAllowsContactChannel(policy, "email"),
                ref: db.collection(SIGNALDESK_COLLECTIONS.CONTACT_IDENTITIES).doc(`email_${hashValue(row.email)}`),
                value: row.email,
            });
            if (row.phone) {
                contactRefs.push({
                    channel: "phone",
                    permissioned: sourcePolicyAllowsContactChannel(policy, "manual"),
                    ref: db.collection(SIGNALDESK_COLLECTIONS.CONTACT_IDENTITIES).doc(`phone_${hashValue(row.phone)}`),
                    value: row.phone,
                });
                if (sourcePolicyAllowsContactChannel(policy, "whatsapp")) {
                    contactRefs.push({ channel: "whatsapp", permissioned: true, ref: db.collection(SIGNALDESK_COLLECTIONS.CONTACT_IDENTITIES).doc(`whatsapp_${hashValue(row.phone)}`), value: row.phone });
                }
            }
            if (row.instagram) contactRefs.push({
                channel: "instagram",
                permissioned: sourcePolicyAllowsContactChannel(policy, "instagram"),
                ref: db.collection(SIGNALDESK_COLLECTIONS.CONTACT_IDENTITIES).doc(`instagram_${hashValue(row.instagram)}`),
                value: row.instagram,
            });
            const suppressionRefs: FirebaseFirestore.DocumentReference[] = [];
            if (row.email) suppressionRefs.push(db.collection(SIGNALDESK_COLLECTIONS.SUPPRESSION_LEDGER).doc(`email_${hashValue(row.email)}`));
            // Reply/suppression writes use the retained phone value (including a
            // leading "+"). Keep the digits-only lookup as legacy compatibility,
            // but never let it replace the authoritative retained-value lookup.
            if (row.phone) suppressionRefs.push(db.collection(SIGNALDESK_COLLECTIONS.SUPPRESSION_LEDGER).doc(`phone_${hashValue(row.phone)}`));
            if (row.canonicalPhone && row.canonicalPhone !== row.phone) {
                suppressionRefs.push(db.collection(SIGNALDESK_COLLECTIONS.SUPPRESSION_LEDGER).doc(`phone_${hashValue(row.canonicalPhone)}`));
            }
            if (row.instagram) suppressionRefs.push(db.collection(SIGNALDESK_COLLECTIONS.SUPPRESSION_LEDGER).doc(`instagram_${hashValue(row.instagram)}`));
            const providerRecordId = normalizeText(row.allowedRow.providerRecordId);
            const providerRecordUrl = normalizeText(row.allowedRow.providerRecordUrl);
            const needsFallbackRefs = usesLegacyIdentity && targetId !== fallbackTargetId;
            return {
                ...row,
                candidateRef: candidateRefFor(targetId),
                contactRefs,
                detailRef: detailRefFor(targetId),
                fallbackCandidateRef: needsFallbackRefs ? candidateRefFor(fallbackTargetId) : null,
                fallbackDetailRef: needsFallbackRefs ? detailRefFor(fallbackTargetId) : null,
                fallbackRetentionRef: needsFallbackRefs ? retentionRefFor(row, fallbackTargetId) : null,
                fallbackSummaryRef: needsFallbackRefs ? summaryRefFor(fallbackTargetId) : null,
                fallbackTargetId: needsFallbackRefs ? fallbackTargetId : null,
                identityRef: lookup.primaryRef,
                identitySnap,
                identityProductMissing: primaryIdentity.legacyProductMissing,
                legacyIdentityProductMissing: legacyIdentity.legacyProductMissing,
                legacyIdentityRef: lookup.legacyRef,
                legacyIdentitySnap,
                providerRecordId,
                providerRecordUrl,
                retentionRef: retentionRefFor(row, targetId),
                suppressionRefs,
                summaryRef: summaryRefFor(targetId),
                targetId,
                usesLegacyIdentity,
            };
        });

        const baseRefs: FirebaseFirestore.DocumentReference[] = [sourceRunRef];
        const providerRunRef = providerCompletion
            ? db.collection(SIGNALDESK_COLLECTIONS.SOURCE_HEALTH_SUMMARIES).doc(providerCompletion.providerRunId)
            : null;
        const vendorRunRef = providerCompletion
            ? db.collection(SIGNALDESK_COLLECTIONS.VENDOR_RUNS).doc(`source_provider_${providerCompletion.idempotencyKeyHash.slice(0, 32)}`)
            : null;
        const claimRef = providerCompletion
            ? db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(providerCompletion.claimDocumentId)
            : null;
        if (providerRunRef) baseRefs.push(providerRunRef);
        if (vendorRunRef) baseRefs.push(vendorRunRef);
        if (claimRef) baseRefs.push(claimRef);
        const rowRefs = resolvedRows.flatMap((row) => [
            row.summaryRef,
            row.detailRef,
            row.candidateRef,
            ...row.contactRefs.map((entry) => entry.ref),
            ...row.suppressionRefs,
            ...(row.retentionRef ? [row.retentionRef] : []),
            ...(row.fallbackSummaryRef ? [row.fallbackSummaryRef] : []),
            ...(row.fallbackDetailRef ? [row.fallbackDetailRef] : []),
            ...(row.fallbackCandidateRef ? [row.fallbackCandidateRef] : []),
            ...(row.fallbackRetentionRef ? [row.fallbackRetentionRef] : []),
        ]);
        const allReadRefs = Array.from(new Map(
            [...baseRefs, ...rowRefs].map((ref) => [ref.path, ref]),
        ).values());
        const allReadSnaps = await Promise.all(allReadRefs.map((ref) => transaction.get(ref)));
        const snapByPath = new Map(allReadSnaps.map((snapshot) => [snapshot.ref.path, snapshot]));
        const snapFor = (ref: FirebaseFirestore.DocumentReference) => {
            const snapshot = snapByPath.get(ref.path);
            if (!snapshot) throw new Error("TARGET_IMPORT_TRANSACTION_READ_MISSING");
            return snapshot;
        };
        if (snapFor(sourceRunRef).exists) throw new Error("TARGET_IMPORT_SOURCE_RUN_CONFLICT");
        if (providerCompletion && providerRunRef && vendorRunRef && claimRef) {
            const claimSnap = snapFor(claimRef);
            const claim = claimSnap.exists ? claimSnap.data() || {} : {};
            if (
                !claimSnap.exists
                || claim.pId !== SIGNALDESK_PRODUCT_CODE
                || claim.claimId !== providerCompletion.claimId
                || claim.accountingDay !== providerCompletion.accountingDay
                || claim.accountingMonth !== providerCompletion.accountingMonth
                || claim.idempotencyKeyHash !== providerCompletion.idempotencyKeyHash
                || claim.requestFingerprintHash !== providerCompletion.requestFingerprintHash
                || toTimestampMillis(claim.reservedAt) !== providerCompletion.reservedAt.toMillis()
                || claim.sourceRunId !== sourceRunRef.id
                || claim.status !== "in_progress"
            ) throw new Error("SOURCE_PROVIDER_IDEMPOTENCY_CONFLICT");
            const existingProviderRun = snapFor(providerRunRef);
            if (existingProviderRun.exists && (
                existingProviderRun.data()?.pId !== SIGNALDESK_PRODUCT_CODE
                || existingProviderRun.data()?.provider !== providerCompletion.provider
            )) throw new Error("SOURCE_PROVIDER_LINEAGE_CONFLICT");
            if (snapFor(vendorRunRef).exists) throw new Error("SOURCE_PROVIDER_LINEAGE_CONFLICT");
        }

        // A stable provider identity may have an older name/location identity
        // index from the pre-v1 contract. Reuse that target only when persisted
        // provider provenance proves it is the same external record. A legacy
        // hash collision is otherwise ignored in favor of the new stable target;
        // it is never allowed to rebind the old target to a different record.
        for (const row of resolvedRows) {
            if (!row.usesLegacyIdentity) continue;
            const legacySummarySnap = snapFor(row.summaryRef);
            const legacyDetailSnap = snapFor(row.detailRef);
            if (!legacySummarySnap.exists || !legacyDetailSnap.exists) {
                throw new Error("TARGET_IMPORT_ORPHANED_IDENTITY");
            }
            parseSignalDeskTargetSummaryDocument(legacySummarySnap.data(), legacySummarySnap.id);
            const legacyDetail = parseSignalDeskTargetDetailDocument(legacyDetailSnap.data(), legacyDetailSnap.id);
            const detailProvesProviderIdentity = Boolean(
                policy.provider
                && legacyDetail.provider === policy.provider
                && (
                    (row.providerRecordId && legacyDetail.providerRecordId === row.providerRecordId)
                    || (!row.providerRecordId && row.providerRecordUrl && legacyDetail.providerRecordUrl === row.providerRecordUrl)
                )
            );
            let retentionProvesProviderIdentity = false;
            if (row.retentionRef) {
                const retentionSnap = snapFor(row.retentionRef);
                if (retentionSnap.exists) {
                    const retention = retentionSnap.data() || {};
                    if (
                        retention.pId !== SIGNALDESK_PRODUCT_CODE
                        || retention.providerSourceRetentionId !== row.retentionRef.id
                        || retention.provider !== policy.provider
                        || retention.targetId !== row.targetId
                        || normalizeText(retention.providerRecordId) !== row.providerRecordId
                        || normalizeText(retention.providerRecordUrl) !== row.providerRecordUrl
                    ) throw new Error("SOURCE_PROVIDER_RETENTION_LINEAGE_CONFLICT");
                    retentionProvesProviderIdentity = true;
                }
            }
            if (detailProvesProviderIdentity || retentionProvesProviderIdentity) continue;
            if (
                !row.fallbackTargetId
                || !row.fallbackSummaryRef
                || !row.fallbackDetailRef
                || !row.fallbackCandidateRef
            ) throw new Error("TARGET_IDENTITY_REBIND");
            row.targetId = row.fallbackTargetId;
            row.summaryRef = row.fallbackSummaryRef;
            row.detailRef = row.fallbackDetailRef;
            row.candidateRef = row.fallbackCandidateRef;
            row.retentionRef = row.fallbackRetentionRef;
            row.usesLegacyIdentity = false;
        }

        const contactTargetByPath = new Map<string, string>();
        const identityByTargetId = new Map<string, string>();
        for (const row of resolvedRows) {
            const priorIdentity = identityByTargetId.get(row.targetId);
            if (priorIdentity && priorIdentity !== row.identityHash) throw new Error("TARGET_IDENTITY_REBIND");
            identityByTargetId.set(row.targetId, row.identityHash);
            for (const contact of row.contactRefs) {
                const priorTargetId = contactTargetByPath.get(contact.ref.path);
                if (priorTargetId && priorTargetId !== row.targetId) throw new Error("CONTACT_IDENTITY_IMPORT_COLLISION");
                contactTargetByPath.set(contact.ref.path, row.targetId);
            }
        }

        const timestamp = now();
        const policyExpiryMillis = getSourcePolicyExpiryMillis(policy);
        if (!policyExpiryMillis) throw new Error(SOURCE_POLICY_REVIEW_REQUIRED);
        if (policyExpiryMillis <= timestamp.toMillis()) throw new Error(SOURCE_POLICY_EXPIRED);
        const sourceDataExpiresAt = admin.firestore.Timestamp.fromMillis(policyExpiryMillis);
        const activeSourceDataLifecycle = {
            sourceDataExpiresAt,
            sourceDataLifecycleCompletedAt: null,
            sourceDataLifecycleFailedAt: null,
            sourceDataLifecycleFailureCode: null,
            sourceDataLifecycleFailurePhase: null,
            sourceDataLifecycleKind: null,
            sourceDataLifecycleLastRetryAt: null,
            sourceDataLifecycleProgress: null,
            sourceDataLifecycleReason: null,
            sourceDataLifecycleRetryAt: null,
            sourceDataLifecycleRetryCount: 0,
            sourceDataLifecycleState: "active",
            sourceDataLifecycleToken: null,
            sourceDataObservedAt: timestamp,
            sourceDataTombstoneVersion: null,
        } as const;
        const providerRefreshDueAt = providerCompletion
            ? admin.firestore.Timestamp.fromMillis(Math.min(
                policyExpiryMillis,
                timestamp.toMillis() + (
                    (providerCompletion.provider === "google-places" ? 365 : policy.retentionDays)
                    * 24 * 60 * 60 * 1_000
                ),
            ))
            : null;
        let suppressedCount = 0;
        let blockedCount = 0;
        let newTargetCount = 0;
        let contactIdentityWriteCount = 0;
        const targets: SignalDeskTargetSummary[] = [];

        for (const row of resolvedRows) {
            const summarySnap = snapFor(row.summaryRef);
            const detailSnap = snapFor(row.detailRef);
            const hasIndex = row.identitySnap.exists || row.usesLegacyIdentity;
            if (hasIndex !== summarySnap.exists || hasIndex !== detailSnap.exists) throw new Error("TARGET_IMPORT_ORPHANED_IDENTITY");
            if (!hasIndex && (summarySnap.exists || detailSnap.exists)) throw new Error("TARGET_IMPORT_ORPHANED_TARGET");
            const existingSummary = summarySnap.exists ? parseSignalDeskTargetSummaryDocument(summarySnap.data(), summarySnap.id) : null;
            const existingDetail = detailSnap.exists ? parseSignalDeskTargetDetailDocument(detailSnap.data(), detailSnap.id) : null;
            if (existingSummary && existingDetail) {
                assertVerifiedFreshSourceObservation(
                    summarySnap.data() as AnyRecord,
                    sourceRunRef.id,
                    timestamp.toMillis(),
                    "TARGET_IMPORT_FRESH_LINEAGE_REQUIRED",
                );
                assertVerifiedFreshSourceObservation(
                    detailSnap.data() as AnyRecord,
                    sourceRunRef.id,
                    timestamp.toMillis(),
                    "TARGET_IMPORT_FRESH_LINEAGE_REQUIRED",
                );
                if (
                    existingDetail.identityHash !== row.identityHash
                    && !(row.usesLegacyIdentity && existingDetail.identityHash === row.legacyIdentityHash)
                ) throw new Error("TARGET_IDENTITY_MISMATCH");
                if (
                    existingSummary.sourcePolicyId !== normalizedInput.sourcePolicyId
                    || existingDetail.sourcePolicyId !== normalizedInput.sourcePolicyId
                    || existingSummary.sourcePolicyId !== existingDetail.sourcePolicyId
                ) throw new Error("TARGET_SOURCE_POLICY_REBIND");
                duplicateCount += 1;
            } else {
                newTargetCount += 1;
            }
            const candidateSnap = snapFor(row.candidateRef);
            if (candidateSnap.exists) {
                const candidate = parseSignalDeskSourceCandidateDocument(candidateSnap.data(), candidateSnap.id);
                if (
                    candidate.targetId !== row.targetId
                    || candidate.sourceRunId !== sourceRunRef.id
                    || candidate.sourcePolicyId !== normalizedInput.sourcePolicyId
                ) throw new Error("SOURCE_CANDIDATE_LINEAGE_CONFLICT");
                if (["pending", "failed"].includes(normalizeText(candidateSnap.data()?.sourceDataLifecycleState))) {
                    throw new Error("SOURCE_DATA_LIFECYCLE_IN_PROGRESS");
                }
                if (normalizeText(candidateSnap.data()?.sourceDataLifecycleState) === "completed") {
                    throw new Error("SOURCE_CANDIDATE_FRESH_LINEAGE_REQUIRED");
                }
            }
            const suppressed = row.suppressionRefs.some((ref) => snapFor(ref).exists);
            if (suppressed) suppressedCount += row.occurrences;
            const effectiveDetail = {
                email: row.email || (allowEmail ? normalizeLower(existingDetail?.email) : ""),
                instagram: row.instagram || (allowInstagram ? normalizeText(existingDetail?.instagram) : ""),
                phone: row.phone || (allowPhone ? normalizeText(existingDetail?.phone) : ""),
            };
            const newTarget: SignalDeskTargetSummary = {
                targetId: row.targetId,
                displayName: row.allowedRow.displayName,
                category: normalizeText(row.allowedRow.category) || null,
                city: normalizeText(row.allowedRow.city) || null,
                country: normalizeText(row.allowedRow.country) || null,
                currentListUrl: normalizeText(row.allowedRow.currentListUrl) || null,
                website: normalizeText(row.allowedRow.website) || null,
                status: suppressed ? "held" : "review",
                segment: suppressed ? "hold" : "c",
                primaryOpportunity: inferOpportunity(row.allowedRow),
                sourceConfidence: allowedUse.evidence ? "medium" : "blocked",
                contactability: allowedUse.contact ? classifyContactability(effectiveDetail) : "blocked",
                suppressionStatus: suppressed ? "suppressed" : "clear",
                nextAction: suppressed ? "hold" : "score",
                sourceRunId: sourceRunRef.id,
                sourcePolicyId: normalizedInput.sourcePolicyId,
                updatedAt: toIso(timestamp),
            };
            const target: SignalDeskTargetSummary = existingSummary ? {
                ...existingSummary,
                displayName: row.allowedRow.displayName,
                category: row.allowedRow.category === undefined ? existingSummary.category : normalizeText(row.allowedRow.category) || null,
                city: row.allowedRow.city === undefined ? existingSummary.city : normalizeText(row.allowedRow.city) || null,
                country: row.allowedRow.country === undefined ? existingSummary.country : normalizeText(row.allowedRow.country) || null,
                currentListUrl: row.allowedRow.currentListUrl === undefined ? existingSummary.currentListUrl : normalizeText(row.allowedRow.currentListUrl) || null,
                website: row.allowedRow.website === undefined ? existingSummary.website : normalizeText(row.allowedRow.website) || null,
                ...(suppressed ? {
                    contactability: "blocked" as const,
                    nextAction: "hold" as const,
                    segment: "hold" as const,
                    status: "held" as const,
                    suppressionStatus: "suppressed" as const,
                } : {}),
                sourcePolicyId: normalizedInput.sourcePolicyId,
                sourceRunId: sourceRunRef.id,
                updatedAt: toIso(timestamp),
            } : parseSignalDeskTargetSummaryDocument({
                ...newTarget,
                pId: SIGNALDESK_PRODUCT_CODE,
                updatedAt: timestamp,
            }, row.targetId);
            if (target.nextAction === "hold") blockedCount += row.occurrences;
            targets.push(target);
            const preservedTimestampFields = new Set([
                "latestManualContactAt",
                "latestOutcomeAt",
                "latestVerifiedActivationAt",
                "ownerQualifiedAt",
            ]);
            const persistedTarget = Object.fromEntries(
                Object.entries(target).filter(([key, value]) => value !== undefined && !preservedTimestampFields.has(key)),
            );

            transaction.set(row.summaryRef, sanitizeForFirestore({
                ...persistedTarget,
                ...activeSourceDataLifecycle,
                pId: SIGNALDESK_PRODUCT_CODE,
                updatedAt: timestamp,
                updatedBy: access.userId,
            }), { merge: true });
            transaction.set(row.detailRef, sanitizeForFirestore({
                ...persistedTarget,
                ...activeSourceDataLifecycle,
                pId: SIGNALDESK_PRODUCT_CODE,
                email: effectiveDetail.email || null,
                phone: effectiveDetail.phone || null,
                instagram: effectiveDetail.instagram || null,
                notes: row.allowedRow.notes === undefined ? existingDetail?.notes || null : normalizeText(row.allowedRow.notes) || null,
                permissionEvidenceRef: row.permissionEvidenceRef || existingDetail?.permissionEvidenceRef || null,
                identityHash: row.identityHash,
                identityVersion: row.identityVersion,
                legacyIdentityHash: row.legacyIdentityHash === row.identityHash ? null : row.legacyIdentityHash,
                provider: policy.sourceType === "provider" ? policy.provider : null,
                providerRecordId: row.providerRecordId || null,
                providerRecordUrl: row.providerRecordUrl || null,
                updatedAt: timestamp,
            }), { merge: true });
            if (row.identityProductMissing) {
                transaction.set(row.identityRef, sanitizeForFirestore({ pId: SIGNALDESK_PRODUCT_CODE, updatedAt: timestamp }), { merge: true });
            } else if (!row.identitySnap.exists) {
                transaction.create(row.identityRef, sanitizeForFirestore({
                    identityHash: row.identityHash,
                    identityVersion: row.identityVersion,
                    legacyIdentityHash: row.legacyIdentityHash === row.identityHash ? null : row.legacyIdentityHash,
                    pId: SIGNALDESK_PRODUCT_CODE,
                    targetId: row.targetId,
                    createdAt: timestamp,
                    updatedAt: timestamp,
                }));
            }
            if (row.usesLegacyIdentity && row.legacyIdentityProductMissing && row.legacyIdentityRef) {
                transaction.set(row.legacyIdentityRef, sanitizeForFirestore({ pId: SIGNALDESK_PRODUCT_CODE, updatedAt: timestamp }), { merge: true });
            }
            if (!candidateSnap.exists) {
                transaction.create(row.candidateRef, sanitizeForFirestore({
                    ...activeSourceDataLifecycle,
                    sourceCandidateId: row.candidateRef.id,
                    pId: SIGNALDESK_PRODUCT_CODE,
                    targetId: row.targetId,
                    sourceRunId: sourceRunRef.id,
                    sourcePolicyId: normalizedInput.sourcePolicyId,
                    displayName: target.displayName,
                    blocked: target.nextAction === "hold",
                    permissionEvidenceRef: row.permissionEvidenceRef || null,
                    createdAt: timestamp,
                }));
            }
            for (const contact of row.contactRefs) {
                const contactSnap = snapFor(contact.ref);
                let retainedPermissionState: SignalDeskContactIdentityDocument["permissionState"] | null = null;
                if (contactSnap.exists) {
                    const rawContact = contactSnap.data() || {};
                    assertVerifiedFreshSourceObservation(
                        rawContact,
                        sourceRunRef.id,
                        timestamp.toMillis(),
                        "CONTACT_IDENTITY_FRESH_LINEAGE_REQUIRED",
                    );
                    const completedTombstone = rawContact.pId === SIGNALDESK_PRODUCT_CODE
                        && rawContact.identityId === contactSnap.id
                        && rawContact.sourceDataLifecycleState === "completed"
                        && rawContact.rawValueStored === false
                        && rawContact.value == null;
                    if (completedTombstone) {
                        if (
                            rawContact.channel !== contact.channel
                            || rawContact.targetId !== row.targetId
                            || rawContact.sourcePolicyId !== normalizedInput.sourcePolicyId
                        ) throw new Error("CONTACT_IDENTITY_REBIND");
                    } else {
                        const existingContact = parseSignalDeskContactIdentityDocument(rawContact, contactSnap.id, { allowExactLegacyProductMissing: true });
                        retainedPermissionState = existingContact.permissionState;
                        if (
                            existingContact.channel !== contact.channel
                            || existingContact.value !== contact.value
                            || existingContact.targetId !== row.targetId
                            || existingContact.sourcePolicyId !== normalizedInput.sourcePolicyId
                        ) throw new Error("CONTACT_IDENTITY_REBIND");
                        if (existingContact.permissionEvidenceRef && existingContact.permissionEvidenceRef !== row.permissionEvidenceRef) {
                            throw new Error("CONTACT_IDENTITY_PERMISSION_EVIDENCE_CONFLICT");
                        }
                        if (existingContact.legacyProductMissing) {
                            const exactLegacyKeys = [
                                "channel", "expiresAt", "identityId", "observedAt", "permissionState", "sourcePolicyId",
                                "sourceRunId", "targetId", "updatedAt", "value",
                            ].sort();
                            if (JSON.stringify(Object.keys(rawContact).sort()) !== JSON.stringify(exactLegacyKeys)) {
                                throw new Error("CONTACT_IDENTITY_SHAPE_INVALID");
                            }
                        }
                    }
                }
                transaction.set(contact.ref, sanitizeForFirestore({
                    ...activeSourceDataLifecycle,
                    identityId: contact.ref.id,
                    pId: SIGNALDESK_PRODUCT_CODE,
                    targetId: row.targetId,
                    channel: contact.channel,
                    value: contact.value,
                    // Import refreshes provenance but is not an authority-upgrade
                    // operation. Existing blocked/review/expired state therefore
                    // survives a replay until the dedicated authority flow acts.
                    permissionState: retainedPermissionState || (contact.permissioned ? "permissioned" : "research_only"),
                    permissionEvidenceRef: row.permissionEvidenceRef,
                    sourcePolicyId: normalizedInput.sourcePolicyId,
                    sourceRunId: sourceRunRef.id,
                    rawValueStored: true,
                    observedAt: timestamp,
                    expiresAt: sourceDataExpiresAt,
                    updatedAt: timestamp,
                }), { merge: true });
                contactIdentityWriteCount += 1;
            }
            if (row.retentionRef && providerCompletion) {
                const retentionSnap = snapFor(row.retentionRef);
                if (retentionSnap.exists) {
                    const retention = retentionSnap.data() || {};
                    assertVerifiedFreshSourceObservation(
                        retention,
                        sourceRunRef.id,
                        timestamp.toMillis(),
                        "SOURCE_PROVIDER_RETENTION_FRESH_LINEAGE_REQUIRED",
                    );
                    const completedTombstone = retention.pId === SIGNALDESK_PRODUCT_CODE
                        && retention.providerSourceRetentionId === row.retentionRef.id
                        && retention.sourceDataLifecycleState === "completed"
                        && retention.rawPayloadStored === false;
                    const expectedProviderIdentityHash = hashValue(JSON.stringify([
                        providerCompletion.provider,
                        row.providerRecordId,
                        row.providerRecordUrl,
                    ]));
                    if (completedTombstone) {
                        if (
                            retention.provider !== providerCompletion.provider
                            || retention.targetId !== row.targetId
                            || retention.sourcePolicyId !== normalizedInput.sourcePolicyId
                            || normalizeText(retention.providerIdentityHash) !== expectedProviderIdentityHash
                        ) throw new Error("SOURCE_PROVIDER_RETENTION_LINEAGE_CONFLICT");
                    } else if (
                        retention.pId !== SIGNALDESK_PRODUCT_CODE
                        || retention.providerSourceRetentionId !== row.retentionRef.id
                        || retention.provider !== providerCompletion.provider
                        || retention.targetId !== row.targetId
                        || retention.sourcePolicyId !== normalizedInput.sourcePolicyId
                        || normalizeText(retention.providerRecordId) !== row.providerRecordId
                        || normalizeText(retention.providerRecordUrl) !== row.providerRecordUrl
                    ) throw new Error("SOURCE_PROVIDER_RETENTION_LINEAGE_CONFLICT");
                }
                transaction.set(row.retentionRef, sanitizeForFirestore({
                    providerSourceRetentionId: row.retentionRef.id,
                    pId: SIGNALDESK_PRODUCT_CODE,
                    provider: providerCompletion.provider,
                    providerRecordId: row.providerRecordId || null,
                    providerRecordUrl: row.providerRecordUrl || null,
                    providerIdentityHash: hashValue(JSON.stringify([
                        providerCompletion.provider,
                        row.providerRecordId,
                        row.providerRecordUrl,
                    ])),
                    rawPayloadStored: false,
                    sourceDataLifecycleCompletedAt: null,
                    sourceDataLifecycleFailedAt: null,
                    sourceDataLifecycleFailureCode: null,
                    sourceDataLifecycleFailurePhase: null,
                    sourceDataLifecycleKind: null,
                    sourceDataLifecycleLastRetryAt: null,
                    sourceDataLifecycleProgress: null,
                    sourceDataLifecycleReason: null,
                    sourceDataLifecycleRetryAt: null,
                    sourceDataLifecycleRetryCount: 0,
                    sourceDataLifecycleState: "active",
                    sourceDataLifecycleToken: null,
                    sourceDataObservedAt: timestamp,
                    sourceDataTombstoneVersion: null,
                    sourcePolicyId: normalizedInput.sourcePolicyId,
                    sourceRunId: sourceRunRef.id,
                    targetId: row.targetId,
                    targetName: target.displayName,
                    status: "active",
                    lastRefreshedAt: timestamp,
                    refreshDueAt: providerRefreshDueAt,
                    retentionExpiresAt: sourceDataExpiresAt,
                    updatedAt: timestamp,
                    updatedBy: access.userId,
                }), { merge: true });
            }
        }

        const importedCount = normalizedInput.rows.length;
        const runData = {
            sourceRunId: sourceRunRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            sourcePolicyId: normalizedInput.sourcePolicyId,
            sourceName: normalizedInput.sourceName,
            status: blockedCount === importedCount ? "blocked" : blockedCount ? "partial" : "completed",
            importedCount,
            duplicateCount,
            suppressedCount,
            blockedCount,
            createdAt: timestamp,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        transaction.create(sourceRunRef, sanitizeForFirestore(runData));
        if (manualImportClaimRef) {
            transaction.create(manualImportClaimRef, sanitizeForFirestore({
                actorId: access.userId,
                completedAt: timestamp,
                idempotencyKeyHash: importIdempotencyHash,
                operation: "target_import",
                pId: SIGNALDESK_PRODUCT_CODE,
                requestFingerprintHash: importRequestFingerprintHash,
                sourceRunId: sourceRunRef.id,
                status: "completed",
                targetIds: targets.map((target) => target.targetId),
                updatedAt: timestamp,
            }));
        }
        if (providerCompletion && providerRunRef && vendorRunRef && claimRef) {
            transaction.set(providerRunRef, sanitizeForFirestore({
                providerRunId: providerRunRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                provider: providerCompletion.provider,
                query: providerCompletion.query,
                resultCount: importedCount,
                sourcePolicyId: normalizedInput.sourcePolicyId,
                status: "completed",
                updatedAt: timestamp,
                updatedBy: access.userId,
            }), { merge: true });
            transaction.create(vendorRunRef, sanitizeForFirestore({
                accountingDay: providerCompletion.accountingDay,
                accountingMonth: providerCompletion.accountingMonth,
                vendorRunId: vendorRunRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                provider: providerCompletion.provider,
                providerUse: "discovery",
                reservedAt: providerCompletion.reservedAt,
                status: "completed",
                requestedField: "business",
                costEstimateUsd: providerCompletion.estimatedCostUsd,
                resultCount: importedCount,
                sourcePolicyId: normalizedInput.sourcePolicyId,
                query: providerCompletion.query,
                updatedAt: timestamp,
                updatedBy: access.userId,
            }));
            transaction.set(claimRef, sanitizeForFirestore({
                claimId: providerCompletion.claimId,
                completedAt: timestamp,
                entityId: providerRunRef.id,
                idempotencyKeyHash: providerCompletion.idempotencyKeyHash,
                requestFingerprintHash: providerCompletion.requestFingerprintHash,
                resultCount: importedCount,
                sourceRunId: sourceRunRef.id,
                status: "completed",
                targetIds: targets.map((target) => target.targetId),
                updatedAt: timestamp,
            }), { merge: true });
            writeRunTimeline(db, transaction, {
                entityId: providerRunRef.id,
                entityType: "provider",
                label: `${providerCompletion.provider} source run`,
                status: "completed",
                steps: [
                    { label: "Source policy approved", status: "completed", at: toIso(timestamp) },
                    { label: "Provider budget checked", status: "completed", at: toIso(timestamp) },
                    { label: `${importedCount} candidates imported`, status: "completed", at: toIso(timestamp) },
                ],
            });
            appendAudit(db, transaction, access, "source_provider_run", "sourceProvider", providerRunRef.id, `${providerCompletion.provider}: ${importedCount} results`);
            updateDailyCost(db, transaction, 7, 0, 0);
        }
        appendAudit(db, transaction, access, "target_import", "sourceRun", sourceRunRef.id, `${importedCount} targets`);
        updateControlSummary(db, transaction, {
            sourceStatus: blockedCount ? "warning" : "healthy",
            targetCount: increment(newTargetCount),
        });
        updateDailyCost(db, transaction, importedCount * 5 + contactIdentityWriteCount + 4, 0);
        return { run: parseSignalDeskSourceRunDocument(runData, sourceRunRef.id), targets };
    });
}

export async function runSignalDeskSourceProviderServer(access: SignalDeskAccessContext, input: SourceProviderRunInput) {
    if (!FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_SOURCE_PROVIDERS) {
        throw new Error("SignalDesk source providers are disabled");
    }
    if (input.provider === "fhrs-fhis" && !FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_FHRS_FHIS_SOURCE_PROVIDER) {
        throw new Error("FHRS/FHIS source provider is disabled");
    }
    if (input.provider === "apify" && !FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_APIFY_SOURCE_BROKER) {
        throw new Error("Apify source broker is disabled");
    }
    const db = requireDb();
    await requireNoActiveKillSwitch(db, "source-provider", "SignalDesk source providers are paused");
    const policy = await readSourcePolicy(db, input.sourcePolicyId);
    await assertSourcePolicyUsable(db, access, policy, {
        entityId: input.sourcePolicyId,
        requiredProvider: input.provider,
        requiredSourceType: "provider",
        use: "provider-run",
    });
    if (policy.sourceType !== "provider") throw new Error("Provider source policy is required");
    const allowedUse = resolveAllowedUse(policy);
    if (!allowedUse.evidence) throw new Error("Evidence use is not approved for this source policy");
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) {
        throw new Error("Source provider idempotency key is invalid");
    }
    const estimatedCostUsd = estimateSourceProviderCostUsd(input.provider, input.maxResults);
    const idempotencyKeyHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const requestFingerprintHash = hashValue(JSON.stringify({
        actorId: access.userId,
        city: normalizeText(input.city),
        country: normalizeText(input.country),
        maxResults: input.maxResults,
        provider: input.provider,
        query: normalizeText(input.query),
        sourcePolicyId: input.sourcePolicyId,
    }));
    const claimId = randomBytes(16).toString("hex");
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`source_provider_${idempotencyKeyHash}`);
    const providerRunRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_HEALTH_SUMMARIES).doc(`provider_${input.provider}`);
    const sourceRunRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_RUN_SUMMARIES).doc(`source_provider_${idempotencyKeyHash.slice(0, 32)}`);
    const accountRef = db.collection(SIGNALDESK_COLLECTIONS.PROVIDER_ACCOUNTS).doc(providerAccountIdFor(input.provider, "discovery"));
    const budgetRef = db.collection(SIGNALDESK_COLLECTIONS.BUDGET_POLICIES).doc(budgetPolicyIdFor("provider", input.provider));
    const reservedAt = now();
    const reservationPeriod = getSignalDeskSpendPeriod(reservedAt.toMillis());
    const costRef = db.collection(SIGNALDESK_COLLECTIONS.COST_DAILY_SUMMARIES).doc(reservationPeriod.spendDayKey);
    const prior = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const [claimSnap, accountSnap, budgetSnap, costSnap] = await Promise.all([
            transaction.get(claimRef), transaction.get(accountRef), transaction.get(budgetRef), transaction.get(costRef),
        ]);
        if (claimSnap.exists) {
            const claim = claimSnap.data() || {};
            if (claim.pId !== SIGNALDESK_PRODUCT_CODE
                || claim.actorId !== access.userId
                || claim.idempotencyKeyHash !== idempotencyKeyHash
                || claim.requestFingerprintHash !== requestFingerprintHash) {
                throw new Error("Source provider idempotency conflict");
            }
            if (claim.status === "completed" && normalizeText(claim.sourceRunId)) return toPlain(claim) as AnyRecord;
            if (claim.status === "unresolved") throw new Error("Source provider outcome requires review");
            throw new Error("Source provider request is already in progress");
        }
        const account = accountSnap.exists
            ? parseSignalDeskProviderAccountDocument(accountSnap.data(), accountRef.id, reservationPeriod)
            : null;
        const providerBudget = budgetSnap.exists
            ? parseSignalDeskBudgetPolicyDocument(budgetSnap.data(), budgetRef.id, reservationPeriod)
            : null;
        assertProviderBudgetState(account, providerBudget, { estimatedCostUsd });
        if (estimatedCostUsd) {
            if (!account) throw new Error("SIGNALDESK_PROVIDER_ACCOUNT_MISSING");
            transaction.set(accountRef, sanitizeForFirestore(buildSignalDeskSpendMutation({
                amountUsd: estimatedCostUsd,
                authority: account,
                currentPeriod: reservationPeriod,
                updatedAt: reservedAt,
            })), { merge: true });
            if (providerBudget) {
                transaction.set(budgetRef, sanitizeForFirestore(buildSignalDeskSpendMutation({
                    amountUsd: estimatedCostUsd,
                    authority: providerBudget,
                    currentPeriod: reservationPeriod,
                    updatedAt: reservedAt,
                })), { merge: true });
            }
        }
        transaction.set(costRef, sanitizeForFirestore(buildSignalDeskDailyCostMutation({
            current: costSnap.exists ? costSnap.data() : null,
            day: reservationPeriod.spendDayKey,
            delta: {
                firestoreWriteEstimate: providerBudget ? 4 : 3,
                providerCostEstimate: estimatedCostUsd,
            },
            updatedAt: reservedAt,
        })));
        transaction.create(claimRef, sanitizeForFirestore({
            accountingDay: reservationPeriod.spendDayKey,
            accountingMonth: reservationPeriod.spendMonthKey,
            actorId: access.userId, claimId, entityId: providerRunRef.id, entityType: "sourceProviderRun",
            idempotencyKeyHash, pId: SIGNALDESK_PRODUCT_CODE, requestFingerprintHash,
            reservedAt,
            reservedCostUsd: estimatedCostUsd, sourceRunId: sourceRunRef.id, status: "in_progress", updatedAt: reservedAt,
        }));
        return null;
    });
    if (prior) {
        const targetIds = (Array.isArray(prior.targetIds) ? prior.targetIds : []).slice(0, 30).map((value: unknown) => normalizeText(String(value || ""))).filter(Boolean);
        const [sourceRunSnap, ...targetSnaps] = await Promise.all([
            db.collection(SIGNALDESK_COLLECTIONS.SOURCE_RUN_SUMMARIES).doc(normalizeText(prior.sourceRunId)).get(),
            ...targetIds.map((targetId: string) => db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(targetId).get()),
        ]);
        if (!sourceRunSnap.exists || targetSnaps.some((snap: any) => !snap.exists)) throw new Error("Source provider idempotency conflict");
        return {
            provider: input.provider,
            providerRunId: normalizeText(prior.entityId),
            resultCount: nonNegativeInteger(prior.resultCount),
            run: parseSignalDeskSourceRunDocument(sourceRunSnap.data(), sourceRunSnap.id),
            targets: targetSnaps.map((snap: any) => parseSignalDeskTargetSummaryDocument(snap.data(), snap.id)),
        };
    }

    let rows: Awaited<ReturnType<typeof runSignalDeskSourceProvider>>;
    try {
        rows = await runSignalDeskSourceProvider({
            city: input.city,
            country: input.country,
            maxResults: input.maxResults,
            provider: input.provider,
            query: input.query,
        });
        if (!rows.length) throw new Error("No provider results returned");
    } catch (error) {
        await markSignalDeskClaimUnresolved({
            access,
            action: "source_provider_outcome_unresolved",
            claimId,
            claimRef,
            db,
            entityId: providerRunRef.id,
            entityType: "sourceProvider",
            failureCode: "source_provider_outcome_unresolved",
            requestFingerprintHash,
        });
        throw error;
    }

    let imported: Awaited<ReturnType<typeof importSignalDeskTargetsServer>>;
    try {
        imported = await importSignalDeskTargetsServer(access, {
            idempotencyKey: `provider:${idempotencyKeyHash}`,
            rows,
            sourceName: `${input.provider}: ${input.query}`,
            sourcePolicyId: input.sourcePolicyId,
        }, {
            accountingDay: reservationPeriod.spendDayKey,
            accountingMonth: reservationPeriod.spendMonthKey,
            claimDocumentId: claimRef.id,
            claimId,
            estimatedCostUsd,
            idempotencyKeyHash,
            provider: input.provider,
            providerRunId: providerRunRef.id,
            query: input.query,
            requestFingerprintHash,
            reservedAt,
            sourceRunId: sourceRunRef.id,
        });
    } catch (error) {
        const committedClaimSnap = await claimRef.get();
        const committedClaim = committedClaimSnap.exists ? committedClaimSnap.data() as AnyRecord : null;
        if (
            committedClaim?.status !== "completed"
            || committedClaim?.claimId !== claimId
            || committedClaim?.requestFingerprintHash !== requestFingerprintHash
        ) {
            await markSignalDeskClaimUnresolved({
                access,
                action: "source_provider_import_unresolved",
                claimId,
                claimRef,
                db,
                entityId: providerRunRef.id,
                entityType: "sourceProvider",
                failureCode: "source_provider_import_unresolved",
                requestFingerprintHash,
            });
            throw error;
        }
        const replayed = await db.collection(SIGNALDESK_COLLECTIONS.SOURCE_RUN_SUMMARIES).doc(sourceRunRef.id).get();
        const targetIds = (Array.isArray(committedClaim.targetIds) ? committedClaim.targetIds : []).slice(0, 30).map((value: unknown) => normalizeText(String(value || ""))).filter(Boolean);
        const replayTargets = await Promise.all(targetIds.map((targetId: string) => db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(targetId).get()));
        if (!replayed.exists || replayTargets.some((snap: any) => !snap.exists)) throw error;
        imported = {
            run: parseSignalDeskSourceRunDocument(replayed.data(), replayed.id),
            targets: replayTargets.map((snap: any) => parseSignalDeskTargetSummaryDocument(snap.data(), snap.id)),
        };
    }

    return { ...imported, providerRunId: providerRunRef.id, provider: input.provider, resultCount: rows.length };
}

export async function createSignalDeskResearchAgentRunServer(access: SignalDeskAccessContext, input: ResearchAgentInput) {
    if (!FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_RESEARCH_AGENT_TABLE) {
        throw new Error("SignalDesk research agent table is disabled");
    }
    const db = requireDb();
    await requireNoActiveKillSwitch(db, "source-provider", "SignalDesk source providers are paused");

    const location = inferResearchLocation(input.prompt, input.city, input.country);
    const category = inferResearchCategory(input.prompt);
    const provider = selectResearchProvider({
        country: location.country || input.country,
        provider: input.provider,
        researchType: input.researchType,
    });
    const requestedSourcePolicyId = normalizeText(input.sourcePolicyId);
    if (requestedSourcePolicyId.length < 3 || requestedSourcePolicyId.length > 180) {
        throw new Error("RESEARCH_SOURCE_POLICY_ID_REQUIRED");
    }
    const sourcePolicy = await readUsableResearchSourcePolicy(db, access, provider, requestedSourcePolicyId);
    const sourcePolicyId = sourcePolicy.sourcePolicyId;
    const maxResults = Math.max(1, Math.min(30, Math.floor(numberOrZero(input.maxResults) || 10)));
    const normalizedQuery = buildResearchProviderQuery({
        category,
        city: location.city,
        prompt: input.prompt,
        researchType: input.researchType,
    });
    const normalizedIdempotencyKey = normalizeText(input.idempotencyKey);
    if (normalizedIdempotencyKey.length < 8 || normalizedIdempotencyKey.length > 180) {
        throw new Error("RESEARCH_IDEMPOTENCY_KEY_INVALID");
    }
    const idempotencyKeyHash = hashValue(normalizedIdempotencyKey);
    const requestFingerprintHash = hashValue(JSON.stringify({
        actorId: access.userId,
        city: normalizeLower(location.city),
        country: normalizeLower(location.country),
        marketPodId: input.marketPodId || null,
        maxResults,
        normalizedQuery,
        provider,
        researchType: input.researchType,
        sourcePolicyId,
    }));
    const idempotencyRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`research_${idempotencyKeyHash}`);
    const timestamp = now();
    const researchRunId = researchRunIdFor(access.userId, idempotencyKeyHash);
    const marketPodId = input.marketPodId || `market_pod_${hashValue([
        normalizeLower(location.city),
        normalizeLower(location.country),
        normalizeLower(category),
        input.researchType,
    ].join("|")).slice(0, 18)}`;
    const runRef = db.collection(SIGNALDESK_COLLECTIONS.RESEARCH_RUNS).doc(researchRunId);
    const queuedRun: SignalDeskResearchRunSummary = {
        category,
        city: location.city,
        country: location.country,
        createdAt: toIso(timestamp),
        enrichmentColumns: researchColumnsFor(input.researchType),
        failCount: 0,
        idempotencyKeyHash,
        marketPodId,
        maxResults,
        normalizedQuery,
        passCount: 0,
        prompt: normalizeText(input.prompt),
        provider,
        providerRunIds: [],
        researchRunId,
        researchType: input.researchType,
        sourcePolicyId,
        sourceTransparency: [`provider:${provider}`, `source-policy:${sourcePolicyId}`],
        status: "running",
        tableRowCount: 0,
        unsureCount: 0,
        updatedAt: toIso(timestamp),
    };
    let priorRunId: string | null;
    try {
        priorRunId = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const priorKey = await transaction.get(idempotencyRef);
            if (priorKey?.exists) {
                const prior = priorKey.data() || {};
                if (
                    prior.pId !== SIGNALDESK_PRODUCT_CODE
                    || prior.entityType !== "researchRun"
                    || prior.idempotencyKeyHash !== idempotencyKeyHash
                    || prior.actorId !== access.userId
                    || prior.requestFingerprintHash !== requestFingerprintHash
                ) {
                    throw new Error("RESEARCH_IDEMPOTENCY_CONFLICT");
                }
                const entityId = normalizeText(prior.entityId);
                if (!entityId) throw new Error("RESEARCH_IDEMPOTENCY_CONFLICT");
                return entityId;
            }
            transaction.set(runRef, sanitizeForFirestore({
                ...queuedRun,
                pId: SIGNALDESK_PRODUCT_CODE,
                createdAt: timestamp,
                createdBy: access.userId,
                updatedAt: timestamp,
            }));
            if (idempotencyRef) {
                transaction.set(idempotencyRef, sanitizeForFirestore({
                    actorId: access.userId,
                    entityId: researchRunId,
                    entityType: "researchRun",
                    idempotencyKeyHash,
                    pId: SIGNALDESK_PRODUCT_CODE,
                    requestFingerprintHash,
                    updatedAt: timestamp,
                }));
            }
            writeRunTimeline(db, transaction, {
                entityId: researchRunId,
                entityType: "research",
                label: "Research agent table",
                status: "ready",
                steps: [
                    { label: "Prompt normalized", status: "completed", at: toIso(timestamp) },
                    { label: "Provider run started", status: "ready", at: toIso(timestamp) },
                ],
            });
            return null;
        });
    } catch (claimError) {
        if (claimError instanceof Error && claimError.message === "RESEARCH_IDEMPOTENCY_CONFLICT") {
            throw claimError;
        }
        const [claimSnap, runSnap] = await Promise.all([idempotencyRef.get(), runRef.get()]);
        const claim = claimSnap.exists ? claimSnap.data() || {} : {};
        const committedClaim = runSnap.exists
            && claim.pId === SIGNALDESK_PRODUCT_CODE
            && claim.entityType === "researchRun"
            && claim.entityId === researchRunId
            && claim.idempotencyKeyHash === idempotencyKeyHash
            && claim.actorId === access.userId
            && claim.requestFingerprintHash === requestFingerprintHash;
        if (!committedClaim) throw claimError;
        priorRunId = null;
    }
    if (priorRunId) {
        const [priorRunSnap, priorRows] = await Promise.all([
            db.collection(SIGNALDESK_COLLECTIONS.RESEARCH_RUNS).doc(priorRunId).get(),
            db.collection(SIGNALDESK_COLLECTIONS.RESEARCH_TABLE_ROWS).where("researchRunId", "==", priorRunId).limit(100).get(),
        ]);
        if (!priorRunSnap.exists) throw new Error("RESEARCH_IDEMPOTENCY_CONFLICT");
        return {
            duplicate: true,
            rows: priorRows.docs.map((doc: any) => parseSignalDeskResearchRowDocument(doc.data(), doc.id)),
            run: parseSignalDeskResearchRunDocument(priorRunSnap.data(), priorRunSnap.id),
        };
    }

    try {
        const providerResult = await runSignalDeskSourceProviderServer(access, {
            city: location.city || undefined,
            country: location.country || undefined,
            idempotencyKey: `research-provider:${researchRunId}`,
            maxResults,
            provider,
            query: normalizedQuery,
            sourcePolicyId,
        });
        const retentionSnap = await db.collection(SIGNALDESK_COLLECTIONS.PROVIDER_SOURCE_RETENTION)
            .where("sourceRunId", "==", providerResult.run.sourceRunId)
            .limit(100)
            .get();
        const retentionByTarget = new Map<string, SignalDeskProviderSourceRetentionSummary>();
        retentionSnap.docs.forEach((doc: any) => {
            const record = toPlain(doc.data()) as SignalDeskProviderSourceRetentionSummary;
            if (record.targetId) retentionByTarget.set(record.targetId, record);
        });
        const rows = providerResult.targets.map((target: SignalDeskTargetSummary, index: number) => buildResearchRow({
            index,
            provider,
            providerRecordUrl: retentionByTarget.get(target.targetId)?.providerRecordUrl || null,
            researchRunId,
            researchType: input.researchType,
            sourcePolicy,
            sourcePolicyId,
            sourceRunId: providerResult.run.sourceRunId,
            target,
        }));
        const passCount = rows.filter((row) => row.fitDecision === "pass").length;
        const failCount = rows.filter((row) => row.fitDecision === "fail").length;
        const unsureCount = rows.filter((row) => row.fitDecision === "unsure").length;
        const completedAt = now();
        const researchPodRef = db.collection(SIGNALDESK_COLLECTIONS.MARKET_PODS).doc(marketPodId);
        await db.runTransaction(async (completeBatch: FirebaseFirestore.Transaction) => {
            const existingResearchPodSnap = await completeBatch.get(researchPodRef);
            if (existingResearchPodSnap.exists && normalizeText(existingResearchPodSnap.data()?.pId) !== SIGNALDESK_PRODUCT_CODE) {
                throw new Error("MARKET_POD_PRODUCT_MISMATCH");
            }
            if (existingResearchPodSnap.data()?.dependentHoldReconciliationPending === true) {
                throw new Error("CONTENT_AUTHORITY_RECONCILIATION_PENDING");
            }
            const existingResearchPod = existingResearchPodSnap.exists
                ? projectSignalDeskMarketPod({
                    ...toPlain(existingResearchPodSnap.data()),
                    [`${SIGNALDESK_COLLECTIONS.MARKET_PODS}DocId`]: researchPodRef.id,
                })
                : null;
            if (existingResearchPodSnap.exists && !existingResearchPod) throw new Error("MARKET_POD_SHAPE_INVALID");
            const founderControlledScope = Boolean(existingResearchPod?.reviewedBy || existingResearchPod?.approvedBy);
            const researchPodStatus: SignalDeskMarketPodSummary["status"] = existingResearchPod?.reviewDecision === "approved" && existingResearchPod.approvedBy
                ? "active"
                : existingResearchPod?.reviewDecision === "rejected"
                    ? "blocked"
                    : "hold";
            rows.forEach((row) => {
                completeBatch.set(db.collection(SIGNALDESK_COLLECTIONS.RESEARCH_TABLE_ROWS).doc(row.researchRowId), sanitizeForFirestore({
                    ...row,
                    pId: SIGNALDESK_PRODUCT_CODE,
                    updatedAt: completedAt,
                }), { merge: true });
            });
            completeBatch.set(runRef, sanitizeForFirestore({
            failCount,
            passCount,
            providerRunIds: [providerResult.providerRunId, providerResult.run.sourceRunId].filter(Boolean),
            sourceTransparency: [
                `provider:${provider}`,
                `source-policy:${sourcePolicyId}`,
                `source-run:${providerResult.run.sourceRunId}`,
                `provider-run:${providerResult.providerRunId}`,
            ],
            status: "completed",
            tableRowCount: rows.length,
            unsureCount,
            updatedAt: completedAt,
            }), { merge: true });
            completeBatch.set(researchPodRef, sanitizeForFirestore({
            approvedAt: existingResearchPod?.approvedAt || null,
            approvedBy: existingResearchPod?.approvedBy || null,
            category: founderControlledScope ? existingResearchPod?.category || null : category,
            city: founderControlledScope ? existingResearchPod?.city || null : location.city || null,
            confidence: passCount > 0 ? "medium" : "low",
            country: founderControlledScope ? existingResearchPod?.country || null : location.country || null,
            marketPodId,
            monthlyBudgetUsd: founderControlledScope ? numberOrZero(existingResearchPod?.monthlyBudgetUsd) : 0,
            name: founderControlledScope
                ? existingResearchPod?.name
                : [category, location.city || location.country || "market"].filter(Boolean).join(" / "),
            offerAngle: founderControlledScope
                ? existingResearchPod?.offerAngle
                : input.researchType === "partner-list"
                ? "Find trusted operators who can introduce MenuList to restaurant owners."
                : "Find businesses with weak current-list presence and route them to a reviewable MenuList preview.",
            recommendation: passCount > 0 ? "activate" : "hold",
            recommendationReason: `${passCount} pass, ${unsureCount} unsure, ${failCount} fail from research run ${researchRunId}.`,
            pId: SIGNALDESK_PRODUCT_CODE,
            reviewDecision: existingResearchPod?.reviewDecision || null,
            reviewedAt: existingResearchPod?.reviewedAt || null,
            reviewedBy: existingResearchPod?.reviewedBy || null,
            reviewReason: existingResearchPod?.reviewReason || null,
            status: researchPodStatus,
            successMetric: founderControlledScope
                ? existingResearchPod?.successMetric
                : "Activated businesses with current lists live on two customer surfaces within seven days.",
            updatedAt: completedAt,
            }), { merge: true });
            writeRunTimeline(db, completeBatch, {
            entityId: researchRunId,
            entityType: "research",
            label: "Research agent table",
            status: "completed",
            steps: [
                { label: "Prompt normalized", status: "completed", at: toIso(timestamp) },
                { label: `${provider} provider run completed`, status: "completed", at: toIso(completedAt) },
                { label: `${rows.length} rows scored pass/fail/unsure`, status: "completed", at: toIso(completedAt) },
            ],
            });
            appendAudit(db, completeBatch, access, "research_agent_run", "researchRun", researchRunId, `${normalizedQuery}: ${rows.length} rows`);
            updateDailyCost(db, completeBatch, rows.length * 3 + 8);
        });

        return {
            duplicate: false,
            rows: rows.map((row) => ({ ...row, updatedAt: toIso(completedAt) })) as SignalDeskResearchTableRowSummary[],
            run: {
                ...queuedRun,
                failCount,
                passCount,
                providerRunIds: [providerResult.providerRunId, providerResult.run.sourceRunId].filter(Boolean),
                sourceTransparency: [
                    `provider:${provider}`,
                    `source-policy:${sourcePolicyId}`,
                    `source-run:${providerResult.run.sourceRunId}`,
                    `provider-run:${providerResult.providerRunId}`,
                ],
                status: "completed",
                tableRowCount: rows.length,
                unsureCount,
                updatedAt: toIso(completedAt),
            } as SignalDeskResearchRunSummary,
        };
    } catch (error) {
        const [committedRunSnap, committedRowsSnap] = await Promise.all([
            runRef.get(),
            db.collection(SIGNALDESK_COLLECTIONS.RESEARCH_TABLE_ROWS).where("researchRunId", "==", researchRunId).limit(100).get(),
        ]);
        const committedRun = committedRunSnap.exists
            ? parseSignalDeskResearchRunDocument(committedRunSnap.data(), committedRunSnap.id)
            : null;
        if (committedRun?.status === "completed") {
            return {
                duplicate: false,
                rows: committedRowsSnap.docs.map((doc: any) => parseSignalDeskResearchRowDocument(doc.data(), doc.id)),
                run: committedRun,
            };
        }
        const blockedAt = now();
        const blockBatch = db.batch();
        blockBatch.set(runRef, sanitizeForFirestore({
            status: "blocked",
            updatedAt: blockedAt,
        }), { merge: true });
        writeRunTimeline(db, blockBatch, {
            entityId: researchRunId,
            entityType: "research",
            label: "Research agent table",
            status: "blocked",
            steps: [
                { label: "Prompt normalized", status: "completed", at: toIso(timestamp) },
                { label: "Provider run blocked", status: "blocked", at: toIso(blockedAt) },
            ],
        });
        appendAudit(db, blockBatch, access, "research_agent_blocked", "researchRun", researchRunId, SIGNALDESK_RESEARCH_AGENT_BLOCKED_REASON);
        await blockBatch.commit();
        throw error;
    }
}

const signalDeskEvidenceIdentityHashFor = (
    targetAuthority: SignalDeskOutcomeTargetAuthority,
    allowedUse: string[],
) => hashValue(JSON.stringify({
    allowedUse,
    category: normalizeText(targetAuthority.target.category),
    city: normalizeText(targetAuthority.target.city),
    currentListUrl: normalizeText(targetAuthority.target.currentListUrl),
    diagnosticVersion: "current-menu-presence-v1",
    displayName: normalizeText(targetAuthority.target.displayName),
    primaryOpportunity: targetAuthority.target.primaryOpportunity,
    sourceConfidence: targetAuthority.target.sourceConfidence,
    sourceDataObservedAt: targetAuthority.sourceDataObservedAt,
    sourcePolicyId: targetAuthority.sourcePolicyId,
    sourceRunId: targetAuthority.sourceRunId,
    targetId: targetAuthority.target.targetId,
    website: normalizeText(targetAuthority.target.website),
})).slice(0, 32);

const signalDeskAiAssistAuthorityFingerprintFor = (input: {
    evidence: SignalDeskEvidencePacketSummary | null;
    policy: SignalDeskSourcePolicy | null;
    targetAuthority: SignalDeskOutcomeTargetAuthority;
}) => hashValue(JSON.stringify({
    evidence: input.evidence ? {
        allowedUse: input.evidence.allowedUse,
        confidence: input.evidence.confidence,
        currentMenuPresence: input.evidence.currentMenuPresence || null,
        evidencePacketId: input.evidence.evidencePacketId,
        rejectedFacts: input.evidence.rejectedFacts,
        summary: input.evidence.summary,
        updatedAt: input.evidence.updatedAt || null,
    } : null,
    policy: input.policy ? {
        allowedContactChannels: input.policy.allowedContactChannels,
        allowedUse: input.policy.allowedUse,
        expiresAt: input.policy.expiresAt || null,
        sourcePolicyId: input.policy.sourcePolicyId,
        status: input.policy.status,
        updatedAt: input.policy.updatedAt || null,
    } : null,
    sourceDataExpiresAt: input.targetAuthority.sourceDataExpiresAt,
    sourceDataObservedAt: input.targetAuthority.sourceDataObservedAt,
    sourceRunId: input.targetAuthority.sourceRunId,
    target: input.targetAuthority.target,
}));

const assertSignalDeskAiAssistTargetActive = (target: SignalDeskTargetSummary) => {
    if (
        target.status === "held"
        || target.status === "rejected"
        || target.nextAction === "hold"
        || target.suppressionStatus !== "clear"
    ) throw new Error("AI_ASSIST_TARGET_NOT_ACTIVE");
};

export async function scoreSignalDeskTargetServer(access: SignalDeskAccessContext, targetId: string) {
    const db = requireDb();
    await requireNoActiveKillSwitch(db, "ai-worker", "SignalDesk AI workers are paused");
    const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(targetId);
    try {
        return await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const targetSnap = await transaction.get(targetRef);
            if (!targetSnap.exists) throw new Error("Target not found");
            const targetAuthority = parseSignalDeskOutcomeTargetAuthority(targetSnap.data(), targetSnap.id);
            const target = targetAuthority.target;
            if (!target.sourcePolicyId) throw new Error(SOURCE_POLICY_REVIEW_REQUIRED);
            const sourcePolicyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(target.sourcePolicyId);
            const sourcePolicySnap = await transaction.get(sourcePolicyRef);
            const sourcePolicy = readSourcePolicySnapshot(sourcePolicySnap);
            const policyError = sourcePolicyUsabilityError(sourcePolicy, { entityId: targetId, use: "evidence" });
            if (policyError) throw new Error(policyError);

            const scoreIdentityHash = hashValue(JSON.stringify({
                category: normalizeLower(target.category),
                contactability: target.contactability,
                currentListUrl: normalizeText(target.currentListUrl),
                sourcePolicyId: target.sourcePolicyId,
                suppressionStatus: target.suppressionStatus,
                sourceDataObservedAt: targetAuthority.sourceDataObservedAt,
                targetId,
                sourceRunId: targetAuthority.sourceRunId,
                workerVersion: "rules-v1",
            })).slice(0, 32);
            const scoreRef = db.collection(SIGNALDESK_COLLECTIONS.AI_WORKER_RUNS).doc(`target_score_${scoreIdentityHash}`);
            const snapshotRef = db.collection(SIGNALDESK_COLLECTIONS.DECISION_SNAPSHOTS).doc(`target_score_snapshot_${scoreIdentityHash}`);
            const ledgerRef = db.collection(SIGNALDESK_COLLECTIONS.AI_OPERATION_LEDGER).doc(`target_score_ledger_${scoreIdentityHash}`);
            const priorScoreSnap = await transaction.get(scoreRef);
            if (priorScoreSnap.exists) {
                return parseSignalDeskTargetScoreDocument(priorScoreSnap.data(), priorScoreSnap.id, targetId);
            }

            const score = computeScore(target);
            const timestamp = now();
            const scoreData = { ...score, scoreId: scoreRef.id, createdAt: timestamp };
            transaction.create(scoreRef, sanitizeForFirestore({
                ...scoreData,
                ...activeSourceDataLifecycleForTargetAuthority(targetAuthority),
                aiDetailExpiresAt: admin.firestore.Timestamp.fromMillis(timestamp.toMillis() + SIGNALDESK_AI_DETAIL_RETENTION_MS),
                aiDetailLifecycleState: "active",
                aiDetailLifecycleUpdatedAt: timestamp,
                aiDetailRetentionAnchorAt: timestamp,
                pId: SIGNALDESK_PRODUCT_CODE,
                sourceDataPayloadStored: true,
                workerType: "target_score",
                workerVersion: "rules-v1",
                targetId,
                costEstimate: 0,
            }));
            transaction.create(snapshotRef, sanitizeForFirestore({
                ...activeSourceDataLifecycleForTargetAuthority(targetAuthority),
                snapshotId: snapshotRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                targetId,
                decisionType: "score",
                confidence: score.segment === "a" ? "high" : score.segment === "b" ? "medium" : "low",
                rejectedFacts: [],
                evidenceRefs: [],
                ruleVersion: "rules-v1",
                decidedBy: "system",
                createdAt: timestamp,
            }));
            transaction.create(ledgerRef, sanitizeForFirestore({
                operationId: ledgerRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                targetId,
                operation: "target_score",
                costEstimate: 0,
                createdAt: timestamp,
            }));
            transaction.set(targetRef, sanitizeForFirestore({
                fitScore: score.fitScore,
                currentListGapScore: score.currentListGapScore,
                contactabilityScore: score.contactabilityScore,
                riskScore: score.riskScore,
                segment: score.segment,
                nextAction: score.nextAction,
                status: score.nextAction === "hold" ? "held" : "ready",
                updatedAt: timestamp,
            }), { merge: true });
            appendAudit(db, transaction, access, "target_score", "target", targetId, `segment:${score.segment}:next:${score.nextAction}`);
            updateDailyCost(db, transaction, 5, 0);
            return toPlain(scoreData) as SignalDeskAiScoreSummary;
        });
    } catch (error) {
        const code = error instanceof Error ? error.message : "";
        if ([SOURCE_POLICY_EXPIRED, SOURCE_POLICY_REVIEW_REQUIRED, SOURCE_POLICY_RETENTION_MISSING, SOURCE_POLICY_USE_NOT_ALLOWED].includes(code)) {
            await appendSourcePolicyBlockedAudit(db, access, null, { entityId: targetId, use: "evidence" }, code);
        }
        throw error;
    }
}

export async function runSignalDeskAiAssistServer(access: SignalDeskAccessContext, input: AiAssistInput) {
    if (!FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_AI_PROVIDER_CALLS) {
        throw new Error("SignalDesk AI provider calls are disabled");
    }
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) {
        throw new Error("AI assist idempotency key is invalid");
    }
    const db = requireDb();
    await requireNoActiveKillSwitch(db, "ai-worker", "SignalDesk AI workers are paused");
    const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(input.targetId);
    const targetSnap = await targetRef.get();
    if (!targetSnap.exists) throw new Error("Target not found");

    const targetAuthority = parseSignalDeskOutcomeTargetAuthority(targetSnap.data(), targetSnap.id);
    const target = targetAuthority.target;
    assertSignalDeskAiAssistTargetActive(target);
    const sourcePolicyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(targetAuthority.sourcePolicyId);
    const sourcePolicySnap = await sourcePolicyRef.get();
    const sourcePolicy = readSourcePolicySnapshot(sourcePolicySnap);
    const sourcePolicyUse = input.task === "draft" ? "draft" : "evidence";
    const policyError = sourcePolicyUsabilityError(sourcePolicy, {
        entityId: input.targetId,
        use: sourcePolicyUse,
    });
    if (policyError) throw new Error(policyError);
    assertOutcomeTargetPolicyLineage(targetAuthority, sourcePolicy);
    const policyAllowedUse = resolveAllowedUse(sourcePolicy);
    const evidenceAllowedUse = ["evidence"];
    if (policyAllowedUse.personalization) evidenceAllowedUse.push("draft-personalization");
    const expectedEvidenceId = `evidence_${signalDeskEvidenceIdentityHashFor(targetAuthority, evidenceAllowedUse)}`;
    const evidenceQuerySnap = await db.collection(SIGNALDESK_COLLECTIONS.EVIDENCE_PACKET_SUMMARIES)
        .where("targetId", "==", input.targetId)
        .orderBy("updatedAt", "desc")
        .limit(1)
        .get();
    const evidenceDocument = evidenceQuerySnap.docs[0] || null;
    const evidence = evidenceDocument
        ? toPlain(evidenceDocument.data()) as SignalDeskEvidencePacketSummary
        : null;
    if (evidenceDocument && evidence) {
        parseSignalDeskOutcomeEvidenceAuthority(
            evidenceDocument.data(),
            evidenceDocument.id,
            targetAuthority,
        );
        if (evidence.evidencePacketId !== expectedEvidenceId) throw new Error("AI_ASSIST_EVIDENCE_LINEAGE_STALE");
    }
    const sourceAuthorityFingerprintHash = signalDeskAiAssistAuthorityFingerprintFor({
        evidence,
        policy: sourcePolicy,
        targetAuthority,
    });
    const { estimatedCostUsd: generationCostUsd, route } = await resolveModelRouteForTask(db, input.task);
    const criticRouteResult = input.multiPass
        ? await resolveModelRouteForTask(db, "quality-critic")
        : null;
    const reservedCriticCostUsd = criticRouteResult?.estimatedCostUsd || 0;
    const reservedEscalationCostUsd = input.multiPass && route.escalationProvider === "gemini" && route.escalationModel
        ? Math.min(numberOrZero(route.maxCostUsd), 0.05)
        : 0;
    const reservedCostUsd = generationCostUsd + reservedCriticCostUsd + reservedEscalationCostUsd;
    const instruction = normalizeText(input.instruction);
    const idempotencyKeyHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const requestFingerprintHash = hashValue(JSON.stringify({
        actorId: access.userId,
        instruction,
        multiPass: Boolean(input.multiPass),
        sourceAuthorityFingerprintHash,
        sourceDataObservedAt: targetAuthority.sourceDataObservedAt,
        sourceRunId: targetAuthority.sourceRunId,
        targetId: input.targetId,
        task: input.task,
        volumeRunId: input.volumeRunId || null,
    }));
    const claimId = randomBytes(16).toString("hex");
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`ai_assist_${idempotencyKeyHash}`);
    const runRef = db.collection(SIGNALDESK_COLLECTIONS.AI_WORKER_RUNS).doc(`ai_assist_${idempotencyKeyHash.slice(0, 32)}`);
    const evidenceRef = db.collection(SIGNALDESK_COLLECTIONS.EVIDENCE_PACKET_SUMMARIES).doc(expectedEvidenceId);
    const volumeLockRef = db.collection(SIGNALDESK_COLLECTIONS.AI_WORKER_RUNS).doc(SIGNALDESK_AI_VOLUME_LOCK_ID);
    const providerAccountRef = db.collection(SIGNALDESK_COLLECTIONS.PROVIDER_ACCOUNTS).doc(providerAccountIdFor(route.defaultProvider, "ai"));
    const providerBudgetRef = db.collection(SIGNALDESK_COLLECTIONS.BUDGET_POLICIES).doc(budgetPolicyIdFor("provider", route.defaultProvider));
    let priorClaim: { runId: string; status: "completed" | "in_progress" } | null = null;
    try {
        priorClaim = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const [
                claimSnap,
                volumeLockSnap,
                providerAccountSnap,
                providerBudgetSnap,
                currentTargetSnap,
                currentPolicySnap,
                currentEvidenceSnap,
            ] = await Promise.all([
                transaction.get(claimRef),
                transaction.get(volumeLockRef),
                transaction.get(providerAccountRef),
                transaction.get(providerBudgetRef),
                transaction.get(targetRef),
                transaction.get(sourcePolicyRef),
                transaction.get(evidenceRef),
            ]);
            if (claimSnap.exists) {
                const claim = claimSnap.data() || {};
                if (
                    claim.pId !== SIGNALDESK_PRODUCT_CODE
                    || claim.actorId !== access.userId
                    || claim.idempotencyKeyHash !== idempotencyKeyHash
                    || claim.requestFingerprintHash !== requestFingerprintHash
                ) {
                    throw new Error("AI assist idempotency conflict");
                }
                if (claim.status === "completed" && normalizeText(claim.entityId)) {
                    return { runId: normalizeText(claim.entityId), status: "completed" as const };
                }
                if (claim.status === "unresolved") throw new Error("AI assist outcome requires review");
                if (claim.status === "in_progress" && normalizeText(claim.entityId) === runRef.id) {
                    return { runId: runRef.id, status: "in_progress" as const };
                }
                throw new Error("AI assist request is already in progress");
            }
            if (!currentTargetSnap.exists) throw new Error("Target not found");
            const currentTargetAuthority = parseSignalDeskOutcomeTargetAuthority(
                currentTargetSnap.data(),
                currentTargetSnap.id,
            );
            assertSignalDeskAiAssistTargetActive(currentTargetAuthority.target);
            const currentPolicy = readSourcePolicySnapshot(currentPolicySnap);
            const currentPolicyError = sourcePolicyUsabilityError(currentPolicy, {
                entityId: input.targetId,
                use: sourcePolicyUse,
            });
            if (currentPolicyError) throw new Error(currentPolicyError);
            assertOutcomeTargetPolicyLineage(currentTargetAuthority, currentPolicy);
            if (
                currentTargetAuthority.sourceRunId !== targetAuthority.sourceRunId
                || currentTargetAuthority.sourceDataObservedAt !== targetAuthority.sourceDataObservedAt
                || currentTargetAuthority.sourceDataExpiresAt !== targetAuthority.sourceDataExpiresAt
            ) throw new Error("AI_ASSIST_SOURCE_AUTHORITY_CHANGED");
            if (evidence) {
                if (!currentEvidenceSnap?.exists) throw new Error("AI_ASSIST_EVIDENCE_LINEAGE_STALE");
                parseSignalDeskOutcomeEvidenceAuthority(
                    currentEvidenceSnap.data(),
                    currentEvidenceSnap.id,
                    currentTargetAuthority,
                );
                const currentExpectedEvidenceId = `evidence_${signalDeskEvidenceIdentityHashFor(currentTargetAuthority, evidenceAllowedUse)}`;
                if (currentEvidenceSnap.id !== currentExpectedEvidenceId) throw new Error("AI_ASSIST_EVIDENCE_LINEAGE_STALE");
            } else if (currentEvidenceSnap?.exists) {
                throw new Error("AI_ASSIST_SOURCE_AUTHORITY_CHANGED");
            }
            const volumeLock = volumeLockSnap.exists ? volumeLockSnap.data() as AnyRecord : null;
            const activeVolumeLock = volumeLock?.status === "running" && toTimestampMillis(volumeLock.expiresAt) > Date.now();
            const claimReservedAt = now();
            const claimSpendPeriod = getSignalDeskSpendPeriod(claimReservedAt.toMillis());
            if (input.volumeRunId) {
                if (!activeVolumeLock || volumeLock?.activeVolumeRunId !== input.volumeRunId) {
                    throw new Error("AI volume claim is not active");
                }
            } else {
                if (activeVolumeLock) throw new Error("SignalDesk AI volume run is already active");
            }
            const providerAccount = providerAccountSnap.exists
                ? parseSignalDeskProviderAccountDocument(providerAccountSnap.data(), providerAccountRef.id, claimSpendPeriod)
                : null;
            const providerBudget = providerBudgetSnap.exists
                ? parseSignalDeskBudgetPolicyDocument(providerBudgetSnap.data(), providerBudgetRef.id, claimSpendPeriod)
                : null;
            assertProviderBudgetState(providerAccount, providerBudget, {
                enforcePerRunBudget: !input.volumeRunId,
                estimatedCostUsd: reservedCostUsd,
            });
            if (!providerAccount) throw new Error("SIGNALDESK_PROVIDER_ACCOUNT_MISSING");
            transaction.set(providerAccountRef, sanitizeForFirestore(buildSignalDeskSpendMutation({
                amountUsd: reservedCostUsd,
                authority: providerAccount,
                currentPeriod: claimSpendPeriod,
                updatedAt: claimReservedAt,
            })), { merge: true });
            if (providerBudget) {
                transaction.set(providerBudgetRef, sanitizeForFirestore(buildSignalDeskSpendMutation({
                    amountUsd: reservedCostUsd,
                    authority: providerBudget,
                    currentPeriod: claimSpendPeriod,
                    updatedAt: claimReservedAt,
                })), { merge: true });
            }
            transaction.create(claimRef, sanitizeForFirestore({
                accountingDay: claimSpendPeriod.spendDayKey,
                accountingMonth: claimSpendPeriod.spendMonthKey,
                actorId: access.userId,
                claimId,
                entityId: runRef.id,
                entityType: "aiWorkerRun",
                idempotencyKeyHash,
                pId: SIGNALDESK_PRODUCT_CODE,
                requestFingerprintHash,
                reservedAt: claimReservedAt,
                reservedBudgetPolicy: Boolean(providerBudget),
                reservedCostUsd,
                status: "in_progress",
                updatedAt: claimReservedAt,
            }));
            return null;
        });
    } catch (error) {
        const committedClaimSnap = await claimRef.get();
        const committedClaim = committedClaimSnap.exists ? committedClaimSnap.data() as AnyRecord : null;
        const exactCommittedClaim = Boolean(
            committedClaim?.pId === SIGNALDESK_PRODUCT_CODE
            && committedClaim?.actorId === access.userId
            && committedClaim?.idempotencyKeyHash === idempotencyKeyHash
            && committedClaim?.requestFingerprintHash === requestFingerprintHash
            && normalizeText(committedClaim?.entityId) === runRef.id
        );
        if (!exactCommittedClaim) throw error;
        if (committedClaim?.status === "completed") {
            priorClaim = { runId: runRef.id, status: "completed" };
        } else if (committedClaim?.status === "in_progress") {
            priorClaim = { runId: runRef.id, status: "in_progress" };
        } else if (committedClaim?.status === "unresolved") {
            throw new Error("AI assist outcome requires review");
        } else {
            throw error;
        }
    }
    if (priorClaim) {
        let priorRunSnap: FirebaseFirestore.DocumentSnapshot | null = null;
        if (priorClaim.status === "in_progress") {
            // Exact concurrent retries wait on durable truth without repeating paid provider work.
            for (const waitMs of [50, 100, 250, 500, 1000, 2000, 4000, 8000, 12000, 16000]) {
                await new Promise<void>((resolve) => setTimeout(resolve, waitMs));
                const retryClaimSnap = await claimRef.get();
                const retryClaim = retryClaimSnap.exists ? retryClaimSnap.data() as AnyRecord : null;
                if (
                    retryClaim?.pId !== SIGNALDESK_PRODUCT_CODE
                    || retryClaim?.actorId !== access.userId
                    || retryClaim?.idempotencyKeyHash !== idempotencyKeyHash
                    || retryClaim?.requestFingerprintHash !== requestFingerprintHash
                    || normalizeText(retryClaim?.entityId) !== priorClaim.runId
                ) {
                    throw new Error("AI assist idempotency conflict");
                }
                if (retryClaim.status === "unresolved") throw new Error("AI assist outcome requires review");
                if (retryClaim.status === "completed") {
                    priorRunSnap = await runRef.get();
                    if (priorRunSnap.exists) break;
                } else if (retryClaim.status !== "in_progress") {
                    throw new Error("AI assist idempotency conflict");
                }
            }
            if (!priorRunSnap?.exists) throw new Error("AI assist request is already in progress");
        } else {
            priorRunSnap = await db.collection(SIGNALDESK_COLLECTIONS.AI_WORKER_RUNS).doc(priorClaim.runId).get();
        }
        if (!priorRunSnap.exists) throw new Error("AI assist idempotency conflict");
        const priorRaw = priorRunSnap.data() as AnyRecord;
        const priorAiDetailExpiresAt = toTimestampMillis(priorRaw.aiDetailExpiresAt);
        if (
            priorRaw.aiDetailLifecycleState !== "active"
            || priorAiDetailExpiresAt === null
            || priorAiDetailExpiresAt <= Date.now()
            || !priorRaw.output
            || typeof priorRaw.output !== "object"
            || Array.isArray(priorRaw.output)
        ) throw new Error("AI_ASSIST_DETAIL_EXPIRED");
        const prior = toPlain(priorRaw) as SignalDeskAiWorkerRunSummary & AnyRecord;
        return {
            aiRunId: prior.aiRunId,
            confidence: prior.confidence,
            critic: null,
            escalated: Boolean(prior.escalated),
            escalationBlocked: Boolean(prior.escalationBlocked),
            estimatedCostUsd: numberOrZero(prior.costEstimate),
            model: prior.model,
            modelCallCount: nonNegativeInteger(prior.modelCallCount),
            output: prior.output as Awaited<ReturnType<typeof runSignalDeskAiAssist>>["output"],
            promptVersion: normalizeText(prior.promptVersion || prior.workerVersion),
            task: input.task,
        };
    }
    const markAiAssistUnresolved = () => markSignalDeskClaimUnresolved({
        access,
        action: "ai_assist_outcome_unresolved",
        claimId,
        claimRef,
        db,
        entityId: runRef.id,
        entityType: "aiWorkerRun",
        failureCode: "ai_assist_outcome_unresolved",
        requestFingerprintHash,
    });
    let initialAssist: Awaited<ReturnType<typeof runSignalDeskAiAssist>>;
    try {
        initialAssist = await runSignalDeskAiAssist({
            evidence,
            instruction: instruction || undefined,
            model: route.defaultModel,
            target,
            task: input.task,
        });
    } catch (error) {
        await markAiAssistUnresolved();
        throw error;
    }
    let finalAssist = initialAssist;
    let finalOutput = initialAssist.output;
    let finalConfidence = initialAssist.confidence;
    let critic: Awaited<ReturnType<typeof runSignalDeskAiCritic>> | null = null;
    let criticCostUsd = 0;
    let escalated = false;
    let escalationBlocked = false;
    let escalationCostUsd = 0;
    let modelCallCount = 1;

    if (input.multiPass) {
        try {
            if (!criticRouteResult) throw new Error("SignalDesk AI critic route is not active");
            criticCostUsd = criticRouteResult.estimatedCostUsd;
            critic = await runSignalDeskAiCritic({
                candidate: initialAssist.output,
                evidence,
                model: criticRouteResult.route.defaultModel,
                target,
                task: input.task,
            });
            modelCallCount += 1;
            if (critic.verdict === "revise" && critic.revisedOutput) finalOutput = critic.revisedOutput;

            const initialRejectedFacts = Array.isArray(initialAssist.output.rejectedFacts) ? initialAssist.output.rejectedFacts : [];
            const needsEscalation = initialAssist.confidence === "low"
                || critic.confidence === "low"
                || critic.verdict !== "pass"
                || initialRejectedFacts.length > 0
                || critic.rejectedFacts.length > 0;
            if (needsEscalation) {
                if (route.escalationProvider === "gemini" && route.escalationModel) {
                    escalationCostUsd = Math.min(numberOrZero(route.maxCostUsd), 0.05);
                    finalAssist = await runSignalDeskAiAssist({
                        evidence,
                        instruction: [
                            input.instruction || "",
                            "Produce a corrected final result after an independent critic review. Do not claim external-action approval.",
                            `Critic verdict: ${critic.verdict}.`,
                            `Critic reasons: ${critic.reasons.join("; ")}.`,
                        ].filter(Boolean).join(" "),
                        model: route.escalationModel,
                        priorOutput: critic.revisedOutput || initialAssist.output,
                        target,
                        task: input.task,
                    });
                    finalOutput = finalAssist.output;
                    finalConfidence = critic.verdict === "hold"
                        ? "low"
                        : finalAssist.confidence === "low"
                            ? "low"
                            : "medium";
                    escalated = true;
                    modelCallCount += 1;
                } else {
                    escalationBlocked = true;
                    finalConfidence = "low";
                }
            } else if (critic.confidence === "medium" || initialAssist.confidence === "medium") {
                finalConfidence = "medium";
            } else {
                finalConfidence = "high";
            }
        } catch (error) {
            await markAiAssistUnresolved();
            throw error;
        }
    }

    const estimatedCostUsd = generationCostUsd + criticCostUsd + escalationCostUsd;

    const timestamp = now();
    const snapshotRef = db.collection(SIGNALDESK_COLLECTIONS.DECISION_SNAPSHOTS).doc();
    const ledgerRef = db.collection(SIGNALDESK_COLLECTIONS.AI_OPERATION_LEDGER).doc();
    const evalRef = db.collection(SIGNALDESK_COLLECTIONS.MODEL_EVALS).doc(`model_eval_${route.task}_${route.defaultProvider}`);
    const rejectedFacts = Array.from(new Set([
        ...(Array.isArray(finalOutput.rejectedFacts) ? finalOutput.rejectedFacts : []),
        ...(critic?.rejectedFacts || []),
    ].filter((fact): fact is string => typeof fact === "string" && Boolean(fact.trim())).map((fact) => fact.trim()))).slice(0, 16);
    if (rejectedFacts.length) finalConfidence = "low";
    let finalizationResult: { persisted: boolean } | null = null;
    try {
        finalizationResult = await db.runTransaction(async (transaction: any) => {
        const [
            evalSnap,
            claimSnap,
            providerAccountSnap,
            providerBudgetSnap,
            currentTargetSnap,
            currentPolicySnap,
            currentEvidenceSnap,
        ] = await Promise.all([
            transaction.get(evalRef),
            transaction.get(claimRef),
            transaction.get(providerAccountRef),
            transaction.get(providerBudgetRef),
            transaction.get(targetRef),
            transaction.get(sourcePolicyRef),
            transaction.get(evidenceRef),
        ]);
        const currentClaim = claimSnap.exists ? claimSnap.data() as AnyRecord : null;
        if (
            currentClaim?.claimId !== claimId
            || currentClaim?.status !== "in_progress"
            || currentClaim?.requestFingerprintHash !== requestFingerprintHash
        ) {
            throw new Error("AI assist claim ownership changed");
        }
        if (
            currentClaim.accountingDay !== normalizeText(currentClaim.accountingDay)
            || currentClaim.accountingMonth !== normalizeText(currentClaim.accountingMonth)
            || currentClaim.reservedCostUsd !== reservedCostUsd
            || typeof currentClaim.reservedBudgetPolicy !== "boolean"
        ) throw new Error("AI assist reservation authority changed");
        const settlementPeriod = getSignalDeskSpendPeriod(timestamp.toMillis());
        const providerAccount = providerAccountSnap.exists
            ? parseSignalDeskProviderAccountDocument(providerAccountSnap.data(), providerAccountRef.id, settlementPeriod)
            : null;
        if (!providerAccount) throw new Error("SIGNALDESK_PROVIDER_ACCOUNT_MISSING");
        const settlementReservation = {
            reservedAmountUsd: reservedCostUsd,
            spendDayKey: currentClaim.accountingDay,
            spendMonthKey: currentClaim.accountingMonth,
        };
        transaction.set(providerAccountRef, sanitizeForFirestore(settleSignalDeskSpendReservation({
            actualAmountUsd: estimatedCostUsd,
            authority: providerAccount,
            currentPeriod: settlementPeriod,
            reservation: settlementReservation,
            updatedAt: timestamp,
        })), { merge: true });
        if (currentClaim.reservedBudgetPolicy) {
            const providerBudget = providerBudgetSnap.exists
                ? parseSignalDeskBudgetPolicyDocument(providerBudgetSnap.data(), providerBudgetRef.id, settlementPeriod)
                : null;
            if (!providerBudget) throw new Error("SIGNALDESK_PROVIDER_BUDGET_RESERVATION_MISSING");
            transaction.set(providerBudgetRef, sanitizeForFirestore(settleSignalDeskSpendReservation({
                actualAmountUsd: estimatedCostUsd,
                authority: providerBudget,
                currentPeriod: settlementPeriod,
                reservation: settlementReservation,
                updatedAt: timestamp,
            })), { merge: true });
        }
        let currentSourceAuthority = false;
        let currentTargetAuthority: SignalDeskOutcomeTargetAuthority | null = null;
        try {
            if (!currentTargetSnap.exists) throw new Error("Target not found");
            currentTargetAuthority = parseSignalDeskOutcomeTargetAuthority(
                currentTargetSnap.data(),
                currentTargetSnap.id,
            );
            assertSignalDeskAiAssistTargetActive(currentTargetAuthority.target);
            const currentPolicy = readSourcePolicySnapshot(currentPolicySnap);
            const currentPolicyError = sourcePolicyUsabilityError(currentPolicy, {
                entityId: input.targetId,
                use: sourcePolicyUse,
            });
            if (currentPolicyError) throw new Error(currentPolicyError);
            assertOutcomeTargetPolicyLineage(currentTargetAuthority, currentPolicy);
            let currentEvidence: SignalDeskEvidencePacketSummary | null = null;
            if (evidence) {
                if (!currentEvidenceSnap?.exists) throw new Error("AI_ASSIST_EVIDENCE_LINEAGE_STALE");
                parseSignalDeskOutcomeEvidenceAuthority(
                    currentEvidenceSnap.data(),
                    currentEvidenceSnap.id,
                    currentTargetAuthority,
                );
                const currentExpectedEvidenceId = `evidence_${signalDeskEvidenceIdentityHashFor(currentTargetAuthority, evidenceAllowedUse)}`;
                if (currentEvidenceSnap.id !== currentExpectedEvidenceId) throw new Error("AI_ASSIST_EVIDENCE_LINEAGE_STALE");
                currentEvidence = toPlain(currentEvidenceSnap.data()) as SignalDeskEvidencePacketSummary;
            } else if (currentEvidenceSnap?.exists) {
                throw new Error("AI_ASSIST_SOURCE_AUTHORITY_CHANGED");
            }
            currentSourceAuthority = signalDeskAiAssistAuthorityFingerprintFor({
                evidence: currentEvidence,
                policy: currentPolicy,
                targetAuthority: currentTargetAuthority,
            }) === sourceAuthorityFingerprintHash;
        } catch {
            currentSourceAuthority = false;
        }
        if (!currentSourceAuthority || !currentTargetAuthority) {
            transaction.set(ledgerRef, sanitizeForFirestore({
                operationId: ledgerRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                targetId: input.targetId,
                operation: `ai_assist_${input.task}`,
                costEstimate: estimatedCostUsd,
                model: finalAssist.model,
                modelCallCount,
                status: "unresolved",
                volumeRunId: input.volumeRunId || null,
                createdAt: timestamp,
            }));
            transaction.set(claimRef, sanitizeForFirestore({
                completedAt: timestamp,
                failureCode: "ai_assist_source_authority_changed",
                status: "unresolved",
                updatedAt: timestamp,
            }), { merge: true });
            appendAudit(db, transaction, access, "ai_assist_source_authority_changed", "target", input.targetId, "authority-changed");
            updateDailyCost(db, transaction, 5, estimatedCostUsd, 0);
            return { persisted: false };
        }
        const rawExistingEval = evalSnap.exists
            ? toPlain(evalSnap.data()) as SignalDeskModelEvalSummary
            : null;
        const existingEval = rawExistingEval ? annotateModelEvalSummary(rawExistingEval) : null;
        const hasExactCumulativeCounts = rawExistingEval?.passedSampleCount !== undefined
            || rawExistingEval?.rejectedFactSampleCount !== undefined;
        const sampleSize = (hasExactCumulativeCounts ? nonNegativeInteger(existingEval?.sampleSize) : 0) + 1;
        const passedSampleCount = (hasExactCumulativeCounts ? nonNegativeInteger(existingEval?.passedSampleCount) : 0) + (finalConfidence === "low" ? 0 : 1);
        const lowConfidenceCount = (hasExactCumulativeCounts ? nonNegativeInteger(existingEval?.lowConfidenceCount) : 0) + (finalConfidence === "low" ? 1 : 0);
        const rejectedFactSampleCount = (hasExactCumulativeCounts ? nonNegativeInteger(existingEval?.rejectedFactSampleCount) : 0) + (rejectedFacts.length ? 1 : 0);

        transaction.set(runRef, sanitizeForFirestore({
            aiRunId: runRef.id,
            ...activeSourceDataLifecycleForTargetAuthority(currentTargetAuthority),
            aiDetailExpiresAt: admin.firestore.Timestamp.fromMillis(timestamp.toMillis() + SIGNALDESK_AI_DETAIL_RETENTION_MS),
            aiDetailLifecycleState: "active",
            aiDetailLifecycleUpdatedAt: timestamp,
            aiDetailRetentionAnchorAt: timestamp,
            pId: SIGNALDESK_PRODUCT_CODE,
            workerType: `ai_assist_${input.task}`,
            workerVersion: critic ? `${initialAssist.promptVersion}+${critic.promptVersion}` : initialAssist.promptVersion,
            promptVersion: finalAssist.promptVersion,
            task: input.task,
            provider: route.defaultProvider,
            model: finalAssist.model,
            modelRouteId: route.modelRouteId,
            modelEvalId: evalRef.id,
            volumeRunId: input.volumeRunId || null,
            targetId: input.targetId,
            confidence: finalConfidence,
            rejectedFactCount: rejectedFacts.length,
            initialOutput: critic ? initialAssist.output : null,
            output: finalOutput,
            criticConfidence: critic?.confidence || null,
            criticModel: critic?.model || null,
            criticPromptVersion: critic?.promptVersion || null,
            criticReasons: critic?.reasons || [],
            criticRejectedFactCount: critic?.rejectedFacts.length || 0,
            criticVerdict: critic?.verdict || null,
            escalated,
            escalationBlocked,
            escalationModel: escalated ? finalAssist.model : route.escalationModel || null,
            modelCallCount,
            costEstimate: estimatedCostUsd,
            reviewDecision: null,
            reviewReason: null,
            reviewedAt: null,
            reviewedBy: null,
            founderAttentionMinutes: 0,
            sourceDataPayloadStored: true,
            createdAt: timestamp,
        }));
        transaction.set(snapshotRef, sanitizeForFirestore({
            ...activeSourceDataLifecycleForTargetAuthority(currentTargetAuthority),
            snapshotId: snapshotRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            targetId: input.targetId,
            decisionType: "score",
            confidence: finalConfidence,
            rejectedFacts,
            evidenceRefs: evidence?.evidencePacketId ? [evidence.evidencePacketId] : [],
            aiWorkerVersion: critic ? `${initialAssist.promptVersion}+${critic.promptVersion}` : initialAssist.promptVersion,
            ruleVersion: "ai-assist-v2",
            decidedBy: "system",
            createdAt: timestamp,
        }));
        transaction.set(ledgerRef, sanitizeForFirestore({
            operationId: ledgerRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            targetId: input.targetId,
            operation: `ai_assist_${input.task}`,
            costEstimate: estimatedCostUsd,
            model: finalAssist.model,
            modelCallCount,
            volumeRunId: input.volumeRunId || null,
            createdAt: timestamp,
        }));
        transaction.set(evalRef, sanitizeForFirestore({
            modelEvalId: evalRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            modelRouteId: route.modelRouteId,
            task: route.task,
            provider: route.defaultProvider,
            model: finalAssist.model,
            status: finalConfidence === "low" ? "needs-review" : existingEval?.status === "failed" ? "failed" : "passed",
            measurementVersion: "cumulative-v1",
            legacySampleSize: hasExactCumulativeCounts
                ? nonNegativeInteger(existingEval?.legacySampleSize)
                : nonNegativeInteger(existingEval?.sampleSize),
            legacyPassRate: hasExactCumulativeCounts
                ? numberOrZero(existingEval?.legacyPassRate)
                : numberOrZero(existingEval?.passRate),
            legacyRejectedFactRate: hasExactCumulativeCounts
                ? numberOrZero(existingEval?.legacyRejectedFactRate)
                : numberOrZero(existingEval?.rejectedFactRate),
            sampleSize,
            passedSampleCount,
            lowConfidenceCount,
            rejectedFactSampleCount,
            reviewedSampleSize: nonNegativeInteger(existingEval?.reviewedSampleSize),
            acceptedCount: nonNegativeInteger(existingEval?.acceptedCount),
            editedCount: nonNegativeInteger(existingEval?.editedCount),
            rejectedCount: nonNegativeInteger(existingEval?.rejectedCount),
            heldCount: nonNegativeInteger(existingEval?.heldCount),
            passRate: ratio(passedSampleCount, sampleSize),
            editRate: numberOrZero(existingEval?.editRate),
            rejectedFactRate: ratio(rejectedFactSampleCount, sampleSize),
            acceptanceRate: numberOrZero(existingEval?.acceptanceRate),
            rejectionRate: numberOrZero(existingEval?.rejectionRate),
            holdRate: numberOrZero(existingEval?.holdRate),
            founderAttentionMinutes: nonNegativeInteger(existingEval?.founderAttentionMinutes),
            updatedAt: timestamp,
            updatedBy: access.userId,
        }), { merge: true });
        writeRunTimeline(db, transaction, {
            entityId: runRef.id,
            entityType: "model",
            label: `${route.defaultProvider}/${finalAssist.model} ${input.task}`,
            status: finalConfidence === "low" ? "held" : "completed",
            steps: [
                { label: "Model route active", status: "completed", at: toIso(timestamp) },
                { label: "Provider budget checked", status: "completed", at: toIso(timestamp) },
                ...(critic ? [{ label: `Critic: ${critic.verdict}`, status: critic.verdict === "pass" ? "completed" as const : "held" as const, at: toIso(timestamp) }] : []),
                ...(escalated ? [{ label: `Escalated: ${finalAssist.model}`, status: "completed" as const, at: toIso(timestamp) }] : []),
                ...(escalationBlocked ? [{ label: "Escalation unavailable", status: "held" as const, at: toIso(timestamp) }] : []),
                { label: "Rejected facts captured", status: rejectedFacts.length ? "held" : "completed", at: toIso(timestamp) },
            ],
        });
        appendAudit(db, transaction, access, "ai_assist_run", "target", input.targetId, input.task);
        updateDailyCost(db, transaction, 8, estimatedCostUsd, 0);
        transaction.set(claimRef, sanitizeForFirestore({
            completedAt: timestamp,
            entityId: runRef.id,
            status: "completed",
            updatedAt: timestamp,
        }), { merge: true });
        return { persisted: true };
        });
    } catch (error) {
        const [committedClaimSnap, committedRunSnap] = await Promise.all([claimRef.get(), runRef.get()]);
        const committedClaim = committedClaimSnap.exists ? committedClaimSnap.data() as AnyRecord : null;
        if (
            committedClaim?.status !== "completed"
            || committedClaim?.claimId !== claimId
            || committedClaim?.requestFingerprintHash !== requestFingerprintHash
            || !committedRunSnap.exists
        ) {
            await markAiAssistUnresolved();
            throw error;
        }
        finalizationResult = { persisted: true };
    }
    if (!finalizationResult?.persisted) throw new Error("AI_ASSIST_SOURCE_AUTHORITY_CHANGED");

    return {
        ...finalAssist,
        aiRunId: runRef.id,
        confidence: finalConfidence,
        critic,
        escalated,
        escalationBlocked,
        estimatedCostUsd,
        modelCallCount,
        output: finalOutput,
    };
}

const signalDeskAiVolumeFailureCode = (error: unknown) => {
    const message = error instanceof Error ? error.message : "";
    if (message.includes("budget") || message.includes("cost")) return "ai_volume_budget_blocked";
    if (message.includes("source policy") || message.startsWith("SOURCE_POLICY_")) return "ai_volume_policy_blocked";
    if (message.includes("provider") || message.includes("route") || message.includes("model")) return "ai_volume_provider_blocked";
    if (message.includes("Target")) return "ai_volume_target_blocked";
    return "ai_volume_child_failed";
};

const SIGNALDESK_AI_VOLUME_LOCK_ID = "ai_volume_lock_global";
const SIGNALDESK_AI_VOLUME_LOCK_TTL_MS = 6 * 60 * 1000;
const SIGNALDESK_AI_VOLUME_INTERRUPTED_CODE = "ai_volume_run_interrupted";

const assertSignalDeskAiVolumeRequestIdentity = (
    existing: SignalDeskAiVolumeRunSummary,
    expected: {
        createdBy: string;
        instruction: string;
        maxEstimatedCostUsd: number;
        requestFingerprintHash: string;
        targetIds: string[];
        tasks: SignalDeskAiVolumeTask[];
    },
) => {
    const legacyRequestMatches = existing.createdBy === expected.createdBy
        && normalizeText(existing.instruction) === expected.instruction
        && numberOrZero(existing.maxEstimatedCostUsd) === expected.maxEstimatedCostUsd
        && JSON.stringify(existing.targetIds || []) === JSON.stringify(expected.targetIds)
        && JSON.stringify(existing.tasks || []) === JSON.stringify(expected.tasks);
    if (
        existing.createdBy !== expected.createdBy
        || (existing.requestFingerprintHash
            ? existing.requestFingerprintHash !== expected.requestFingerprintHash
            : !legacyRequestMatches)
    ) {
        throw new Error("AI volume idempotency conflict");
    }
};

const recoverExpiredSignalDeskAiVolumeRun = async (params: {
    access: SignalDeskAccessContext;
    db: any;
    existingSnap: any;
    lockRef: any;
    volumeRef: any;
}): Promise<SignalDeskAiVolumeRunSummary> => {
    const existingRaw = params.existingSnap.data() as AnyRecord;
    const existing = toPlain(existingRaw) as SignalDeskAiVolumeRunSummary;
    if (existing.status !== "running") return existing;
    const fallbackAnchorMillis = toTimestampMillis(existingRaw.updatedAt || existingRaw.createdAt);
    const expiresAtMillis = toTimestampMillis(existingRaw.lockExpiresAt)
        || (fallbackAnchorMillis ? fallbackAnchorMillis + SIGNALDESK_AI_VOLUME_LOCK_TTL_MS : null);
    if (!expiresAtMillis || expiresAtMillis > Date.now()) return existing;

    const childSnaps = await params.db.collection(SIGNALDESK_COLLECTIONS.AI_WORKER_RUNS)
        .where("volumeRunId", "==", params.volumeRef.id)
        .limit(20)
        .get();
    const recoveredChildren = childSnaps.docs
        .map((doc: any) => toPlain(doc.data()) as SignalDeskAiWorkerRunSummary)
        .filter((run: SignalDeskAiWorkerRunSummary) => String(run.workerType || "").startsWith("ai_assist_"));
    const recoveredChildRunIds = Array.from(new Set([
        ...(existing.childRunIds || []),
        ...recoveredChildren.map((run) => run.aiRunId).filter(Boolean),
    ])).slice(0, 15);
    const recoveredCostUsd = recoveredChildren.reduce((sum, run) => sum + numberOrZero(run.costEstimate), 0);
    const recoveredModelCallCount = recoveredChildren.reduce((sum, run) => sum + nonNegativeInteger(run.modelCallCount || 1), 0);
    const recoveredAt = now();

    return params.db.runTransaction(async (transaction: any) => {
        const [currentSnap, lockSnap] = await Promise.all([
            transaction.get(params.volumeRef),
            transaction.get(params.lockRef),
        ]);
        if (!currentSnap.exists) return existing;
        const currentRaw = currentSnap.data() as AnyRecord;
        const current = toPlain(currentRaw) as SignalDeskAiVolumeRunSummary;
        if (current.status !== "running") return current;
        const currentFallbackAnchorMillis = toTimestampMillis(currentRaw.updatedAt || currentRaw.createdAt);
        const currentExpiresAtMillis = toTimestampMillis(currentRaw.lockExpiresAt)
            || (currentFallbackAnchorMillis ? currentFallbackAnchorMillis + SIGNALDESK_AI_VOLUME_LOCK_TTL_MS : null);
        if (!currentExpiresAtMillis || currentExpiresAtMillis > recoveredAt.toMillis()) return current;

        const requestedPairCount = nonNegativeInteger(current.requestedPairCount);
        const completedPairCount = recoveredChildRunIds.length;
        const fullyRecovered = requestedPairCount > 0 && completedPairCount >= requestedPairCount;
        const status: SignalDeskAiVolumeRunSummary["status"] = fullyRecovered
            ? "completed"
            : completedPairCount > 0
                ? "partial"
                : "blocked";
        const failureCodes = fullyRecovered
            ? Array.from(new Set(current.failureCodes || []))
            : Array.from(new Set([...(current.failureCodes || []), SIGNALDESK_AI_VOLUME_INTERRUPTED_CODE]));
        const updates = {
            childRunIds: recoveredChildRunIds,
            completedAt: recoveredAt,
            completedPairCount,
            estimatedCostUsd: Math.max(numberOrZero(current.estimatedCostUsd), recoveredCostUsd),
            failedPairCount: fullyRecovered ? 0 : Math.max(0, requestedPairCount - completedPairCount),
            failureCodes,
            modelCallCount: Math.max(nonNegativeInteger(current.modelCallCount), recoveredModelCallCount),
            status,
            updatedAt: recoveredAt,
        };
        transaction.set(params.volumeRef, sanitizeForFirestore(updates), { merge: true });
        const lock = lockSnap.exists ? lockSnap.data() as AnyRecord : null;
        if (lock?.activeVolumeRunId === params.volumeRef.id) {
            transaction.set(params.lockRef, sanitizeForFirestore({
                activeVolumeRunId: params.volumeRef.id,
                expiresAt: recoveredAt,
                recoveryReason: SIGNALDESK_AI_VOLUME_INTERRUPTED_CODE,
                status: "completed",
                updatedAt: recoveredAt,
            }), { merge: true });
        }
        writeRunTimeline(params.db, transaction, {
            entityId: params.volumeRef.id,
            entityType: "model",
            label: `AI volume batch recovered: ${completedPairCount}/${requestedPairCount} pairs`,
            status: status === "completed" ? "completed" : status === "partial" ? "held" : "blocked",
            steps: [
                { label: "Expired running parent detected", status: "held", at: toIso(recoveredAt) },
                { label: `${completedPairCount} child runs recovered`, status: completedPairCount ? "completed" : "blocked", at: toIso(recoveredAt) },
                { label: `Recovered as ${status}`, status: status === "completed" ? "completed" : status === "partial" ? "held" : "blocked", at: toIso(recoveredAt) },
            ],
        });
        appendAudit(params.db, transaction, params.access, "ai_volume_batch_recovered", "aiWorkerRun", params.volumeRef.id, status);
        updateDailyCost(params.db, transaction, lock?.activeVolumeRunId === params.volumeRef.id ? 5 : 4, 0);
        return toPlain({ ...current, ...updates }) as SignalDeskAiVolumeRunSummary;
    });
};

export async function runSignalDeskAiVolumeBatchServer(
    access: SignalDeskAccessContext,
    input: AiVolumeBatchInput,
) {
    if (!FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_AI_VOLUME_MODE) {
        throw new Error("SignalDesk AI Volume Mode is disabled");
    }
    if (!FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_AI_PROVIDER_CALLS) {
        throw new Error("SignalDesk AI provider calls are disabled");
    }
    if (access.role !== "founder-admin" || !access.permissions.includes("signaldesk.configure")) {
        throw new Error("Founder approval is required for AI volume runs");
    }
    const idempotencyKey = normalizeText(input.idempotencyKey);
    const targetIds = Array.from(new Set(input.targetIds.map((targetId) => normalizeText(targetId)).filter(Boolean)));
    const tasks = Array.from(new Set(input.tasks));
    const allowedTasks: SignalDeskAiVolumeTask[] = ["score", "evidence", "draft", "reply-classification"];
    if (
        idempotencyKey.length < 8
        || idempotencyKey.length > 180
        || !targetIds.length
        || targetIds.length > 5
        || targetIds.some((targetId) => targetId.length < 3 || targetId.length > 160)
        || !tasks.length
        || tasks.length > 3
        || tasks.some((task) => !allowedTasks.includes(task))
        || numberOrZero(input.maxEstimatedCostUsd) < 0.01
        || numberOrZero(input.maxEstimatedCostUsd) > 5
    ) {
        throw new Error("AI volume batch limits are invalid");
    }

    const db = requireDb();
    const idempotencyKeyHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const instruction = normalizeText(input.instruction);
    const requestFingerprintHash = hashValue(JSON.stringify({
        createdBy: access.userId,
        instruction,
        maxEstimatedCostUsd: input.maxEstimatedCostUsd,
        targetIds,
        tasks,
    }));
    const workerClaimId = randomBytes(16).toString("hex");
    const expectedRequestIdentity = {
        createdBy: access.userId,
        instruction,
        maxEstimatedCostUsd: input.maxEstimatedCostUsd,
        requestFingerprintHash,
        targetIds,
        tasks,
    };
    const volumeRef = db.collection(SIGNALDESK_COLLECTIONS.AI_WORKER_RUNS).doc(`ai_volume_${idempotencyKeyHash.slice(0, 24)}`);
    const lockRef = db.collection(SIGNALDESK_COLLECTIONS.AI_WORKER_RUNS).doc(SIGNALDESK_AI_VOLUME_LOCK_ID);
    const volumeProviderAccountRef = db.collection(SIGNALDESK_COLLECTIONS.PROVIDER_ACCOUNTS).doc(providerAccountIdFor("gemini", "ai"));
    const volumeProviderBudgetRef = db.collection(SIGNALDESK_COLLECTIONS.BUDGET_POLICIES).doc(budgetPolicyIdFor("provider", "gemini"));
    const existingVolumeSnap = await volumeRef.get();
    if (existingVolumeSnap.exists) {
        assertSignalDeskAiVolumeRequestIdentity(
            toPlain(existingVolumeSnap.data()) as SignalDeskAiVolumeRunSummary,
            expectedRequestIdentity,
        );
        return recoverExpiredSignalDeskAiVolumeRun({
            access,
            db,
            existingSnap: existingVolumeSnap,
            lockRef,
            volumeRef,
        });
    }
    await requireNoActiveKillSwitch(db, "ai-worker", "SignalDesk AI workers are paused");
    const [criticRoute, ...taskRoutes] = await Promise.all([
        readModelRoute(db, "quality-critic"),
        ...tasks.map((task) => readModelRoute(db, task)),
    ]);
    if (!criticRoute || criticRoute.status !== "active" || criticRoute.defaultProvider !== "gemini") {
        throw new Error("SignalDesk AI critic route is not active");
    }
    taskRoutes.forEach((route) => {
        if (!route || route.status !== "active" || route.defaultProvider !== "gemini") {
            throw new Error("SignalDesk AI route is not active");
        }
    });
    const projectedPairCostUsd = taskRoutes.reduce((sum, route) => sum
        + Math.min(numberOrZero(route?.maxCostUsd), 0.05)
        + Math.min(numberOrZero(criticRoute.maxCostUsd), 0.05)
        + (route?.escalationProvider === "gemini" && route.escalationModel ? Math.min(numberOrZero(route.maxCostUsd), 0.05) : 0), 0);
    const projectedMaxCostUsd = projectedPairCostUsd * targetIds.length;
    if (projectedMaxCostUsd > numberOrZero(input.maxEstimatedCostUsd) + 0.000001) {
        throw new Error("AI volume projected cost exceeds founder maximum");
    }
    await requireProviderBudget(db, {
        enforcePerRunBudget: false,
        estimatedCostUsd: projectedMaxCostUsd,
        provider: "gemini",
        use: "ai",
    });

    const timestamp = now();
    const lockExpiresAt = admin.firestore.Timestamp.fromMillis(timestamp.toMillis() + SIGNALDESK_AI_VOLUME_LOCK_TTL_MS);
    const initialVolumeRun = {
        aiRunId: volumeRef.id,
        volumeRunId: volumeRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        workerType: "ai_volume_batch" as const,
        workerVersion: "ai-volume-v1" as const,
        status: "running" as const,
        targetIds,
        tasks,
        requestedPairCount: targetIds.length * tasks.length,
        completedPairCount: 0,
        failedPairCount: 0,
        modelCallCount: 0,
        estimatedCostUsd: 0,
        maxEstimatedCostUsd: input.maxEstimatedCostUsd,
        projectedMaxCostUsd,
        childRunIds: [] as string[],
        failureCodes: [] as string[],
        idempotencyKeyHash,
        requestFingerprintHash,
        workerClaimId,
        instruction: instruction || null,
        lockExpiresAt,
        createdAt: timestamp,
        createdBy: access.userId,
        updatedAt: timestamp,
    };
    let startResult: { created: boolean; run: SignalDeskAiVolumeRunSummary | null };
    try {
        startResult = await db.runTransaction(async (transaction: any) => {
            const [existingSnap, lockSnap, providerAccountSnap, providerBudgetSnap] = await Promise.all([
                transaction.get(volumeRef),
                transaction.get(lockRef),
                transaction.get(volumeProviderAccountRef),
                transaction.get(volumeProviderBudgetRef),
            ]);
            if (existingSnap.exists) {
                const existing = toPlain(existingSnap.data()) as SignalDeskAiVolumeRunSummary;
                assertSignalDeskAiVolumeRequestIdentity(existing, expectedRequestIdentity);
                return { created: false, run: existing };
            }
            const lock = lockSnap.exists ? lockSnap.data() as AnyRecord : null;
            const activeLockExpiresAt = lock?.expiresAt?.toMillis?.() || 0;
            if (lock?.status === "running" && activeLockExpiresAt > timestamp.toMillis()) {
                throw new Error("SignalDesk AI volume run is already active");
            }
            const spendPeriod = getSignalDeskSpendPeriod(timestamp.toMillis());
            const providerAccount: SignalDeskProviderAccountAuthority | null = providerAccountSnap.exists
                ? parseSignalDeskProviderAccountDocument(providerAccountSnap.data(), volumeProviderAccountRef.id, spendPeriod)
                : null;
            const providerBudget: SignalDeskBudgetPolicyAuthority | null = providerBudgetSnap.exists
                ? parseSignalDeskBudgetPolicyDocument(providerBudgetSnap.data(), volumeProviderBudgetRef.id, spendPeriod)
                : null;
            assertProviderBudgetState(
                providerAccount,
                providerBudget,
                { enforcePerRunBudget: false, estimatedCostUsd: projectedMaxCostUsd },
            );
            transaction.set(lockRef, sanitizeForFirestore({
                activeVolumeRunId: volumeRef.id,
                createdAt: lock?.createdAt || timestamp,
                expiresAt: lockExpiresAt,
                pId: SIGNALDESK_PRODUCT_CODE,
                status: "running",
                updatedAt: timestamp,
                workerType: "ai_volume_lock",
            }));
            transaction.set(volumeRef, sanitizeForFirestore(initialVolumeRun));
            writeRunTimeline(db, transaction, {
                entityId: volumeRef.id,
                entityType: "model",
                label: `AI volume batch: ${targetIds.length} targets / ${tasks.length} tasks`,
                status: "ready",
                steps: [
                    { label: "Founder cost envelope checked", status: "completed", at: toIso(timestamp) },
                    { label: `${initialVolumeRun.requestedPairCount} target/task pairs queued`, status: "ready", at: toIso(timestamp) },
                ],
            });
            appendAudit(db, transaction, access, "ai_volume_batch_started", "aiWorkerRun", volumeRef.id, `${targetIds.length} targets; ${tasks.length} tasks`);
            updateDailyCost(db, transaction, 4, 0);
            return { created: true, run: null };
        });
    } catch (error) {
        const committedSnap = await volumeRef.get();
        if (!committedSnap.exists) throw error;
        const committed = toPlain(committedSnap.data()) as SignalDeskAiVolumeRunSummary;
        assertSignalDeskAiVolumeRequestIdentity(committed, expectedRequestIdentity);
        if (committed.workerClaimId !== workerClaimId) throw error;
        startResult = { created: true, run: committed };
    }
    if (!startResult.created && startResult.run) return startResult.run;

    const pairs = targetIds.flatMap((targetId) => tasks.map((task) => ({ targetId, task })));
    const childRunIds: string[] = [];
    const failureCodes: string[] = [];
    let estimatedCostUsd = 0;
    let modelCallCount = 0;
    let cursor = 0;
    const worker = async () => {
        while (cursor < pairs.length) {
            const pair = pairs[cursor];
            cursor += 1;
            try {
                const result = await runSignalDeskAiAssistServer(access, {
                    idempotencyKey: `${volumeRef.id}:${pair.targetId}:${pair.task}`,
                    instruction: input.instruction,
                    multiPass: true,
                    targetId: pair.targetId,
                    task: pair.task,
                    volumeRunId: volumeRef.id,
                });
                childRunIds.push(result.aiRunId);
                estimatedCostUsd += numberOrZero(result.estimatedCostUsd);
                modelCallCount += nonNegativeInteger(result.modelCallCount);
            } catch (error) {
                const failureCode = signalDeskAiVolumeFailureCode(error);
                failureCodes.push(failureCode);
                logRuntimeFailure("signaldesk_ai_volume_child_failed", error, {
                    ...getBoundedRuntimeStringContext("targetId", pair.targetId),
                    product: "signaldesk",
                    task: pair.task,
                    volumeRunId: volumeRef.id,
                });
            }
        }
    };
    await Promise.all(Array.from({ length: Math.min(3, pairs.length) }, () => worker()));

    const completedPairCount = childRunIds.length;
    const failedPairCount = failureCodes.length;
    const status: SignalDeskAiVolumeRunSummary["status"] = completedPairCount === pairs.length
        ? "completed"
        : completedPairCount > 0
            ? "partial"
            : "blocked";
    const completedAt = now();
    const updates = {
        childRunIds,
        completedAt,
        completedPairCount,
        estimatedCostUsd,
        failedPairCount,
        failureCodes: Array.from(new Set(failureCodes)),
        modelCallCount,
        status,
        updatedAt: completedAt,
    };
    await db.runTransaction(async (transaction: any) => {
        const lockSnap = await transaction.get(lockRef);
        transaction.set(volumeRef, sanitizeForFirestore(updates), { merge: true });
        const lock = lockSnap.exists ? lockSnap.data() as AnyRecord : null;
        if (lock?.activeVolumeRunId === volumeRef.id) {
            transaction.set(lockRef, sanitizeForFirestore({
                activeVolumeRunId: volumeRef.id,
                expiresAt: completedAt,
                status: "completed",
                updatedAt: completedAt,
            }), { merge: true });
        }
        writeRunTimeline(db, transaction, {
            entityId: volumeRef.id,
            entityType: "model",
            label: `AI volume batch: ${targetIds.length} targets / ${tasks.length} tasks`,
            status: status === "completed" ? "completed" : status === "partial" ? "held" : "blocked",
            steps: [
                { label: "Founder cost envelope checked", status: "completed", at: toIso(timestamp) },
                { label: `${completedPairCount} pairs completed`, status: completedPairCount ? "completed" : "blocked", at: toIso(completedAt) },
                { label: `${failedPairCount} pairs failed`, status: failedPairCount ? "held" : "completed", at: toIso(completedAt) },
            ],
        });
        appendAudit(db, transaction, access, "ai_volume_batch_finished", "aiWorkerRun", volumeRef.id, status);
        updateDailyCost(db, transaction, lock?.activeVolumeRunId === volumeRef.id ? 5 : 4, 0);
    });

    return toPlain({ ...initialVolumeRun, ...updates }) as SignalDeskAiVolumeRunSummary;
}

export async function reviewSignalDeskAiShadowRunServer(
    access: SignalDeskAccessContext,
    input: AiShadowReviewInput,
) {
    if (access.role !== "founder-admin" || !access.permissions.includes("signaldesk.configure")) {
        throw new Error("Founder approval is required for AI shadow review");
    }
    if (input.decision !== "accepted" && !normalizeText(input.reason)) {
        throw new Error("AI shadow review reason is required");
    }
    const db = requireDb();
    const runRef = db.collection(SIGNALDESK_COLLECTIONS.AI_WORKER_RUNS).doc(input.aiRunId);
    const revenueSummaryRef = db.collection(SIGNALDESK_COLLECTIONS.REVENUE_CONTROL_SUMMARIES).doc(SIGNALDESK_SUMMARY_DOCS.REVENUE);

    return db.runTransaction(async (transaction: any) => {
        const runSnap = await transaction.get(runRef);
        if (!runSnap.exists) throw new Error("AI run not found");
        const run = toPlain(runSnap.data()) as SignalDeskAiWorkerRunSummary;
        if (!String(run.workerType || "").startsWith("ai_assist_") || !run.provider || !run.modelEvalId) {
            throw new Error("Only provider-backed AI assist runs can be reviewed");
        }
        const evalRef = db.collection(SIGNALDESK_COLLECTIONS.MODEL_EVALS).doc(run.modelEvalId);
        const [evalSnap, revenueSummarySnap] = await Promise.all([
            transaction.get(evalRef),
            transaction.get(revenueSummaryRef),
        ]);
        if (!evalSnap.exists) throw new Error("AI model evaluation not found");

        const existingEval = annotateModelEvalSummary(toPlain(evalSnap.data()) as SignalDeskModelEvalSummary);
        const previousDecision = run.reviewDecision || null;
        const previousAttentionMinutes = nonNegativeInteger(run.founderAttentionMinutes);
        const nextAttentionMinutes = nonNegativeInteger(input.founderAttentionMinutes);
        const countFor = (decision: SignalDeskAiShadowReviewDecision) => Math.max(
            0,
            nonNegativeInteger({
                accepted: existingEval.acceptedCount,
                edited: existingEval.editedCount,
                rejected: existingEval.rejectedCount,
                held: existingEval.heldCount,
            }[decision]) - (previousDecision === decision ? 1 : 0) + (input.decision === decision ? 1 : 0),
        );
        const acceptedCount = countFor("accepted");
        const editedCount = countFor("edited");
        const rejectedCount = countFor("rejected");
        const heldCount = countFor("held");
        const reviewedSampleSize = acceptedCount + editedCount + rejectedCount + heldCount;
        const founderAttentionMinutes = Math.max(
            0,
            nonNegativeInteger(existingEval.founderAttentionMinutes) - previousAttentionMinutes + nextAttentionMinutes,
        );
        const timestamp = now();
        const reason = normalizeText(input.reason || (input.decision === "accepted" ? "Accepted unchanged." : ""));

        transaction.set(runRef, sanitizeForFirestore({
            reviewDecision: input.decision,
            reviewReason: reason,
            reviewedAt: timestamp,
            reviewedBy: access.userId,
            founderAttentionMinutes: nextAttentionMinutes,
        }), { merge: true });
        const evalUpdates = {
            acceptedCount,
            editedCount,
            rejectedCount,
            heldCount,
            reviewedSampleSize,
            acceptanceRate: ratio(acceptedCount, reviewedSampleSize),
            editRate: ratio(editedCount, reviewedSampleSize),
            rejectionRate: ratio(rejectedCount, reviewedSampleSize),
            holdRate: ratio(heldCount, reviewedSampleSize),
            founderAttentionMinutes,
            updatedAt: timestamp,
            updatedBy: access.userId,
        };
        transaction.set(evalRef, sanitizeForFirestore(evalUpdates), { merge: true });

        if (revenueSummarySnap.exists) {
            const revenueSummary = toPlain(revenueSummarySnap.data()) as SignalDeskRevenueControlSummary;
            transaction.set(revenueSummaryRef, sanitizeForFirestore({
                founderAttentionMinutes: Math.max(
                    0,
                    nonNegativeInteger(revenueSummary.founderAttentionMinutes) - previousAttentionMinutes + nextAttentionMinutes,
                ),
                pId: SIGNALDESK_PRODUCT_CODE,
                revenueControlSummaryId: revenueSummaryRef.id,
                updatedAt: timestamp,
            }), { merge: true });
        }
        appendAudit(db, transaction, access, "ai_shadow_review", "aiWorkerRun", input.aiRunId, `${input.decision}: ${reason}`);
        writeRunTimeline(db, transaction, {
            entityId: input.aiRunId,
            entityType: "model",
            label: `${run.provider}/${run.model} shadow review`,
            status: input.decision === "accepted" ? "completed" : input.decision === "rejected" ? "blocked" : "held",
            steps: [
                { label: "Founder decision recorded", status: "completed", at: toIso(timestamp) },
                { label: `Decision: ${input.decision}`, status: input.decision === "accepted" ? "completed" : input.decision === "rejected" ? "blocked" : "held", at: toIso(timestamp) },
                { label: `${nextAttentionMinutes} founder minute${nextAttentionMinutes === 1 ? "" : "s"}`, status: "completed", at: toIso(timestamp) },
            ],
        });
        updateDailyCost(db, transaction, revenueSummarySnap.exists ? 5 : 4, 0);

        return {
            run: toPlain({ ...run, reviewDecision: input.decision, reviewReason: reason, reviewedAt: timestamp, reviewedBy: access.userId, founderAttentionMinutes: nextAttentionMinutes }),
            modelEval: annotateModelEvalSummary(toPlain({ ...existingEval, ...evalUpdates }) as SignalDeskModelEvalSummary),
        };
    });
}

export async function createSignalDeskEvidenceServer(access: SignalDeskAccessContext, targetId: string) {
    const db = requireDb();
    const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(targetId);
    try {
        return await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const targetSnap = await transaction.get(targetRef);
            if (!targetSnap.exists) throw new Error("Target not found");
            const targetAuthority = parseSignalDeskOutcomeTargetAuthority(targetSnap.data(), targetSnap.id);
            const target = targetAuthority.target;
            const policyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(target.sourcePolicyId);
            const policySnap = await transaction.get(policyRef);
            const policy = readSourcePolicySnapshot(policySnap);
            const policyError = sourcePolicyUsabilityError(policy, { entityId: targetId, use: "evidence" });
            if (policyError) throw new Error(policyError);
            if (!policy) throw new Error(SOURCE_POLICY_REVIEW_REQUIRED);
            const policyAllowedUse = resolveAllowedUse(policy);
            if (!policyAllowedUse.evidence) throw new Error("Evidence use is not approved for this target");
            const allowedUse = ["evidence"];
            if (policyAllowedUse.personalization) allowedUse.push("draft-personalization");

            const evidenceIdentityHash = signalDeskEvidenceIdentityHashFor(targetAuthority, allowedUse);
            const evidenceRef = db.collection(SIGNALDESK_COLLECTIONS.EVIDENCE_PACKETS).doc(`evidence_${evidenceIdentityHash}`);
            const summaryRef = db.collection(SIGNALDESK_COLLECTIONS.EVIDENCE_PACKET_SUMMARIES).doc(evidenceRef.id);
            const priorSummarySnap = await transaction.get(summaryRef);
            if (priorSummarySnap.exists) {
                parseSignalDeskOutcomeEvidenceAuthority(
                    priorSummarySnap.data(),
                    priorSummarySnap.id,
                    targetAuthority,
                );
                return toPlain(priorSummarySnap.data()) as SignalDeskEvidencePacketSummary;
            }

            const timestamp = now();
            const assessedAt = toIso(timestamp) as string;
            const currentMenuPresence = buildCurrentMenuPresenceDiagnostic(target, assessedAt);
            const rejectedFacts = [
                target.currentListUrl ? "" : "No current-list URL was observed in approved source data; this does not prove that no menu exists.",
                "Owner control of the observed menu destination was not verified.",
                "Mobile accessibility was not verified.",
                "Customer loss, sales impact, ranking impact, and platform partnership were not verified.",
            ].filter(Boolean);
            const summary = {
                evidencePacketId: evidenceRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                targetId,
                targetName: target.displayName,
                confidence: target.sourceConfidence === "high" ? "high" : target.sourceConfidence === "blocked" ? "low" : "medium",
                allowedUse,
                rejectedFacts,
                summary: `Approved source data for ${target.displayName} in ${target.city || "unknown city"} was classified as ${target.primaryOpportunity.replace(/-/g, " ")}; owner control and mobile access remain unverified.`,
                currentMenuPresence,
                createdAt: timestamp,
                updatedAt: timestamp,
            };
            transaction.create(evidenceRef, sanitizeForFirestore({
                ...summary,
                ...activeSourceDataLifecycleForTargetAuthority(targetAuthority),
                facts: {
                    category: target.category || null,
                    city: target.city || null,
                    currentListUrl: target.currentListUrl || null,
                    website: target.website || null,
                },
            }));
            transaction.create(summaryRef, sanitizeForFirestore(summary));
            transaction.set(targetRef, sanitizeForFirestore({
                nextAction: "draft",
                updatedAt: timestamp,
            }), { merge: true });
            appendAudit(db, transaction, access, "evidence_packet_create", "target", targetId, `confidence:${summary.confidence}`);
            updateDailyCost(db, transaction, 4, 0);
            return toPlain(summary) as SignalDeskEvidencePacketSummary;
        });
    } catch (error) {
        const code = error instanceof Error ? error.message : "";
        if ([SOURCE_POLICY_EXPIRED, SOURCE_POLICY_REVIEW_REQUIRED, SOURCE_POLICY_RETENTION_MISSING, SOURCE_POLICY_USE_NOT_ALLOWED].includes(code)) {
            await appendSourcePolicyBlockedAudit(db, access, null, { entityId: targetId, use: "evidence" }, code);
        }
        throw error;
    }
}

export async function createSignalDeskDraftServer(access: SignalDeskAccessContext, input: {
    targetId: string;
    templateId?: string;
}) {
    const db = requireDb();
    const templateId = input.templateId || "template_current_list_intro_v1";
    const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(input.targetId);
    const templateRef = db.collection(SIGNALDESK_COLLECTIONS.TEMPLATE_SUMMARIES).doc(templateId);
    const [selectedEvidence, selectedCta, selectedSender] = await Promise.all([
        readRecentByTarget<SignalDeskEvidencePacketSummary>(db, SIGNALDESK_COLLECTIONS.EVIDENCE_PACKET_SUMMARIES, input.targetId, 1).then((rows) => rows[0] || null),
        readDefaultCta(db),
        readReadySenderDomain(db),
    ]);
    try {
        return await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const targetSnap = await transaction.get(targetRef);
            if (!targetSnap.exists) throw new Error("Target not found");
            const target = toPlain(targetSnap.data()) as SignalDeskTargetSummary;
            const policyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(target.sourcePolicyId);
            const evidenceRef = selectedEvidence
                ? db.collection(SIGNALDESK_COLLECTIONS.EVIDENCE_PACKET_SUMMARIES).doc(selectedEvidence.evidencePacketId)
                : null;
            const ctaRef = db.collection(SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS).doc(selectedCta.ctaId);
            const senderRef = selectedSender
                ? db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(selectedSender.senderDomainId)
                : null;
            const conversationRef = target.latestConversationId
                ? db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES).doc(target.latestConversationId)
                : null;
            const [policySnap, currentTemplateSnap, evidenceSnap, ctaSnap, senderSnap, conversationSnap] = await Promise.all([
                transaction.get(policyRef),
                transaction.get(templateRef),
                evidenceRef ? transaction.get(evidenceRef) : Promise.resolve(null),
                transaction.get(ctaRef),
                senderRef ? transaction.get(senderRef) : Promise.resolve(null),
                conversationRef ? transaction.get(conversationRef) : Promise.resolve(null),
            ]);
            const policy = readSourcePolicySnapshot(policySnap);
            const policyError = sourcePolicyUsabilityError(policy, { entityId: input.targetId, use: "draft" });
            if (policyError) throw new Error(policyError);
            if (!policy) throw new Error(SOURCE_POLICY_REVIEW_REQUIRED);
            if (!currentTemplateSnap.exists) throw new Error("Active template is required");
            const template = toPlain(currentTemplateSnap.data()) as SignalDeskTemplateSummary;
            if (template.status !== "active") throw new Error("Template is inactive");
            if (!evidenceSnap?.exists) throw new Error("Evidence packet is required before draft");
            const evidence = toPlain(evidenceSnap.data()) as SignalDeskEvidencePacketSummary;
            if (evidence.targetId !== target.targetId) throw new Error("Evidence packet does not belong to target");
            if (!Array.isArray(evidence.allowedUse) || !evidence.allowedUse.includes("draft-personalization")) {
                throw new Error("Draft personalization is not approved for this target");
            }
            if (target.suppressionStatus !== "clear" || target.nextAction === "hold" || target.segment === "reject") {
                throw new Error("Target is not draft-ready");
            }
            const priorGuard = targetPriorGuard(
                target,
                conversationSnap?.exists ? conversationSnap.data() as AnyRecord : null,
            );
            if (!priorGuard.clear) throw new Error("Target has prior contact or outcome");
            const ctaAuthority = await readSignalDeskCtaAuthority(db, transaction, {
                ctaId: selectedCta.ctaId,
                existingSnap: ctaSnap,
                requireActive: true,
                useAuthoritativePreview: true,
            });
            const cta = ctaAuthority.cta;
            const sender = projectSenderDomainDocument(senderSnap);
            if (!isSenderDomainReady(sender)) throw new Error("Sender domain is not ready");
            const senderDomainFingerprintHash = senderDomainFingerprintHashFor(sender);
            const rendered = buildDraftBody(template, target, evidence, cta);
            const draftIdentityHash = hashValue(JSON.stringify({
                body: rendered.body,
                ctaFingerprintHash: ctaAuthority.ctaFingerprintHash,
                ctaId: cta.ctaId,
                evidencePacketId: evidence.evidencePacketId,
                policyAllowedUse: resolveAllowedUse(policy),
                policyExpiresAt: getSourcePolicyExpiryMillis(policy),
                senderDomainFingerprintHash,
                senderDomainId: sender.senderDomainId,
                subject: rendered.subject,
                targetId: target.targetId,
                templateId,
            })).slice(0, 32);
            const draftRef = db.collection(SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES).doc(`draft_${draftIdentityHash}`);
            const approvalRef = db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE).doc(`approval_${draftIdentityHash}`);
            const approvalPacketRef = db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_PACKETS).doc(`packet_${draftIdentityHash}`);
            const [priorDraftSnap, priorApprovalSnap, priorPacketSnap] = await Promise.all([
                transaction.get(draftRef),
                transaction.get(approvalRef),
                transaction.get(approvalPacketRef),
            ]);
            if (priorDraftSnap.exists && priorApprovalSnap.exists && priorPacketSnap.exists) {
                const priorDraft = toPlain(priorDraftSnap.data()) as SignalDeskDraftSummary;
                const priorPacket = toPlain(priorPacketSnap.data()) as SignalDeskApprovalPacketSummary;
                if (
                    priorDraft.ctaId !== cta.ctaId
                    || priorDraft.ctaFingerprintHash !== ctaAuthority.ctaFingerprintHash
                    || priorPacket.ctaId !== cta.ctaId
                    || priorPacket.ctaFingerprintHash !== ctaAuthority.ctaFingerprintHash
                ) throw new Error("CONTENT_CTA_STALE");
                return {
                    approval: toPlain(priorApprovalSnap.data()) as SignalDeskApprovalItem,
                    approvalPacket: priorPacket,
                    draft: priorDraft,
                };
            }

            const timestamp = now();
            const draft = {
                draftId: draftRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                targetId: target.targetId,
                targetName: target.displayName,
                templateId,
                channel: "email",
                status: "queued",
                subject: rendered.subject,
                body: rendered.body,
                evidencePacketId: evidence.evidencePacketId,
                approvalId: approvalRef.id,
                ctaFingerprintHash: ctaAuthority.ctaFingerprintHash,
                ctaId: cta.ctaId,
                senderDomainFingerprintHash,
                senderDomainId: sender.senderDomainId,
                personalizationEvidenceIds: rendered.personalizationEvidenceIds,
                unsupportedClaims: rendered.unsupportedClaims,
                createdAt: timestamp,
                updatedAt: timestamp,
                updatedBy: access.userId,
            };
            const approval = {
                approvalId: approvalRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                targetId: target.targetId,
                targetName: target.displayName,
                draftId: draftRef.id,
                status: "pending",
                priority: target.segment === "a" ? "high" : "normal",
                reviewReason: "Draft created from evidence packet.",
                channel: "email",
                approvalPacketId: approvalPacketRef.id,
                dueAt: null,
                createdAt: timestamp,
                updatedAt: timestamp,
            };
            const approvalPacketCore = await buildApprovalPacketSummary(db, {
                approval: toPlain(approval) as SignalDeskApprovalItem,
                cta,
                draft: toPlain(draft) as SignalDeskDraftSummary,
                evidence,
                priorGuard,
                sender,
                sourcePolicy: policy,
                target,
            });
            const approvalPacket = {
                approvalPacketId: approvalPacketRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                ...approvalPacketCore,
                updatedAt: timestamp,
                updatedBy: access.userId,
            };

            transaction.create(draftRef, sanitizeForFirestore(draft));
            transaction.create(approvalRef, sanitizeForFirestore(approval));
            transaction.create(approvalPacketRef, sanitizeForFirestore(approvalPacket));
            transaction.set(targetRef, sanitizeForFirestore({
                latestApprovalId: approvalRef.id,
                latestDraftId: draftRef.id,
                nextAction: "approve",
                updatedAt: timestamp,
            }), { merge: true });
            appendAudit(db, transaction, access, "draft_create", "draft", draftRef.id, target.displayName);
            writeRunTimeline(db, transaction, {
                entityId: approvalPacketRef.id,
                entityType: "approval",
                label: "Draft approval packet",
                status: approvalPacketCore.recommendedAction === "approve" ? "ready" : "held",
                steps: [
                    { label: "Evidence-bound personalization", status: "completed", at: toIso(timestamp) },
                    { label: "CTA attached", status: "completed", at: toIso(timestamp) },
                    { label: "Sender domain checked", status: approvalPacketCore.channelReadiness === "ready" ? "completed" : "held", at: toIso(timestamp) },
                ],
            });
            updateQueueSummary(db, transaction, { approvalBacklog: increment(1), humanReview: increment(1) });
            updateDailyCost(db, transaction, 7, 0);
            return {
                approval: toPlain(approval) as SignalDeskApprovalItem,
                approvalPacket: toPlain(approvalPacket) as SignalDeskApprovalPacketSummary,
                draft: toPlain(draft) as SignalDeskDraftSummary,
            };
        });
    } catch (error) {
        const code = error instanceof Error ? error.message : "";
        if ([SOURCE_POLICY_EXPIRED, SOURCE_POLICY_REVIEW_REQUIRED, SOURCE_POLICY_RETENTION_MISSING, SOURCE_POLICY_USE_NOT_ALLOWED].includes(code)) {
            await appendSourcePolicyBlockedAudit(db, access, null, { entityId: input.targetId, use: "draft" }, code);
        }
        throw error;
    }
}

export async function reviewSignalDeskApprovalServer(access: SignalDeskAccessContext, input: {
    approvalId: string;
    reason?: string;
    rejectionReason?: SignalDeskApprovalRejectionReason;
    status: "approved" | "rejected";
}) {
    const reviewNote = normalizeText(input.reason);
    if (input.status === "rejected") {
        if (!input.rejectionReason || !APPROVAL_REJECTION_REASONS.has(input.rejectionReason)) {
            throw new Error("Approval rejection reason is required");
        }
        if (input.rejectionReason === "other" && !reviewNote) {
            throw new Error("Approval rejection note is required for other");
        }
    }
    const db = requireDb();
    const approvalRef = db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE).doc(input.approvalId);
    const rejectionProjection = input.status === "rejected"
        ? input.rejectionReason === "evidence-weak-or-stale"
            ? { nextAction: "evidence" as const, status: "review" as const }
            : input.rejectionReason === "identity-uncertain"
                ? { nextAction: "enrich" as const, status: "review" as const }
                : input.rejectionReason === "contact-route-not-allowed" || input.rejectionReason === "other"
                    ? { nextAction: "hold" as const, status: "held" as const }
                    : { nextAction: "reject" as const, status: "rejected" as const }
        : null;
    let transactionResult: { blockedReason: string | null };
    try {
        transactionResult = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const currentApprovalSnap = await transaction.get(approvalRef);
            if (!currentApprovalSnap.exists) throw new Error("Approval not found");
            const currentApproval = toPlain(currentApprovalSnap.data()) as SignalDeskApprovalItem;
            if (currentApproval.status !== "pending") throw new Error("Approval is not pending");
            const draftRef = currentApproval.draftId
                ? db.collection(SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES).doc(currentApproval.draftId)
                : null;
            const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(currentApproval.targetId);
            const approvalPacketRef = currentApproval.approvalPacketId
                ? db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_PACKETS).doc(currentApproval.approvalPacketId)
                : null;
            const [currentDraftSnap, currentTargetSnap, currentApprovalPacketSnap] = await Promise.all([
                draftRef ? transaction.get(draftRef) : Promise.resolve(null),
                transaction.get(targetRef),
                approvalPacketRef ? transaction.get(approvalPacketRef) : Promise.resolve(null),
            ]);
            if (!currentTargetSnap.exists) throw new Error("Target not found");
            const currentTarget = toPlain(currentTargetSnap.data()) as SignalDeskTargetSummary;
            const currentDraft = currentDraftSnap?.exists
                ? toPlain(currentDraftSnap.data()) as SignalDeskDraftSummary
                : null;
            const currentApprovalPacket = currentApprovalPacketSnap?.exists
                ? toPlain(currentApprovalPacketSnap.data()) as SignalDeskApprovalPacketSummary
                : null;
            if (input.status === "approved") {
                if (!currentDraft) throw new Error("Draft is required before approval");
                if (
                    currentDraft.approvalId !== currentApproval.approvalId
                    || currentDraft.targetId !== currentApproval.targetId
                    || currentDraft.status !== "queued"
                ) {
                    throw new Error("Draft does not match pending approval");
                }
                if (
                    !currentApprovalPacket
                    || currentApprovalPacket.approvalId !== currentApproval.approvalId
                    || currentApprovalPacket.targetId !== currentApproval.targetId
                    || currentApprovalPacket.evidencePacketId !== currentDraft.evidencePacketId
                    || currentApprovalPacket.ctaId !== currentDraft.ctaId
                    || currentApprovalPacket.ctaFingerprintHash !== currentDraft.ctaFingerprintHash
                    || currentApprovalPacket.senderDomainId !== currentDraft.senderDomainId
                    || currentApprovalPacket.senderDomainFingerprintHash !== currentDraft.senderDomainFingerprintHash
                ) {
                    throw new Error("Approval packet does not match pending draft");
                }
                if (
                    currentTarget.latestApprovalId !== currentApproval.approvalId
                    || currentTarget.latestDraftId !== currentDraft.draftId
                ) {
                    throw new Error("Approval is stale");
                }
                const policyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(currentTarget.sourcePolicyId);
                const conversationRef = currentTarget.latestConversationId
                    ? db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES).doc(currentTarget.latestConversationId)
                    : null;
                const evidenceRef = currentDraft.evidencePacketId
                    ? db.collection(SIGNALDESK_COLLECTIONS.EVIDENCE_PACKET_SUMMARIES).doc(currentDraft.evidencePacketId)
                    : null;
                const ctaRef = currentApprovalPacket.ctaId
                    ? db.collection(SIGNALDESK_COLLECTIONS.SELF_SERVICE_CTAS).doc(currentApprovalPacket.ctaId)
                    : null;
                const senderRef = currentDraft.senderDomainId
                    ? db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(currentDraft.senderDomainId)
                    : null;
                const [policySnap, conversationSnap, evidenceSnap, ctaSnap, senderSnap] = await Promise.all([
                    transaction.get(policyRef),
                    conversationRef ? transaction.get(conversationRef) : Promise.resolve(null),
                    evidenceRef ? transaction.get(evidenceRef) : Promise.resolve(null),
                    ctaRef ? transaction.get(ctaRef) : Promise.resolve(null),
                    senderRef ? transaction.get(senderRef) : Promise.resolve(null),
                ]);
        const policy = readSourcePolicySnapshot(policySnap);
                const policyError = sourcePolicyUsabilityError(policy, {
                    entityId: currentApproval.targetId,
                    use: "approval",
                });
                if (policyError) throw new Error(policyError);
                const priorGuard = targetPriorGuard(
                    currentTarget,
                    conversationSnap?.exists ? conversationSnap.data() as AnyRecord : null,
                );
                if (
                    !priorGuard.clear
                    || currentTarget.nextAction !== "approve"
                    || currentTarget.segment === "reject"
                    || currentTarget.segment === "hold"
                ) {
                    throw new Error("Target is not approval-ready");
                }
                if (currentDraft.unsupportedClaims?.length) {
                    appendAudit(db, transaction, access, "approval_block", "approval", input.approvalId, "Draft has unsupported claims");
                    return { blockedReason: "Draft has unsupported claims" };
                }
                const currentSender = projectSenderDomainDocument(senderSnap);
                assertDraftSenderAuthority(currentDraft, currentSender);
                const currentCtaAuthority = await readSignalDeskCtaAuthority(db, transaction, {
                    ctaId: currentDraft.ctaId,
                    existingSnap: ctaSnap,
                    requireActive: true,
                });
                if (currentDraft.ctaFingerprintHash !== currentCtaAuthority.ctaFingerprintHash) {
                    throw new Error("CONTENT_CTA_STALE");
                }
                const expectedPacket = await buildApprovalPacketSummary(db, {
                    approval: currentApproval,
                    cta: currentCtaAuthority.cta,
                    draft: currentDraft,
                    evidence: evidenceSnap?.exists ? toPlain(evidenceSnap.data()) as SignalDeskEvidencePacketSummary : null,
                    priorGuard,
                    sender: currentSender,
                    sourcePolicy: policy,
                    target: currentTarget,
                });
                if (
                    !currentApprovalPacket.actionFingerprintHash
                    || currentApprovalPacket.actionFingerprintHash !== expectedPacket.actionFingerprintHash
                ) {
                    appendAudit(db, transaction, access, "approval_block", "approval", input.approvalId, "Approval packet is stale");
                    return { blockedReason: "Approval packet is stale" };
                }
                if (expectedPacket.recommendedAction !== "approve" || expectedPacket.allowedRoute === "none") {
                    appendAudit(db, transaction, access, "approval_block", "approval", input.approvalId, expectedPacket.riskSummary);
                    return { blockedReason: "Approval packet is not action-ready" };
                }
            }

            const timestamp = now();
            const reviewReason = input.status === "rejected"
                ? [input.rejectionReason, reviewNote].filter(Boolean).join(": ")
                : reviewNote || currentApproval.reviewReason;
            transaction.set(approvalRef, sanitizeForFirestore({
                rejectionReason: input.status === "rejected" ? input.rejectionReason : null,
                status: input.status,
                reviewReason,
                reviewedAt: timestamp,
                reviewedBy: access.userId,
                updatedAt: timestamp,
            }), { merge: true });
            if (draftRef) {
                transaction.set(draftRef, sanitizeForFirestore({
                    status: input.status,
                    updatedAt: timestamp,
                }), { merge: true });
            }
            transaction.set(targetRef, sanitizeForFirestore({
                nextAction: input.status === "approved" ? "export" : rejectionProjection?.nextAction,
                ...(rejectionProjection ? { status: rejectionProjection.status } : {}),
                updatedAt: timestamp,
            }), { merge: true });
            if (approvalPacketRef) {
                transaction.set(approvalPacketRef, sanitizeForFirestore({
                    status: input.status,
                    recommendedAction: input.status === "approved" ? "approve" : "reject",
                    updatedAt: timestamp,
                    updatedBy: access.userId,
                }), { merge: true });
            }
            appendAudit(db, transaction, access, `draft_${input.status}`, "approval", input.approvalId, reviewReason);
            updateQueueSummary(db, transaction, { approvalBacklog: increment(-1), humanReview: increment(-1) });
            updateDailyCost(db, transaction, 4, 0);
            return { blockedReason: null };
        });
    } catch (error) {
        const code = error instanceof Error ? error.message : "";
        if ([SOURCE_POLICY_EXPIRED, SOURCE_POLICY_REVIEW_REQUIRED, SOURCE_POLICY_RETENTION_MISSING, SOURCE_POLICY_USE_NOT_ALLOWED].includes(code)) {
            await appendSourcePolicyBlockedAudit(db, access, null, { entityId: input.approvalId, use: "approval" }, code);
        }
        throw error;
    }
    if (transactionResult.blockedReason) throw new Error(transactionResult.blockedReason);

    return {
        approvalId: input.approvalId,
        rejectionReason: input.status === "rejected" ? input.rejectionReason : null,
        status: input.status,
    };
}

const getAssistedRecipientForChannel = (targetDetail: AnyRecord, channel: Exclude<SignalDeskOutboundChannel, "manual">) => {
    if (channel === "email") return normalizeLower(targetDetail.email);
    if (channel === "whatsapp") return normalizeText(targetDetail.phone).replace(/[^\d+]/g, "");
    if (channel === "instagram") return normalizeLower(targetDetail.instagram).replace(/^@/, "");
    // Messenger has no safe public-handle assisted destination.
    if (channel === "messenger") return "";
    return "";
};

const getProviderRecipientForChannel = (targetDetail: AnyRecord, channel: Exclude<SignalDeskOutboundChannel, "manual">) => {
    if (channel === "email") return normalizeLower(targetDetail.email);
    if (channel === "whatsapp") return normalizeText(targetDetail.phone).replace(/[^\d+]/g, "");
    const providerScopedId = channel === "instagram"
        ? normalizeText(targetDetail.instagramRecipientId)
        : normalizeText(targetDetail.messengerRecipientId || targetDetail.messengerPsid);
    return /^[1-9]\d{4,39}$/.test(providerScopedId) ? providerScopedId : "";
};

const maskedRecipientPreview = (recipient: string, channel: Exclude<SignalDeskOutboundChannel, "manual">) => {
    if (channel === "email") {
        const [local, domain] = recipient.split("@");
        return local && domain ? `${local.slice(0, 1)}***@${domain}` : "email configured";
    }
    if (channel === "instagram") return recipient ? `@${recipient.slice(0, 1)}***` : "Instagram configured";
    const digits = recipient.replace(/\D/g, "");
    return digits ? `***${digits.slice(-4)}` : `${channel} configured`;
};

const canRevealSignalDeskContact = (access: SignalDeskAccessContext) => (
    access.permissions.includes("contact.reveal")
);

const getSuppressionIdentityForReply = (
    targetDetail: AnyRecord,
    channel: SignalDeskConversationSummary["channel"],
    targetId: string,
) => {
    const email = normalizeLower(targetDetail.email);
    const phone = normalizeText(targetDetail.phone).replace(/[^\d+]/g, "");
    const instagram = normalizeLower(targetDetail.instagram || targetDetail.instagramRecipientId).replace(/^@/, "");
    const messenger = normalizeText(targetDetail.messengerRecipientId || targetDetail.messengerPsid);
    const fallback = `${channel}_${hashValue(targetId)}`;

    if (channel === "email" && email) return { identityHash: hashValue(email), suppressionId: `email_${hashValue(email)}` };
    if (channel === "whatsapp" && phone) return { identityHash: hashValue(phone), suppressionId: `phone_${hashValue(phone)}` };
    if (channel === "instagram" && instagram) return { identityHash: hashValue(instagram), suppressionId: `instagram_${hashValue(instagram)}` };
    if (channel === "messenger" && messenger) return { identityHash: hashValue(messenger), suppressionId: `messenger_${hashValue(messenger)}` };
    return { identityHash: hashValue(targetId), suppressionId: fallback };
};

const suppressionLedgerRefsForRecipient = (
    db: FirebaseFirestore.Firestore,
    channel: Exclude<SignalDeskOutboundChannel, "manual">,
    recipient: string,
    aliases: string[] = [],
) => {
    const prefix = channel === "whatsapp" ? "phone" : channel;
    const values = channel === "whatsapp"
        ? [recipient, recipient.replace(/\D/g, ""), ...aliases]
        : [recipient, ...aliases];
    return Array.from(new Set(values.filter(Boolean))).map((value) => (
        db.collection(SIGNALDESK_COLLECTIONS.SUPPRESSION_LEDGER).doc(`${prefix}_${hashValue(value)}`)
    ));
};

const assertRecipientNotSuppressed = async (
    transaction: FirebaseFirestore.Transaction,
    db: FirebaseFirestore.Firestore,
    channel: Exclude<SignalDeskOutboundChannel, "manual">,
    recipient: string,
    aliases: string[] = [],
) => {
    const suppressionSnapshots = await Promise.all(
        suppressionLedgerRefsForRecipient(db, channel, recipient, aliases).map((reference) => transaction.get(reference)),
    );
    if (suppressionSnapshots.some((snapshot) => snapshot.exists)) throw new Error("Target is suppressed");
};

const writeChannelDeliveryState = (params: {
    access: SignalDeskAccessContext;
    approval: SignalDeskApprovalItem;
    batch: any;
    channel: Exclude<SignalDeskOutboundChannel, "manual">;
    db: any;
    draft: SignalDeskDraftSummary;
    providerMessageId?: string | null;
    providerName: string;
    recipientPreview: string;
    sender: SignalDeskSenderDomainSummary | null;
    status: "exported" | "sent";
    target: SignalDeskTargetSummary;
    exportRef: any;
}) => {
    const timestamp = now();
    const exportRef = params.exportRef;
    const conversationRef = params.db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES).doc(params.target.latestConversationId || `conv_${params.approval.targetId}`);
    params.batch.set(exportRef, sanitizeForFirestore({
        exportId: exportRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        approvalId: params.approval.approvalId,
        draftId: params.approval.draftId || null,
        targetId: params.approval.targetId,
        targetName: params.approval.targetName,
        channel: params.channel,
        ctaFingerprintHash: params.draft.ctaFingerprintHash || null,
        ctaId: params.draft.ctaId || null,
        subject: params.draft.subject,
        body: params.draft.body,
        provider: params.providerName,
        providerMessageId: params.providerMessageId || null,
        recipientPreview: params.recipientPreview,
        senderDomainFingerprintHash: params.sender ? senderDomainFingerprintHashFor(params.sender) : null,
        senderDomainId: params.sender?.senderDomainId || null,
        status: params.status,
        createdAt: timestamp,
        createdBy: params.access.userId,
    }));
    params.batch.set(conversationRef, sanitizeForFirestore({
        conversationId: conversationRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        targetId: params.approval.targetId,
        targetName: params.approval.targetName,
        channel: params.channel,
        state: params.status === "sent" ? "contacted" : "exported",
        lastMessagePreview: params.draft.subject,
        ...(params.status === "sent" ? { lastOutboundAt: timestamp } : {}),
        updatedAt: timestamp,
    }), { merge: true });
    params.batch.set(params.db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE).doc(params.approval.approvalId), sanitizeForFirestore({
        status: params.status,
        updatedAt: timestamp,
    }), { merge: true });
    if (params.approval.draftId) {
        params.batch.set(params.db.collection(SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES).doc(params.approval.draftId), sanitizeForFirestore({
            status: params.status,
            updatedAt: timestamp,
        }), { merge: true });
    }
    params.batch.set(params.db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(params.approval.targetId), sanitizeForFirestore({
        latestConversationId: conversationRef.id,
        nextAction: params.status === "sent" ? "reply" : "contact",
        status: params.status === "sent" ? "contacted" : params.target.status,
        updatedAt: timestamp,
    }), { merge: true });
    params.batch.set(params.db.collection(SIGNALDESK_COLLECTIONS.CHANNEL_HEALTH_SUMMARIES).doc(params.channel), sanitizeForFirestore({
        channel: params.channel,
        configured: params.status === "sent",
        lastEventAt: timestamp,
        status: params.status === "sent" ? "healthy" : "warning",
        updatedAt: timestamp,
    }), { merge: true });
    appendAudit(params.db, params.batch, params.access, params.status === "sent" ? "message_send" : "channel_handoff", "messageExport", exportRef.id, params.approval.targetName);
    return exportRef.id;
};

export async function prepareSignalDeskChannelHandoffServer(access: SignalDeskAccessContext, input: ChannelActionInput) {
    if (!FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_ASSISTED_CHANNELS) {
        throw new Error("SignalDesk assisted channels are disabled");
    }
    const db = requireDb();
    const operationHash = hashValue(`${input.approvalId}|${input.channel}|assisted-handoff-v1`).slice(0, 32);
    const exportRef = db.collection(SIGNALDESK_COLLECTIONS.MESSAGE_EXPORTS).doc(`handoff_${operationHash}`);
    try {
        return await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const priorExportSnap = await transaction.get(exportRef);
            if (priorExportSnap.exists) {
                const priorExport = toPlain(priorExportSnap.data()) as AnyRecord;
                await assertSignalDeskCtaLineage(db, transaction, priorExport);
                if (input.channel === "email") {
                    const priorSenderRef = normalizeText(priorExport.senderDomainId)
                        ? db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(priorExport.senderDomainId)
                        : null;
                    const priorSenderSnap = priorSenderRef ? await transaction.get(priorSenderRef) : null;
                    assertSenderDomainAuthorityBinding(priorExport, projectSenderDomainDocument(priorSenderSnap));
                }
                return {
                    channel: input.channel,
                    exportId: exportRef.id,
                    recipient: null,
                    recipientPreview: normalizeText(priorExport.recipientPreview) || null,
                    replay: true,
                    status: "handoff_ready",
                };
            }
            const approvalRef = db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE).doc(input.approvalId);
            const approvalSnap = await transaction.get(approvalRef);
            if (!approvalSnap.exists) throw new Error("Approval not found");
            const approval = toPlain(approvalSnap.data()) as SignalDeskApprovalItem;
            if (approval.status !== "approved" || !approval.draftId) {
                throw new Error("Approval must be approved before handoff");
            }
            const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(approval.targetId);
            const targetDetailRef = db.collection(SIGNALDESK_COLLECTIONS.TARGETS).doc(approval.targetId);
            const draftRef = db.collection(SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES).doc(approval.draftId);
            const globalPauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_global-outbound");
            const channelPauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc(`scope_${input.channel}`);
            const [targetSnap, targetDetailSnap, draftSnap, globalPauseSnap, channelPauseSnap] = await Promise.all([
                transaction.get(targetRef),
                transaction.get(targetDetailRef),
                transaction.get(draftRef),
                transaction.get(globalPauseRef),
                transaction.get(channelPauseRef),
            ]);
            if (!targetSnap.exists) throw new Error("Target not found");
            if (!draftSnap.exists) throw new Error("Draft is required before handoff");
            const target = toPlain(targetSnap.data()) as SignalDeskTargetSummary;
            const targetDetail = toPlain(targetDetailSnap.data() || {}) as AnyRecord;
            const draft = toPlain(draftSnap.data()) as SignalDeskDraftSummary;
            if (approval.targetId !== target.targetId
                || draft.targetId !== target.targetId
                || draft.approvalId !== approval.approvalId
                || target.latestApprovalId !== approval.approvalId
                || target.latestDraftId !== draft.draftId) {
                throw new Error("Assisted handoff truth is stale");
            }
            const conversationRef = db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES)
                .doc(target.latestConversationId || `conv_${target.targetId}`);
            const policyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(target.sourcePolicyId);
            const senderRef = input.channel === "email" && draft.senderDomainId
                ? db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(draft.senderDomainId)
                : null;
            const targetWindowRef = input.channel === "email" ? null : db.collection(SIGNALDESK_COLLECTIONS.CHANNEL_WINDOW_STATES)
                .doc(channelWindowIdFor(input.channel, target.targetId));
            const globalWindowRef = input.channel === "email" ? null : db.collection(SIGNALDESK_COLLECTIONS.CHANNEL_WINDOW_STATES)
                .doc(channelWindowIdFor(input.channel));
            const [conversationSnap, policySnap, senderSnap, targetWindowSnap, globalWindowSnap] = await Promise.all([
                transaction.get(conversationRef),
                transaction.get(policyRef),
                senderRef ? transaction.get(senderRef) : Promise.resolve(null),
                targetWindowRef ? transaction.get(targetWindowRef) : Promise.resolve(null),
                globalWindowRef ? transaction.get(globalWindowRef) : Promise.resolve(null),
            ]);
            const policy = readSourcePolicySnapshot(policySnap);
            const policyError = sourcePolicyUsabilityError(policy, {
                entityId: input.approvalId,
                use: input.channel === "email" ? "export" : "handoff",
            });
            if (policyError) throw new Error(policyError);
            if (globalPauseSnap.data()?.status === "active" || channelPauseSnap.data()?.status === "active") {
                throw new Error("Outbound export is paused");
            }
            if (target.suppressionStatus !== "clear") throw new Error("Target is suppressed");
            if (draft.status !== "approved" || !draft.evidencePacketId) {
                throw new Error("Draft must be approved before handoff");
            }
            await assertSignalDeskCtaLineage(db, transaction, draft);
            const priorGuard = targetPriorGuard(target, conversationSnap.exists ? conversationSnap.data() as AnyRecord : null);
            if (!priorGuard.clear) throw new Error("Target has prior contact or outcome");
            const recipient = getAssistedRecipientForChannel(targetDetail, input.channel);
            if (!recipient) throw new Error("ASSISTED_CHANNEL_RECIPIENT_NOT_SAFE");
            await assertRecipientNotSuppressed(transaction, db, input.channel, recipient);
            const recipientPreview = maskedRecipientPreview(recipient, input.channel);
            const sender = projectSenderDomainDocument(senderSnap);
            if (input.channel === "email" && target.contactability !== "ready") {
                throw new Error("Target contact is not export-ready");
            }
            if (input.channel === "email") assertDraftSenderAuthority(draft, sender);
            if (input.channel !== "email") {
                const targetWindow = targetWindowSnap?.exists
                    ? toPlain(targetWindowSnap.data()) as SignalDeskChannelWindowStateSummary
                    : null;
                const globalWindow = globalWindowSnap?.exists
                    ? toPlain(globalWindowSnap.data()) as SignalDeskChannelWindowStateSummary
                    : null;
                if (!isChannelWindowEligible(targetWindow) && !isChannelWindowEligible(globalWindow)) {
                    throw new Error("Channel window is not ready");
                }
            }
            writeChannelDeliveryState({
                access,
                approval,
                batch: transaction,
                channel: input.channel,
                db,
                draft,
                exportRef,
                providerName: "assisted-handoff",
                recipientPreview,
                sender: input.channel === "email" ? sender : null,
                status: "exported",
                target,
            });
            const revealRecipient = canRevealSignalDeskContact(access);
            if (revealRecipient) {
                appendAudit(db, transaction, access, "contact_recipient_reveal", "messageExport", exportRef.id, input.channel);
            }
            updateDailyCost(db, transaction, 7, 0, 0);
            return {
                channel: input.channel,
                exportId: exportRef.id,
                recipient: revealRecipient ? recipient : null,
                recipientPreview,
                status: "handoff_ready",
            };
        });
    } catch (error) {
        const code = error instanceof Error ? error.message : "";
        if ([SOURCE_POLICY_EXPIRED, SOURCE_POLICY_REVIEW_REQUIRED, SOURCE_POLICY_RETENTION_MISSING, SOURCE_POLICY_USE_NOT_ALLOWED].includes(code)) {
            await appendSourcePolicyBlockedAudit(db, access, null, {
                entityId: input.approvalId,
                use: input.channel === "email" ? "export" : "handoff",
            }, code);
        }
        throw error;
    }
}

export async function sendSignalDeskApprovedMessageServer(access: SignalDeskAccessContext, input: ChannelActionInput) {
    if (!FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_PROVIDER_SEND) {
        throw new Error("SignalDesk provider send is disabled");
    }
    const db = requireDb();
    const operationHash = hashValue(`${input.approvalId}|${input.channel}|provider-send-v1`).slice(0, 32);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`provider_send_${operationHash}`);
    const exportRef = db.collection(SIGNALDESK_COLLECTIONS.MESSAGE_EXPORTS).doc(`send_${operationHash}`);
    const start = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const [claimSnap, exportSnap] = await Promise.all([
            transaction.get(claimRef),
            transaction.get(exportRef),
        ]);
        if (claimSnap.exists) {
            const claim = toPlain(claimSnap.data()) as AnyRecord;
            if (claim.status === "completed" && exportSnap.exists) {
                const historicalExport = toPlain(exportSnap.data()) as AnyRecord;
                let currentCtaAuthority = true;
                try {
                    await assertSignalDeskCtaLineage(db, transaction, historicalExport);
                } catch {
                    currentCtaAuthority = false;
                }
                const historicalSenderDomainId = normalizeText(historicalExport.senderDomainId);
                const historicalSenderSnap = historicalSenderDomainId
                    ? await transaction.get(db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(historicalSenderDomainId))
                    : null;
                const currentSenderAuthority = input.channel !== "email" || isSenderDomainAuthorityBindingCurrent(
                    historicalExport,
                    projectSenderDomainDocument(historicalSenderSnap),
                );
                return {
                    context: null,
                    currentCtaAuthority,
                    currentSenderAuthority,
                    replay: {
                        exportId: historicalExport.exportId,
                        providerMessageId: historicalExport.providerMessageId || null,
                    },
                };
            }
            throw new Error("PROVIDER_SEND_REVIEW_REQUIRED");
        }
        const approvalRef = db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE).doc(input.approvalId);
        const approvalSnap = await transaction.get(approvalRef);
        if (!approvalSnap.exists) throw new Error("Approval not found");
        const approval = toPlain(approvalSnap.data()) as SignalDeskApprovalItem;
        if (approval.status !== "approved" || !approval.draftId) throw new Error("Approval must be approved before send");
        const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(approval.targetId);
        const targetDetailRef = db.collection(SIGNALDESK_COLLECTIONS.TARGETS).doc(approval.targetId);
        const draftRef = db.collection(SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES).doc(approval.draftId);
        const globalPauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_global-outbound");
        const channelPauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc(`scope_${input.channel}`);
        const [targetSnap, targetDetailSnap, draftSnap, globalPauseSnap, channelPauseSnap] = await Promise.all([
            transaction.get(targetRef),
            transaction.get(targetDetailRef),
            transaction.get(draftRef),
            transaction.get(globalPauseRef),
            transaction.get(channelPauseRef),
        ]);
        if (!targetSnap.exists) throw new Error("Target not found");
        if (!draftSnap.exists) throw new Error("Draft is required before send");
        const target = toPlain(targetSnap.data()) as SignalDeskTargetSummary;
        const targetDetail = toPlain(targetDetailSnap.data() || {}) as AnyRecord;
        const draft = toPlain(draftSnap.data()) as SignalDeskDraftSummary;
        if (draft.targetId !== target.targetId
            || draft.approvalId !== approval.approvalId
            || target.latestApprovalId !== approval.approvalId
            || target.latestDraftId !== draft.draftId) {
            throw new Error("Approved send truth is stale");
        }
        const conversationRef = db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES)
            .doc(target.latestConversationId || `conv_${target.targetId}`);
        const policyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(target.sourcePolicyId);
        const senderRef = input.channel === "email" && draft.senderDomainId
            ? db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(draft.senderDomainId)
            : null;
        const targetWindowRef = input.channel === "email" ? null : db.collection(SIGNALDESK_COLLECTIONS.CHANNEL_WINDOW_STATES)
            .doc(channelWindowIdFor(input.channel, target.targetId));
        const globalWindowRef = input.channel === "email" ? null : db.collection(SIGNALDESK_COLLECTIONS.CHANNEL_WINDOW_STATES)
            .doc(channelWindowIdFor(input.channel));
        const [conversationSnap, policySnap, senderSnap, targetWindowSnap, globalWindowSnap] = await Promise.all([
            transaction.get(conversationRef),
            transaction.get(policyRef),
            senderRef ? transaction.get(senderRef) : Promise.resolve(null),
            targetWindowRef ? transaction.get(targetWindowRef) : Promise.resolve(null),
            globalWindowRef ? transaction.get(globalWindowRef) : Promise.resolve(null),
        ]);
        const policy = readSourcePolicySnapshot(policySnap);
        const policyError = sourcePolicyUsabilityError(policy, { entityId: input.approvalId, use: "send" });
        if (policyError) throw new Error(policyError);
        if (globalPauseSnap.data()?.status === "active" || channelPauseSnap.data()?.status === "active") {
            throw new Error("Outbound export is paused");
        }
        if (target.suppressionStatus !== "clear") throw new Error("Target is suppressed");
        if (draft.status !== "approved" || !draft.evidencePacketId) throw new Error("Draft must be approved before send");
        const priorGuard = targetPriorGuard(target, conversationSnap.exists ? conversationSnap.data() as AnyRecord : null);
        if (!priorGuard.clear) throw new Error("Target has prior contact or outcome");
        const recipient = getProviderRecipientForChannel(targetDetail, input.channel);
        if (!recipient) throw new Error("PROVIDER_SCOPED_RECIPIENT_REQUIRED");
        const suppressionAliases = input.channel === "instagram"
            ? [normalizeLower(targetDetail.instagram).replace(/^@/, "")]
            : [];
        await assertRecipientNotSuppressed(transaction, db, input.channel, recipient, suppressionAliases);
        const sender = projectSenderDomainDocument(senderSnap);
        if (input.channel === "email" && target.contactability !== "ready") throw new Error("Target contact is not export-ready");
        if (input.channel === "email") assertDraftSenderAuthority(draft, sender);
        const ctaAuthority = await assertSignalDeskCtaLineage(db, transaction, draft);
        if (input.channel !== "email") {
            const targetWindow = targetWindowSnap?.exists
                ? toPlain(targetWindowSnap.data()) as SignalDeskChannelWindowStateSummary
                : null;
            const globalWindow = globalWindowSnap?.exists
                ? toPlain(globalWindowSnap.data()) as SignalDeskChannelWindowStateSummary
                : null;
            if (!isChannelWindowEligible(targetWindow) && !isChannelWindowEligible(globalWindow)) {
                throw new Error("Channel window is not ready");
            }
        }
        if (input.channel === "email") {
            assertSignalDeskEmailSenderDomainAuthority(sender?.domain || null);
        } else {
            const readiness = getSignalDeskChannelReadiness()[input.channel];
            if (!readiness?.configured) throw new Error("Channel provider is not configured");
        }
        const requestFingerprintHash = hashValue(JSON.stringify({
            approvalId: approval.approvalId,
            body: draft.body,
            channel: input.channel,
            ctaFingerprintHash: ctaAuthority.ctaFingerprintHash,
            ctaId: ctaAuthority.cta.ctaId,
            draftId: draft.draftId,
            recipientHash: hashValue(recipient),
            senderDomainFingerprintHash: input.channel === "email" && sender ? senderDomainFingerprintHashFor(sender) : null,
            senderDomainId: input.channel === "email" ? sender?.senderDomainId || null : null,
            subject: draft.subject,
            targetId: target.targetId,
        }));
        const timestamp = now();
        const senderReservation = input.channel === "email"
            ? await reserveSignalDeskOwnedEmailSenderCapacity(db, transaction, timestamp)
            : null;
        transaction.create(claimRef, sanitizeForFirestore({
            ...(senderReservation || {}),
            actorId: access.userId,
            claimId: claimRef.id,
            entityId: exportRef.id,
            operation: "provider_send",
            pId: SIGNALDESK_PRODUCT_CODE,
            ctaFingerprintHash: ctaAuthority.ctaFingerprintHash,
            ctaId: ctaAuthority.cta.ctaId,
            requestFingerprintHash,
            status: "running",
            updatedAt: timestamp,
        }));
        appendAudit(db, transaction, access, "provider_send_started", "messageExport", exportRef.id, input.channel);
        updateDailyCost(db, transaction, 4, 0);
        return {
            currentCtaAuthority: true,
            currentSenderAuthority: true,
            replay: null,
            context: { approval, draft, recipient, requestFingerprintHash, sender, target },
        };
    });
    if (start.replay) {
        return {
            channel: input.channel,
            exportId: start.replay.exportId,
            providerMessageId: start.replay.providerMessageId || null,
            currentAuthority: start.currentCtaAuthority && start.currentSenderAuthority,
            historicalReplay: true,
            replay: true,
            status: "sent",
        };
    }
    if (!start.context) throw new Error("PROVIDER_SEND_REVIEW_REQUIRED");
    const { approval, draft, recipient, requestFingerprintHash, sender, target } = start.context;
    let providerResult: Awaited<ReturnType<typeof sendSignalDeskProviderMessage>>;
    try {
        providerResult = await sendSignalDeskProviderMessage({
            body: draft.body,
            channel: input.channel,
            recipient,
            senderDomain: input.channel === "email" ? sender?.domain || null : null,
            subject: draft.subject,
        });
    } catch (error) {
        await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const claimSnap = await transaction.get(claimRef);
            if (claimSnap.exists && claimSnap.data()?.status === "running") {
                transaction.set(claimRef, sanitizeForFirestore({
                    failureCode: "provider_send_outcome_unresolved",
                    status: "unresolved",
                    updatedAt: now(),
                }), { merge: true });
                appendAudit(db, transaction, access, "provider_send_unresolved", "messageExport", exportRef.id, input.channel);
                updateDailyCost(db, transaction, 3, 0);
            }
        });
        throw new Error("PROVIDER_SEND_OUTCOME_UNRESOLVED", { cause: error });
    }

    try {
        await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const claimSnap = await transaction.get(claimRef);
            if (!claimSnap.exists
                || claimSnap.data()?.status !== "running"
                || claimSnap.data()?.requestFingerprintHash !== requestFingerprintHash) {
                throw new Error("PROVIDER_SEND_REVIEW_REQUIRED");
            }
            await assertSignalDeskCtaLineage(db, transaction, draft);
            writeChannelDeliveryState({
                access,
                approval,
                batch: transaction,
                channel: input.channel,
                db,
                draft,
                exportRef,
                providerMessageId: providerResult.providerMessageId,
                providerName: providerResult.provider,
                recipientPreview: maskedRecipientPreview(recipient, input.channel),
                sender: input.channel === "email" ? sender : null,
                status: "sent",
                target,
            });
            transaction.set(claimRef, sanitizeForFirestore({
                completedAt: now(),
                providerMessageId: providerResult.providerMessageId || null,
                providerName: providerResult.provider,
                status: "completed",
                updatedAt: now(),
            }), { merge: true });
            updateDailyCost(db, transaction, 9, 0, 0.01);
        });
    } catch (error) {
        const [claimSnap, exportSnap] = await Promise.all([claimRef.get(), exportRef.get()]);
        if (claimSnap.data()?.status !== "completed" || !exportSnap.exists) {
            await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
                const currentClaimSnap = await transaction.get(claimRef);
                if (currentClaimSnap.exists && currentClaimSnap.data()?.status === "running") {
                    transaction.set(claimRef, sanitizeForFirestore({
                        failureCode: "provider_send_persistence_unresolved",
                        providerMessageId: providerResult.providerMessageId || null,
                        providerName: providerResult.provider,
                        status: "unresolved",
                        updatedAt: now(),
                    }), { merge: true });
                    appendAudit(db, transaction, access, "provider_send_unresolved", "messageExport", exportRef.id, input.channel);
                    updateDailyCost(db, transaction, 3, 0);
                }
            });
            throw new Error("PROVIDER_SEND_OUTCOME_UNRESOLVED", { cause: error });
        }
    }
    return {
        channel: input.channel,
        exportId: exportRef.id,
        providerMessageId: providerResult.providerMessageId || null,
        status: "sent",
    };
}

export async function exportSignalDeskMessageServer(access: SignalDeskAccessContext, approvalId: string) {
    const db = requireDb();
    const exportRef = db.collection(SIGNALDESK_COLLECTIONS.MESSAGE_EXPORTS)
        .doc(`export_${hashValue(`${approvalId}|email-export-v1`).slice(0, 32)}`);
    try {
        return await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const priorExportSnap = await transaction.get(exportRef);
            if (priorExportSnap.exists) {
                const priorExport = toPlain(priorExportSnap.data()) as AnyRecord;
                await assertSignalDeskCtaLineage(db, transaction, priorExport);
                const priorSenderRef = normalizeText(priorExport.senderDomainId)
                    ? db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(priorExport.senderDomainId)
                    : null;
                const priorSenderSnap = priorSenderRef ? await transaction.get(priorSenderRef) : null;
                assertSenderDomainAuthorityBinding(priorExport, projectSenderDomainDocument(priorSenderSnap));
                return priorExport;
            }
            const approvalRef = db.collection(SIGNALDESK_COLLECTIONS.APPROVAL_QUEUE).doc(approvalId);
            const approvalSnap = await transaction.get(approvalRef);
            if (!approvalSnap.exists) throw new Error("Approval not found");
            const approval = toPlain(approvalSnap.data()) as SignalDeskApprovalItem;
            if (approval.status !== "approved") throw new Error("Approval must be approved before export");
            if (!approval.draftId) throw new Error("Draft is required before export");
            const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(approval.targetId);
            const draftRef = db.collection(SIGNALDESK_COLLECTIONS.DRAFT_SUMMARIES).doc(approval.draftId);
            const [targetSnap, draftSnap, globalPauseSnap, emailPauseSnap] = await Promise.all([
                transaction.get(targetRef),
                transaction.get(draftRef),
                transaction.get(db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_global-outbound")),
                transaction.get(db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_email")),
            ]);
            if (!targetSnap.exists) throw new Error("Target not found");
            if (!draftSnap.exists) throw new Error("Draft is required before export");
            const target = toPlain(targetSnap.data()) as SignalDeskTargetSummary;
            const draft = toPlain(draftSnap.data()) as SignalDeskDraftSummary;
            if (draft.targetId !== target.targetId
                || draft.approvalId !== approvalId
                || target.latestApprovalId !== approvalId
                || target.latestDraftId !== draft.draftId) {
                throw new Error("Approved export truth is stale");
            }
            const conversationRef = db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES)
                .doc(target.latestConversationId || `conv_${approval.targetId}`);
            const senderRef = draft.senderDomainId
                ? db.collection(SIGNALDESK_COLLECTIONS.SENDER_DOMAINS).doc(draft.senderDomainId)
                : null;
            const [policySnap, senderSnap, conversationSnap] = await Promise.all([
                transaction.get(db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(target.sourcePolicyId)),
                senderRef ? transaction.get(senderRef) : Promise.resolve(null),
                transaction.get(conversationRef),
            ]);
            const policy = readSourcePolicySnapshot(policySnap);
            const policyError = sourcePolicyUsabilityError(policy, { entityId: approvalId, use: "export" });
            if (policyError) throw new Error(policyError);
            if (!policy) throw new Error(SOURCE_POLICY_REVIEW_REQUIRED);
            if (globalPauseSnap.data()?.status === "active" || emailPauseSnap.data()?.status === "active") {
                throw new Error("Outbound export is paused");
            }
            if (target.suppressionStatus !== "clear") throw new Error("Target is suppressed");
            if (!resolveAllowedUse(policy).contact) throw new Error("Contact use is not approved for this target");
            if (target.contactability !== "ready") throw new Error("Target contact is not export-ready");
            if (draft.status !== "approved") throw new Error("Draft must be approved before export");
            if (!draft.evidencePacketId) throw new Error("Evidence packet is required before draft");
            const sender = projectSenderDomainDocument(senderSnap);
            assertDraftSenderAuthority(draft, sender);
            const ctaAuthority = await assertSignalDeskCtaLineage(db, transaction, draft);
            const priorGuard = targetPriorGuard(target, conversationSnap.exists ? conversationSnap.data() as AnyRecord : null);
            if (!priorGuard.clear) throw new Error("Target has prior contact or outcome");

            const timestamp = now();
            const exportData = {
                exportId: exportRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                approvalId,
                draftId: approval.draftId,
                targetId: approval.targetId,
                targetName: approval.targetName,
                channel: "email",
                ctaFingerprintHash: ctaAuthority.ctaFingerprintHash,
                ctaId: ctaAuthority.cta.ctaId,
                subject: draft.subject,
                body: draft.body,
                senderDomainFingerprintHash: senderDomainFingerprintHashFor(sender),
                senderDomainId: sender.senderDomainId,
                status: "exported",
                createdAt: timestamp,
                createdBy: access.userId,
            };
            transaction.create(exportRef, sanitizeForFirestore(exportData));
            transaction.set(conversationRef, sanitizeForFirestore({
                conversationId: conversationRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                targetId: approval.targetId,
                targetName: approval.targetName,
                channel: "email",
                state: "exported",
                lastMessagePreview: draft.subject,
                updatedAt: timestamp,
            }), { merge: true });
            transaction.set(approvalRef, sanitizeForFirestore({ status: "exported", updatedAt: timestamp }), { merge: true });
            transaction.set(draftRef, sanitizeForFirestore({ status: "exported", updatedAt: timestamp }), { merge: true });
            transaction.set(targetRef, sanitizeForFirestore({
                latestConversationId: conversationRef.id,
                nextAction: "contact",
                status: target.status,
                updatedAt: timestamp,
            }), { merge: true });
            appendAudit(db, transaction, access, "message_export", "messageExport", exportRef.id, approval.targetName);
            updateDailyCost(db, transaction, 7, 0);
            return toPlain(exportData);
        });
    } catch (error) {
        const code = error instanceof Error ? error.message : "";
        if ([SOURCE_POLICY_EXPIRED, SOURCE_POLICY_REVIEW_REQUIRED, SOURCE_POLICY_RETENTION_MISSING, SOURCE_POLICY_USE_NOT_ALLOWED].includes(code)) {
            await appendSourcePolicyBlockedAudit(db, access, null, { entityId: approvalId, use: "export" }, code);
        }
        throw error;
    }
}

export async function recordSignalDeskManualContactServer(access: SignalDeskAccessContext, input: ManualContactInput) {
    const occurredAtMillis = new Date(input.occurredAt).getTime();
    const currentMillis = Date.now();
    if (!Number.isFinite(occurredAtMillis)
        || occurredAtMillis > currentMillis + MANUAL_CONTACT_FUTURE_SKEW_MS
        || occurredAtMillis < currentMillis - MANUAL_CONTACT_MAX_AGE_MS) {
        throw new Error("Manual contact timestamp is invalid");
    }
    if (input.result === "introduced" && input.route !== "partner-intro") {
        throw new Error("Manual contact result does not match route");
    }

    const db = requireDb();
    const note = normalizeText(input.note);
    const idempotencyHash = hashValue(`${access.userId}:${input.targetId}:${input.idempotencyKey}`);
    const requestFingerprintHash = hashValue(JSON.stringify({
        note,
        occurredAt: new Date(occurredAtMillis).toISOString(),
        result: input.result,
        route: input.route,
        sourcePolicyId: input.sourcePolicyId,
        targetId: input.targetId,
    }));
    const timelineRef = db.collection(SIGNALDESK_COLLECTIONS.RUN_TIMELINES).doc(`manual_contact_${idempotencyHash.slice(0, 32)}`);
    const existingTimelineSnap = await timelineRef.get();
    if (existingTimelineSnap.exists) {
        if (existingTimelineSnap.data()?.requestFingerprintHash !== requestFingerprintHash) {
            throw new Error("Manual contact idempotency conflict");
        }
        return {
            duplicate: true,
            manualContactId: timelineRef.id,
            result: input.result,
            route: input.route,
            targetId: input.targetId,
        };
    }
    const [targetSnap, targetDetailSnap] = await Promise.all([
        db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(input.targetId).get(),
        db.collection(SIGNALDESK_COLLECTIONS.TARGETS).doc(input.targetId).get(),
    ]);
    if (!targetSnap.exists) throw new Error("Target not found");
    const target = toPlain(targetSnap.data()) as SignalDeskTargetSummary;
    const targetDetail = toPlain(targetDetailSnap.data() || {}) as AnyRecord;
    if (target.sourcePolicyId !== input.sourcePolicyId) throw new Error("Manual contact source policy changed");
    if (target.suppressionStatus !== "clear") throw new Error("Target is suppressed");
    if (target.status === "rejected" || target.status === "converted") throw new Error("Target is not eligible for manual contact");

    const policy = await assertSourcePolicyUsable(db, access, await readSourcePolicy(db, target.sourcePolicyId), {
        entityId: input.targetId,
        use: "contact",
    });
    await requireNoActiveKillSwitch(db, "global-outbound", "Outbound contact is paused");
    if (input.route === "email-export") await requireNoActiveKillSwitch(db, "email", "Outbound contact is paused");
    if (input.route === "partner-intro") await requireNoActiveKillSwitch(db, "trust-partner", "Outbound contact is paused");

    const allowedRoutes = new Set<SignalDeskManualContactRoute>();
    if (target.contactability === "ready") allowedRoutes.add("email-export");
    if (policy.accessMethod === "permissioned-referral") allowedRoutes.add("partner-intro");
    if (!allowedRoutes.has(input.route)) throw new Error("Manual contact route is not allowed");

    if (input.route === "email-export") {
        const conversationSnap = await db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES)
            .doc(target.latestConversationId || `conv_${input.targetId}`)
            .get();
        const conversation = conversationSnap.exists
            ? toPlain(conversationSnap.data()) as SignalDeskConversationSummary
            : null;
        if (conversation?.state !== "exported") throw new Error("Prepared email export is required");
        const exportSnap = await db.collection(SIGNALDESK_COLLECTIONS.MESSAGE_EXPORTS)
            .where("targetId", "==", input.targetId)
            .limit(20)
            .get();
        const preparedExport = exportSnap.docs.some((doc: any) => {
            const data = doc.data() as AnyRecord;
            const preparedAt = toTimestampMillis(data.createdAt);
            return data.status === "exported" && Boolean(
                preparedAt
                && preparedAt <= occurredAtMillis
                && preparedAt >= currentMillis - MANUAL_CONTACT_MAX_AGE_MS
            );
        });
        if (!preparedExport) throw new Error("Prepared email export is required");
    }

    const conversationRef = db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES).doc(target.latestConversationId || `conv_${input.targetId}`);
    const occurredAt = admin.firestore.Timestamp.fromDate(new Date(occurredAtMillis));
    const timestamp = now();
    const channel: SignalDeskConversationSummary["channel"] = input.route === "email-export" ? "email" : "manual";
    const conversationState: SignalDeskConversationSummary["state"] = input.result === "wrong-contact"
        ? "wrong_contact"
        : input.result === "declined"
            ? "not_interested"
            : "contacted";
    const nextAction: SignalDeskNextAction = input.result === "contacted" || input.result === "introduced"
        ? "reply"
        : input.result === "declined"
            ? "reject"
            : "hold";
    const nextStatus: SignalDeskTargetSummary["status"] = input.result === "wrong-contact" || input.result === "declined"
        ? "rejected"
        : "contacted";
    const eventSummary = `${input.route}:${input.result}`;

    const batch = db.batch();
    batch.create(timelineRef, sanitizeForFirestore({
        runTimelineId: timelineRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        entityType: "target",
        entityId: input.targetId,
        idempotencyKeyHash: idempotencyHash,
        requestFingerprintHash,
        label: "Manual contact attempt",
        result: input.result,
        route: input.route,
        status: input.result === "wrong-contact" || input.result === "declined" ? "held" : "completed",
        steps: [
            { label: `Policy-approved route: ${input.route}`, status: "completed", at: toIso(occurredAt) },
            { label: `Founder-recorded result: ${input.result}`, status: input.result === "wrong-contact" ? "blocked" : "completed", at: toIso(occurredAt) },
        ],
        sourcePolicyId: input.sourcePolicyId,
        updatedAt: timestamp,
    }));
    batch.set(conversationRef, sanitizeForFirestore({
        conversationId: conversationRef.id,
        pId: SIGNALDESK_PRODUCT_CODE,
        targetId: input.targetId,
        targetName: target.displayName,
        channel,
        state: conversationState,
        lastMessagePreview: `Manual contact: ${input.result} via ${input.route}`,
        lastOutboundAt: occurredAt,
        updatedAt: timestamp,
    }), { merge: true });
    batch.set(targetSnap.ref, sanitizeForFirestore({
        ...(input.result === "wrong-contact" ? {
            contactability: "blocked",
            suppressionStatus: "wrong-contact",
        } : {}),
        latestConversationId: conversationRef.id,
        latestManualContactAt: occurredAt,
        latestManualContactResult: input.result,
        latestManualContactRoute: input.route,
        nextAction,
        status: nextStatus,
        updatedAt: timestamp,
    }), { merge: true });
    if (input.result === "wrong-contact") {
        const suppressionIdentity = getSuppressionIdentityForReply(targetDetail, channel, input.targetId);
        batch.set(db.collection(SIGNALDESK_COLLECTIONS.SUPPRESSION_LEDGER).doc(suppressionIdentity.suppressionId), sanitizeForFirestore({
            suppressionId: suppressionIdentity.suppressionId,
            pId: SIGNALDESK_PRODUCT_CODE,
            targetId: input.targetId,
            identityHash: suppressionIdentity.identityHash,
            channel,
            reason: "wrong-contact",
            source: "manual-contact",
            createdAt: timestamp,
        }), { merge: true });
    }
    appendAudit(db, batch, access, "manual_contact_record", "target", input.targetId, [eventSummary, note].filter(Boolean).join(": "));
    updateDailyCost(db, batch, input.result === "wrong-contact" ? 6 : 5, 0);

    try {
        await batch.commit();
    } catch (error) {
        if (!isAlreadyExistsError(error)) throw error;
        const concurrentTimelineSnap = await timelineRef.get();
        if (!concurrentTimelineSnap.exists || concurrentTimelineSnap.data()?.requestFingerprintHash !== requestFingerprintHash) {
            throw new Error("Manual contact idempotency conflict");
        }
        return {
            duplicate: true,
            manualContactId: timelineRef.id,
            result: input.result,
            route: input.route,
            targetId: input.targetId,
        };
    }

    return {
        duplicate: false,
        manualContactId: timelineRef.id,
        result: input.result,
        route: input.route,
        targetId: input.targetId,
    };
}

export async function captureSignalDeskReplyServer(access: SignalDeskAccessContext, input: {
    channel: SignalDeskConversationSummary["channel"];
    idempotencyKey: string;
    message: string;
    targetId: string;
}) {
    const idempotencyKey = normalizeText(input.idempotencyKey);
    const message = input.message.trim();
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("Reply idempotency key is required");
    if (!message || message.length > 4000) throw new Error("Reply message is invalid");
    const db = requireDb();
    const state = classifyReply(message);
    const requestFingerprintHash = hashValue(JSON.stringify({
        channel: input.channel,
        message,
        targetId: input.targetId,
    }));
    const requiresIncidentPause = state === "complaint" || state === "privacy_request" || state === "legal_request";
    const pendingMissionRef = requiresIncidentPause
        ? db.collection(SIGNALDESK_COLLECTIONS.GROWTH_MISSIONS).doc(growthMissionIdFor(todayKey()))
        : null;
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`).slice(0, 32);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`reply_capture_${operationHash}`);
    const transactionResult = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const claimSnap = await transaction.get(claimRef);
        if (claimSnap.exists) {
            const claim = toPlain(claimSnap.data()) as AnyRecord;
            if (claim.actorId !== access.userId || claim.requestFingerprintHash !== requestFingerprintHash) {
                throw new Error("Reply idempotency conflict");
            }
            return {
                conversationId: String(claim.conversationId || ""),
                duplicate: true,
                revenueSyncStatus: (claim.revenueSyncStatus || "pending") as "not-applicable" | "updated" | "pending",
                state: claim.replyState as SignalDeskConversationSummary["state"],
            };
        }
        const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(input.targetId);
        const targetDetailRef = db.collection(SIGNALDESK_COLLECTIONS.TARGETS).doc(input.targetId);
        const [targetSnap, targetDetailSnap, pendingMissionSnap] = await Promise.all([
            transaction.get(targetRef),
            transaction.get(targetDetailRef),
            pendingMissionRef ? transaction.get(pendingMissionRef) : Promise.resolve(null),
        ]);
        if (!targetSnap.exists) throw new Error("Target not found");
        const persistedOwnerQualifiedAt = targetSnap.data()?.ownerQualifiedAt || null;
        const target = toPlain(targetSnap.data()) as SignalDeskTargetSummary;
        const targetDetail = toPlain(targetDetailSnap.data() || {}) as AnyRecord;
        const conversationRef = db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES)
            .doc(target.latestConversationId || `conv_${input.targetId}`);
        await transaction.get(conversationRef);
        const timestamp = now();
        const messageRef = db.collection(SIGNALDESK_COLLECTIONS.MESSAGES).doc(`reply_message_${operationHash}`);
        const classificationRef = db.collection(SIGNALDESK_COLLECTIONS.REPLY_CLASSIFICATIONS).doc(`reply_classification_${operationHash}`);
        const requiresSuppression = state === "dnc"
            || state === "wrong_contact"
            || state === "complaint"
            || state === "privacy_request"
            || state === "legal_request";
        const missionPatch = pendingMissionRef && pendingMissionSnap
            ? criticalReplyGrowthMissionPatch({
                conversationId: conversationRef.id,
                missionSnap: pendingMissionSnap,
                state,
                timestamp,
            })
            : null;
        transaction.set(conversationRef, sanitizeForFirestore({
            conversationId: conversationRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            targetId: input.targetId,
            targetName: target.displayName,
            channel: input.channel,
            state,
            lastMessagePreview: message.slice(0, 180),
            lastInboundAt: timestamp,
            updatedAt: timestamp,
        }), { merge: true });
        transaction.create(messageRef, sanitizeForFirestore({
            messageId: messageRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            conversationId: conversationRef.id,
            targetId: input.targetId,
            direction: "inbound",
            body: message,
            channel: input.channel,
            createdAt: timestamp,
        }));
        transaction.create(classificationRef, sanitizeForFirestore({
            classificationId: classificationRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            conversationId: conversationRef.id,
            targetId: input.targetId,
            state,
            confidence: state === "needs_review" ? "low" : "high",
            classifierVersion: "rules-v1",
            createdAt: timestamp,
        }));
        if (requiresSuppression) {
            const suppressionIdentity = getSuppressionIdentityForReply(targetDetail, input.channel, input.targetId);
            transaction.set(db.collection(SIGNALDESK_COLLECTIONS.SUPPRESSION_LEDGER).doc(suppressionIdentity.suppressionId), sanitizeForFirestore({
                suppressionId: suppressionIdentity.suppressionId,
                pId: SIGNALDESK_PRODUCT_CODE,
                targetId: input.targetId,
                identityHash: suppressionIdentity.identityHash,
                channel: input.channel,
                reason: state === "dnc" ? "dnc" : state === "wrong_contact" ? "wrong-contact" : state,
                source: "inbound",
                createdAt: timestamp,
            }), { merge: true });
        }
        if (requiresIncidentPause) {
            const incidentRef = db.collection(SIGNALDESK_COLLECTIONS.INCIDENTS).doc(`reply_incident_${operationHash}`);
            const pauseScope = input.channel === "manual" ? "global-outbound" : input.channel;
            transaction.create(incidentRef, sanitizeForFirestore({
                incidentId: incidentRef.id,
                pId: SIGNALDESK_PRODUCT_CODE,
                severity: state === "complaint" ? "high" : "critical",
                status: "open",
                title: `${state.replace(/_/g, " ")} requires founder review`,
                targetId: input.targetId,
                channel: input.channel,
                createdAt: timestamp,
                updatedAt: timestamp,
            }));
            transaction.set(db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc(`scope_${pauseScope}`), sanitizeForFirestore({
                killSwitchId: `scope_${pauseScope}`,
                pId: SIGNALDESK_PRODUCT_CODE,
                scope: pauseScope,
                status: "active",
                reason: `${state} received; outbound paused pending founder review.`,
                activatedAt: timestamp,
                activatedBy: access.userId,
                updatedAt: timestamp,
            }), { merge: true });
            appendAudit(db, transaction, access, "reply_incident_pause", "conversation", conversationRef.id, `${state}:${pauseScope}`);
            updateControlSummary(db, transaction, { incidentCount: increment(1), safetyStatus: "blocked" });
        }
        if (pendingMissionRef && missionPatch) {
            transaction.set(pendingMissionRef, sanitizeForFirestore(missionPatch), { merge: true });
            appendAudit(db, transaction, access, "growth_mission_critical_reply_refresh", "growthMission", pendingMissionRef.id, conversationRef.id);
        }
        transaction.set(targetRef, sanitizeForFirestore({
            latestConversationId: conversationRef.id,
            nextAction: target.status === "converted" || state === "interested" ? "outcome" : state === "needs_review" || requiresIncidentPause ? "review" : "hold",
            ownerQualifiedAt: state === "interested" ? persistedOwnerQualifiedAt || timestamp : persistedOwnerQualifiedAt,
            status: target.status === "converted" ? "converted" : "replied",
            suppressionStatus: state === "dnc"
                ? "suppressed"
                : state === "wrong_contact"
                    ? "wrong-contact"
                    : requiresIncidentPause
                        ? "complaint"
                        : target.suppressionStatus,
            updatedAt: timestamp,
        }), { merge: true });
        appendAudit(db, transaction, access, "reply_capture", "conversation", conversationRef.id, state);
        updateQueueSummary(db, transaction, { inboxBacklog: state === "needs_review" || state === "interested" || requiresIncidentPause ? increment(1) : increment(0) });
        updateDailyCost(db, transaction, requiresIncidentPause ? missionPatch ? 13 : 11 : 7, 0);
        const revenueSyncStatus: "not-applicable" | "pending" = state === "interested"
            && FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_REVENUE_OPERATING_LAYER
            ? "pending"
            : "not-applicable";
        transaction.create(claimRef, sanitizeForFirestore({
            actorId: access.userId,
            claimId: claimRef.id,
            conversationId: conversationRef.id,
            entityId: messageRef.id,
            operation: "reply_capture",
            pId: SIGNALDESK_PRODUCT_CODE,
            replyState: state,
            requestFingerprintHash,
            revenueSyncStatus,
            status: "completed",
            updatedAt: timestamp,
        }));
        return { conversationId: conversationRef.id, duplicate: false, revenueSyncStatus, state };
    });

    if (transactionResult.duplicate) return transactionResult;
    let revenueSyncStatus = transactionResult.revenueSyncStatus;
    if (state === "interested" && FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_REVENUE_OPERATING_LAYER) {
        try {
            await qualifySignalDeskRevenueAccountServer(access, {
                locationType: "single-location",
                targetId: input.targetId,
            });
            revenueSyncStatus = "updated";
            try {
                await claimRef.set(sanitizeForFirestore({ revenueSyncStatus, updatedAt: now() }), { merge: true });
            } catch (error) {
                logRuntimeFailure(SIGNALDESK_INTERESTED_REPLY_REVENUE_SYNC_FAILED, error, {
                    phase: "claim-status",
                    product: "signaldesk",
                    targetIdPresent: true,
                });
            }
        } catch (error) {
            revenueSyncStatus = "pending";
            logRuntimeFailure(SIGNALDESK_INTERESTED_REPLY_REVENUE_SYNC_FAILED, error, {
                channel: input.channel,
                product: "signaldesk",
                targetIdPresent: true,
            });
        }
    }

    return { ...transactionResult, revenueSyncStatus };
}

export async function createSignalDeskRouteTokenServer(access: SignalDeskAccessContext, input: RouteTokenInput) {
    const db = requireDb();
    const bridgeSecret = normalizeText(process.env[SIGNALDESK_INTEGRATION_ENV.OUTCOME_BRIDGE_SECRET]);
    if (bridgeSecret.length < 32) throw new Error("SIGNALDESK_OUTCOME_BRIDGE_SECRET_REQUIRED");
    const idempotencyKey = normalizeText(input.idempotencyKey);
    const idempotencyKeyHash = signalDeskRouteTokenIdempotencyHashFor({
        actorId: access.userId,
        idempotencyKey,
    });
    const requestFingerprintHash = createSignalDeskRouteTokenIntentFingerprint({
        actionId: normalizeText(input.actionId) || null,
        actorId: access.userId,
        channel: input.channel,
        ctaId: normalizeText(input.ctaId) || null,
        targetId: input.targetId,
        templateId: normalizeText(input.templateId) || null,
    });
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS)
        .doc(`route_token_${idempotencyKeyHash}`);
    try {
        return await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
            const priorClaimSnap = await transaction.get(claimRef);
            if (priorClaimSnap.exists) {
                const claim = parseSignalDeskRouteTokenIdempotencyClaimDocument(
                    priorClaimSnap.data(),
                    priorClaimSnap.id,
                );
                if (
                    claim.actorId !== access.userId
                    || claim.idempotencyKeyHash !== idempotencyKeyHash
                    || claim.requestFingerprintHash !== requestFingerprintHash
                ) {
                    throw new Error("ROUTE_TOKEN_IDEMPOTENCY_CONFLICT");
                }
                const routeTokenSnap = await transaction.get(
                    db.collection(SIGNALDESK_COLLECTIONS.ROUTE_TOKENS).doc(claim.entityId),
                );
                if (!routeTokenSnap.exists) throw new Error("ROUTE_TOKEN_IDEMPOTENCY_REPLAY_MISSING");
                const routeToken = parseSignalDeskRouteTokenDocument(routeTokenSnap.data(), routeTokenSnap.id);
                assertSignalDeskRouteTokenClaimMatchesDocument(claim, routeToken);
                if (routeToken.targetId !== input.targetId || routeToken.channel !== input.channel) {
                    throw new Error("ROUTE_TOKEN_IDEMPOTENCY_CONFLICT");
                }
                const tokenFingerprintHash = createSignalDeskRouteTokenRequestFingerprint({
                    actorId: claim.actorId,
                    channel: routeToken.channel,
                    ctaId: routeToken.ctaId,
                    expiresAt: routeToken.expiresAt,
                    ownerQualifiedAt: routeToken.ownerQualifiedAt,
                    sourceActionId: routeToken.sourceActionId,
                    sourcePolicyId: routeToken.sourcePolicyId,
                    sourceRunId: routeToken.sourceRunId,
                    targetId: routeToken.targetId,
                    templateId: routeToken.templateId,
                });
                if (claim.tokenFingerprintHash !== tokenFingerprintHash) {
                    throw new Error("ROUTE_TOKEN_IDEMPOTENCY_REPLAY_INVALID");
                }
                const material = deriveSignalDeskRouteTokenMaterial({
                    bridgeSecret,
                    idempotencyKey,
                    requestFingerprintHash: tokenFingerprintHash,
                });
                if (material.routeTokenId !== routeToken.routeTokenId || material.tokenHash !== routeToken.tokenHash) {
                    throw new Error("ROUTE_TOKEN_IDEMPOTENCY_REPLAY_INVALID");
                }
                return {
                    channel: routeToken.channel,
                    duplicate: true,
                    expiresAt: routeToken.expiresAt,
                    routeTokenId: routeToken.routeTokenId,
                    targetId: routeToken.targetId,
                    token: material.token,
                };
            }

            const pauseRef = db.collection(SIGNALDESK_COLLECTIONS.KILL_SWITCHES).doc("scope_menu-list-bridge");
            const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(input.targetId);
            const [pauseSnap, targetSnap] = await Promise.all([
                transaction.get(pauseRef),
                transaction.get(targetRef),
            ]);
            if (pauseSnap.data()?.status === "active") throw new Error("MenuList outcome bridge is paused");
            if (!targetSnap.exists) throw new Error("Target not found");
            const issuedAtMillis = Date.now();
            const targetAuthority = parseSignalDeskOutcomeTargetAuthority(
                targetSnap.data(),
                targetSnap.id,
                issuedAtMillis,
            );
            const target = targetAuthority.target;
            if (target.suppressionStatus !== "clear") throw new Error("Target is suppressed");
            const policyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES).doc(targetAuthority.sourcePolicyId);
            const conversationRef = target.latestConversationId
                ? db.collection(SIGNALDESK_COLLECTIONS.CONVERSATION_SUMMARIES).doc(target.latestConversationId)
                : null;
            const [policySnap, conversationSnap, evidenceSnap] = await Promise.all([
                transaction.get(policyRef),
                conversationRef ? transaction.get(conversationRef) : Promise.resolve(null),
                transaction.get(latestOutcomeEvidenceQuery(db, target.targetId)),
            ]);
            const policy = readSourcePolicySnapshot(policySnap);
            const policyError = sourcePolicyUsabilityError(policy, { entityId: input.targetId, use: "evidence" });
            if (policyError) throw new Error(policyError);
            assertOutcomeTargetPolicyLineage(targetAuthority, policy);
            const evidenceDocument = evidenceSnap.docs[0];
            if (!evidenceDocument) throw new Error("OUTCOME_CURRENT_EVIDENCE_REQUIRED");
            parseSignalDeskOutcomeEvidenceAuthority(
                evidenceDocument.data(),
                evidenceDocument.id,
                targetAuthority,
                issuedAtMillis,
            );
            const conversation = conversationSnap?.exists
                ? parseSignalDeskConversationSummaryDocument(conversationSnap.data(), conversationSnap.id)
                : null;
            if (
                !conversation
                || conversation.state !== "interested"
                || conversation.targetId !== target.targetId
                || conversation.targetName !== target.displayName
            ) {
                throw new Error("OWNER_QUALIFIED_INTENT_REQUIRED");
            }
            const ownerQualifiedAt = target.ownerQualifiedAt
                || conversation.lastInboundAt
                || conversation.lastInboundOccurredAt;
            if (!ownerQualifiedAt) throw new Error("OWNER_QUALIFIED_INTENT_REQUIRED");
            const sourceActionId = normalizeText(input.actionId)
                || normalizeText(input.ctaId)
                || normalizeText(input.templateId)
                || conversation.conversationId;
            const expiresAtMillis = Math.min(
                issuedAtMillis + (14 * 24 * 60 * 60 * 1000),
                Date.parse(targetAuthority.sourceDataExpiresAt),
            );
            if (expiresAtMillis <= issuedAtMillis) throw new Error("OUTCOME_TARGET_SOURCE_LIFECYCLE_INACTIVE");
            const timestamp = admin.firestore.Timestamp.fromMillis(issuedAtMillis);
            const expiresAt = admin.firestore.Timestamp.fromMillis(expiresAtMillis);
            const tokenFingerprintHash = createSignalDeskRouteTokenRequestFingerprint({
                actorId: access.userId,
                channel: input.channel,
                ctaId: normalizeText(input.ctaId) || null,
                expiresAt: new Date(expiresAtMillis).toISOString(),
                ownerQualifiedAt,
                sourceActionId,
                sourcePolicyId: targetAuthority.sourcePolicyId,
                sourceRunId: targetAuthority.sourceRunId,
                targetId: target.targetId,
                templateId: normalizeText(input.templateId) || null,
            });
            const material = deriveSignalDeskRouteTokenMaterial({
                bridgeSecret,
                idempotencyKey,
                requestFingerprintHash: tokenFingerprintHash,
            });
            const routeToken = {
                routeTokenId: material.routeTokenId,
                pId: SIGNALDESK_PRODUCT_CODE,
                tokenHash: material.tokenHash,
                scope: SIGNALDESK_OUTCOME_ROUTE_SCOPE,
                targetId: target.targetId,
                targetName: target.displayName,
                sourcePolicyId: targetAuthority.sourcePolicyId,
                sourceRunId: targetAuthority.sourceRunId,
                channel: input.channel,
                templateId: normalizeText(input.templateId) || null,
                ctaId: normalizeText(input.ctaId) || null,
                sourceActionId,
                status: "active",
                ownerQualifiedAt: admin.firestore.Timestamp.fromMillis(Date.parse(ownerQualifiedAt)),
                expiresAt,
                revokedAt: null,
                revokedBy: null,
                createdAt: timestamp,
                createdBy: access.userId,
                updatedAt: timestamp,
            };
            const parsedRouteToken = parseSignalDeskRouteTokenDocument(routeToken, material.routeTokenId);
            if (!isSignalDeskRouteTokenActiveAt(parsedRouteToken, issuedAtMillis)) {
                throw new Error("ROUTE_TOKEN_ACTIVE_WINDOW_INVALID");
            }
            const claimRecord = {
                actorId: access.userId,
                entityId: material.routeTokenId,
                idempotencyKeyHash,
                operation: "route_token_create",
                pId: SIGNALDESK_PRODUCT_CODE,
                requestFingerprintHash,
                tokenFingerprintHash,
                updatedAt: timestamp,
            };
            const parsedClaim = parseSignalDeskRouteTokenIdempotencyClaimDocument(claimRecord, claimRef.id);
            assertSignalDeskRouteTokenClaimMatchesDocument(parsedClaim, parsedRouteToken);
            transaction.create(
                db.collection(SIGNALDESK_COLLECTIONS.ROUTE_TOKENS).doc(material.routeTokenId),
                sanitizeForFirestore(routeToken),
            );
            transaction.create(claimRef, sanitizeForFirestore(claimRecord));
            appendAudit(db, transaction, access, "route_token_create", "routeToken", material.routeTokenId, `${input.targetId}:${input.channel}`);
            updateDailyCost(db, transaction, 3, 0);
            return {
                channel: input.channel,
                duplicate: false,
                expiresAt: toIso(expiresAt),
                routeTokenId: material.routeTokenId,
                targetId: input.targetId,
                token: material.token,
            };
        });
    } catch (error) {
        const code = error instanceof Error ? error.message : "";
        if ([SOURCE_POLICY_EXPIRED, SOURCE_POLICY_REVIEW_REQUIRED, SOURCE_POLICY_RETENTION_MISSING, SOURCE_POLICY_USE_NOT_ALLOWED].includes(code)) {
            await appendSourcePolicyBlockedAudit(db, access, null, { entityId: input.targetId, use: "evidence" }, code);
        }
        throw error;
    }
}

export async function revokeSignalDeskRouteTokenServer(
    access: SignalDeskAccessContext,
    input: RouteTokenRevocationInput,
) {
    const db = requireDb();
    const routeTokenRef = db.collection(SIGNALDESK_COLLECTIONS.ROUTE_TOKENS).doc(input.routeTokenId);
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const routeTokenSnap = await transaction.get(routeTokenRef);
        if (!routeTokenSnap.exists) throw new Error("Route token not found");
        const routeToken = parseSignalDeskRouteTokenDocument(routeTokenSnap.data(), routeTokenSnap.id);
        if (routeToken.status === "revoked" || routeToken.revokedAt) {
            return {
                duplicate: true,
                routeTokenId: input.routeTokenId,
                status: "revoked" as const,
            };
        }
        const timestamp = now();
        transaction.set(routeTokenRef, sanitizeForFirestore({
            revocationReason: input.reason,
            revokedAt: timestamp,
            revokedBy: access.userId,
            status: "revoked",
            updatedAt: timestamp,
        }), { merge: true });
        appendAudit(db, transaction, access, "route_token_revoke", "routeToken", input.routeTokenId, input.reason);
        updateDailyCost(db, transaction, 2, 0);
        return {
            duplicate: false,
            routeTokenId: input.routeTokenId,
            status: "revoked" as const,
        };
    });
}

export async function recordSignalDeskOutcomeServer(access: SignalDeskAccessContext, input: OutcomeInput) {
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("OUTCOME_IDEMPOTENCY_KEY_REQUIRED");
    const targetId = normalizeText(input.targetId);
    const evidenceRef = normalizeText(input.evidenceRef);
    if (!targetId) throw new Error("OUTCOME_TARGET_REQUIRED");
    if (!evidenceRef) throw new Error("OUTCOME_EVIDENCE_REQUIRED");
    const surfaces = Array.from(new Set(input.surfaces || []));
    const isActivation = input.outcomeType === "two_surface_activation";
    if (isActivation && surfaces.length < 2) throw new Error("ACTIVATION_TWO_DISTINCT_SURFACES_REQUIRED");
    const ownerQualifiedMillis = toTimestampMillis(input.ownerQualifiedAt);
    const ownerReviewedMillis = toTimestampMillis(input.ownerReviewedAt);
    const maximumAcceptedTimestamp = Date.now() + (5 * 60 * 1000);
    if ((ownerQualifiedMillis && ownerQualifiedMillis > maximumAcceptedTimestamp) || (ownerReviewedMillis && ownerReviewedMillis > maximumAcceptedTimestamp)) {
        throw new Error("OUTCOME_TIMESTAMP_INVALID");
    }
    if (isActivation && (!ownerQualifiedMillis || !ownerReviewedMillis)) throw new Error("ACTIVATION_OWNER_REVIEW_REQUIRED");
    if (isActivation && ownerReviewedMillis! < ownerQualifiedMillis!) throw new Error("ACTIVATION_OWNER_REVIEW_REQUIRED");
    if (input.source === "route-token" && input.integrityStatus !== "menulist-signed") {
        throw new Error("OUTCOME_BRIDGE_SIGNATURE_REQUIRED");
    }
    if (input.source === "route-token" && !input.routeTokenValidation) throw new Error("INVALID_SIGNALDESK_ROUTE_TOKEN");
    if (input.source !== "route-token" && input.routeTokenValidation) throw new Error("INVALID_SIGNALDESK_ROUTE_TOKEN");
    const sourceEventId = normalizeText(input.sourceEventId);
    if (input.source === "manual" && sourceEventId) throw new Error("OUTCOME_MANUAL_SOURCE_EVENT_NOT_ALLOWED");
    if (input.source === "demand-signal" && !/^demand_[a-f0-9]{32}$/.test(sourceEventId)) {
        throw new Error("OUTCOME_DEMAND_SOURCE_EVENT_REQUIRED");
    }
    if (input.source === "route-token" && !sourceEventId) throw new Error("OUTCOME_ROUTE_SOURCE_EVENT_REQUIRED");
    const integrityStatus: NonNullable<SignalDeskOutcomeSummary["integrityStatus"]> = isActivation
        ? input.integrityStatus === "menulist-signed" ? "menulist-signed" : "owner-reviewed-manual"
        : input.integrityStatus === "menulist-signed" ? "menulist-signed" : "unverified";
    const idempotencyKeyHash = hashValue(`${access.userId}\0${idempotencyKey}`);
    const requestFingerprintHash = hashValue(JSON.stringify({
        channel: input.channel,
        evidenceRef,
        outcomeType: input.outcomeType,
        ownerQualifiedAt: ownerQualifiedMillis || null,
        ownerReviewedAt: ownerReviewedMillis || null,
        source: input.source,
        sourceEventId: sourceEventId || null,
        surfaces: [...surfaces].sort(),
        targetId,
        routeTokenId: input.routeTokenValidation?.routeTokenId || null,
    }));
    const outcomeRef = db.collection(SIGNALDESK_COLLECTIONS.OUTCOME_EVENTS).doc(`outcome_${idempotencyKeyHash.slice(0, 32)}`);
    const idempotencyRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`outcome_${idempotencyKeyHash}`);
    const routeTokenRef = input.routeTokenValidation
        ? db.collection(SIGNALDESK_COLLECTIONS.ROUTE_TOKENS).doc(input.routeTokenValidation.routeTokenId)
        : null;
    const transactionResult = await db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const priorIdempotencySnap = await transaction.get(idempotencyRef);
        if (priorIdempotencySnap.exists) {
            const claim = parseSignalDeskOutcomeIdempotencyClaimDocument(
                priorIdempotencySnap.data(),
                priorIdempotencySnap.id,
            );
            if (
                claim.actorId !== access.userId
                || claim.idempotencyKeyHash !== idempotencyKeyHash
                || claim.requestFingerprintHash !== requestFingerprintHash
            ) {
                throw new Error("OUTCOME_IDEMPOTENCY_CONFLICT");
            }
            const priorOutcomeSnap = await transaction.get(
                db.collection(SIGNALDESK_COLLECTIONS.OUTCOME_EVENTS).doc(claim.entityId),
            );
            if (!priorOutcomeSnap.exists) throw new Error("OUTCOME_IDEMPOTENCY_REPLAY_MISSING");
            const priorOutcome = parseSignalDeskOutcomeEventDocument(
                priorOutcomeSnap.data(),
                priorOutcomeSnap.id,
            );
            assertSignalDeskOutcomeClaimMatchesEvent(claim, priorOutcome);
            return {
                duplicate: true,
                outcomeEventId: priorOutcome.outcomeEventId,
                outcomeSummaryId: signalDeskOutcomeSummaryIdFor({
                    channel: priorOutcome.channel,
                    day: priorOutcome.createdAt.slice(0, 10),
                    outcomeType: priorOutcome.outcomeType,
                    source: priorOutcome.source,
                    targetId: priorOutcome.targetId,
                }),
            };
        }

        const targetRef = db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(targetId);
        const targetSnap = await transaction.get(targetRef);
        if (!targetSnap.exists) throw new Error("Target not found");
        const operationAtMillis = Date.now();
        const day = signalDeskOutcomeDayForMillis(operationAtMillis);
        const summaryId = signalDeskOutcomeSummaryIdFor({
            channel: input.channel,
            day,
            outcomeType: input.outcomeType,
            source: input.source,
            targetId,
        });
        const summaryRef = db.collection(SIGNALDESK_COLLECTIONS.OUTCOME_SUMMARIES).doc(summaryId);
        const targetAuthority = parseSignalDeskOutcomeTargetAuthority(
            targetSnap.data(),
            targetSnap.id,
            operationAtMillis,
        );
        const target = targetAuthority.target;
        const policyRef = db.collection(SIGNALDESK_COLLECTIONS.SOURCE_POLICIES)
            .doc(targetAuthority.sourcePolicyId);
        const demandSourceRef = input.source === "demand-signal"
            ? db.collection(SIGNALDESK_COLLECTIONS.DEMAND_SIGNALS).doc(sourceEventId)
            : null;
        const [policySnap, evidenceSnap, routeTokenSnap, summarySnap, demandSourceSnap] = await Promise.all([
            transaction.get(policyRef),
            transaction.get(latestOutcomeEvidenceQuery(db, targetId)),
            routeTokenRef ? transaction.get(routeTokenRef) : Promise.resolve(null),
            transaction.get(summaryRef),
            demandSourceRef ? transaction.get(demandSourceRef) : Promise.resolve(null),
        ]);
        const policy = readSourcePolicySnapshot(policySnap);
        const policyError = sourcePolicyUsabilityError(policy, { entityId: targetId, use: "evidence" });
        if (policyError) throw new Error(policyError);
        assertOutcomeTargetPolicyLineage(targetAuthority, policy);
        const evidenceDocument = evidenceSnap.docs[0];
        if (!evidenceDocument) throw new Error("OUTCOME_CURRENT_EVIDENCE_REQUIRED");
        parseSignalDeskOutcomeEvidenceAuthority(
            evidenceDocument.data(),
            evidenceDocument.id,
            targetAuthority,
            operationAtMillis,
        );

        const routeToken: SignalDeskRouteTokenAuthority | null = routeTokenSnap?.exists
            ? parseSignalDeskRouteTokenDocument(routeTokenSnap.data(), routeTokenSnap.id)
            : null;
        if (routeTokenRef) {
            if (
                !routeToken
                || !isSignalDeskRouteTokenActiveAt(routeToken, operationAtMillis)
                || routeToken.tokenHash !== input.routeTokenValidation?.routeTokenHash
                || routeToken.targetId !== targetId
                || routeToken.channel !== input.channel
                || routeToken.sourcePolicyId !== targetAuthority.sourcePolicyId
                || routeToken.sourceRunId !== targetAuthority.sourceRunId
            ) {
                throw new Error("INVALID_SIGNALDESK_ROUTE_TOKEN");
            }
        }
        if (input.source === "demand-signal") {
            if (!demandSourceSnap?.exists) throw new Error("OUTCOME_DEMAND_SOURCE_EVENT_INVALID");
            const demandSource = parseSignalDeskOutcomeDemandSourceDocument(
                demandSourceSnap.data(),
                demandSourceSnap.id,
                operationAtMillis,
            );
            if (demandSource.targetId !== targetId || demandSource.targetName !== target.displayName) {
                throw new Error("OUTCOME_DEMAND_SOURCE_EVENT_INVALID");
            }
        }

        let priorSummaryCount = 0;
        if (summarySnap.exists) {
            const priorSummary = parseSignalDeskOutcomeSummaryDocument(summarySnap.data(), summarySnap.id);
            const priorSummaryEventSnap = await transaction.get(
                db.collection(SIGNALDESK_COLLECTIONS.OUTCOME_EVENTS).doc(priorSummary.latestOutcomeEventId),
            );
            if (!priorSummaryEventSnap.exists) throw new Error("OUTCOME_SUMMARY_EVENT_MISSING");
            const priorSummaryEvent = parseSignalDeskOutcomeEventDocument(
                priorSummaryEventSnap.data(),
                priorSummaryEventSnap.id,
            );
            assertSignalDeskOutcomeSummaryMatchesEvent(priorSummary, priorSummaryEvent);
            priorSummaryCount = priorSummary.count;
        }

        const timestamp = admin.firestore.Timestamp.fromMillis(operationAtMillis);
        const outcomeRecord = {
            outcomeEventId: outcomeRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            targetId,
            targetName: target.displayName,
            outcomeType: input.outcomeType,
            source: input.source,
            channel: input.channel,
            evidenceRef,
            idempotencyKeyHash,
            integrityStatus,
            ownerQualifiedAt: ownerQualifiedMillis ? admin.firestore.Timestamp.fromMillis(ownerQualifiedMillis) : null,
            ownerReviewedAt: ownerReviewedMillis ? admin.firestore.Timestamp.fromMillis(ownerReviewedMillis) : null,
            sourceEventId: sourceEventId || null,
            routeTokenId: routeTokenRef?.id || null,
            surfaces,
            createdAt: timestamp,
            createdBy: access.userId,
        };
        const parsedOutcome = parseSignalDeskOutcomeEventDocument(outcomeRecord, outcomeRef.id);
        if (routeToken) assertSignalDeskOutcomeEventMatchesRouteToken(parsedOutcome, routeToken);
        const summaryRecord = {
            outcomeSummaryId: summaryId,
            pId: SIGNALDESK_PRODUCT_CODE,
            targetId,
            targetName: target.displayName,
            outcomeType: input.outcomeType,
            source: input.source,
            channel: input.channel,
            count: priorSummaryCount + 1,
            day,
            evidenceRef,
            integrityStatus,
            latestOutcomeEventId: outcomeRef.id,
            ownerQualifiedAt: ownerQualifiedMillis ? admin.firestore.Timestamp.fromMillis(ownerQualifiedMillis) : null,
            ownerReviewedAt: ownerReviewedMillis ? admin.firestore.Timestamp.fromMillis(ownerReviewedMillis) : null,
            sourceEventId: sourceEventId || null,
            routeTokenId: routeTokenRef?.id || null,
            surfaces,
            updatedAt: timestamp,
        };
        const parsedSummary = parseSignalDeskOutcomeSummaryDocument(summaryRecord, summaryRef.id);
        assertSignalDeskOutcomeSummaryMatchesEvent(parsedSummary, parsedOutcome);
        const claimRecord = {
            actorId: access.userId,
            entityId: outcomeRef.id,
            entityType: "outcome",
            idempotencyKeyHash,
            operation: "outcome_record",
            pId: SIGNALDESK_PRODUCT_CODE,
            requestFingerprintHash,
            updatedAt: timestamp,
        };
        const parsedClaim = parseSignalDeskOutcomeIdempotencyClaimDocument(claimRecord, idempotencyRef.id);
        assertSignalDeskOutcomeClaimMatchesEvent(parsedClaim, parsedOutcome);
        const attributionTouchRef = db.collection(SIGNALDESK_COLLECTIONS.ATTRIBUTION_TOUCHES)
            .doc(`touch_${hashValue(outcomeRef.id).slice(0, 32)}`);
        const attributionTouch = {
            actionId: input.source === "route-token"
                ? routeToken?.sourceActionId
                : input.source === "demand-signal"
                    ? sourceEventId
                    : outcomeRef.id,
            channel: input.channel,
            createdAt: timestamp,
            eventId: outcomeRef.id,
            method: input.source === "route-token"
                ? "route-token-direct-v1"
                : input.source === "demand-signal"
                    ? "demand-signal-direct-v1"
                    : "manual-direct-v1",
            pId: SIGNALDESK_PRODUCT_CODE,
            targetId,
            touchId: attributionTouchRef.id,
            touchType: "direct",
            weight: 1,
        };
        const parsedAttributionTouch = parseSignalDeskAttributionTouchDocument(
            attributionTouch,
            attributionTouchRef.id,
        );
        assertSignalDeskAttributionTouchMatchesOutcome(parsedAttributionTouch, parsedOutcome, routeToken);

        transaction.create(outcomeRef, sanitizeForFirestore(outcomeRecord));
        if (summarySnap.exists) transaction.set(summaryRef, sanitizeForFirestore(summaryRecord));
        else transaction.create(summaryRef, sanitizeForFirestore(summaryRecord));
        transaction.create(idempotencyRef, sanitizeForFirestore(claimRecord));
        transaction.create(attributionTouchRef, sanitizeForFirestore(attributionTouch));

        const existingOwnerQualifiedMillis = toTimestampMillis(target.ownerQualifiedAt);
        const targetUpdates: AnyRecord = {
            latestOutcomeAt: timestamp,
            nextAction: isActivation || target.status === "converted" ? "outcome" : "review",
            status: isActivation || target.status === "converted" ? "converted" : "replied",
            updatedAt: timestamp,
        };
        if (ownerQualifiedMillis && (!existingOwnerQualifiedMillis || ownerQualifiedMillis < existingOwnerQualifiedMillis)) {
            targetUpdates.ownerQualifiedAt = admin.firestore.Timestamp.fromMillis(ownerQualifiedMillis);
        }
        if (isActivation) {
            targetUpdates.latestVerifiedActivationAt = admin.firestore.Timestamp.fromMillis(ownerReviewedMillis!);
            targetUpdates.latestVerifiedActivationEvidenceRef = evidenceRef;
            targetUpdates.latestVerifiedActivationIntegrityStatus = integrityStatus;
            targetUpdates.latestVerifiedActivationSurfaces = surfaces;
        }
        transaction.set(targetRef, sanitizeForFirestore(targetUpdates), { merge: true });
        if (routeTokenRef) {
            transaction.set(routeTokenRef, sanitizeForFirestore({
                lastOutcomeAt: timestamp,
                lastOutcomeEventIdHash: hashValue(sourceEventId || outcomeRef.id),
                updatedAt: timestamp,
            }), { merge: true });
        }
        appendAudit(db, transaction, access, "outcome_record", "outcome", outcomeRef.id, `${input.outcomeType}:${integrityStatus}`);
        updateControlSummary(db, transaction, { outcomeCount: increment(1) });
        updateDailyCost(
            db,
            transaction,
            7 + (routeTokenRef ? 1 : 0),
            0,
        );
        return { duplicate: false, outcomeEventId: outcomeRef.id, outcomeSummaryId: summaryId };
    });

    let activationWatch: SignalDeskActivationWatchSummary | null = null;
    let activationWatchSyncStatus: "not-applicable" | "updated" | "pending" = "not-applicable";
    if (!transactionResult.duplicate && FEATURE_FLAGS.ENABLE_MENULIST_SIGNALDESK_REVENUE_OPERATING_LAYER) {
        const accountSnap = await db.collection(SIGNALDESK_COLLECTIONS.REVENUE_ACCOUNTS)
            .doc(revenueAccountIdFor(targetId))
            .get();
        if (accountSnap.exists) {
            try {
                activationWatch = await refreshSignalDeskActivationWatchServer(access, { targetId });
                activationWatchSyncStatus = "updated";
            } catch (error) {
                activationWatchSyncStatus = "pending";
                logRuntimeFailure(SIGNALDESK_ACTIVATION_WATCH_AUTO_SYNC_FAILED, error, {
                    outcomeType: input.outcomeType,
                    product: "signaldesk",
                    targetIdPresent: true,
                });
            }
        }
    }

    return {
        activationWatch,
        activationWatchSyncStatus,
        duplicate: transactionResult.duplicate,
        outcomeEventId: transactionResult.outcomeEventId,
        outcomeSummaryId: transactionResult.outcomeSummaryId,
    };
}

export async function captureSignalDeskDemandSignalServer(access: SignalDeskAccessContext, input: {
    idempotencyKey: string;
    signalType: SignalDeskDemandSignalSummary["signalType"];
    sourceSurface: SignalDeskDemandSignalSummary["sourceSurface"];
    targetId?: string;
    targetName?: string;
}) {
    const db = requireDb();
    const idempotencyKey = normalizeText(input.idempotencyKey);
    if (idempotencyKey.length < 8 || idempotencyKey.length > 180) throw new Error("DEMAND_SIGNAL_IDEMPOTENCY_KEY_REQUIRED");
    const requestFingerprintHash = hashValue(JSON.stringify({
        signalType: input.signalType,
        sourceSurface: input.sourceSurface,
        targetId: input.targetId || null,
        targetName: input.targetId ? null : normalizeText(input.targetName),
    }));
    const operationHash = hashValue(`${access.userId}|${idempotencyKey}`);
    const day = todayKey();
    const signalRef = db.collection(SIGNALDESK_COLLECTIONS.DEMAND_SIGNALS).doc(`demand_${operationHash.slice(0, 32)}`);
    const claimRef = db.collection(SIGNALDESK_COLLECTIONS.IDEMPOTENCY_KEYS).doc(`demand_signal_${operationHash}`);
    const summaryId = `${day}_${input.signalType}_${input.sourceSurface}_${input.targetId || "general"}`;
    const summaryRef = db.collection(SIGNALDESK_COLLECTIONS.DEMAND_SIGNAL_SUMMARIES).doc(summaryId);
    return db.runTransaction(async (transaction: FirebaseFirestore.Transaction) => {
        const [claimSnap, targetSnap] = await Promise.all([
            transaction.get(claimRef),
            input.targetId
                ? transaction.get(db.collection(SIGNALDESK_COLLECTIONS.TARGET_SUMMARIES).doc(input.targetId))
                : Promise.resolve(null),
        ]);
        if (claimSnap.exists) {
            if (normalizeText(claimSnap.data()?.requestFingerprintHash) !== requestFingerprintHash) {
                throw new Error("DEMAND_SIGNAL_IDEMPOTENCY_CONFLICT");
            }
            return { demandSignalId: signalRef.id, duplicate: true, summaryId };
        }
        if (input.targetId && !targetSnap?.exists) throw new Error("Target not found");
        const targetName = targetSnap?.exists
            ? normalizeText(targetSnap.data()?.displayName)
            : normalizeText(input.targetName) || null;
        const timestamp = now();
        transaction.create(signalRef, sanitizeForFirestore({
            demandSignalId: signalRef.id,
            pId: SIGNALDESK_PRODUCT_CODE,
            targetId: input.targetId || null,
            targetName,
            signalType: input.signalType,
            sourceSurface: input.sourceSurface,
            createdAt: timestamp,
            createdBy: access.userId,
        }));
        transaction.set(summaryRef, sanitizeForFirestore({
            demandSignalId: summaryId,
            pId: SIGNALDESK_PRODUCT_CODE,
            targetId: input.targetId || null,
            targetName,
            signalType: input.signalType,
            sourceSurface: input.sourceSurface,
            count: increment(1),
            day,
            updatedAt: timestamp,
        }), { merge: true });
        transaction.create(claimRef, sanitizeForFirestore({
            actorId: access.userId,
            entityId: signalRef.id,
            operation: "demand_signal_capture",
            pId: SIGNALDESK_PRODUCT_CODE,
            requestFingerprintHash,
            updatedAt: timestamp,
        }));
        appendAudit(db, transaction, access, "demand_signal_capture", "demandSignal", signalRef.id, input.signalType);
        updateControlSummary(db, transaction, { demandSignalCount: increment(1) });
        updateDailyCost(db, transaction, 4, 0);
        return { demandSignalId: signalRef.id, duplicate: false, summaryId };
    });
}
